const fmtMoney = (n) => {
  const x = invoiceModalRound2(Number(n || 0));
  const abs = Math.abs(x).toFixed(2);
  // show negatives as -£12.34, positives as £12.34
  return (x < 0) ? `-£${abs}` : `£${abs}`;
};

// Quick DOM helper
const byId = (id)=>document.getElementById(id);

function ensureFinanceValidationStyles() {
  try {
    if (document.getElementById('financeValidationStyles')) return;
    const style = document.createElement('style');
    style.id = 'financeValidationStyles';
    style.textContent = `
      .finance-field-invalid { border-color: var(--danger,#ef4444) !important; box-shadow: 0 0 0 1px rgba(239,68,68,.25) inset; }
      .finance-row-invalid { color: var(--danger,#ef4444); }
      .finance-field-derived { background: var(--bg-soft,#f3f4f6) !important; opacity: .82; }
      .finance-validation-message { color: var(--danger,#ef4444); margin-top: 6px; }
    `;
    document.head.appendChild(style);
  } catch {}
}

function isValidCurrencyInput(value, opts = {}) {
  const { required = false, allowZero = false, allowNegative = false, strict = true } = opts || {};
  const s = String(value ?? '').trim();
  if (!s) return { valid: !required, reason: required ? 'Value is required.' : '' };
  const re = strict
    ? (allowNegative ? /^-?\d+(?:\.\d{1,2})?$/ : /^\d+(?:\.\d{1,2})?$/)
    : (allowNegative ? /^-?\d*(?:\.\d{0,2})?$/ : /^\d*(?:\.\d{0,2})?$/);
  if (!re.test(s)) return { valid: false, reason: 'Enter a valid amount with up to 2 decimal places.' };
  const n = Number(s);
  if (!Number.isFinite(n)) return { valid: false, reason: 'Enter a valid amount.' };
  if (!allowNegative && n < 0) return { valid: false, reason: 'Amount cannot be negative.' };
  if (!allowZero && n <= 0) return { valid: false, reason: 'Amount must be greater than 0.' };
  return { valid: true, number: n, normalized: strict ? n.toFixed(2) : s };
}

function formatCurrencyOnBlur(value, opts = {}) {
  const check = isValidCurrencyInput(value, { ...opts, strict: true });
  return check.valid ? check.normalized : String(value ?? '').trim();
}

function markFinanceInputInvalid(input, message) {
  if (!input) return;
  ensureFinanceValidationStyles();
  input.classList.add('finance-field-invalid');
  const row = input.closest('.row');
  if (row) row.classList.add('finance-row-invalid');
  const controls = input.closest('.controls') || row || input.parentElement;
  if (!controls) return;
  let msgEl = controls.querySelector('.finance-validation-message');
  if (!msgEl) {
    msgEl = document.createElement('div');
    msgEl.className = 'mini finance-validation-message';
    controls.appendChild(msgEl);
  }
  msgEl.textContent = String(message || 'Invalid value.');
}

function clearFinanceInputInvalid(input) {
  if (!input) return;
  input.classList.remove('finance-field-invalid');
  const row = input.closest('.row');
  if (row) row.classList.remove('finance-row-invalid');
  const controls = input.closest('.controls') || row || input.parentElement;
  const msgEl = controls ? controls.querySelector('.finance-validation-message') : null;
  if (msgEl) msgEl.remove();
}

function readCurrencyOrMarkInvalid(input, opts = {}) {
  const check = isValidCurrencyInput(input ? input.value : '', { ...opts, strict: true });
  if (!check.valid) {
    markFinanceInputInvalid(input, check.reason || 'Enter a valid amount.');
    return { ok: false, reason: check.reason || 'Invalid value.' };
  }
  clearFinanceInputInvalid(input);
  return { ok: true, number: check.number, text: check.normalized };
}

function readPositiveIntegerOrMarkInvalid(input, opts = {}) {
  const { required = true, min = 1, label = 'Value' } = opts || {};
  const s = String(input ? input.value : '').trim();
  if (!s) {
    if (required) {
      markFinanceInputInvalid(input, `${label} is required.`);
      return { ok: false, reason: `${label} is required.` };
    }
    clearFinanceInputInvalid(input);
    return { ok: true, number: null, text: '' };
  }
  if (!/^\d+$/.test(s)) {
    markFinanceInputInvalid(input, `${label} must be a whole number.`);
    return { ok: false, reason: `${label} must be a whole number.` };
  }
  const n = Number(s);
  if (!Number.isFinite(n) || n < min) {
    markFinanceInputInvalid(input, `${label} must be at least ${min}.`);
    return { ok: false, reason: `${label} must be at least ${min}.` };
  }
  clearFinanceInputInvalid(input);
  return { ok: true, number: n, text: String(Math.trunc(n)) };
}

// ===== Session handling =====
function saveSession(sess){
  const previousPrincipalId = String(
    SESSION?.user?.id || SESSION?.user?.user_id || SESSION?.user?.sub || ''
  ).trim();
  const nextPrincipalId = String(
    sess?.user?.id || sess?.user?.user_id || sess?.user?.sub || ''
  ).trim();
  const samePrincipal = !!(
    previousPrincipalId && nextPrincipalId && previousPrincipalId === nextPrincipalId
  );
  SESSION = sess;
  const persist = document.getElementById('rememberMe')?.checked ?? true;
  const store = persist ? localStorage : sessionStorage;
  store.setItem('cloudtms.session', JSON.stringify(sess));
  if (persist) sessionStorage.removeItem('cloudtms.session');
  scheduleRefresh();
  renderUserChip();
  window.dispatchEvent(new CustomEvent('cloudtms:office-session-ready', {
    detail: { same_principal: samePrincipal }
  }));
}
// FRONTEND — loadUserGridPrefs
async function loadUserGridPrefs(section) {
  // If already loaded and shaped correctly, just reuse
  if (window.__gridPrefs && typeof window.__gridPrefs === 'object') {
    if (!window.__gridPrefs.grid || typeof window.__gridPrefs.grid !== 'object') {
      window.__gridPrefs = { grid: {} };
    }
    if (!window.__gridPrefs.grid[section] || typeof window.__gridPrefs.grid[section] !== 'object') {
      window.__gridPrefs.grid[section] = {};
    }
    return window.__gridPrefs;
  }

  // GET once per app session from backend (which applies defaults if needed)
  let prefs;
  try {
    const res = await authFetch(API('/api/users/me/grid-prefs'));
    prefs = (await res.json()) || {};
  } catch (e) {
    console.error('[GRID] failed to load user grid prefs', e);
    prefs = {};
  }

  // Normalise to at least { grid: {} }
  if (!prefs || typeof prefs !== 'object') {
    prefs = { grid: {} };
  }
  if (!prefs.grid || typeof prefs.grid !== 'object') {
    prefs.grid = {};
  }
  // ensure object for this section
  if (!prefs.grid[section] || typeof prefs.grid[section] !== 'object') {
    prefs.grid[section] = {};
  }

  // One-time import from legacy localStorage, if present and no columns yet
  try {
    const legacyKey = 'cloudtms.cols.' + section;
    const legacy = localStorage.getItem(legacyKey);
    if (legacy && !prefs.grid[section].columns) {
      const cols = JSON.parse(legacy);
      if (Array.isArray(cols)) {
        const columns = {};
        cols.forEach((k, i) => {
          columns[k] = { visible: true, order: i };
        });
        prefs.grid[section].columns = columns;
        // Persist immediately so backend has them
        window.__gridPrefs = prefs;
        await saveUserGridPrefsDebounced(section, { columns }, true);
      }
      try { localStorage.removeItem(legacyKey); } catch (_) {}
    }
  } catch (e) {
    console.warn('[GRID] legacy grid prefs import failed', e);
  }

  window.__gridPrefs = prefs;
  return prefs;
}

const __saveTimers = new Map();
async function saveUserGridPrefsDebounced(section, partial, immediate = false) {
  // Ensure global shape
  if (!window.__gridPrefs || typeof window.__gridPrefs !== 'object') {
    window.__gridPrefs = { grid: {} };
  }
  if (!window.__gridPrefs.grid || typeof window.__gridPrefs.grid !== 'object') {
    window.__gridPrefs.grid = {};
  }

  const grid = window.__gridPrefs.grid;
  const existing = (grid[section] && typeof grid[section] === 'object') ? grid[section] : {};
  grid[section] = { ...existing, ...(partial || {}) };

  const key = `grid:${section}`;

  const fire = async () => {
   const body = {
  section,
  prefs: grid[section] || {}
};

    try {
      const res = await authFetch(API('/api/users/me/grid-prefs'), {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });
      const saved = await res.json().catch(() => null);
      // If server returned a full prefs object with .grid, adopt it as source of truth
      if (saved && typeof saved === 'object' && saved.grid && typeof saved.grid === 'object') {
        window.__gridPrefs = saved;
      }
    } catch (e) {
      console.error('Failed to save grid prefs', e);
    }
  };

  if (immediate) {
    return fire();
  }

  window.__saveTimers = window.__saveTimers || new Map();
  if (window.__saveTimers.has(key)) {
    clearTimeout(window.__saveTimers.get(key));
  }
  window.__saveTimers.set(key, setTimeout(fire, 300));
}

function getVisibleBulkAuthoriseRows(state) {
  const st = (state && typeof state === 'object') ? state : {};
  const ds = (st.dataset && typeof st.dataset === 'object') ? st.dataset : {};
  const rows = Array.isArray(ds.rows) ? ds.rows.slice() : [];
  const filters = (st.filters && typeof st.filters === 'object') ? st.filters : {};

  const trimStr = (value) => String(value == null ? '' : value).trim();
  const upper = (value) => trimStr(value).toUpperCase();
  const lower = (value) => trimStr(value).toLowerCase();
  const readFirst = (...values) => {
    for (const value of values) {
      if (value !== undefined && value !== null) return value;
    }
    return null;
  };
  const readBool = (value, defaultValue) => {
    if (value === true) return true;
    if (value === false) return false;
    if (value == null || trimStr(value) === '') return !!defaultValue;
    const s = lower(value);
    if (s === 'false' || s === '0' || s === 'no' || s === 'n' || s === 'off') return false;
    if (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on') return true;
    return !!defaultValue;
  };

  const classificationRaw = upper(readFirst(st.classification, filters.classification, ds?.filters?.classification, 'TIMESHEETS'));
  const classification = (classificationRaw === 'NHSP' || classificationRaw === 'HR' || classificationRaw === 'TIMESHEETS')
    ? classificationRaw
    : 'TIMESHEETS';
  const weeklySourceCategory = normaliseBulkAuthoriseWeeklySourceCategory(
    readFirst(st.weekly_source_category, filters.weekly_source_category, 'STANDARD_TIMESHEETS')
  );

  const q = lower(readFirst(filters.q, filters.search, filters.text, ''));
  const clientId = trimStr(readFirst(filters.client_id, filters.clientId, ''));
  const candidateId = trimStr(readFirst(filters.candidate_id, filters.candidateId, ''));

  const showDaily = readBool(readFirst(filters.show_daily, filters.showDaily), true);
  const showWeekly = readBool(readFirst(filters.show_weekly, filters.showWeekly), true);
  const showManual = readBool(readFirst(filters.show_manual, filters.showManual), true);
  const showQr = readBool(readFirst(filters.show_qr, filters.showQr), true);
  const showElectronic = readBool(readFirst(filters.show_electronic, filters.showElectronic), true);
  const validationAlready = readBool(readFirst(filters.validation_already, filters.validationAlready), true);
  const validationAwaiting = readBool(readFirst(filters.validation_awaiting, filters.validationAwaiting), false);

  const getRowClassification = (row) => {
    const explicit = upper(row?.bulk_authorise_classification || '');
    if (explicit === 'NHSP' || explicit === 'HR' || explicit === 'TIMESHEETS') return explicit;
    return 'TIMESHEETS';
  };

  const getRowWeeklySourceCategory = (row) => {
    return deriveBulkAuthoriseWeeklySourceCategory(row);
  };

  const getPeriodType = (row) => {
    const explicit = upper(row?.period_type || '');
    if (explicit === 'DAILY' || explicit === 'WEEKLY') return explicit;
    return 'WEEKLY';
  };

  const getTimesheetType = (row) => {
    const family = upper(row?.route_family || row?.underlying_channel_family || '');
    const typeSort = Number(row?.timesheet_type_sort_key);

    if (family === 'MANUAL_NON_QR' || typeSort === 1) return 'MANUAL';
    if (family === 'QR' || typeSort === 2) return 'QR';
    if (family === 'ELECTRONIC' || typeSort === 3) return 'ELECTRONIC';
    return 'UNKNOWN';
  };

  const rowMatchesText = (row) => {
    if (!q) return true;
    const haystack = [
      row?.candidate_id,
      row?.candidate_name,
      row?.candidate_display_name,
      row?.candidate_first_name,
      row?.candidate_surname,
      row?.occupant_key_norm,
      row?.client_id,
      row?.client_name,
      row?.client_display_name,
      row?.hospital_name,
      row?.hospital_norm,
      row?.site_name,
      row?.ward_name,
      row?.ward_norm,
      row?.booking_ref,
      row?.external_ref,
      row?.reference_number,
      row?.timesheet_id,
      row?.current_timesheet_id,
      row?.requested_timesheet_id,
      row?.expected_timesheet_id,
      row?.contract_week_id,
      row?.contract_id,
      row?.row_key,
      row?.route_family,
      row?.route_subfamily,
      row?.underlying_channel_family,
      row?.bulk_authorise_classification,
      row?.bulk_authorise_section,
      row?.route_type,
      row?.route_display,
      row?.sheet_scope,
      row?.period_type,
      row?.submission_mode,
      row?.submission_mode_snapshot,
      row?.summary_stage,
      row?.tools_stage,
      row?.processing_status,
      row?.processing_status_display,
      row?.validation_status,
      row?.pay_icon_code,
      row?.pay_status_code,
      row?.processed_by_display,
      row?.authorised_by_display,
      row?.processed_by_user_id,
      row?.authorised_by_user_id,
      row?.nhsp_highlight_reason,
      row?.deviation_marker_reason,
      ...(Array.isArray(row?.issue_codes) ? row.issue_codes : [])
    ].map((value) => lower(value)).filter(Boolean).join(' ');
    return haystack.includes(q);
  };

  const rowMatchesClient = (row) => {
    if (!clientId) return true;
    return trimStr(row?.client_id || row?.clientId || '') === clientId;
  };

  const rowMatchesCandidate = (row) => {
    if (!candidateId) return true;
    return trimStr(row?.candidate_id || row?.candidateId || '') === candidateId;
  };

  const rowMatchesTimesheetFilters = (row) => {
    if (weeklySourceCategory !== 'STANDARD_TIMESHEETS' || classification !== 'TIMESHEETS') return true;

    const periodType = getPeriodType(row);
    if (periodType === 'DAILY' && !showDaily) return false;
    if (periodType === 'WEEKLY' && !showWeekly) return false;

    const timesheetType = getTimesheetType(row);
    if (timesheetType === 'MANUAL' && !showManual) return false;
    if (timesheetType === 'QR' && !showQr) return false;
    if (timesheetType === 'ELECTRONIC' && !showElectronic) return false;
    if (timesheetType === 'UNKNOWN' && !(showManual && showQr && showElectronic)) return false;

    const isAwaitingValidation = row?.hr_validation_awaiting === true;
    if (validationAlready && validationAwaiting) return true;
    if (validationAlready) return !isAwaitingValidation;
    if (validationAwaiting) return isAwaitingValidation;
    return false;
  };

  const sortRows = (list) => {
    const sorted = Array.isArray(list) ? list.slice() : [];
    if (typeof compareBulkAuthoriseRows === 'function') {
      sorted.sort((a, b) => compareBulkAuthoriseRows(a, b, st.sort_state));
      return sorted;
    }
    sorted.sort((a, b) => {
      const aWeek = trimStr(a?.week_ending_date || a?.contract_week_ending_date || a?.date || '');
      const bWeek = trimStr(b?.week_ending_date || b?.contract_week_ending_date || b?.date || '');
      if (aWeek !== bWeek) return aWeek.localeCompare(bWeek);
      const aClient = lower(a?.client_name || a?.client_display_name || '');
      const bClient = lower(b?.client_name || b?.client_display_name || '');
      if (aClient !== bClient) return aClient.localeCompare(bClient);
      const aCandidate = lower(a?.candidate_name || a?.candidate_display_name || '');
      const bCandidate = lower(b?.candidate_name || b?.candidate_display_name || '');
      if (aCandidate !== bCandidate) return aCandidate.localeCompare(bCandidate);
      return trimStr(a?.row_key || '').localeCompare(trimStr(b?.row_key || ''));
    });
    return sorted;
  };

  const baseRows = rows.filter((row) => row && typeof row === 'object');
  const classificationRows = baseRows.filter((row) => (
    getRowClassification(row) === classification && getRowWeeklySourceCategory(row) === weeklySourceCategory
  ));
  const textRows = classificationRows.filter(rowMatchesText);
  const clientFilteredRows = textRows.filter(rowMatchesClient);
  const candidateFilteredRows = clientFilteredRows.filter(rowMatchesCandidate);
  const visibleRows = sortRows(candidateFilteredRows.filter(rowMatchesTimesheetFilters));

  const serverCandidateOptions = Array.isArray(ds.candidate_option_rows) ? ds.candidate_option_rows : null;
  const serverClientOptions = Array.isArray(ds.client_option_rows) ? ds.client_option_rows : null;

  const candidateOptionRows = serverCandidateOptions
    ? sortRows(serverCandidateOptions.filter((row) => getRowClassification(row) === classification && getRowWeeklySourceCategory(row) === weeklySourceCategory).filter(rowMatchesText).filter(rowMatchesClient).filter(rowMatchesTimesheetFilters))
    : sortRows(textRows.filter(rowMatchesClient).filter(rowMatchesTimesheetFilters));

  const clientOptionRows = serverClientOptions
    ? sortRows(serverClientOptions.filter((row) => getRowClassification(row) === classification && getRowWeeklySourceCategory(row) === weeklySourceCategory).filter(rowMatchesText).filter(rowMatchesCandidate).filter(rowMatchesTimesheetFilters))
    : sortRows(textRows.filter(rowMatchesCandidate).filter(rowMatchesTimesheetFilters));

  const visibleProcessedEligibleRows = visibleRows.filter((row) => trimStr(row?.bulk_authorise_section || '') === 'processed_eligible');
  const visibleAuthorisedEligibleRows = visibleRows.filter((row) => trimStr(row?.bulk_authorise_section || '') === 'authorised_eligible');
  const visibleReviewRequiredRows = visibleRows.filter((row) => (
    trimStr(row?.bulk_authorise_section || '') === 'processed_review_required' ||
    upper(row?.bulk_authorise_block_code || '') === 'DUPLICATE_EXPENSE_REVIEW_REQUIRED'
  ));

  return {
    visible_rows: visibleRows,
    visible_processed_eligible_rows: visibleProcessedEligibleRows,
    visible_authorised_eligible_rows: visibleAuthorisedEligibleRows,
    visible_review_required_rows: visibleReviewRequiredRows,
    visible_unauthorised_rows: visibleProcessedEligibleRows.slice(),
    candidate_option_rows: candidateOptionRows,
    client_option_rows: clientOptionRows
  };
}





function getVisibleColumnsForSection(section, rows) {
  const defaults = (typeof defaultColumnKeysForSection === 'function')
    ? defaultColumnKeysForSection(section)
    : (typeof defaultColumnsFor === 'function'
        ? defaultColumnsFor(section)
        : []);

  const root = (window.__gridPrefs && window.__gridPrefs.grid) || {};
  const prefsRoot = (root[section] && typeof root[section] === 'object') ? root[section] : {};
  const colPrefs  = prefsRoot.columns      || {};
  const userMeta  = prefsRoot.columns_meta || {};

  const globalMeta =
    (typeof GRID_COLUMN_META_DEFAULTS === 'object' &&
     GRID_COLUMN_META_DEFAULTS[section]) || {};

  // ✅ Build catalog of known columns: defaults + grid prefs keys + meta keys + first row's keys
  // This keeps the visible column set stable even when rows is empty.
  const known = new Set(defaults);

  // Include any keys the user has ever saved prefs for (even if data is currently empty)
  try { Object.keys(colPrefs || {}).forEach((k) => known.add(k)); } catch {}
  try { Object.keys(userMeta || {}).forEach((k) => known.add(k)); } catch {}
  try { Object.keys(globalMeta || {}).forEach((k) => known.add(k)); } catch {}

  // Also include keys from current dataset (when present)
  if (Array.isArray(rows) && rows.length > 0 && rows[0] && typeof rows[0] === 'object') {
    Object.keys(rows[0]).forEach((k) => known.add(k));
  }

  const entries = Array.from(known).map((k) => {
    const p = colPrefs[k] || {};
    const meta = {
      ...(globalMeta[k] || {}),
      ...(userMeta[k]   || {})
    };

    const selectable = (meta.selectable !== false); // default true

    // ✅ FIX: Visibility must NOT default to true for non-default columns.
    // - defaults are visible by default
    // - if user explicitly set visible true/false, respect it
    // - otherwise hide (prevents "hundreds of columns" explosion)
    const hasExplicitVisible = Object.prototype.hasOwnProperty.call(p, 'visible');
    const isTimesheetOfficeDefault = section === 'timesheets'
      && ['candidate_submission', 'issue_codes'].includes(k);
    const visible = hasExplicitVisible
      ? (p.visible !== false)
      : (defaults.indexOf(k) >= 0 || isTimesheetOfficeDefault);

    const order = (typeof p.order === 'number')
      ? p.order
      : (defaults.indexOf(k) >= 0 ? defaults.indexOf(k) : 9999);

    const width = (typeof p.width === 'number') ? p.width : null;

    return { key: k, selectable, visible, order, width };
  });

  // Only include columns that are globally/user-selectable AND marked visible
  const filtered = entries.filter((e) => e.selectable && e.visible);
  filtered.sort((a, b) => a.order - b.order);

  if (section === 'timesheets') {
    const keys = filtered.map(entry => entry.key);
    const placeDefault = (key, afterKey) => {
      const pref = colPrefs[key] || {};
      if (typeof pref.order === 'number') return;
      const current = keys.indexOf(key);
      if (current < 0) return;
      keys.splice(current, 1);
      const after = keys.indexOf(afterKey);
      keys.splice(after >= 0 ? after + 1 : keys.length, 0, key);
    };
    const processingKey = keys.includes('processing_status_display')
      ? 'processing_status_display'
      : 'processing_status';
    placeDefault('candidate_submission', processingKey);
    placeDefault('issue_codes', 'candidate_submission');
    return keys;
  }

  return filtered.map((e) => e.key);
}

function applyUserGridPrefs(section, tables, cols) {
  const root = (window.__gridPrefs && window.__gridPrefs.grid) || {};
  const prefsRoot = root[section] || {};
  const colPrefs = prefsRoot.columns || {};
  const MIN_W = 80, MAX_W = 600;
  const resolvedWidths = new Map();

  const headTable = (tables && tables.head) ? tables.head : tables;
  const bodyTable = (tables && tables.body) ? tables.body : tables;

  let widthGroup = null;
  if (headTable && Array.isArray(cols)) {
    widthGroup = headTable.querySelector(':scope > colgroup[data-grid-width-owner="1"]');
    if (!widthGroup) {
      widthGroup = document.createElement('colgroup');
      widthGroup.dataset.gridWidthOwner = '1';
      const selectorCol = document.createElement('col');
      selectorCol.style.width = '40px';
      widthGroup.appendChild(selectorCol);
      cols.forEach((key) => {
        const col = document.createElement('col');
        col.dataset.colKey = String(key);
        widthGroup.appendChild(col);
      });
      headTable.insertBefore(widthGroup, headTable.firstChild);
    }
  }

  const widthOf = (k) => {
    let w = colPrefs[k]?.width;
    if (typeof w !== 'number' || !(w > 0)) return null; // auto → we’ll measure below
    if (w < MIN_W) w = MIN_W;
    if (w > MAX_W) w = MAX_W;
    return w;
  };

  const setColWidthPx = (colKey, pxOrNull) => {
    if (widthGroup) {
      const col = widthGroup.querySelector(
        `col[data-col-key="${CSS.escape(colKey)}"]`
      );
      if (col) col.style.width = (pxOrNull == null ? '' : `${pxOrNull}px`);
    }
    if (headTable) {
      const th = headTable.querySelector(
        `thead th[data-col-key="${CSS.escape(colKey)}"]`
      );
      if (th) {
        th.style.width = (pxOrNull == null ? '' : `${pxOrNull}px`);
      }
    }

    if (bodyTable) {
      const tds = bodyTable.querySelectorAll(
        `tbody td[data-col-key="${CSS.escape(colKey)}"]`
      );
      tds.forEach(td => {
        td.style.width = (pxOrNull == null ? '' : `${pxOrNull}px`);
      });
    }
  };

  // 🔑 NEW: ensure we have a mutable columns prefs object so we can persist
  const ensureColsPrefs = () => {
    window.__gridPrefs = window.__gridPrefs || { grid: {} };
    window.__gridPrefs.grid = window.__gridPrefs.grid || {};
    const g = window.__gridPrefs.grid;
    g[section] = g[section] || {};
    g[section].columns = g[section].columns || {};
    return g[section].columns;
  };

  (cols || []).forEach((k) => {
    let w = widthOf(k);

    // If no saved width, measure the header cell’s current width
    if (w == null && headTable) {
      const th = headTable.querySelector(
        `thead th[data-col-key="${CSS.escape(k)}"]`
      );
      if (th) {
        const rect = th.getBoundingClientRect();
        w = Math.round(rect.width);
        if (w < MIN_W) w = MIN_W;
        if (w > MAX_W) w = MAX_W;

        // Persist this as the column’s width so future renders stay aligned
        const colsPrefs = ensureColsPrefs();
        colsPrefs[k] = { ...(colsPrefs[k] || {}), width: w };
        // Fire-and-forget; no need to await
        saveUserGridPrefsDebounced(section, { columns: colsPrefs });
      }
    }

    // Now apply the width (either from prefs or measured)
    if (w != null) {
      resolvedWidths.set(k, w);
      setColWidthPx(k, w);
    }
  });

  // A fixed-layout table with width:100% compresses an enlarged column back
  // into the viewport, so the handle can appear to do nothing and adjacent
  // headers can stop tracking their persisted positions. Own the table's
  // pixel width from the resolved column widths instead. The summary host is
  // already horizontally scrollable and min-width:100% keeps short grids tidy.
  if (headTable && resolvedWidths.size) {
    const selectorWidth = 40;
    const resolvedTableWidth = selectorWidth + Array.from(resolvedWidths.values())
      .reduce((sum, width) => sum + Number(width || 0), 0);
    headTable.style.width = `${Math.max(selectorWidth, Math.round(resolvedTableWidth))}px`;
    headTable.style.minWidth = '100%';
  }
}

function wireGridColumnResizing(section, tables) {
  const MIN_W = 80, MAX_W = 600;

  const headTable = (tables && tables.head) ? tables.head : tables;
  const bodyTable = (tables && tables.body) ? tables.body : tables;

  const ensureColsPrefs = () => {
    if (!window.__gridPrefs || typeof window.__gridPrefs !== 'object') {
      window.__gridPrefs = { grid: {} };
    }
    if (!window.__gridPrefs.grid || typeof window.__gridPrefs.grid !== 'object') {
      window.__gridPrefs.grid = {};
    }
    const g = window.__gridPrefs.grid;
    g[section] = g[section] || {};
    g[section].columns = g[section].columns || {};
    return g[section].columns;
  };

  let drag = null;

  const onMove = (ev) => {
    if (!drag) return;
    const dx = (ev.clientX || 0) - drag.startX;
    let w = Math.max(MIN_W, Math.min(MAX_W, drag.startW + dx));
    drag.th.style.width = `${w}px`;
    drag.cells.forEach(td => { td.style.width = `${w}px`; });
    if (drag.col) drag.col.style.width = `${w}px`;
    if (headTable && Number.isFinite(drag.startTableW)) {
      headTable.style.width = `${Math.max(drag.startTableW + (w - drag.startW), MIN_W)}px`;
      headTable.style.minWidth = '100%';
    }
  };

  const onUp = () => {
    if (!drag) return;
    const th = drag.th;
    const key = th.dataset.colKey;
    const rect = th.getBoundingClientRect();
    const w = Math.max(MIN_W, Math.min(MAX_W, Math.round(rect.width)));
    const colsPrefs = ensureColsPrefs();
    colsPrefs[key] = { ...(colsPrefs[key] || {}), width: w };
    saveUserGridPrefsDebounced(section, { columns: colsPrefs });
    drag = null;
    document.removeEventListener('mousemove', onMove);
    document.removeEventListener('mouseup', onUp, true);
  };

  if (!headTable) return;

  headTable.querySelectorAll('thead th').forEach((th) => {
    const handle = th.querySelector('.col-resizer');
    if (!handle) return;

    handle.addEventListener('mousedown', (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      const key = th.dataset.colKey;
      const col = headTable.querySelector(
        `:scope > colgroup[data-grid-width-owner="1"] col[data-col-key="${CSS.escape(key)}"]`
      );
      const cells = bodyTable
        ? Array.from(bodyTable.querySelectorAll(`tbody td[data-col-key="${CSS.escape(key)}"]`))
        : [];
      drag = {
        th,
        startX: ev.clientX || 0,
        startW: Math.round(th.getBoundingClientRect().width || MIN_W),
        startTableW: Math.round(headTable.getBoundingClientRect().width || 0),
        col,
        cells
      };
      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp, true);
    });

    // Double-click handle resets width for this column to auto
    handle.addEventListener('dblclick', (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      const key = th.dataset.colKey;
      th.style.width = '';
      const col = headTable.querySelector(
        `:scope > colgroup[data-grid-width-owner="1"] col[data-col-key="${CSS.escape(key)}"]`
      );
      if (col) col.style.width = '';
      if (bodyTable) {
        bodyTable
          .querySelectorAll(`tbody td[data-col-key="${CSS.escape(key)}"]`)
          .forEach(td => { td.style.width = ''; });
      }
      const colsPrefs = ensureColsPrefs();
      if (colsPrefs[key]) delete colsPrefs[key].width;
      saveUserGridPrefsDebounced(section, { columns: colsPrefs });
    });
  });
}

const installPlainTokenMessageHelpers = () => {
  const existingHelpers = window.__mailshotPlainTokenMessageHelpers;
  if (
    existingHelpers &&
    typeof existingHelpers === 'object' &&
    existingHelpers.__version === 'plain-token-v4' &&
    typeof existingHelpers.decorateRawToHtml === 'function' &&
    typeof existingHelpers.serializeSurfaceToRaw === 'function' &&
    typeof existingHelpers.sync === 'function' &&
    typeof existingHelpers.initSurface === 'function' &&
    typeof existingHelpers.captureSelection === 'function' &&
    typeof existingHelpers.restoreSelection === 'function' &&
    typeof existingHelpers.bindSurface === 'function'
  ) {
    return existingHelpers;
  }

  const trimStrSafe = (v) => String(v == null ? '' : v).trim();

  const normalizeEntityTypeSafe = (v) => {
    if (typeof normalizeEntityType === 'function') {
      try {
        return normalizeEntityType(v);
      } catch {}
    }
    const s0 = trimStrSafe(v).toLowerCase();
    return ['candidate', 'client', 'contract', 'timesheet', 'invoice', 'umbrella'].includes(s0) ? s0 : '';
  };

  const normalizeOutputTypeSafe = (v) => {
    if (typeof normalizeOutputType === 'function') {
      try {
        return normalizeOutputType(v);
      } catch {}
    }
    const up = trimStrSafe(v).toUpperCase();
    if (up === 'CSV') return 'EXCEL';
    return ['EMAIL', 'WORD', 'EXCEL', 'WHATSAPP', 'SMS', 'VOICE'].includes(up) ? up : '';
  };

  const getModalCtxSafe = () => {
    try {
      if (typeof modalCtx !== 'undefined' && modalCtx && typeof modalCtx === 'object') {
        return modalCtx;
      }
    } catch {}
    try {
      if (window.modalCtx && typeof window.modalCtx === 'object') {
        return window.modalCtx;
      }
    } catch {}
    return null;
  };

  const esc = (s) => String(s ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');

  const tokenRe = /\{\{[^{}]+\}\}/g;
  const selectionStateBySurface = new Map();
  let documentSelectionBound = false;

  const normalizeRaw = (raw) => {
    return String(raw == null ? '' : raw)
      .replace(/\r/g, '')
      .replace(/\u00a0/g, ' ');
  };

  const getSurfaceOutputType = (surfaceEl) => {
    const attrOutputType = normalizeOutputTypeSafe(
      surfaceEl && typeof surfaceEl.getAttribute === 'function'
        ? (
            surfaceEl.getAttribute('data-msw-output-type') ||
            surfaceEl.getAttribute('data-dt-output-type') ||
            surfaceEl.getAttribute('data-plain-output-type') ||
            ''
          )
        : ''
    );
    if (attrOutputType) return attrOutputType;

    const ctx = getModalCtxSafe();
    return normalizeOutputTypeSafe(
      ctx &&
      ctx.documentTemplatesDraft &&
      ctx.documentTemplatesDraft.editor &&
      ctx.documentTemplatesDraft.editor.output_type
    );
  };

  const shouldCollapseSurfaceNewlines = (surfaceEl) => {
    const explicit = trimStrSafe(
      surfaceEl && typeof surfaceEl.getAttribute === 'function'
        ? (surfaceEl.getAttribute('data-msw-collapse-newlines') || '')
        : ''
    ).toLowerCase();

    if (explicit === '1' || explicit === 'true' || explicit === 'yes') return true;
    if (explicit === '0' || explicit === 'false' || explicit === 'no') return false;

    return getSurfaceOutputType(surfaceEl) === 'WHATSAPP';
  };

  const finalizeSerializedSurfaceRaw = (surfaceEl, raw) => {
    let out = normalizeRaw(raw).replace(/\n{3,}/g, '\n\n');

    if (shouldCollapseSurfaceNewlines(surfaceEl)) {
      out = out.replace(/\s*\n+\s*/g, ' ');
      out = out.replace(/[ \t]{2,}/g, ' ');
      return out.trim();
    }

    return out
      .replace(/^\n+/, '')
      .replace(/\n+$/, '');
  };

  const tokenTextToLabel = (tokenText) => {
    const raw = String(tokenText || '');
    const inner = raw.startsWith('{{') && raw.endsWith('}}')
      ? raw.slice(2, -2).trim()
      : raw.trim();

    if (!inner) return raw;

    const ctx = getModalCtxSafe();
    const entityType = normalizeEntityTypeSafe(
      (ctx && ctx.documentTemplatesDraft && ctx.documentTemplatesDraft.editor && ctx.documentTemplatesDraft.editor.entity_type) || ''
    );

    try {
      const fieldDraft = (ctx && ctx.documentTemplatesDraft && ctx.documentTemplatesDraft.field_palette && typeof ctx.documentTemplatesDraft.field_palette === 'object')
        ? ctx.documentTemplatesDraft.field_palette
        : null;
      const items = fieldDraft && Array.isArray(fieldDraft.items) ? fieldDraft.items : [];
      const hit = items.find((it) => {
        const fk = trimStrSafe(it && it.field_key);
        const et = normalizeEntityTypeSafe(it && it.entity_type);
        return fk === inner && (!entityType || !et || et === entityType);
      });
      if (hit) {
        return trimStrSafe(hit.label_effective || hit.effective_label || hit.label_override || hit.label_default || hit.label || inner) || inner;
      }
    } catch {}

    return inner;
  };

  const decorateRawToHtml = (raw) => {
    const src = normalizeRaw(raw);
    if (!src) return '';

    tokenRe.lastIndex = 0;

    let html = '';
    let lastIdx = 0;
    let match;

    while ((match = tokenRe.exec(src)) !== null) {
      const start = Number(match.index || 0);
      const end = start + String(match[0] || '').length;

      if (start > lastIdx) {
        html += esc(src.slice(lastIdx, start)).replace(/\n/g, '<br>');
      }

      const tokenText = String(match[0] || '');
      const tokenLabel = tokenTextToLabel(tokenText);

      html += `<span data-msw-plain-token="${esc(tokenText)}" contenteditable="false" class="template-merge-token" style="display:inline-block;padding:1px 6px;border:1px solid rgba(255,255,255,0.18);border-radius:999px;background:rgba(255,255,255,0.08);white-space:nowrap;vertical-align:baseline;">${esc(tokenLabel)}</span>`;
      lastIdx = end;
    }

    if (lastIdx < src.length) {
      html += esc(src.slice(lastIdx)).replace(/\n/g, '<br>');
    }

    return html;
  };

  const serializeSurfaceNode = (node) => {
    if (!node) return '';

    if (node.nodeType === Node.TEXT_NODE) {
      return String(node.nodeValue || '');
    }

    if (node.nodeType !== Node.ELEMENT_NODE) {
      return '';
    }

    if (node.hasAttribute && node.hasAttribute('data-msw-plain-token')) {
      return String(node.getAttribute('data-msw-plain-token') || '');
    }

    const tag = String(node.tagName || '').toUpperCase();
    if (tag === 'BR') return '\n';

    let out = '';
    const children = Array.from(node.childNodes || []);
    for (const child of children) {
      out += serializeSurfaceNode(child);
    }

    if (tag === 'DIV' || tag === 'P') {
      if (out && !out.endsWith('\n')) out += '\n';
    }

    return out;
  };

  const serializeNodesToRaw = (nodes) => {
    let raw = '';
    const list = Array.isArray(nodes) ? nodes : Array.from(nodes || []);
    for (const child of list) {
      raw += serializeSurfaceNode(child);
    }
    return normalizeRaw(raw).replace(/\n{3,}/g, '\n\n');
  };

  const serializeSurfaceToRaw = (surfaceEl) => {
    if (!surfaceEl) return '';

    let raw = '';
    const children = Array.from(surfaceEl.childNodes || []);
    for (const child of children) {
      raw += serializeSurfaceNode(child);
    }

    return finalizeSerializedSurfaceRaw(surfaceEl, raw);
  };

  const getSurfaceState = (surfaceId) => {
    const key = String(surfaceId || '').trim();
    if (!key) return null;
    if (!selectionStateBySurface.has(key)) {
      selectionStateBySurface.set(key, {
        surface_id: key,
        start: null,
        end: null,
        bound: false
      });
    }
    return selectionStateBySurface.get(key) || null;
  };

  const setSelectionOffsets = (surfaceId, start, end) => {
    const state = getSurfaceState(surfaceId);
    if (!state) return null;

    const safeStart = Number.isFinite(Number(start)) ? Math.max(0, Math.trunc(Number(start))) : 0;
    const safeEndBase = Number.isFinite(Number(end)) ? Math.max(0, Math.trunc(Number(end))) : safeStart;
    const safeEnd = Math.max(safeStart, safeEndBase);

    state.start = safeStart;
    state.end = safeEnd;
    return state;
  };

  const computeOffsetFromRangeBoundary = (surfaceEl, container, offset) => {
    if (!surfaceEl || !container) return 0;

    try {
      const range = document.createRange();
      range.selectNodeContents(surfaceEl);
      range.setEnd(container, Number(offset || 0));
      return serializeNodesToRaw(Array.from(range.cloneContents().childNodes || [])).length;
    } catch {
      return serializeNodesToRaw(Array.from(surfaceEl.childNodes || [])).length;
    }
  };

  const resolvePointFromOffset = (surfaceEl, rawOffset) => {
    const totalLength = serializeNodesToRaw(Array.from(surfaceEl && surfaceEl.childNodes || [])).length;
    let remaining = Math.max(0, Math.min(Number.isFinite(Number(rawOffset)) ? Math.trunc(Number(rawOffset)) : 0, totalLength));

    const walk = (parentNode) => {
      const children = Array.from(parentNode && parentNode.childNodes || []);
      if (!children.length) {
        return {
          node: parentNode,
          offset: 0
        };
      }

      for (let idx = 0; idx < children.length; idx += 1) {
        const child = children[idx];
        const childRaw = serializeSurfaceNode(child);
        const childLength = childRaw.length;

        if (remaining > childLength) {
          remaining -= childLength;
          continue;
        }

        if (child.nodeType === Node.TEXT_NODE) {
          const textLength = String(child.nodeValue || '').length;
          return {
            node: child,
            offset: Math.max(0, Math.min(remaining, textLength))
          };
        }

        if (
          child.nodeType === Node.ELEMENT_NODE &&
          child.hasAttribute &&
          child.hasAttribute('data-msw-plain-token')
        ) {
          return {
            node: parentNode,
            offset: remaining <= 0 ? idx : idx + 1
          };
        }

        if (
          child.nodeType === Node.ELEMENT_NODE &&
          String(child.tagName || '').toUpperCase() === 'BR'
        ) {
          return {
            node: parentNode,
            offset: remaining <= 0 ? idx : idx + 1
          };
        }

        if (child.nodeType === Node.ELEMENT_NODE) {
          return walk(child);
        }

        return {
          node: parentNode,
          offset: idx
        };
      }

      return {
        node: parentNode,
        offset: children.length
      };
    };

    return walk(surfaceEl);
  };

  const captureSelection = (surfaceId) => {
    const surfaceEl = document.getElementById(String(surfaceId || ''));
    if (!surfaceEl) return false;

    const selection = window.getSelection ? window.getSelection() : null;
    if (!selection || selection.rangeCount <= 0) return false;

    const range = selection.getRangeAt(0);
    const inside =
      surfaceEl.contains(range.startContainer) &&
      surfaceEl.contains(range.endContainer);

    if (!inside) return false;

    const start = computeOffsetFromRangeBoundary(surfaceEl, range.startContainer, range.startOffset);
    const end = computeOffsetFromRangeBoundary(surfaceEl, range.endContainer, range.endOffset);
    setSelectionOffsets(surfaceId, start, end);
    return true;
  };

  const restoreSelection = (surfaceId, options = {}) => {
    const surfaceEl = document.getElementById(String(surfaceId || ''));
    const state = getSurfaceState(surfaceId);
    if (!surfaceEl || !state) return false;

    const totalLength = serializeNodesToRaw(Array.from(surfaceEl.childNodes || [])).length;
    const fallback = String((options && options.fallback) || '').trim().toLowerCase();

    let start = Number.isFinite(Number(state.start)) ? Math.trunc(Number(state.start)) : null;
    let end = Number.isFinite(Number(state.end)) ? Math.trunc(Number(state.end)) : null;

    if (start === null || end === null) {
      if (fallback === 'start') {
        start = 0;
        end = 0;
      } else if (fallback === 'end') {
        start = totalLength;
        end = totalLength;
      } else {
        return false;
      }
    }

    start = Math.max(0, Math.min(start, totalLength));
    end = Math.max(start, Math.min(end, totalLength));

    const startPoint = resolvePointFromOffset(surfaceEl, start);
    const endPoint = resolvePointFromOffset(surfaceEl, end);
    if (!startPoint || !endPoint) return false;

    try {
      surfaceEl.focus();
    } catch {}

    try {
      const range = document.createRange();
      range.setStart(startPoint.node, startPoint.offset);
      range.setEnd(endPoint.node, endPoint.offset);

      const selection = window.getSelection ? window.getSelection() : null;
      if (!selection) return false;
      selection.removeAllRanges();
      selection.addRange(range);

      setSelectionOffsets(surfaceId, start, end);
      return true;
    } catch {
      return false;
    }
  };

  const bindSurface = (surfaceId, hiddenId) => {
    const surfaceEl = document.getElementById(String(surfaceId || ''));
    const hiddenEl = document.getElementById(String(hiddenId || ''));
    const state = getSurfaceState(surfaceId);
    if (!surfaceEl || !hiddenEl || !state) return false;

    if (!state.bound) {
      const captureSoon = () => {
        setTimeout(() => {
          try {
            captureSelection(surfaceId);
          } catch {}
        }, 0);
      };

      surfaceEl.addEventListener('keydown', captureSoon);
      surfaceEl.addEventListener('beforeinput', captureSoon);
      surfaceEl.addEventListener('keyup', captureSoon);
      surfaceEl.addEventListener('mouseup', captureSoon);
      surfaceEl.addEventListener('mousedown', captureSoon);
      surfaceEl.addEventListener('input', captureSoon);
      surfaceEl.addEventListener('focus', captureSoon);
      surfaceEl.addEventListener('click', captureSoon);

      state.bound = true;
    }

    if (!documentSelectionBound) {
      document.addEventListener('selectionchange', () => {
        try {
          const selection = window.getSelection ? window.getSelection() : null;
          if (!selection || selection.rangeCount <= 0) return;

          const range = selection.getRangeAt(0);
          selectionStateBySurface.forEach((surfaceState, surfaceKey) => {
            if (!surfaceState || surfaceState.bound !== true) return;
            const surfaceNode = document.getElementById(String(surfaceKey || ''));
            if (!surfaceNode) return;

            const inside =
              surfaceNode.contains(range.startContainer) &&
              surfaceNode.contains(range.endContainer);

            if (!inside) return;
            captureSelection(surfaceKey);
          });
        } catch {}
      }, true);

      documentSelectionBound = true;
    }

    return true;
  };

  const sync = (surfaceId, hiddenId, redecorate = false) => {
    const surfaceEl = document.getElementById(String(surfaceId || ''));
    const hiddenEl = document.getElementById(String(hiddenId || ''));
    if (!surfaceEl || !hiddenEl) return '';

    bindSurface(surfaceId, hiddenId);

    const activeEl = document.activeElement || null;
    const hadFocus = !!(
      activeEl &&
      (activeEl === surfaceEl || surfaceEl.contains(activeEl))
    );

    captureSelection(surfaceId);

    const raw = serializeSurfaceToRaw(surfaceEl);
    hiddenEl.value = raw;

    if (redecorate === true) {
      const nextHtml = decorateRawToHtml(raw);
      if (surfaceEl.innerHTML !== nextHtml) {
        surfaceEl.innerHTML = nextHtml;
      }
      if (hadFocus) {
        restoreSelection(surfaceId, { fallback: 'end' });
      }
    }

    return raw;
  };

  const initSurface = (surfaceId, hiddenId) => {
    const surfaceEl = document.getElementById(String(surfaceId || ''));
    const hiddenEl = document.getElementById(String(hiddenId || ''));
    if (!surfaceEl || !hiddenEl) return;

    bindSurface(surfaceId, hiddenId);

    const raw = normalizeRaw(hiddenEl.value || '');
    const nextHtml = decorateRawToHtml(raw);

    if (surfaceEl.innerHTML !== nextHtml) {
      surfaceEl.innerHTML = nextHtml;
    }

    const activeEl = document.activeElement || null;
    const hasFocus = !!(
      activeEl &&
      (activeEl === surfaceEl || surfaceEl.contains(activeEl))
    );

    if (hasFocus) {
      restoreSelection(surfaceId, { fallback: 'end' });
    }
  };

  const helpers = {
    __version: 'plain-token-v4',
    decorateRawToHtml,
    serializeSurfaceToRaw,
    sync,
    initSurface,
    captureSelection,
    restoreSelection,
    bindSurface
  };

  window.__mailshotPlainTokenMessageHelpers = helpers;
  return helpers;
};

// FRONTEND — wireGridColumnReorder
function wireGridColumnReorder(section, tables) {
  const headTable = (tables && tables.head) ? tables.head : tables;

  const ensureSectionPrefs = () => {
    if (!window.__gridPrefs || typeof window.__gridPrefs !== 'object') {
      window.__gridPrefs = { grid: {} };
    }
    if (!window.__gridPrefs.grid || typeof window.__gridPrefs.grid !== 'object') {
      window.__gridPrefs.grid = {};
    }
    const g = window.__gridPrefs.grid;
    g[section] = g[section] || {};
    g[section].columns = g[section].columns || {};
    return g[section];
  };

  if (!headTable) return;

  let dragKey = null;

  headTable.querySelectorAll('thead th[data-col-key]').forEach((th) => {
    if (!th.dataset.colKey) return;

    th.addEventListener('dragstart', (ev) => {
      dragKey = th.dataset.colKey;
      if (ev.dataTransfer) {
        ev.dataTransfer.setData('text/plain', dragKey);
        ev.dataTransfer.effectAllowed = 'move';
      }
    });

    th.addEventListener('dragover', (ev) => {
      ev.preventDefault();
      if (ev.dataTransfer) {
        ev.dataTransfer.dropEffect = 'move';
      }
    });

    th.addEventListener('drop', async (ev) => {
      ev.preventDefault();
      const targetKey = th.dataset.colKey;
      if (!dragKey || dragKey === targetKey) return;

      const headers = Array.from(headTable.querySelectorAll('thead th[data-col-key]'));
      const keys = headers.map((h) => h.dataset.colKey);

      const from = keys.indexOf(dragKey);
      const to   = keys.indexOf(targetKey);
      if (from < 0 || to < 0) return;

      // Move dragKey to the index of targetKey
      keys.splice(to, 0, keys.splice(from, 1)[0]);

      const secPrefs = ensureSectionPrefs();
      const colPrefs = { ...(secPrefs.columns || {}) };

      keys.forEach((k, i) => {
        colPrefs[k] = { ...(colPrefs[k] || {}), order: i };
      });

      await saveUserGridPrefsDebounced(section, { columns: colPrefs }, true);

      const data = await loadSection();
      renderSummary(data);
    });
  });
}

// === Shared field error helpers (red highlight + ✖) =======================

function clearFieldErrors(root) {
  if (!root) return;
  root.querySelectorAll('.field-error, .error').forEach(el => {
    el.classList.remove('field-error');
    el.classList.remove('error');
  });
  root.querySelectorAll('[aria-invalid="true"]').forEach(el => {
    el.removeAttribute('aria-invalid');
    const errorId = String(el.dataset.fieldErrorDescribedby || '').trim();
    if (errorId) {
      const keep = String(el.getAttribute('aria-describedby') || '')
        .split(/\s+/)
        .filter(Boolean)
        .filter(id => id !== errorId);
      if (keep.length) el.setAttribute('aria-describedby', keep.join(' '));
      else el.removeAttribute('aria-describedby');
      delete el.dataset.fieldErrorDescribedby;
    }
  });
  root.querySelectorAll('.field-error-msg').forEach(el => el.remove());
  root.querySelectorAll('.field-error-icon').forEach(el => el.remove());
}

function markFieldError(root, fieldName, message) {
  if (!root) return;
  let field = root.querySelector(`[name="${fieldName}"]`);
  if (!field) field = root.querySelector(`#${fieldName}`);
  if (!field) return;

  const row = field.closest('.row') || field.parentElement;
  if (!row) return;

  row.classList.add('field-error');
  row.classList.add('error');
  field.classList.add('field-error');
  field.setAttribute('aria-invalid', 'true');

  const label = row.querySelector('label');
  if (label && !label.querySelector('.field-error-icon')) {
    const icon = document.createElement('span');
    icon.className = 'field-error-icon';
    icon.textContent = '✖';
    icon.style.color = 'red';
    icon.style.marginLeft = '4px';
    label.appendChild(icon);
  }

  if (message) {
    let msg = row.querySelector('.field-error-msg');
    if (!msg) {
      msg = document.createElement('div');
      msg.className = 'field-error-msg';
      msg.id = `field-error-${String(fieldName || 'field').replace(/[^a-z0-9_-]+/gi, '-')}`;
      msg.style.color = 'red';
      msg.style.fontSize = '0.8em';
      msg.style.marginTop = '4px';
      row.appendChild(msg);
    }
    msg.textContent = message;
    const describedBy = new Set(String(field.getAttribute('aria-describedby') || '').split(/\s+/).filter(Boolean));
    describedBy.add(msg.id);
    field.setAttribute('aria-describedby', Array.from(describedBy).join(' '));
    field.dataset.fieldErrorDescribedby = msg.id;
  }
}

// === Candidate main tab validation =======================================

function validateCandidateMain(payload) {
  const root = document.querySelector('#tab-main, #tab-pay');
  if (!root) return true;

  clearFieldErrors(root);
  let ok = true;

  const first = (payload.first_name || '').trim();
  const last  = (payload.last_name  || '').trim();
  if (!first) {
    ok = false;
    markFieldError(root, 'first_name', 'First name is required');
  }
  if (!last) {
    ok = false;
    markFieldError(root, 'last_name', 'Last name is required');
  }

  // Telephone: required, optional leading +, digits only, >= 11 digits
  const phoneRaw = (payload.phone || '').trim();
  if (!phoneRaw) {
    ok = false;
    markFieldError(root, 'phone', 'Telephone number is required');
  } else {
    const phoneDigits = phoneRaw.replace(/\D/g, '');
    const phonePattern = /^\+?\d+$/;
    if (!phonePattern.test(phoneRaw) || phoneDigits.length < 11) {
      ok = false;
      markFieldError(root, 'phone', 'Telephone must be numbers only (optionally leading +) and at least 11 digits');
    }
  }

  // Email: required, simple email format
  const emailRaw = (payload.email || '').trim();
  if (!emailRaw) {
    ok = false;
    markFieldError(root, 'email', 'Email is required');
  } else {
    const emailPattern = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
    if (!emailPattern.test(emailRaw)) {
      ok = false;
      markFieldError(root, 'email', 'Please enter a valid email address');
    }
  }

  // NI: optional, but if present must be AA999999A (2 letters, 6 digits, 1 letter)
  const niRaw = (payload.ni_number || '').trim();
  if (niRaw) {
    const normNi = niRaw.replace(/\s+/g, '').toUpperCase();
    const niPattern = /^[A-Z]{2}\d{6}[A-Z]$/;
    if (!niPattern.test(normNi)) {
      ok = false;
      markFieldError(root, 'ni_number', 'Format must be like JR547853B');
    } else {
      payload.ni_number = normNi; // normalise for save
    }
  }

  // Gender: must be selected (not blank option)
  const genderRaw = (payload.gender || '').trim();
  if (!genderRaw) {
    ok = false;
    markFieldError(root, 'gender', 'Please select a gender');
  }

  // Address: either completely blank, or must have line 1 AND postcode
  const address1 = (payload.address_line1 || '').trim();
  const address2 = (payload.address_line2 || '').trim();
  const address3 = (payload.address_line3 || '').trim();
  const town     = (payload.town_city     || '').trim();
  const county   = (payload.county        || '').trim();
  const postcode = (payload.postcode      || '').trim();

  const anyAddress = address1 || address2 || address3 || town || county || postcode;
  if (anyAddress) {
    if (!address1) {
      ok = false;
      markFieldError(root, 'address_line1', 'Address line 1 is required when an address is entered');
    }
    if (!postcode) {
      ok = false;
      markFieldError(root, 'postcode', 'Postcode is required when an address is entered');
    }
  }

  return ok;
}

// === Client main tab validation ==========================================

function validateClientMain(payload) {
  const root = document.querySelector('#tab-main, #clientSettingsForm');
  if (!root) return true;

  clearFieldErrors(root);
  let ok = true;

  const name = (payload.name || '').trim();
  if (!name) {
    ok = false;
    markFieldError(root, 'name', 'Client name is required');
  }

  // Primary invoice email is optional. Existing clients may legitimately have no
  // contact details yet, and that must not block an unrelated Client settings save.
  // When supplied, still reject malformed addresses.
  const emailRaw = (payload.primary_invoice_email || '').trim();
  if (emailRaw) {
    const emailPattern = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
    if (!emailPattern.test(emailRaw)) {
      ok = false;
      markFieldError(root, 'primary_invoice_email', 'Please enter a valid invoice email');
    }
  }

  // A/P phone: blank OR an ordinary formatted telephone number with >= 8 digits.
  const apPhoneRaw = (payload.ap_phone || '').trim();
  if (apPhoneRaw) {
    const digits = apPhoneRaw.replace(/\D/g, '');
    if (!/^[+\d\s().-]+$/.test(apPhoneRaw) || digits.length < 8) {
      ok = false;
      markFieldError(root, 'ap_phone', 'A/P phone must be a valid telephone number with at least 8 digits if entered');
    }
  }

  return ok;
}





async function restoreGridPrefsToDefault(section) {
  try {
    const res = await authFetch(API('/api/users/me/grid-prefs'), {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ section, reset: true })
    });
    const prefs = await res.json().catch(() => null);
    if (prefs && typeof prefs === 'object' && prefs.grid) {
      window.__gridPrefs = prefs;
    } else {
      window.__gridPrefs = prefs || { grid: {} };
    }

    await loadUserGridPrefs(section);
    const data = await loadSection();
    renderSummary(data);
  } catch (e) {
    console.error('[GRID] restoreGridPrefsToDefault failed', e);
  }
}
// FRONTEND — attachHeaderContextMenu
function attachHeaderContextMenu(section, tables) {
  const headTable = (tables && tables.head) ? tables.head : tables;
  const bodyTable = (tables && tables.body) ? tables.body : tables;

  let menu = document.createElement('div');
  menu.style.cssText =
    'position:fixed;z-index:10000;background:#0b1528;border:1px solid var(--line);' +
    'padding:6px;border-radius:8px;display:none;min-width:220px;';
  document.body.appendChild(menu);

  const hide = () => { menu.style.display = 'none'; };
  document.addEventListener('click', hide);
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') hide(); });

  const mkItem = (label, cb) => {
    const it = document.createElement('div');
    it.textContent = label;
    it.style.cssText = 'padding:6px 10px;cursor:pointer;';
    it.addEventListener('click', () => { hide(); cb && cb(); });
    it.addEventListener('mouseover', () => { it.style.background = '#101c36'; });
    it.addEventListener('mouseout',  () => { it.style.background = 'transparent'; });
    return it;
  };

  const ensureSectionPrefs = () => {
    if (!window.__gridPrefs || typeof window.__gridPrefs !== 'object') {
      window.__gridPrefs = { grid: {} };
    }
    if (!window.__gridPrefs.grid || typeof window.__gridPrefs.grid !== 'object') {
      window.__gridPrefs.grid = {};
    }
    const g = window.__gridPrefs.grid;
    g[section] = g[section] || {};
    g[section].columns = g[section].columns || {};
    return g[section];
  };

  const resetAllWidths = () => {
    const sec = ensureSectionPrefs();
    const cols = { ...(sec.columns || {}) };
    Object.keys(cols).forEach((k) => {
      if ('width' in cols[k]) delete cols[k].width;
    });

    if (headTable) {
      headTable.querySelectorAll('thead th[data-col-key]').forEach((th) => {
        th.style.width = '';
      });
    }
    if (bodyTable) {
      bodyTable.querySelectorAll('tbody td[data-col-key]').forEach((td) => {
        td.style.width = '';
      });
    }

    saveUserGridPrefsDebounced(section, { columns: cols }, true);
  };

  const autoWidthThisColumn = (colKey) => {
    if (!headTable) return;
    const th = headTable.querySelector(`thead th[data-col-key="${CSS.escape(colKey)}"]`);
    if (!th) return;

    const cells = bodyTable
      ? bodyTable.querySelectorAll(`tbody td[data-col-key="${CSS.escape(colKey)}"]`)
      : [];

    const measure = (el) => Math.ceil(el.scrollWidth) + 16;
    let maxW = measure(th);
    cells.forEach((td) => { maxW = Math.max(maxW, measure(td)); });

    const w = Math.max(80, Math.min(600, maxW));
    th.style.width = `${w}px`;
    cells.forEach((td) => { td.style.width = `${w}px`; });

    const sec = ensureSectionPrefs();
    const cols = { ...(sec.columns || {}) };
    cols[colKey] = { ...(cols[colKey] || {}), width: w };
    saveUserGridPrefsDebounced(section, { columns: cols }, true);
  };

  if (!headTable) return;

  headTable.addEventListener('contextmenu', (ev) => {
    const th = ev.target && ev.target.closest('th');
    if (!th || !th.dataset || !th.dataset.colKey) return;
    ev.preventDefault();

    const colKey = th.dataset.colKey;
    menu.innerHTML = '';

    // Restore full layout for this section from backend defaults
    menu.appendChild(
      mkItem('Restore layout to default', () => {
        restoreGridPrefsToDefault(section);
      })
    );

    // Reset only widths for this section
    menu.appendChild(
      mkItem('Reset View (Auto widths)', () => resetAllWidths())
    );

    const hr = document.createElement('hr');
    hr.style.border = '1px solid var(' + '--line' + ')';
    menu.appendChild(hr);

    menu.appendChild(
      mkItem('Auto-size this column', () => autoWidthThisColumn(colKey))
    );

    menu.appendChild(
      mkItem('Reset this column width', () => {
        th.style.width = '';
        if (bodyTable) {
          bodyTable
            .querySelectorAll(`tbody td[data-col-key="${CSS.escape(colKey)}"]`)
            .forEach(td => { td.style.width = ''; });
        }

        const sec = ensureSectionPrefs();
        const cols = { ...(sec.columns || {}) };
        if (cols[colKey]) delete cols[colKey].width;
        saveUserGridPrefsDebounced(section, { columns: cols }, true);
      })
    );

    menu.appendChild(
      mkItem('Hide column', async () => {
        const sec = ensureSectionPrefs();
        const cols = { ...(sec.columns || {}) };
        cols[colKey] = { ...(cols[colKey] || {}), visible: false };
        await saveUserGridPrefsDebounced(section, { columns: cols }, true);
        const data = await loadSection();
        renderSummary(data);
      })
    );

    menu.appendChild(
      mkItem('Columns…', () => openColumnsDialog(section))
    );

    // Position the context menu
    menu.style.left = `${ev.clientX}px`;
    menu.style.top  = `${ev.clientY}px`;
    menu.style.display = 'block';
  });
}

function openColumnsDialog(section) {
  const rootPrefs =
    (window.__gridPrefs &&
     window.__gridPrefs.grid &&
     window.__gridPrefs.grid[section]) || {};

  const colPrefs  = rootPrefs.columns      || {};
  const userMeta  = rootPrefs.columns_meta || {};
  const globalMeta = (typeof GRID_COLUMN_META_DEFAULTS === 'object' && GRID_COLUMN_META_DEFAULTS[section]) || {};

  const mergeMetaFor = (key) => ({
    ...(globalMeta[key] || {}),
    ...(userMeta[key]   || {})
  });

  const useFriendly = (rootPrefs.use_friendly_labels !== false);
  const labels      = rootPrefs.labels || {};

  // Build master key list: visible columns, defaults, current row keys
  const known = new Set(
    getVisibleColumnsForSection(section, currentRows).concat(defaultColumnsFor(section))
  );
  if (Array.isArray(currentRows) && currentRows[0]) {
    Object.keys(currentRows[0]).forEach(k => known.add(k));
  }

  // Filter out columns that are globally/user marked selectable:false
  const list = Array.from(known).filter(k => {
    const meta = mergeMetaFor(k);
    return meta.selectable !== false;
  });

  const overlay = document.createElement('div');
  overlay.style.cssText =
    'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:10000;' +
    'display:flex;align-items:center;justify-content:center;';
  const modal = document.createElement('div');
  modal.style.cssText =
    'background:#0b152a;border:1px solid var(--line);border-radius:10px;' +
    'min-width:480px;max-width:80vw;max-height:80vh;overflow:auto;padding:14px;';
  overlay.appendChild(modal);

  const title = document.createElement('div');
  title.textContent = `Columns — ${section}`;
  title.style.cssText = 'font-weight:600;margin-bottom:10px;';
  modal.appendChild(title);

  // Friendly labels toggle
  const lblWrap = document.createElement('label');
  const lblCb = document.createElement('input');
  lblCb.type = 'checkbox';
  lblCb.checked = useFriendly;
  lblWrap.appendChild(lblCb);
  lblWrap.appendChild(document.createTextNode(' Use friendly header labels'));
  lblWrap.style.cssText = 'display:flex;align-items:center;gap:8px;margin-bottom:8px;font-size:12px;';
  modal.appendChild(lblWrap);

  lblCb.addEventListener('change', () => {
    saveUserGridPrefsDebounced(section, { use_friendly_labels: !!lblCb.checked });
  });

  // Table: Visible + Column key + Display name + Order
  const t = document.createElement('table');
  t.style.cssText = 'width:100%;border-collapse:collapse;font-size:12px;';
  t.innerHTML = `
    <thead>
      <tr>
        <th style="text-align:left;padding:6px;border-bottom:1px solid var(--line)">Visible</th>
        <th style="text-align:left;padding:6px;border-bottom:1px solid var(--line)">Column key</th>
        <th style="text-align:left;padding:6px;border-bottom:1px solid var(--line)">Display name</th>
        <th style="text-align:left;padding:6px;border-bottom:1px solid var(--line)">Order</th>
      </tr>
    </thead>
    <tbody></tbody>
  `;
  modal.appendChild(t);
  const tb = t.querySelector('tbody');

  const orderOf = (k) => {
    const cp = colPrefs[k];
    if (cp && typeof cp.order === 'number') return cp.order;
    const idx = defaultColumnsFor(section).indexOf(k);
    return (idx >= 0 ? idx : 9999);
  };

  const rowsModel = list
    .map(k => ({
      key: k,
      visible: (colPrefs[k]?.visible !== false),
      label: labels[k] || k,
      order: orderOf(k)
    }))
    .sort((a, b) => a.order - b.order);

  const persist = () => {
    const columns   = {};
    const labelsOut = {};
    const metaOut   = { ...(rootPrefs.columns_meta || {}) }; // carry existing meta

    rowsModel.forEach((r, idx) => {
      columns[r.key] = { visible: !!r.visible, order: r.order };
      labelsOut[r.key] = String(r.label || r.key);
    });

    saveUserGridPrefsDebounced(section, {
      columns,
      labels: labelsOut,
      columns_meta: metaOut,
      use_friendly_labels: !!lblCb.checked
    });
  };

  const reindex = () => {
    rowsModel.forEach((r, i) => { r.order = i; });
    persist();
    refresh();
  };

  const refresh = () => {
    tb.innerHTML = '';
    rowsModel.sort((a, b) => a.order - b.order).forEach(r => {
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td style="padding:6px"><input type="checkbox" ${r.visible ? 'checked' : ''}></td>
        <td style="padding:6px;font-family:monospace">${r.key}</td>
        <td style="padding:6px"><input type="text" style="width:100%;background:#000;border:1px solid var(--line);color:var(--text);border-radius:6px;padding:4px 8px;font-size:12px;"></td>
        <td style="padding:6px;white-space:nowrap">
          <button class="btn mini" data-move="up">▲</button>
          <button class="btn mini" data-move="down">▼</button>
        </td>
      `;

      const elVisible = tr.querySelector('td:nth-child(1) input');
      const elLabel   = tr.querySelector('td:nth-child(3) input');
      const btnUp     = tr.querySelector('button[data-move="up"]');
      const btnDown   = tr.querySelector('button[data-move="down"]');

      elLabel.value = r.label;

      elVisible.addEventListener('change', () => {
        r.visible = !!elVisible.checked;
        persist();
      });

      elLabel.addEventListener('change', () => {
        r.label = elLabel.value;
        persist();
      });

      btnUp.addEventListener('click', () => {
        const i = rowsModel.indexOf(r);
        if (i > 0) {
          [rowsModel[i - 1], rowsModel[i]] = [rowsModel[i], rowsModel[i - 1]];
          reindex();
        }
      });

      btnDown.addEventListener('click', () => {
        const i = rowsModel.indexOf(r);
        if (i >= 0 && i < rowsModel.length - 1) {
          [rowsModel[i + 1], rowsModel[i]] = [rowsModel[i], rowsModel[i - 1]];
          reindex();
        }
      });

      tb.appendChild(tr);
    });
  };

  refresh();

  // Footer: Reset widths + Close
  const footer = document.createElement('div');
  footer.style.cssText = 'display:flex;justify-content:space-between;gap:8px;margin-top:10px;';
  const left  = document.createElement('div');
  const right = document.createElement('div');
  footer.appendChild(left);
  footer.appendChild(right);

  const btnResetWidths = document.createElement('button');
  btnResetWidths.textContent = 'Reset all widths';
  btnResetWidths.className = 'btn mini';
  btnResetWidths.addEventListener('click', () => {
    const prefsRoot =
      (window.__gridPrefs &&
       window.__gridPrefs.grid &&
       window.__gridPrefs.grid[section]) || {};

    const cols = { ...(prefsRoot.columns || {}) };
    Object.keys(cols).forEach(k => { if ('width' in cols[k]) delete cols[k].width; });
    saveUserGridPrefsDebounced(section, { columns: cols });
  });
  left.appendChild(btnResetWidths);

  const btnClose = document.createElement('button');
  btnClose.textContent = 'Close';
  btnClose.className = 'btn mini';
  btnClose.addEventListener('click', async () => {
    document.body.removeChild(overlay);
    const data = await loadSection();
    renderSummary(data);
  });
  right.appendChild(btnClose);

  modal.appendChild(footer);
  document.body.appendChild(overlay);
}


function loadSession(){
  try {
    const raw = localStorage.getItem('cloudtms.session') || sessionStorage.getItem('cloudtms.session');
    const sess = raw ? JSON.parse(raw) : null;
    if (!sess || !sess.accessToken) return false;
    saveSession(sess);             // mirrors globals & schedules refresh
    return true;
  } catch { return false; }
}


// Get label honoring section prefs toggle and overrides
function getFriendlyHeaderLabel(section, key) {
  const prefs = (window.__gridPrefs && window.__gridPrefs.grid && window.__gridPrefs.grid[section]) || {};
  const useFriendly = prefs.use_friendly_labels !== false; // default ON
  if (!useFriendly) return key;

  const overrides = prefs.labels || {};
  const def = (DEFAULT_COLUMN_LABELS[section] || {});
  const hit = overrides[key] || def[key];
  if (hit) return hit;

  const k = String(key || '');
  if (k.includes('_')) {
    const raw = k.replace(/_/g, ' ').toLowerCase();
    const tc = raw.replace(/\b\w/g, (c) => c.toUpperCase());
    return tc
      .replace(/\bNhsp\b/g, 'NHSP')
      .replace(/\bHr\b/g, 'HR')
      .replace(/\bNhs\b/g, 'NHS')
      .replace(/\bVat\b/g, 'VAT');
  }

  return k;
}


// ─────────────────────────────────────────────────────────────────────────────
// UPDATED: loadSection()
// - After loading the visible page, triggers background priming of membership
//   (ALL matching ids for current filters) regardless of page size.
// ─────────────────────────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────────────────────────
// UPDATED: loadSection()
// - Ensures grid prefs are loaded
// - Defaults Contracts status quick filter to "active"
// - After loading the visible page, triggers background priming of membership
//   (ALL matching ids for current filters) regardless of page size.
// ─────────────────────────────────────────────────────────────────────────────

async function loadSection() {
  const gl = beginGlobalLoading('Loading list…');

  try {
    const sectionKey = String(currentSection || '').trim().toLowerCase();

    window.__listState = window.__listState || {};
    const st = (window.__listState[sectionKey] ||= {
      page: 1,
      pageSize: 50,
      total: null,
      hasMore: false,
      filters: null,
      sort: { key: null, dir: 'asc' }
    });

    const continuousSummary = window.CloudTMSSummaryContinuousGrid || null;
    const isContinuousSummary = !!(
      continuousSummary &&
      typeof continuousSummary.isEnabled === 'function' &&
      continuousSummary.isEnabled(sectionKey)
    );
    if (isContinuousSummary) {
      st.pageSize = Number(continuousSummary.DEFAULT_PAGE_SIZE || 50);
      st.page = Math.max(1, Number(st.page || 1));
    }

    if (!st.sort || typeof st.sort !== 'object') {
      st.sort = { key: null, dir: 'asc' };
    }


    const getPayBatchFilterId = (filters) => {
      if (!filters || typeof filters !== 'object' || Array.isArray(filters)) return '';
      return String(
        filters.pay_batch_id ||
        filters.payBatchId ||
        filters.batch_id ||
        filters.batchId ||
        ''
      ).trim();
    };

    const isBankingPayBatchTimesheetShortcutView = () => {
      const state = (window.__listState && window.__listState.timesheets && typeof window.__listState.timesheets === 'object')
        ? window.__listState.timesheets
        : st;
      return !!(
        sectionKey === 'timesheets' &&
        state &&
        typeof state === 'object' &&
        getPayBatchFilterId(state.filters) &&
        (
          state.__openedFromBankingPayBatchShortcut === true ||
          state.openedFromBankingPayBatchShortcut === true
        )
      );
    };

    if (isBankingPayBatchTimesheetShortcutView() && String(st.pageSize || '').trim().toUpperCase() === 'ALL') {
      st.pageSize = 50;
    }

    const clonePlain = (value) => {
      if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
      try {
        return JSON.parse(JSON.stringify(value));
      } catch {
        const out = {};
        Object.keys(value).forEach((key) => {
          out[key] = value[key];
        });
        return out;
      }
    };

    const OMIT = Symbol('omit-empty-array');
    const normalizeDatasetKey = (rawValue) => {
      const normalizeValue = (value) => {
        if (Array.isArray(value)) {
          const normalizedArray = value
            .map(normalizeValue)
            .filter((item) => item !== OMIT);
          return normalizedArray.length ? normalizedArray : OMIT;
        }

        if (value && typeof value === 'object') {
          const normalizedObject = {};
          Object.keys(value)
            .sort()
            .forEach((key) => {
              const normalizedChild = normalizeValue(value[key]);
              if (normalizedChild !== OMIT) {
                normalizedObject[key] = normalizedChild;
              }
            });
          return normalizedObject;
        }

        return value;
      };

      const rawString = String(rawValue == null ? '' : rawValue).trim();
      if (!rawString) return '';

      try {
        return JSON.stringify(normalizeValue(JSON.parse(rawString)));
      } catch {
        return rawString;
      }
    };

    const liveTypeAheadState = (
      window.__summaryTypeAheadState &&
      window.__summaryTypeAheadState[sectionKey] &&
      typeof window.__summaryTypeAheadState[sectionKey] === 'object'
    )
      ? window.__summaryTypeAheadState[sectionKey]
      : null;

    const typeAheadSortKey = String(liveTypeAheadState && liveTypeAheadState.sort_key || '').trim();
    const typeAheadSortDir = String(liveTypeAheadState && liveTypeAheadState.sort_dir || 'asc').trim().toLowerCase() === 'desc' ? 'desc' : 'asc';

    if ((!st.sort.key || !String(st.sort.key).trim()) && typeAheadSortKey) {
      st.sort = {
        key: typeAheadSortKey,
        dir: typeAheadSortDir
      };
    }

    const summaryMembershipSections = new Set([
      'candidates',
      'clients',
      'umbrellas',
      'contracts',
      'timesheets',
      'invoices',
      'outbox'
    ]);

    const related = (st.filters && typeof st.filters === 'object' && st.filters.related && typeof st.filters.related === 'object')
      ? st.filters.related
      : null;

    const inRelatedMode =
      !!related &&
      String(related.source_entity || '').trim() &&
      String(related.source_id || '').trim() &&
      String(related.relation_type || '').trim();

    if (!inRelatedMode && sectionKey === 'contracts') {
      if (!st.filters || typeof st.filters !== 'object') st.filters = {};
      if (!('status' in st.filters) || !st.filters.status) {
        st.filters.status = 'active';
      }
    }

    if (!inRelatedMode && sectionKey === 'umbrellas' && !st._umbrellasFilterInitDone) {
      const currentFilters = (st.filters && typeof st.filters === 'object')
        ? { ...st.filters }
        : {};
      if (!Object.prototype.hasOwnProperty.call(currentFilters, 'enabled')) {
        currentFilters.enabled = true;
      }
      st.filters = currentFilters;
      st._umbrellasFilterInitDone = true;
    }

    if (!inRelatedMode && sectionKey === 'invoices') {
      if (!st.filters || typeof st.filters !== 'object') st.filters = {};
      const cur = st.filters.status;
      const hasStatus =
        (Array.isArray(cur) && cur.length > 0) ||
        (typeof cur === 'string' && cur.trim().length > 0);
      if (!hasStatus) {
        st.filters.status = ['DRAFT','ON_HOLD','ISSUED','PAID'];
      }
    }

    await loadUserGridPrefs(sectionKey);


    if (isBankingPayBatchTimesheetShortcutView() && String(st.pageSize || '').trim().toUpperCase() === 'ALL') {
      st.pageSize = 50;
    }

    if ((!st.sort || !st.sort.key || !String(st.sort.key).trim()) && typeAheadSortKey) {
      st.sort = {
        key: typeAheadSortKey,
        dir: typeAheadSortDir
      };
    }

    const datasetKey = (() => {
      try {
        return String(getSummaryFingerprint(sectionKey) || '').trim();
      } catch {
        return '';
      }
    })();

    const normalizedDatasetKey = normalizeDatasetKey(datasetKey);

    const normalizedSort = {
      key: st.sort && st.sort.key ? String(st.sort.key) : null,
      dir: (st.sort && st.sort.dir === 'desc') ? 'desc' : 'asc'
    };

    const viewKey = JSON.stringify({
      section: sectionKey,
      dataset_key: datasetKey,
      page: Number(st.page || 1),
      pageSize: (st.pageSize === 'ALL') ? 'ALL' : Number(st.pageSize || 50),
      sort: normalizedSort
    });

    const prevDatasetKey = String(st.__lastSelectionDatasetKey || '').trim();
    const normalizedPrevDatasetKey = normalizeDatasetKey(prevDatasetKey);
    const prevViewKey = String(st.__lastSelectionViewKey || '').trim();

   if (typeof resetSelectionForDataset === 'function') {
      if (!normalizedPrevDatasetKey || normalizedPrevDatasetKey !== normalizedDatasetKey) {
        resetSelectionForDataset(sectionKey, datasetKey, 'dataset-changed');
      } else {
        const sel = ensureSelection(sectionKey);
        sel.dataset_key = datasetKey;
        sel.fingerprint = datasetKey;

        if (!(sel.included_ids instanceof Set)) sel.included_ids = new Set();
        if (!(sel.excluded_ids instanceof Set)) sel.excluded_ids = new Set();
        if (!(sel.ids instanceof Set)) sel.ids = new Set(Array.from(sel.included_ids));

        if (prevViewKey && prevViewKey !== viewKey) {
          sel.anchor_row_id = '';
          sel.anchor_view_key = '';
          sel.anchor_fingerprint = datasetKey;
        }
      }
    } else {
      const sel = ensureSelection(sectionKey);
      sel.dataset_key = datasetKey;
      sel.fingerprint = datasetKey;
    }

    const syncSelectionMembershipState = () => {
      if (typeof ensureSelection !== 'function') return null;

      const sel = ensureSelection(sectionKey);
      sel.dataset_key = datasetKey;
      sel.fingerprint = datasetKey;

      if (!summaryMembershipSections.has(sectionKey)) {
        return sel;
      }
const selectionMode = String(sel.mode || 'explicit').trim().toLowerCase() === 'all_filtered'
        ? 'all_filtered'
        : 'explicit';

      const previousAuthoritativeTotal = (
        sel.membership_authoritative === true &&
        Number.isFinite(Number(sel.membership_total)) &&
        Number(sel.membership_total) > 0
      )
        ? Number(sel.membership_total)
        : null;

      const previousFallbackTotal = (
        Number.isFinite(Number(sel.membership_fallback_total)) &&
        Number(sel.membership_fallback_total) > 0
      )
        ? Number(sel.membership_fallback_total)
        : null;

      const previousKnownPositiveTotal = (() => {
        const candidates = [previousAuthoritativeTotal, previousFallbackTotal]
          .filter((value) => Number.isFinite(Number(value)) && Number(value) > 0)
          .map(Number);
        return candidates.length ? Math.max(...candidates) : null;
      })();

      if (selectionMode !== 'all_filtered') {
        sel.membership_total = null;
        sel.membership_status = 'none';
        sel.membership_source = 'none';
        sel.membership_authoritative = false;
        sel.membership_fallback_total = null;
        return sel;
      }

      let membership = null;
      try {
        if (typeof getSummaryMembership === 'function') {
          membership = getSummaryMembership(sectionKey, datasetKey);
        }
      } catch {
        membership = null;
      }

      const membershipIds = Array.isArray(membership && membership.ids)
        ? membership.ids.map(v => String(v == null ? '' : v).trim()).filter(Boolean)
        : (Array.isArray(membership && membership.row_ids)
            ? membership.row_ids.map(v => String(v == null ? '' : v).trim()).filter(Boolean)
            : []);

      const membershipTotalRaw = Number(
        membership && (
          membership.total_count ??
          membership.total ??
          membership.count ??
          membership.row_count ??
          membershipIds.length
        )
      );

      const membershipDatasetKey = String(
        membership && (membership.dataset_key || datasetKey) || datasetKey
      ).trim();

      const normalizedMembershipDatasetKey = normalizeDatasetKey(membershipDatasetKey);

      const membershipCompleteCache = !!(
        membership &&
        normalizedDatasetKey &&
        normalizedMembershipDatasetKey &&
        normalizedMembershipDatasetKey === normalizedDatasetKey &&
        Number.isFinite(membershipTotalRaw) &&
        membershipTotalRaw >= 0 &&
        membershipIds.length === membershipTotalRaw &&
        (Array.isArray(membership.ids) || Array.isArray(membership.row_ids))
      );

      const membershipFresh = !!(
        membershipCompleteCache &&
        membership.stale === false
      );

      const membershipFreshPositive = !!(
        membershipFresh &&
        membershipTotalRaw > 0
      );

      const membershipFreshZero = !!(
        membershipFresh &&
        membershipTotalRaw === 0
      );

      const membershipFallbackUsable = !!(
        membershipCompleteCache &&
        membership.stale !== false &&
        membershipTotalRaw > 0
      );

      const resolvedMembershipState = (() => {
        if (membershipFreshPositive) {
          return {
            membership_total: membershipTotalRaw,
            membership_status: 'ready',
            membership_authoritative: true,
            membership_fallback_total: null
          };
        }

        if (membershipFreshZero && previousKnownPositiveTotal === null) {
          return {
            membership_total: 0,
            membership_status: 'ready',
            membership_authoritative: true,
            membership_fallback_total: null
          };
        }

        if (previousAuthoritativeTotal !== null) {
          return {
            membership_total: previousAuthoritativeTotal,
            membership_status: 'ready',
            membership_authoritative: true,
            membership_fallback_total: null
          };
        }

        if (membershipFallbackUsable) {
          return {
            membership_total: null,
            membership_status: 'fallback',
            membership_authoritative: false,
            membership_fallback_total: membershipTotalRaw
          };
        }

        if (previousFallbackTotal !== null) {
          return {
            membership_total: null,
            membership_status: 'fallback',
            membership_authoritative: false,
            membership_fallback_total: previousFallbackTotal
          };
        }

        return {
          membership_total: null,
          membership_status: 'pending',
          membership_authoritative: false,
          membership_fallback_total: null
        };
      })();

      sel.membership_total = resolvedMembershipState.membership_total;
      sel.membership_status = resolvedMembershipState.membership_status;
      sel.membership_source = 'summary_membership';
      sel.membership_authoritative = resolvedMembershipState.membership_authoritative;
      sel.membership_fallback_total = resolvedMembershipState.membership_fallback_total;
      return sel;
    };

   const getSelectionMembershipLoadStatus = (selState) => {
      if (!summaryMembershipSections.has(sectionKey)) {
        return 'n/a';
      }

      const safeSel = (selState && typeof selState === 'object') ? selState : {};
      const status = String(safeSel.membership_status || '').trim().toLowerCase();

      const authoritativeTotal = Number(safeSel.membership_total);
      const fallbackTotal = Number(safeSel.membership_fallback_total);
      const hasPositiveFallback = Number.isFinite(fallbackTotal) && fallbackTotal > 0;

      if (
        status === 'ready' &&
        safeSel.membership_authoritative === true &&
        Number.isFinite(authoritativeTotal)
      ) {
        if (authoritativeTotal > 0) {
          return 'ready';
        }

        if (authoritativeTotal === 0 && !hasPositiveFallback) {
          return 'ready';
        }
      }

      if (status === 'fallback' && hasPositiveFallback) {
        return 'fallback';
      }

      return 'pending';
    };

    const nextLoadGeneration = Math.max(1, Number(st.__summaryLoadGeneration || 0) + 1);
    st.__summaryLoadGeneration = nextLoadGeneration;

    window.__summaryLoadState = window.__summaryLoadState || {};
    window.__summaryLoadState[sectionKey] = {
      section: sectionKey,
      dataset_key: datasetKey,
      view_key: viewKey,
      generation: nextLoadGeneration,
      membership_status: summaryMembershipSections.has(sectionKey) ? 'pending' : 'n/a'
    };

    syncSelectionMembershipState();

    const hasFilters = !!st.filters && Object.keys(st.filters).length > 0;
    const hasSort    = !!(st.sort && st.sort.key);

    const useSearch =
      (sectionKey === 'candidates' ||
       sectionKey === 'contracts'  ||
       sectionKey === 'invoices'   ||
       sectionKey === 'clients'    ||
       sectionKey === 'umbrellas')
        ? true
        : (hasFilters || hasSort);

    const relatedListPromises = new Map();

    const fetchRelatedPage = async (section, page, pageSize, rel, options = {}) => {
      const suppressListStateMutation = !!(options && options.suppressListStateMutation);

      window.__listState = window.__listState || {};
      const stSec = (window.__listState[section] ||= {
        page: 1,
        pageSize: 50,
        total: null,
        hasMore: false,
        filters: null,
        sort: { key: null, dir: 'asc' }
      });

      if (!suppressListStateMutation) {
        stSec.page = page;
        stSec.pageSize = pageSize;
      }

      const srcEntity = String(rel.source_entity || '').trim();
      const srcId     = String(rel.source_id || '').trim();
      const relType   = String(rel.relation_type || '').trim();

      const requestedPageSize = pageSize === 'ALL'
        ? 100
        : Math.max(1, Math.min(100, Math.trunc(Number(pageSize || 50))));
      const requestedPage = Math.max(1, Math.trunc(Number(page || 1)));
      const requestedOffset = pageSize === 'ALL' ? 0 : (requestedPage - 1) * requestedPageSize;
      const requestKey = `${srcEntity}:${srcId}:${relType}:${requestedPageSize}:${requestedOffset}`;

      if (!relatedListPromises.has(requestKey)) {
        const request = Promise.resolve(fetchRelated(srcEntity, srcId, relType, {
          limit: requestedPageSize,
          offset: requestedOffset
        })).finally(() => relatedListPromises.delete(requestKey));
        relatedListPromises.set(requestKey, request);
      }
      const list = await relatedListPromises.get(requestKey);

      const items = Array.isArray(list?.items) ? list.items : (Array.isArray(list) ? list : []);
      const totalFromApi = (list && typeof list === 'object' && typeof list.total === 'number') ? list.total : null;

      if (section === 'invoices') {
        const idsAll = [];
        try {
          (items || []).forEach(it => {
            if (!it || typeof it !== 'object') return;
            const id = it.id ?? it.invoice_id ?? null;
            if (id != null) idsAll.push(String(id));
          });
        } catch {}

        const seen = new Set();
        const idsDedup = [];
        for (const id of idsAll) {
          const s = String(id || '').trim();
          if (!s || seen.has(s)) continue;
          seen.add(s);
          idsDedup.push(s);
        }

        const total = (typeof totalFromApi === 'number') ? totalFromApi : idsDedup.length;
        stSec.total = total;

        stSec.hasMore = (requestedOffset + idsDedup.length) < total;

        const pageIds = idsDedup;

        if (!pageIds.length) return [];

        const canon = await search('invoices', { ids: pageIds });
        const canonRows = Array.isArray(canon?.rows) ? canon.rows : (Array.isArray(canon) ? canon : []);

        const byId = new Map();
        canonRows.forEach(r => {
          const rid = r && (r.id ?? r.invoice_id);
          if (rid != null) byId.set(String(rid), r);
        });

        const ordered = [];
        pageIds.forEach(id => {
          const row = byId.get(String(id)) || null;
          if (row) ordered.push(row);
        });

        if (ordered.length !== canonRows.length) {
          canonRows.forEach(r => {
            const rid = r && (r.id ?? r.invoice_id);
            const k = (rid != null) ? String(rid) : '';
            if (!k) return;
            if (!ordered.includes(r)) ordered.push(r);
          });
        }

        return ordered;
      }

      const total = (typeof totalFromApi === 'number') ? totalFromApi : items.length;
      stSec.total = total;

      const pageItems = items;
      stSec.hasMore = (requestedOffset + pageItems.length) < total;

      return pageItems;
    };

    const fetchOutboxPage = async (page, pageSize, options = {}) => {
      const suppressListStateMutation = !!(options && options.suppressListStateMutation);

      const stOut = (window.__listState['outbox'] ||= {
        page: 1,
        pageSize: 50,
        total: null,
        hasMore: false,
        filters: null,
        sort: { key: null, dir: 'asc' }
      });

      if (!suppressListStateMutation) {
        stOut.page = page;
        stOut.pageSize = pageSize;
      }

      const filters = (stOut.filters && typeof stOut.filters === 'object') ? stOut.filters : {};
      const sort = (stOut.sort && typeof stOut.sort === 'object') ? stOut.sort : { key: null, dir: 'asc' };

      const pageNum = Math.max(1, Number(page || 1));
      const pageSizeNum = (pageSize === 'ALL') ? 200 : Math.max(1, Number(pageSize || 50));
      const limit = Math.min(500, pageSizeNum);
      const offset = Math.max(0, (pageNum - 1) * pageSizeNum);

      const res = await apiListOutbox({
        limit,
        offset,
        search: String(filters.search || filters.q || '').trim(),
        channel: String(filters.channel || '').trim(),
        queue_state: String(filters.queue_state || '').trim(),
        status: filters.status,
        sort_by: String(sort.key || ''),
        sort_dir: sort.dir === 'desc' ? 'desc' : 'asc'
      });

      const rows = Array.isArray(res && res.items) ? res.items : [];
      const total = (res && typeof res.total_count === 'number' && Number.isFinite(res.total_count))
        ? Number(res.total_count)
        : null;

      stOut.total = total;

      if (typeof stOut.total === 'number') {
        stOut.hasMore = (offset + rows.length) < stOut.total;
      } else {
        stOut.hasMore = Array.isArray(rows) && rows.length === limit;
      }

      return rows;
    };

    const fetchAuditEventsPage = async (page, pageSize, options = {}) => {
      const suppressListStateMutation = !!(options && options.suppressListStateMutation);

      const stAudit = (window.__listState['audit'] ||= {
        page: 1,
        pageSize: 50,
        total: null,
        hasMore: false,
        filters: null,
        sort: { key: null, dir: 'asc' }
      });

      if (!suppressListStateMutation) {
        stAudit.page = page;
        stAudit.pageSize = pageSize;
      }

      const filters = (stAudit.filters && typeof stAudit.filters === 'object') ? stAudit.filters : {};
      const sort = (stAudit.sort && typeof stAudit.sort === 'object') ? stAudit.sort : { key: null, dir: 'asc' };

      const pageNum = Math.max(1, Number(page || 1));
      const pageSizeNum = (pageSize === 'ALL') ? 200 : Math.max(1, Number(pageSize || 50));
      const limit = Math.min(500, pageSizeNum);
      const offset = Math.max(0, (pageNum - 1) * pageSizeNum);

      const res = await apiListAuditEvents({
        limit,
        offset,
        search: String(filters.search || filters.q || '').trim(),
        action: String(filters.action || '').trim(),
        object_type: String(filters.object_type || filters.objectType || '').trim(),
        actor_display: String(filters.actor_display || filters.actor || '').trim(),
        sort_by: String(sort.key || 'ts_utc'),
        sort_dir: sort.dir === 'asc' ? 'asc' : 'desc'
      });

      const rows = Array.isArray(res && res.items) ? res.items : [];
      const total = (res && typeof res.total_count === 'number' && Number.isFinite(res.total_count))
        ? Number(res.total_count)
        : null;

      stAudit.total = total;

      if (typeof stAudit.total === 'number') {
        stAudit.hasMore = (offset + rows.length) < stAudit.total;
      } else {
        stAudit.hasMore = Array.isArray(rows) && rows.length === limit;
      }

      return rows;
    };

    const fetchOne = async (section, page, pageSize, options = {}) => {
      const suppressListStateMutation = !!(options && options.suppressListStateMutation);
      const stSection = (window.__listState[section] ||= {
        page: 1,
        pageSize: 50,
        total: null,
        hasMore: false,
        filters: null,
        sort: { key: null, dir: 'asc' }
      });

      const prevPage = stSection.page;
      const prevPageSize = stSection.pageSize;

      if (!suppressListStateMutation) {
        stSection.page = page;
        stSection.pageSize = pageSize;
      }

      try {
        if (inRelatedMode) {
          return await fetchRelatedPage(section, page, pageSize, related, options);
        }

        if (section === 'timesheets') {
          if (suppressListStateMutation) {
            stSection.page = page;
            stSection.pageSize = pageSize;
            try {
              return await listTimesheetsSummary(stSection.filters || {});
            } finally {
              stSection.page = prevPage;
              stSection.pageSize = prevPageSize;
            }
          }
          return await listTimesheetsSummary(stSection.filters || {});
        }

        if (section === 'outbox') {
          return await fetchOutboxPage(page, pageSize, options);
        }

        if (section === 'audit') {
          return await fetchAuditEventsPage(page, pageSize, options);
        }

        if (useSearch) {
            const searchOptions = {
            pageOverride: page,
            pageSizeOverride: pageSize,
            sortOverride: clonePlain(
              (stSection.sort && typeof stSection.sort === 'object')
                ? stSection.sort
                : {}
            ),
            suppressSelectionReset: true
          };

          if (suppressListStateMutation) {
            stSection.page = page;
            stSection.pageSize = pageSize;
            try {
              return await search(section, stSection.filters || {}, searchOptions);
            } finally {
              stSection.page = prevPage;
              stSection.pageSize = prevPageSize;
            }
          }
          return await search(section, stSection.filters || {}, searchOptions);
        } else {
          switch (section) {
            case 'candidates': return await listCandidates();
            case 'clients':    return await listClients();
            case 'umbrellas':  return await listUmbrellas();
            case 'settings':   return await getSettings();
            default:           return [];
          }
        }
      } finally {
        if (suppressListStateMutation && section !== 'timesheets' && section !== 'outbox' && section !== 'audit' && !useSearch && !inRelatedMode) {
          stSection.page = prevPage;
          stSection.pageSize = prevPageSize;
        } else if (suppressListStateMutation && inRelatedMode) {
          stSection.page = prevPage;
          stSection.pageSize = prevPageSize;
        } else if (suppressListStateMutation && (section === 'outbox' || section === 'audit')) {
          stSection.page = prevPage;
          stSection.pageSize = prevPageSize;
        }
      }
    };

    const queueMembershipPrime = () => {
      if (!summaryMembershipSections.has(sectionKey)) {
        window.__summaryLoadState = window.__summaryLoadState || {};
        if (window.__summaryLoadState[sectionKey]) {
          window.__summaryLoadState[sectionKey] = {
            ...window.__summaryLoadState[sectionKey],
            membership_status: 'n/a'
          };
        }
        return;
      }

      if (isBankingPayBatchTimesheetShortcutView()) {
        window.__summaryLoadState = window.__summaryLoadState || {};
        if (window.__summaryLoadState[sectionKey]) {
          window.__summaryLoadState[sectionKey] = {
            ...window.__summaryLoadState[sectionKey],
            membership_status: 'deferred'
          };
        }

        try {
          if (typeof ensureSelection === 'function') {
            const sel = ensureSelection(sectionKey);
            if (sel && typeof sel === 'object') {
              sel.dataset_key = datasetKey;
              sel.fingerprint = datasetKey;
              sel.membership_total = null;
              sel.membership_status = 'deferred';
              sel.membership_source = 'banking_pay_batch_shortcut';
              sel.membership_authoritative = false;
              sel.membership_fallback_total = null;
            }
          }
        } catch {}
        return;
      }

      void (async () => {
        try {
          await primeSummaryMembership(sectionKey, datasetKey);
        } catch {}
        try {
          const liveSectionKey = String(currentSection || '').trim().toLowerCase();
          const liveState = window.__summaryLoadState && window.__summaryLoadState[sectionKey]
            ? window.__summaryLoadState[sectionKey]
            : null;
          const liveListState = window.__listState && window.__listState[sectionKey]
            ? window.__listState[sectionKey]
            : null;

          if (!liveState || !liveListState) return;
          if (Number(liveState.generation || 0) !== nextLoadGeneration) return;
          if (Number(liveListState.__summaryLoadGeneration || 0) !== nextLoadGeneration) return;
          if (String(liveState.dataset_key || '').trim() !== datasetKey) return;
          if (normalizeDatasetKey(String(liveListState.__lastSelectionDatasetKey || '').trim()) !== normalizedDatasetKey) return;
          if (liveSectionKey !== sectionKey) return;

          const selAfterPrime = syncSelectionMembershipState();

          window.__summaryLoadState[sectionKey] = {
            ...window.__summaryLoadState[sectionKey],
            membership_status: getSelectionMembershipLoadStatus(selAfterPrime)
          };
        } catch {}
      })();
    };

    if (isContinuousSummary) {
      const continuousPageSize = Number(continuousSummary.DEFAULT_PAGE_SIZE || 50);
      st.pageSize = continuousPageSize;

      const controller = continuousSummary.configure({
        section: sectionKey,
        datasetKey,
        sortKey: normalizedSort.key || '',
        sortDir: normalizedSort.dir,
        pageSize: continuousPageSize,
        initialPage: st.page,
        total: st.total,
        fetchPage: (requestedPage, requestedPageSize) => fetchOne(
          sectionKey,
          requestedPage,
          requestedPageSize,
          { suppressListStateMutation: true }
        ),
        getTotal: () => window.__listState?.[sectionKey]?.total,
        onTargetPage: (targetPage) => {
          const liveState = window.__listState?.[sectionKey];
          if (liveState) liveState.page = Math.max(1, Number(targetPage || 1));
        },
        onRender: (view) => {
          if (!view || String(currentSection || '').trim().toLowerCase() !== sectionKey) return;
          let liveDatasetKey = '';
          try { liveDatasetKey = String(getSummaryFingerprint(sectionKey) || '').trim(); } catch {}
          if (liveDatasetKey !== datasetKey) return;
          renderSummary(Array.isArray(view.rows) ? view.rows : []);
        }
      });

      const continuousView = await controller.load(st.page);
      const rows = Array.isArray(continuousView?.rows) ? continuousView.rows : [];
      const page = Number(continuousView?.targetPage || st.page || 1);
      const continuousTotalRaw = continuousView?.total;
      const total = continuousTotalRaw == null ? null : Number(continuousTotalRaw);

      st.page = Math.max(1, page);
      st.pageSize = continuousPageSize;
      if (Number.isFinite(total) && total >= 0) st.total = total;
      st.hasMore = Number.isFinite(Number(st.total))
        ? ((st.page * continuousPageSize) < Number(st.total))
        : rows.length >= continuousPageSize;
      st.__lastSelectionDatasetKey = datasetKey;
      st.__lastSelectionViewKey = viewKey;
      st.__allRowsCache = null;

      const selAfterContinuousList = syncSelectionMembershipState();
      window.__summaryLoadState = window.__summaryLoadState || {};
      if (window.__summaryLoadState[sectionKey]) {
        window.__summaryLoadState[sectionKey] = {
          ...window.__summaryLoadState[sectionKey],
          membership_status: getSelectionMembershipLoadStatus(selAfterContinuousList)
        };
      }

      queueMembershipPrime();
      return rows;
    }

    if (st.pageSize === 'ALL') {
      const allRowsCacheKey = JSON.stringify({
        section: sectionKey,
        dataset_key: datasetKey,
        sort: normalizedSort
      });

      const cachedAllRows =
        st.__allRowsCache &&
        typeof st.__allRowsCache === 'object' &&
        String(st.__allRowsCache.cache_key || '') === allRowsCacheKey &&
        Array.isArray(st.__allRowsCache.rows)
          ? st.__allRowsCache.rows.slice()
          : null;

      if (cachedAllRows) {
        window.__listState[sectionKey].page = 1;
        window.__listState[sectionKey].pageSize = 'ALL';
        window.__listState[sectionKey].hasMore = false;
        window.__listState[sectionKey].total = cachedAllRows.length;
        window.__listState[sectionKey].__lastSelectionDatasetKey = datasetKey;
        window.__listState[sectionKey].__lastSelectionViewKey = JSON.stringify({
          section: sectionKey,
          dataset_key: datasetKey,
          page: 1,
          pageSize: 'ALL',
          sort: normalizedSort
        });

        const selAfterCachedList = syncSelectionMembershipState();
        window.__summaryLoadState = window.__summaryLoadState || {};
        if (window.__summaryLoadState[sectionKey]) {
          window.__summaryLoadState[sectionKey] = {
            ...window.__summaryLoadState[sectionKey],
            membership_status: getSelectionMembershipLoadStatus(selAfterCachedList)
          };
        }

        queueMembershipPrime();
        return cachedAllRows;
      }

      const acc = [];
      let p = 1;

      const transportChunkSize = inRelatedMode ? 100 : 200;

      let gotMore = true;
      while (gotMore) {
        const rows = await fetchOne(sectionKey, p, transportChunkSize, { suppressListStateMutation: true });
        acc.push(...(rows || []));

        if (inRelatedMode) {
          const total = window.__listState[sectionKey].total;
          if (typeof total === 'number') {
            gotMore = acc.length < total;
          } else {
            gotMore = Array.isArray(rows) && rows.length === transportChunkSize;
          }
        } else if (sectionKey === 'outbox' || sectionKey === 'audit') {
          const total = window.__listState[sectionKey].total;
          if (typeof total === 'number') {
            gotMore = acc.length < total;
          } else {
            gotMore = Array.isArray(rows) && rows.length === transportChunkSize;
          }
        } else {
          gotMore = Array.isArray(rows) && rows.length === transportChunkSize;
        }

        p += 1;
        if (!gotMore) break;
      }

      window.__listState[sectionKey].page = 1;
      window.__listState[sectionKey].pageSize = 'ALL';
      window.__listState[sectionKey].hasMore = false;
      window.__listState[sectionKey].total = acc.length;
      window.__listState[sectionKey].__allRowsCache = {
        cache_key: allRowsCacheKey,
        rows: acc.slice()
      };
      window.__listState[sectionKey].__lastSelectionDatasetKey = datasetKey;
      window.__listState[sectionKey].__lastSelectionViewKey = JSON.stringify({
        section: sectionKey,
        dataset_key: datasetKey,
        page: 1,
        pageSize: 'ALL',
        sort: normalizedSort
      });

      const selAfterList = syncSelectionMembershipState();
      window.__summaryLoadState = window.__summaryLoadState || {};
      if (window.__summaryLoadState[sectionKey]) {
        window.__summaryLoadState[sectionKey] = {
          ...window.__summaryLoadState[sectionKey],
          membership_status: getSelectionMembershipLoadStatus(selAfterList)
        };
      }

      queueMembershipPrime();
      return acc;
    }

    const page = Number(st.page || 1);
    const ps   = Number(st.pageSize || 50);

    const rows = await fetchOne(sectionKey, page, ps);

    if (!inRelatedMode && sectionKey !== 'outbox' && sectionKey !== 'audit') {
      const total = window.__listState[sectionKey].total;
      if (typeof total === 'number' && Number.isFinite(total)) {
        window.__listState[sectionKey].hasMore = (page * ps) < total;
      } else {
        window.__listState[sectionKey].hasMore = Array.isArray(rows) && rows.length === ps;
      }
    }

    window.__listState[sectionKey].__lastSelectionDatasetKey = datasetKey;
    window.__listState[sectionKey].__lastSelectionViewKey = viewKey;

    const currentAllCacheKey = JSON.stringify({
      section: sectionKey,
      dataset_key: datasetKey,
      sort: normalizedSort
    });

    if (
      !window.__listState[sectionKey].__allRowsCache ||
      typeof window.__listState[sectionKey].__allRowsCache !== 'object' ||
      String(window.__listState[sectionKey].__allRowsCache.cache_key || '') !== currentAllCacheKey
    ) {
      window.__listState[sectionKey].__allRowsCache = null;
    }

    const selAfterList = syncSelectionMembershipState();
    window.__summaryLoadState = window.__summaryLoadState || {};
    if (window.__summaryLoadState[sectionKey]) {
      window.__summaryLoadState[sectionKey] = {
        ...window.__summaryLoadState[sectionKey],
        membership_status: getSelectionMembershipLoadStatus(selAfterList)
      };
    }

    queueMembershipPrime();
    return rows;
  } finally {
    endGlobalLoading();
  }
}


const OFFICE_AUTH_REFRESH_INVALID_CODES = new Set([
  'REFRESH_COOKIE_MISSING',
  'REFRESH_TOKEN_INVALID',
  'REFRESH_CLAIMS_INVALID',
  'REFRESH_EXPIRED',
  'REFRESH_SESSION_MISSING',
  'REFRESH_USER_DISABLED',
  'REFRESH_SESSION_VERSION_CHANGED'
]);
const OFFICE_AUTH_REFRESH_RETRY_DELAYS_MS = Object.freeze([5_000, 15_000, 30_000, 60_000]);
let officeAuthRefreshRetryAttempt = 0;

function getOfficeAuthRefreshFailureDisposition(status, payload) {
  const code = String(payload?.code || payload?.error_code || '').trim().toUpperCase();
  if (Number(status) === 401 && OFFICE_AUTH_REFRESH_INVALID_CODES.has(code)) {
    return { kind: 'invalid', code };
  }
  return { kind: 'transient', code };
}

function scheduleOfficeAuthRefreshRetry() {
  clearTimeout(refreshTimer);
  if (!SESSION?.accessToken) return;
  const index = Math.min(officeAuthRefreshRetryAttempt, OFFICE_AUTH_REFRESH_RETRY_DELAYS_MS.length - 1);
  const delay = OFFICE_AUTH_REFRESH_RETRY_DELAYS_MS[index];
  officeAuthRefreshRetryAttempt = Math.min(officeAuthRefreshRetryAttempt + 1, OFFICE_AUTH_REFRESH_RETRY_DELAYS_MS.length - 1);
  refreshTimer = setTimeout(() => {
    refreshToken().catch(() => {});
  }, delay);
}

function scheduleRefresh(){
  clearTimeout(refreshTimer);
  officeAuthRefreshRetryAttempt = 0;
  if (!SESSION?.exp) return;
  const ms = Math.max(15_000, (SESSION.exp*1000) - Date.now() - 60_000);
  refreshTimer = setTimeout(() => {
    refreshToken().catch(() => {});
  }, ms);
}

// ─────────────────────────────────────────────────────────────
// API helpers: Assignment ↔ Band mappings
// Endpoints (backend):
//  GET    /api/assignment-band-mappings
//  POST   /api/assignment-band-mappings
//  PATCH  /api/assignment-band-mappings/:id
//  DELETE /api/assignment-band-mappings/:id   (soft delete on backend)
// ─────────────────────────────────────────────────────────────

function __qs(params) {
  const q = new URLSearchParams();
  Object.entries(params || {}).forEach(([k, v]) => {
    if (v === undefined || v === null) return;
    const s = String(v);
    if (!s.trim()) return;
    q.set(k, s);
  });
  const out = q.toString();
  return out ? `?${out}` : '';
}

function __unwrapRows(json) {
  if (!json) return [];
  if (Array.isArray(json)) return json;
  if (Array.isArray(json.rows)) return json.rows;
  if (Array.isArray(json.items)) return json.items;
  if (Array.isArray(json.data)) return json.data;
  return [];
}

function __unwrapSingle(json) {
  if (!json) return null;
  if (json.row && typeof json.row === 'object') return json.row;
  if (json.item && typeof json.item === 'object') return json.item;
  if (json.data && typeof json.data === 'object') return json.data;
  if (typeof json === 'object' && !Array.isArray(json)) return json;
  return null;
}



async function apiCreateAssignmentBandMapping(payload) {
  const res = await authFetch(API(`/api/assignment-band-mappings`), {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(payload || {})
  });

  const txt = await res.text().catch(() => '');
  if (!res.ok) throw new Error(txt || `Failed to create assignment-band-mapping (${res.status})`);

  let json;
  try { json = txt ? JSON.parse(txt) : null; } catch { json = null; }

  return __unwrapSingle(json);
}

async function apiUpdateAssignmentBandMapping(id, patch) {
  if (!id) throw new Error('Missing id for apiUpdateAssignmentBandMapping');
  const encId = encodeURIComponent(String(id));

  const res = await authFetch(API(`/api/assignment-band-mappings/${encId}`), {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(patch || {})
  });

  const txt = await res.text().catch(() => '');
  if (!res.ok) throw new Error(txt || `Failed to update assignment-band-mapping (${res.status})`);

  let json;
  try { json = txt ? JSON.parse(txt) : null; } catch { json = null; }

  return __unwrapSingle(json);
}

async function apiDeleteAssignmentBandMapping(id) {
  if (!id) throw new Error('Missing id for apiDeleteAssignmentBandMapping');
  const encId = encodeURIComponent(String(id));

  const res = await authFetch(API(`/api/assignment-band-mappings/${encId}`), {
    method: 'DELETE'
  });

  const txt = await res.text().catch(() => '');
  if (!res.ok) throw new Error(txt || `Failed to delete assignment-band-mapping (${res.status})`);

  let json;
  try { json = txt ? JSON.parse(txt) : null; } catch { json = null; }

  // backend returns the updated row (active=false) if using soft delete
  return __unwrapSingle(json) || { id };
}


