async function bankingPayBatchRemittancesSend(payBatchId, scope = 'ALL', opts = {}) {
  const deep = (o) => JSON.parse(JSON.stringify(o || null));
  const id = (payBatchId == null) ? '' : String(payBatchId).trim();
  const sc = String(scope || 'ALL').trim().toUpperCase();
  const scopeNorm = (sc === 'PAYE' || sc === 'UMBRELLA' || sc === 'ALL') ? sc : 'ALL';
  const silent = !!(opts && typeof opts === 'object' && opts.silent === true);
  const skipConfirm = !!(opts && typeof opts === 'object' && opts.skipConfirm === true);

  const asObj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : null;
  const asArr = (v) => Array.isArray(v) ? v : [];
  const trimStr = (v) => String(v == null ? '' : v).trim();
  const upperTrim = (v) => trimStr(v).toUpperCase();

  const mc = (window.modalCtx && typeof window.modalCtx === 'object') ? window.modalCtx : null;
  if (!mc || String(mc.entity || '') !== 'banking') return null;

  mc.banking = (mc.banking && typeof mc.banking === 'object') ? mc.banking : {};
  mc.banking.pay = (mc.banking.pay && typeof mc.banking.pay === 'object') ? mc.banking.pay : {};
  mc.banking.pay.actionsBusy = (mc.banking.pay.actionsBusy && typeof mc.banking.pay.actionsBusy === 'object') ? mc.banking.pay.actionsBusy : {
    executingBank: false,
    preparing: false,
    scheduling: false,
    polling: false,
    exporting: false,
    manualConfirming: false,
    sendingRemittances: false
  };
  mc.banking.pay.selected = (mc.banking.pay.selected && typeof mc.banking.pay.selected === 'object') ? mc.banking.pay.selected : {
    data: null,
    loading: false,
    error: ''
  };

  const st = mc.banking;
  const pay = st.pay;

  if (!id) return null;

  const actionKind = (scopeNorm === 'PAYE') ? 'SEND_REMITTANCES_PAYE' : 'SEND_REMITTANCES';

  const gate = (typeof bankingIsActionBlocked === 'function')
    ? bankingIsActionBlocked(actionKind)
    : { blocked: false, reasonCode: '', message: '' };

  if (gate && gate.blocked) {
    if (!silent) {
      try { pay.selected.error = String(gate.message || gate.reasonCode || 'Action blocked'); } catch {}
      try { if (typeof window.__toast === 'function') window.__toast(String(gate.message || gate.reasonCode || 'Action blocked')); } catch {}
    }
    return null;
  }

  const currentData = (pay.selected && pay.selected.data && typeof pay.selected.data === 'object') ? pay.selected.data : null;
  const childData = (pay.child && pay.child.data && typeof pay.child.data === 'object' && String(pay.child.batchId || '').trim() === id) ? pay.child.data : null;
  const sourceData = childData || currentData;

  const normalizeCandidateLineEntries = (data, candidateId) => {
    const d = asObj(data);
    const cid = trimStr(candidateId);
    const top = asArr(d?.candidate_lines);
    const out = [];

    for (const x of top) {
      if (!x || typeof x !== 'object') continue;

      const xid = trimStr(x?.candidate_id);
      if (cid && xid && xid !== cid) continue;

      const normalizedBlock = asObj(x.candidate_lines_normalized);
      if (normalizedBlock) {
        const tsNorm = asArr(normalizedBlock.tsLines);
        const nonTsNorm = asArr(normalizedBlock.nonTsLines);
        for (const t of tsNorm) {
          if (t && typeof t === 'object') out.push({ ...t, candidate_id: cid || xid });
        }
        for (const n of nonTsNorm) {
          if (n && typeof n === 'object') out.push({ ...n, candidate_id: cid || xid });
        }
        continue;
      }

      const hasTsLines = Array.isArray(x.ts_lines);
      const hasNonTsLines = Array.isArray(x.non_ts_lines);
      if (hasTsLines || hasNonTsLines) {
        for (const t of (hasTsLines ? x.ts_lines : [])) {
          if (t && typeof t === 'object') out.push({ ...t, candidate_id: cid || xid });
        }
        for (const n of (hasNonTsLines ? x.non_ts_lines : [])) {
          if (n && typeof n === 'object') out.push({ ...n, candidate_id: cid || xid });
        }
        continue;
      }

      if (Array.isArray(x.timesheets)) {
        for (const t of x.timesheets) {
          if (t && typeof t === 'object') out.push({ ...t, candidate_id: cid || xid });
        }
        continue;
      }

      out.push({ ...x, candidate_id: cid || xid });
    }

    return out;
  };

  const financeLineLabel = (line) => {
    const itemType = upperTrim(line?.item_type || line?.line_kind || line?.kind || line?.normalizedKind || '');
    const paymentOrDeduction = upperTrim(line?.payment_or_deduction || '');
    const candidateDirected = line?.is_candidate_directed_oneoff_payout === true;
    const appearsOnRemittance = line?.appears_on_umbrella_remittance === true;

    if (candidateDirected) {
      if (itemType === 'PAYMENT_ADVANCE' || itemType === 'LOAN_PAYMENT' || itemType === 'PAYMENT_ADVANCE_PAYMENT') {
        return 'Loan to candidate';
      }
      if (itemType === 'MANUAL_CREDIT_ADJUSTMENT') {
        return 'Manual credit to candidate';
      }
      return 'Candidate payout notice';
    }

    if (itemType === 'LOAN_REPAYMENT' || itemType === 'PAYMENT_ADVANCE_REPAYMENT') {
      return 'Loan repayment';
    }

    if (itemType === 'MANUAL_DEBT_RECOVERY' || (itemType === 'MANUAL_DEBT_ADJUSTMENT' && paymentOrDeduction === 'DEDUCTION')) {
      return 'Manual debt repayment';
    }

    if (appearsOnRemittance) {
      return 'Umbrella remittance';
    }

    return trimStr(line?.item_type_label || line?.line_kind || line?.kind || line?.normalizedKind || line?.item_type || 'Finance item') || 'Finance item';
  };

  const candidateLinePreview = (candidate, lines) => {
    const labels = [];
    const seen = new Set();

    for (const line of asArr(lines)) {
      const label = financeLineLabel(line);
      const destinationLabel = trimStr(line?.destination_label || line?.payout_destination || '');
      const maskedAccount = trimStr(line?.masked_bank_account_paid_to || line?.masked_bank_account || '');
      const beneficiary = trimStr(line?.beneficiary_name || '');
      const differentDestination =
        line?.different_destination_marker === true ||
        line?.is_separate_destination_payment === true ||
        line?.candidate_has_multiple_payment_destinations === true;

      let composed = label;
      if (line?.is_candidate_directed_oneoff_payout === true) {
        const parts = [];
        if (destinationLabel) parts.push(destinationLabel);
        if (maskedAccount) parts.push(maskedAccount);
        if (beneficiary) parts.push(beneficiary);
        if (parts.length) composed += ` → ${parts.join(' • ')}`;
      }
      if (differentDestination) composed += ' • ! Beneficiary Account different';

      const key = composed.toUpperCase();
      if (!seen.has(key)) {
        seen.add(key);
        labels.push(composed);
      }
    }

    const displayName =
      trimStr(candidate?.candidate_display_name) ||
      trimStr(candidate?.display_name) ||
      trimStr(candidate?.candidate_name) ||
      trimStr(candidate?.candidate_tms_ref) ||
      trimStr(candidate?.tms_ref) ||
      'Candidate';

    return {
      displayName,
      labels
    };
  };

  const deriveCommunicationState = (data, sendResultObj) => {
    const d = asObj(data);
    const resultObj = asObj(sendResultObj);

    const summary = asObj(d?.communications) ? deep(d.communications) : null;
    const remittanceSummary = asObj(summary?.remittance);
    const payoutNoticeSummary = asObj(summary?.payout_notice);

    const remittanceResult = asObj(resultObj?.remittance_result) ? deep(resultObj.remittance_result) : null;
    const payoutNoticeResult = asObj(resultObj?.payout_notice_result) ? deep(resultObj.payout_notice_result) : null;

    const mode = upperTrim(resultObj?.communication_mode || summary?.mode || '');

    const remittanceTargets = Number(remittanceSummary?.target_count || remittanceSummary?.targets_count || remittanceSummary?.candidate_count || remittanceSummary?.count || 0);
    const payoutTargets = Number(payoutNoticeSummary?.target_count || payoutNoticeSummary?.targets_count || payoutNoticeSummary?.candidate_count || payoutNoticeSummary?.count || 0);

    const remittanceQueued = Number(remittanceResult?.queued_count || 0);
    const remittanceSent = Number(remittanceResult?.sent_count || 0);
    const remittanceSkipped = Number(remittanceResult?.skipped_count || 0);

    const payoutQueued = Number(payoutNoticeResult?.queued_count || 0);
    const payoutSent = Number(payoutNoticeResult?.sent_count || 0);
    const payoutSkipped = Number(payoutNoticeResult?.skipped_count || 0);

    const allCandidateLines = asArr(d?.candidates).flatMap((candidate) => {
      const cid = trimStr(candidate?.candidate_id);
      return cid ? normalizeCandidateLineEntries(d, cid) : [];
    });

    const fallbackHasRemittances = allCandidateLines.some((line) => line?.appears_on_umbrella_remittance === true);
    const fallbackHasPayoutNotices = allCandidateLines.some((line) => line?.generates_candidate_payment_advice === true || line?.is_candidate_directed_oneoff_payout === true);

    const hasRemittances =
      remittanceTargets > 0 ||
      remittanceQueued > 0 ||
      remittanceSent > 0 ||
      remittanceSkipped > 0 ||
      fallbackHasRemittances;

    const hasPayoutNotices =
      payoutTargets > 0 ||
      payoutQueued > 0 ||
      payoutSent > 0 ||
      payoutSkipped > 0 ||
      fallbackHasPayoutNotices;

    return {
      summary,
      result: {
        mode,
        remittance: remittanceResult,
        payout_notice: payoutNoticeResult
      },
      mode,
      has_remittances: !!hasRemittances,
      has_payout_notices: !!hasPayoutNotices,
      has_both: !!(hasRemittances && hasPayoutNotices)
    };
  };

  const sourceCandidates = asArr(sourceData?.candidates);
  const candidatePreviewEntries = sourceCandidates.map((candidate) => {
    const cid = trimStr(candidate?.candidate_id);
    const lines = cid ? normalizeCandidateLineEntries(sourceData, cid) : [];
    return candidateLinePreview(candidate, lines);
  }).filter((entry) => entry.labels.length > 0);

  const sourceCommState = deriveCommunicationState(sourceData, null);
  const commModeLabel = (() => {
    if (sourceCommState.has_both) return 'Remittances + payout notices';
    if (sourceCommState.has_remittances) return 'Remittances only';
    if (sourceCommState.has_payout_notices) return 'Payout notices only';
    return 'No communications';
  })();

  if (!skipConfirm && !silent && typeof openUiConfirmModal === 'function') {
    const previewLines = candidatePreviewEntries.slice(0, 8).map((entry) => {
      return `${entry.displayName} — ${entry.labels.join('; ')}`;
    }).join('\n');

    const moreCount = candidatePreviewEntries.length > 8 ? candidatePreviewEntries.length - 8 : 0;
    const confirmMessage =
      `You are about to send batch communications.\n\n` +
      `This send will produce: ${commModeLabel}.\n\n` +
      (
        previewLines
          ? `Preview:\n${previewLines}${moreCount ? `\n… and ${moreCount} more candidate(s).` : ''}\n\n`
          : `Preview:\nNo candidate communication lines were returned in the current batch payload.\n\n`
      ) +
      `Continue?`;

    const ok = await openUiConfirmModal({
      title: 'Send communications',
      message: confirmMessage,
      confirm_label: 'Send',
      cancel_label: 'Cancel',
      confirm_class: 'btn btn-primary'
    });

    if (!ok) return null;
  }

  pay.actionsBusy.sendingRemittances = true;

  try {
    const obj = await apiPostJson(`/api/banking/pay/batch/${encodeURIComponent(id)}/remittances/send`, {
      scope: scopeNorm
    });

    const sendCommState = deriveCommunicationState(sourceData, obj);

    try {
      pay.selected = (pay.selected && typeof pay.selected === 'object') ? pay.selected : { data: null, loading: false, error: '' };
      pay.selected.lastCommunicationSendResult = deep(obj);
      pay.selected.lastCommunicationResult = deep(sendCommState);
      pay.selected.lastRemittanceSendResult = deep(obj);
    } catch {}

    let fresh = null;
    try {
      if (typeof bankingPayBatchGet === 'function') {
        fresh = await bankingPayBatchGet(id);
      }
    } catch {}

    const freshObj = (fresh && typeof fresh === 'object') ? fresh : null;
    const refreshedCommState = deriveCommunicationState(freshObj || pay.selected.data || sourceData, obj);

    try {
      if (freshObj) {
        pay.selected.data = deep(freshObj);
      }
      pay.selected.lastCommunicationResult = deep(refreshedCommState);
      pay.selected.error = '';
    } catch {}

    try {
      if (pay.child && typeof pay.child === 'object' && String(pay.child.batchId || '').trim() === id) {
        if (freshObj) {
          pay.child.data = deep(freshObj);
          pay.child.error = '';
          pay.child.loading = false;
        }
        pay.child.communications = deep(refreshedCommState);
        pay.child.lastCommunicationSendResult = deep(obj);
      }
    } catch {}

    try { if (typeof bankingRerender === 'function') await bankingRerender(null); } catch {}

    return deep(obj);

  } catch (e) {
    if (!silent) {
      try {
        if (typeof bankingHandleApiError === 'function') {
          bankingHandleApiError(e, { action: 'SEND_REMITTANCES', scope: scopeNorm, batchId: id, errorPath: ['pay', 'selected', 'error'] });
        }
      } catch {}
    }
    return null;

  } finally {
    try { pay.actionsBusy.sendingRemittances = false; } catch {}
  }
}

async function bankingIdPreview() {
  const deep = (o) => JSON.parse(JSON.stringify(o || null));

  const mc = (window.modalCtx && typeof window.modalCtx === 'object') ? window.modalCtx : null;
  if (!mc || String(mc.entity || '') !== 'banking') return null;

  mc.banking = (mc.banking && typeof mc.banking === 'object') ? mc.banking : {};
  mc.banking.id = (mc.banking.id && typeof mc.banking.id === 'object') ? mc.banking.id : {};
  mc.banking.id.preview = (mc.banking.id.preview && typeof mc.banking.id.preview === 'object') ? mc.banking.id.preview : { data: null, loading: false, error: '' };

  const st = mc.banking;
  const idSt = st.id;

  const gate = (typeof bankingIsActionBlocked === 'function')
    ? bankingIsActionBlocked('ID_PREVIEW')
    : { blocked: false, reasonCode: '', message: '' };

  if (gate && gate.blocked) {
    try { idSt.preview.error = String(gate.message || gate.reasonCode || 'Action blocked'); } catch {}
    try { if (typeof window.__toast === 'function') window.__toast(String(gate.message || gate.reasonCode || 'Action blocked')); } catch {}
    return null;
  }

  idSt.preview.loading = true;
  idSt.preview.error = '';

  const safeParse = (txt) => {
    try { return txt ? JSON.parse(txt) : null; } catch { return null; }
  };

  try {
    const res = await authFetch(API('/api/banking/id/preview'));
    const txt = await res.text().catch(() => '');
    const parsed = safeParse(txt);

    if (!res.ok) {
      const msg =
        (parsed && typeof parsed === 'object' && (parsed.error || parsed.message))
          ? String(parsed.error || parsed.message)
          : (txt || `Request failed (${res.status})`);

      const err = new Error(String(msg || 'Failed to load ID preview'));
      err.status = res.status;
      err.body = txt || '';
      err.json = parsed;
      throw err;
    }

    const obj = (parsed && typeof parsed === 'object') ? parsed : {};
    idSt.preview.data = deep(obj);
    idSt.preview.loading = false;
    idSt.preview.error = '';

    try { if (typeof bankingRerender === 'function') await bankingRerender(null); } catch {}

    return deep(obj);

  } catch (e) {
    try {
      if (typeof bankingHandleApiError === 'function') {
        bankingHandleApiError(e, { action: 'ID_PREVIEW', scope: null, batchId: null, errorPath: ['id', 'preview', 'error'] });
      }
    } catch {}

    return null;

  } finally {
    try { idSt.preview.loading = false; } catch {}
  }
} 

