  const refPrefix = trimStr(reference_prefix);
  const refContains = trimStr(reference_contains);
  const searchText = trimStr(search || (useChildScope && ctxIdNorm ? `pay_batch:${ctxIdNorm}` : ''));
  const channelNorm = upperTrim(channel || 'EMAIL') || 'EMAIL';
  const queueStateNorm = upperTrim(queue_state);
  const statusNorm = upperTrim(status);
  const sortBy = trimStr(sort_by || 'created_at_utc') || 'created_at_utc';
  const sortDir = lowerTrim(sort_dir) === 'asc' ? 'asc' : 'desc';

