      if (referenceLower.includes('payout_notice')) return 'PAYOUT_NOTICE';
      if (referenceLower.startsWith('remit:')) return 'REMITTANCE';
      if (referenceLower.includes('remittance')) return 'REMITTANCE';
      if (ctxKindCmp === 'pay_batch' && recipientKind === 'umbrella') return 'REMITTANCE';
      if (ctxKindCmp === 'pay_batch' && recipientKind === 'candidate') return 'PAYOUT_NOTICE';
