      last_error: trimStr(rawRow?.last_error || raw.last_error || rawRow?.failed_reason || raw.failed_reason || rawRow?.error || raw.error) || null,
      created_at_utc: trimStr(rawRow?.created_at_utc || raw.created_at_utc || rawRow?.created_at || raw.created_at) || null,
      sent_at_utc: trimStr(rawRow?.sent_at || raw.sent_at || rawRow?.sent_at_utc || raw.sent_at_utc) || null,
