      delivered_at: trimStr(rawRow?.delivered_at || raw.delivered_at) || null,
      read_at: trimStr(rawRow?.read_at || raw.read_at) || null,
      failed_at: trimStr(rawRow?.failed_at || raw.failed_at) || null,
      scheduled_for_utc: trimStr(rawRow?.scheduled_for_utc || raw.scheduled_for_utc) || null,
      next_attempt_at_utc: trimStr(rawRow?.next_attempt_at_utc || raw.next_attempt_at_utc) || null,
      effective_ready_at_utc: trimStr(rawRow?.effective_ready_at_utc || raw.effective_ready_at_utc) || null,
      recipient_kind: recipientKind || null,
      recipient_id: recipientId || null,
      recipient_display_name: recipientDisplayName || null,
      recipient_label: recipientDisplayName || toAddress || recipientId || 'Recipient',
      context_kind: contextKindOut || null,
      context_id: contextIdOut || null,
      kind_key: kindKey || null,
