    'REAUTH_REQUIRED',
    'RAIL_NOT_CONFIGURED',
    'UNKNOWN_RAIL_PROVIDER',
    'RAIL_RETRY_EXECUTION_NOT_SUPPORTED',
    'MANUAL_CONFIRM_NOT_SUPPORTED_FOR_THIS_RAIL',
