    const pe = ctxState ? ctxState.pe : null;
    const contextObj = (context && typeof context === 'object' && !Array.isArray(context)) ? context : {};
    const friendly = normalisePayeEntryFriendlyError(errorValue, fallbackCode, contextObj);
