  if (!signatureHtmlTrimmed) {
    return {
      ok: true,
      applied: false,
      reason: 'NO_SIGNATURE_HTML'
    };
  }

  const explicitMode = trimStr(src.mode || src.signature_mode || src.apply_mode || '').toLowerCase();
  const wizardState = (window.modalCtx && typeof window.modalCtx === 'object' && window.modalCtx.mailshotWizard && typeof window.modalCtx.mailshotWizard === 'object')
    ? window.modalCtx.mailshotWizard
    : null;

