    const startBoundary = document.createElement('span');
    startBoundary.setAttribute('data-template-signature-boundary', 'start');
    startBoundary.setAttribute('data-template-signature-block-id', blockId);
    startBoundary.setAttribute('data-template-signature-fingerprint', fingerprint);
    startBoundary.setAttribute('contenteditable', 'false');
    startBoundary.style.display = 'none';
    startBoundary.textContent = '\u200B';

    const body = document.createElement('div');
    body.setAttribute('data-template-signature-body', '1');
    body.innerHTML = signatureHtml;

    const endBoundary = document.createElement('span');
    endBoundary.setAttribute('data-template-signature-boundary', 'end');
    endBoundary.setAttribute('data-template-signature-block-id', blockId);
    endBoundary.setAttribute('data-template-signature-fingerprint', fingerprint);
    endBoundary.setAttribute('contenteditable', 'false');
    endBoundary.style.display = 'none';
