      if (typeof fmtUkDateTime === 'function') return fmtUkDateTime(v);
      const d = new Date(v);
      if (!Number.isFinite(d.getTime())) return String(v);
      return new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Europe/London',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      }).format(d).replace(',', '');
