function extractFiltersFromForm(formSel='#searchForm'){
  const raw = collectForm(formSel, false);

  Object.keys(raw).forEach(k=>{
    const el = document.querySelector(`${formSel} [name="${k}"]`);
    if (!el) return;
    if (el.tagName==='SELECT' && el.multiple){
      raw[k] = Array.from(el.selectedOptions).map(o=>o.value);
    }
    if (el.tagName==='SELECT' && (el.value === 'true' || el.value === 'false')){
      raw[k] = (el.value === 'true');
    }
    if (el.type === 'number' && raw[k] === '') raw[k] = null;
    if (raw[k] === '') delete raw[k];
  });

  const dateFields = [
    'created_from','created_to',
    'updated_from','updated_to',
    'worked_from','worked_to',
    'week_ending_from','week_ending_to',
    'issued_from','issued_to',
    'due_from','due_to',
    'dob',
    'start_date_from','start_date_to',
    'end_date_from','end_date_to',
    'active_on'
  ];

  dateFields.forEach(f => {
    if (raw[f]) {
      const s = String(raw[f] == null ? '' : raw[f]).trim();
      if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
        raw[f] = s;
        return;
      }

      let iso = null;
      try {
        if (typeof parseUkDateToIso === 'function') {
          iso = parseUkDateToIso(s);
        }
      } catch {
        iso = null;
      }

      if (!iso) {
        const m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
        if (m) iso = `${m[3]}-${m[2]}-${m[1]}`;
      }

      if (iso) raw[f] = iso;
    }
  });

  const parseIdArray = (value) => {
    const rawList = Array.isArray(value)
      ? value
      : (typeof value === 'string' ? value.split(',') : []);
    const seen = new Set();
    const out = [];
    for (const item of rawList) {
      const id = String(item == null ? '' : item).trim();
      if (!id || seen.has(id)) continue;
      seen.add(id);
      out.push(id);
    }
    return out;
  };

  const parseBool = (value) => {
    if (value === true || value === false) return value;
    const rawVal = String(value == null ? '' : value).trim().toLowerCase();
    return rawVal === 'true' || rawVal === '1' || rawVal === 'yes' || rawVal === 'y' || rawVal === 'on';
  };

  const includeIds = parseIdArray(raw.job_title_include_node_ids);
  const excludeIds = parseIdArray(raw.job_title_exclude_node_ids);
  const roleIds = parseIdArray(raw.job_title_role_ids);
  const primaryOnly = parseBool(raw.job_title_primary_only);

  if (roleIds.length) {
    raw.job_title_include_node_ids = includeIds;
    raw.job_title_exclude_node_ids = excludeIds;
    raw.job_title_role_ids = roleIds;
    raw.job_title_primary_only = !!primaryOnly;
  } else {
    delete raw.job_title_include_node_ids;
    delete raw.job_title_exclude_node_ids;
    delete raw.job_title_role_ids;
    delete raw.job_title_primary_only;
  }

  [
    'job_title_contains',
    'primary_job_title_contains',
    'ts_stage',
    'summary_stage',
    'status_code',
    'processing_status',
    'client_invoiced',
    'needs_attention'
  ].forEach(k => {
    if (Object.prototype.hasOwnProperty.call(raw, k)) delete raw[k];
  });

  return raw;
}


function populateSearchFormFromFilters(filters={}, formSel='#searchForm'){
  const form = document.querySelector(formSel);
  if (!form) return;

  const dateFields = [
    'created_from','created_to',
    'updated_from','updated_to',
    'worked_from','worked_to',
    'week_ending_from','week_ending_to',
    'issued_from','issued_to',
    'due_from','due_to',
    'dob',
    'start_date_from','start_date_to',
    'end_date_from','end_date_to',
    'active_on'
  ];

  const setArrayOrScalar = (el, value) => {
    if (!el) return;
    if (Array.isArray(value) && el.tagName === 'SELECT' && el.multiple) {
      const values = new Set(value.map(String));
      Array.from(el.options).forEach(opt => { opt.selected = values.has(opt.value); });
      return;
    }
    if (Array.isArray(value)) {
      el.value = value.join(',');
      return;
    }
    if (typeof value === 'boolean' && el.tagName === 'SELECT') {
      el.value = value ? 'true' : 'false';
      return;
    }
    if (el.type === 'checkbox') {
      el.checked = !!value;
      return;
    }
    el.value = (value == null ? '' : String(value));
  };

  ['job_title_include_node_ids','job_title_exclude_node_ids','job_title_role_ids','job_title_primary_only'].forEach((name) => {
    const el = form.querySelector(`[name="${name}"]`);
    if (!el) return;
    if (name === 'job_title_primary_only') {
      if (el.type === 'checkbox') {
        el.checked = false;
      } else {
        el.value = 'false';
      }
    } else {
      el.value = '';
    }
  });

  for (const [k,v] of Object.entries(filters || {})) {
    if (k === 'job_title_contains' ||
        k === 'primary_job_title_contains' ||
        k === 'ts_stage' ||
        k === 'summary_stage' ||
        k === 'status_code' ||
        k === 'processing_status' ||
        k === 'client_invoiced' ||
        k === 'needs_attention') {
      continue;
    }

    const el = form.querySelector(`[name="${k}"]`);
    if (!el) continue;

    if ((k === 'stage' || k === 'tools_stage') && String(v || '').trim().toUpperCase() === 'ARCHIVED') {
      el.value = 'WITHDRAWN';
      continue;
    }

    const isDateField = dateFields.includes(k);
    if (isDateField && typeof v === 'string') {
      const uk = (typeof formatIsoToUk === 'function') ? formatIsoToUk(v) : v;
      el.value = uk || '';
      continue;
    }

    if (k === 'job_title_include_node_ids' ||
        k === 'job_title_exclude_node_ids' ||
        k === 'job_title_role_ids') {
      setArrayOrScalar(el, Array.isArray(v) ? v : (typeof v === 'string' ? v.split(',').map(x => String(x).trim()).filter(Boolean) : []));
      continue;
    }

    if (k === 'job_title_primary_only') {
      if (el.type === 'checkbox') {
        el.checked = !!v;
      } else {
        el.value = (v ? 'true' : 'false');
      }
      continue;
    }

    setArrayOrScalar(el, v);
  }
}



// Build querystring per section


// -----------------------------
// UPDATED: search()
// -----------------------------
// ======================================
// FRONTEND — search (UPDATED: no extra logic beyond existing; kept for completeness)
// ======================================

// ──────────────────────────────────────────────────────────────────────────────
// FIX 1: Search route mismatch (contracts now calls /api/contracts with filters)
// ──────────────────────────────────────────────────────────────────────────────

async function search(section, filters = {}, options = {}) {
  const sec = String(section == null ? '' : section).trim();

  window.__listState = window.__listState || {};
  const st = (window.__listState[sec] ||= {
    page: 1,
    pageSize: 50,
    total: null,
    hasMore: false,
    filters: null,
    sort: { key: null, dir: 'asc' }
  });

  if (!st.sort || typeof st.sort !== 'object') {
    st.sort = { key: null, dir: 'asc' };
  }

  const clonePlain = (value) => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
    try {
      return JSON.parse(JSON.stringify(value));
    } catch {
      const out = {};
      Object.keys(value).forEach((key) => {
        out[key] = value[key];
      });
      return out;
    }
  };

  const normalizeIdArray = (arr) => Array.from(new Set(
    (Array.isArray(arr) ? arr : [])
      .map(v => String(v == null ? '' : v).trim())
      .filter(Boolean)
  ));

  const normalizeSortSpec = (value) => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
      return { key: null, dir: 'asc' };
    }
    const key = String(value.key ?? value.sort_key ?? '').trim();
    const dir = String(value.dir ?? value.sort_dir ?? 'asc').trim().toLowerCase() === 'desc' ? 'desc' : 'asc';
    return { key: key || null, dir };
  };

   const optionsObj = clonePlain(
    (options && typeof options === 'object' && !Array.isArray(options))
      ? options
      : {}
  );
  const suppressSelectionReset = optionsObj.suppressSelectionReset === true;

  const liveTypeAheadState = (
    window.__summaryTypeAheadState &&
    window.__summaryTypeAheadState[sec] &&
    typeof window.__summaryTypeAheadState[sec] === 'object'
  )
    ? window.__summaryTypeAheadState[sec]
    : null;

  const typeAheadFallbackSort = normalizeSortSpec({
    key: liveTypeAheadState && liveTypeAheadState.sort_key,
    dir: liveTypeAheadState && liveTypeAheadState.sort_dir
  });

  if ((!st.sort.key || !String(st.sort.key).trim()) && typeAheadFallbackSort.key) {
    st.sort = {
      key: typeAheadFallbackSort.key,
      dir: typeAheadFallbackSort.dir
    };
  }

  const existingFilters = clonePlain(
    (st.filters && typeof st.filters === 'object' && !Array.isArray(st.filters))
      ? st.filters
      : {}
  );

  const incomingFilters = clonePlain(
    (filters && typeof filters === 'object' && !Array.isArray(filters))
      ? filters
      : {}
  );

  const related = (existingFilters.related && typeof existingFilters.related === 'object')
    ? existingFilters.related
    : null;

  const inRelatedMode =
    !!related &&
    String(related.source_entity || '').trim() &&
    String(related.source_id || '').trim() &&
    String(related.relation_type || '').trim();

  const incomingKeys = Object.keys(incomingFilters);
  const oneShotIdsInRelatedMode =
    sec === 'invoices' &&
    inRelatedMode &&
    incomingKeys.length === 1 &&
    incomingKeys[0] === 'ids' &&
    normalizeIdArray(incomingFilters.ids).length > 0;

  const prevDatasetKey = (() => {
    try {
      return String(getSummaryFingerprint(sec) || '').trim();
    } catch {
      return '';
    }
  })();

  let effectiveFilters = null;
  let nextDatasetKey = prevDatasetKey;

  if (oneShotIdsInRelatedMode) {
    effectiveFilters = { ids: normalizeIdArray(incomingFilters.ids) };
  } else {
    effectiveFilters = (typeof buildMergedSectionFilters === 'function')
      ? buildMergedSectionFilters(sec, incomingFilters, { mode: 'merge' })
      : clonePlain(incomingFilters);

    if (effectiveFilters && typeof effectiveFilters === 'object' && Array.isArray(effectiveFilters.ids)) {
      effectiveFilters.ids = normalizeIdArray(effectiveFilters.ids);
      if (!effectiveFilters.ids.length) delete effectiveFilters.ids;
    }

    st.filters = effectiveFilters && Object.keys(effectiveFilters).length ? clonePlain(effectiveFilters) : null;
    nextDatasetKey = (() => {
      try {
        return String(getSummaryFingerprint(sec) || '').trim();
      } catch {
        return prevDatasetKey;
      }
    })();

    const datasetChanged = nextDatasetKey !== prevDatasetKey;

    if (datasetChanged) {
      st.page = 1;
      st.total = null;
      st.hasMore = false;
    }

    if (!suppressSelectionReset && typeof resetSelectionForDataset === 'function') {
      resetSelectionForDataset(sec, nextDatasetKey, datasetChanged ? 'dataset-changed' : 'search');
    } else if (!suppressSelectionReset && datasetChanged) {
      const sel = ensureSelection(sec);
      sel.dataset_key = nextDatasetKey;
      sel.fingerprint = nextDatasetKey;
      clearSelection(sec);
    } else {
      const sel = ensureSelection(sec);
      sel.dataset_key = nextDatasetKey;
      sel.fingerprint = nextDatasetKey;
    }
  }

  if (sec === 'timesheets') {
    return await listTimesheetsSummary(
      clonePlain(oneShotIdsInRelatedMode ? effectiveFilters : (st.filters || effectiveFilters || {}))
    );
  }

  const map = {
    candidates: '/api/search/candidates',
    clients: '/api/search/clients',
    umbrellas: '/api/search/umbrellas',
    invoices: '/api/invoices'
  };

  const path = (sec === 'contracts') ? '/api/contracts' : map[sec];
  if (!path) return [];

  const requestFilters = clonePlain(
    oneShotIdsInRelatedMode
      ? effectiveFilters
      : ((st.filters && typeof st.filters === 'object' && !Array.isArray(st.filters)) ? st.filters : {})
  );

  const sortOverride = normalizeSortSpec(optionsObj.sortOverride);
  const requestSort = sortOverride.key
    ? sortOverride
    : (st.sort && st.sort.key ? normalizeSortSpec(st.sort) : typeAheadFallbackSort);

  if ((!st.sort.key || !String(st.sort.key).trim()) && requestSort.key) {
    st.sort = {
      key: requestSort.key,
      dir: requestSort.dir
    };
  }

  const requestPage = oneShotIdsInRelatedMode
    ? 1
    : Math.max(
        1,
        Number(
          Object.prototype.hasOwnProperty.call(optionsObj, 'pageOverride')
            ? optionsObj.pageOverride
            : (st.page || 1)
        )
      );

  const requestPageSize = oneShotIdsInRelatedMode
    ? Math.max(1, normalizeIdArray(requestFilters.ids).length || 1)
    : (
        Object.prototype.hasOwnProperty.call(optionsObj, 'pageSizeOverride')
          ? optionsObj.pageSizeOverride
          : st.pageSize
      );

  const qs = new URLSearchParams();

  Object.entries(requestFilters || {}).forEach(([k, v]) => {
    if (v == null) return;
    if (typeof v === 'object' && !Array.isArray(v)) return;

    if (k === 'ids' && Array.isArray(v)) {
      const csv = normalizeIdArray(v).join(',');
      if (csv) qs.set('ids', csv);
      return;
    }

    if (Array.isArray(v)) {
      v.forEach((vv) => {
        const clean = String(vv == null ? '' : vv).trim();
        if (!clean) return;
        qs.append(k, clean);
      });
      return;
    }

    if (typeof v === 'boolean') {
      qs.set(k, v ? 'true' : 'false');
      return;
    }

    const clean = String(v).trim();
    if (!clean) return;
    qs.set(k, clean);
  });

  if (requestPageSize !== 'ALL') {
    qs.set('page', String(requestPage));
    qs.set('page_size', String(Number(requestPageSize || 50)));
  }

  if (!oneShotIdsInRelatedMode && requestSort && requestSort.key) {
    qs.set('order_by', String(requestSort.key));
    qs.set('order_dir', requestSort.dir === 'desc' ? 'desc' : 'asc');
  }

  if (!oneShotIdsInRelatedMode && requestPageSize !== 'ALL') {
    if (sec === 'candidates' || sec === 'clients' || sec === 'umbrellas' || sec === 'contracts' || sec === 'invoices') {
      qs.set('include_count', 'true');
    }
  }

  if (sec === 'invoices') {
    qs.set('include_totals', 'true');
  }

  const url = qs.toString() ? `${path}?${qs.toString()}` : path;

  const safeJson = async (res) => { try { return await res.json(); } catch { return null; } };

  const toast = (msg) => {
    try {
      if (typeof window.toast === 'function') return window.toast(msg);
      if (typeof window.showToast === 'function') return window.showToast(msg);
      if (typeof window.notify === 'function') return window.notify(msg);
      if (typeof window.__toast === 'function') return window.__toast(msg);
      console.log('[SEARCH][TOAST]', msg);
    } catch {}
  };

  const r = await authFetch(API(url));
  const j = await safeJson(r);

  try {
    const hasPayloadError = !!(j && typeof j === 'object' && !Array.isArray(j) && j.error);
    const retryKey = JSON.stringify({
      section: sec,
      dataset_key: oneShotIdsInRelatedMode ? prevDatasetKey : nextDatasetKey,
      request_filters: requestFilters || {},
      sort: (!oneShotIdsInRelatedMode && requestSort && requestSort.key) ? requestSort : null
    });
    const alreadyRetriedForThisFingerprint = (st && st.__searchRetryFingerprint === retryKey);

    if (hasPayloadError) {
      const errMsg = String(j.error || 'Search failed');
      const retrySortKey = (!oneShotIdsInRelatedMode && requestSort && requestSort.key) ? String(requestSort.key) : '';

      if (sec === 'candidates' && retrySortKey && !alreadyRetriedForThisFingerprint) {
        st.__searchRetryFingerprint = retryKey;
        st.sort = { key: null, dir: 'asc' };
        toast(`Sorting reset due to backend error: ${errMsg}`);
        return await search(sec, requestFilters, optionsObj);
      }

      toast(`Search failed: ${errMsg}`);
    }

    if (!hasPayloadError && st && st.__searchRetryFingerprint) {
      st.__searchRetryFingerprint = null;
    }
  } catch {}

  const rows =
    Array.isArray(j) ? j :
    (j && Array.isArray(j.items)) ? j.items :
    (j && Array.isArray(j.rows)) ? j.rows :
    [];

  if (oneShotIdsInRelatedMode) {
    return rows;
  }

  const ps = (requestPageSize === 'ALL') ? null : Number(requestPageSize || 50);

  try {
    if (j && typeof j === 'object') {
      const cnt =
        (typeof j.count === 'number') ? Number(j.count) :
        (typeof j.total === 'number') ? Number(j.total) :
        null;

      if (cnt != null && Number.isFinite(cnt)) {
        st.total = cnt;
      }

      if (sec === 'invoices') {
        if (j.totals && typeof j.totals === 'object') st.totals = j.totals;
      }
    }
  } catch {}

  if (sec === 'contracts') {
    try {
      const qsCount = new URLSearchParams(qs);
      qsCount.delete('page');
      qsCount.delete('page_size');
      qsCount.delete('order_by');
      qsCount.delete('order_dir');
      qsCount.delete('include_totals');

      const cr = await authFetch(API(`/api/contracts/count?${qsCount.toString()}`));
      const cj = await safeJson(cr);
      if (cr.ok && cj && typeof cj.count === 'number') {
        st.total = Number(cj.count);
      }
    } catch {}
  }

  if (ps != null && typeof st.total === 'number' && Number.isFinite(st.total)) {
    st.hasMore = (requestPage * ps) < st.total;
  } else {
    st.hasMore = (ps != null) ? (Array.isArray(rows) && rows.length === ps) : false;
  }

  return rows;
}


function defaultColumnsFor(section){
  // No longer read localStorage; server grid prefs are the source of truth.
  switch(section){
    case 'candidates':
      return ['last_name','first_name','phone','role','postcode','email'];
    case 'clients':
      return ['name','primary_invoice_email','invoice_address','postcode','ap_phone'];
    case 'umbrellas':
      return ['name','vat_chargeable','bank_name','sort_code','account_number','enabled'];
    case 'audit':
      return ['type','to','subject','status','created_at_utc','last_error'];
    case 'contracts':
      // Sensible defaults for the new section
      return ['candidate_display','client_name','role','band','pay_method_snapshot','default_submission_mode','start_date','end_date','bucket_labels_preview'];
    default:
      return ['id'];
  }
}






