    const det = (bpCtx.details && typeof bpCtx.details === 'object') ? bpCtx.details : {};
    const ts = (det.timesheet && typeof det.timesheet === 'object') ? det.timesheet : {};
    const tf = (det.tsfin && typeof det.tsfin === 'object') ? det.tsfin : {};
