            emailSelection: new Map(),

            // existing
            invalidationSelection: new Map(), // key: `${timesheet_id}|${comparison_key}` -> boolean

            // ✅ Alternative Email per email key (`${timesheet_id}|${issue_fingerprint}`)
            altEmailByKey: new Map(),

