function resetBulkProcessDirtyBaseline(state, reason, detail = {}) {
  const st = (state && typeof state === 'object') ? state : null;
  if (!st) return;
  const trimStr = (v) => String(v == null ? '' : v).trim();
  const deriveRowKey = () => {
    const explicit = trimStr(st.active_row_key || st.active_row?.row_key || '');
    if (explicit) return explicit;

    const row = (st.active_row && typeof st.active_row === 'object') ? st.active_row : {};
    const ctx = (st.active_ctx && typeof st.active_ctx === 'object') ? st.active_ctx : {};
    const details = (ctx.details && typeof ctx.details === 'object')
      ? ctx.details
      : ((st.active_details && typeof st.active_details === 'object') ? st.active_details : {});

    const tsId = trimStr(
      row.timesheet_id ||
      details.current_timesheet_id ||
      details?.timesheet?.timesheet_id ||
      ''
    );
    if (tsId) return `timesheet:${tsId}`;

    const cwId = trimStr(
      row.contract_week_id ||
      details.contract_week_id ||
      details?.contract_week?.id ||
      row.id ||
      ''
    );
    if (cwId) return `contract_week:${cwId}`;
    return '';
  };

  const wasDirty = !!st.dirty;
  const rowKey = deriveRowKey() || null;
  const traceDetail = {
    ...(detail && typeof detail === 'object' ? detail : {}),
    transition: wasDirty ? 'dirty->clean' : 'clean->clean',
    baseline_row_key: rowKey
  };

  if (!Object.prototype.hasOwnProperty.call(traceDetail, 'note')) {
    traceDetail.note = rowKey
      ? 'editable baseline reset for active row'
      : 'no active row; editable baseline cleared';
  }

  if (!rowKey) {
    st.__dirty_baseline_row_key = null;
    st.__dirty_baseline_state = null;
    st.dirty = false;

    traceBulkProcessDirty(
      st,
      String(reason || 'baseline-reset'),
      traceDetail
    );
    return;
  }

  st.__dirty_baseline_row_key = rowKey;
  st.__dirty_baseline_state = buildBulkProcessEditableDraftSnapshot(st);
  st.dirty = false;

  traceBulkProcessDirty(
    st,
    String(reason || 'baseline-reset'),
    traceDetail
  );
}








