async function apiListRecipientComms(recipient_kind, recipient_id, opts = {}) {
  const kind = String(recipient_kind || '').trim().toLowerCase();
  const rid = String(recipient_id || '').trim();

  if (!kind) throw new Error('recipient_kind is required');
  if (!rid) throw new Error('recipient_id is required');

  const allowed = new Set(['candidate', 'client', 'umbrella']);
  if (!allowed.has(kind)) throw new Error('invalid_recipient_kind');

  const limit = Number.isFinite(Number(opts && opts.limit)) ? Math.trunc(Number(opts.limit)) : 50;
  const offset = Number.isFinite(Number(opts && opts.offset)) ? Math.trunc(Number(opts.offset)) : 0;

  const safeJson = async (res) => { try { return await res.json(); } catch { return null; } };

  const normalizeItem = (item) => {
    const raw = (item && typeof item === 'object') ? item : {};
    const channel = String(raw.channel || '').trim().toUpperCase();
    return {
      id: String(raw.outbox_id || ''),
      outbox_id: String(raw.outbox_id || ''),
      channel,
      outbox_type: raw.outbox_type ?? null,

      status: raw.status ?? null,
      delivery_status: raw.delivery_status ?? null,
      queue_state: raw.queue_state ?? null,
      is_scheduled: !!raw.is_scheduled,

      created_at_utc: raw.created_at_utc ?? null,
      sent_at: raw.sent_at ?? null,
      delivered_at: raw.delivered_at ?? null,
      read_at: raw.read_at ?? null,
      failed_at: raw.failed_at ?? null,

      to_address: raw.to_address ?? null,
      subject: raw.subject ?? null,
      body_preview: raw.body_preview ?? null,
      message_preview: (channel === 'EMAIL') ? null : (raw.body_preview ?? null),

      reference: raw.reference ?? null,
      provider_message_id: raw.provider_message_id ?? null,
      last_error: raw.last_error ?? null,

      created_by: raw.created_by ?? null,
      recipient_kind: raw.recipient_kind ?? null,
      recipient_id: raw.recipient_id ?? null,
      context_kind: raw.context_kind ?? null,
      context_id: raw.context_id ?? null,
      mailshot_run_id: raw.mailshot_run_id ?? null,
      document_template_id: raw.document_template_id ?? null,

      scheduled_for_utc: raw.scheduled_for_utc ?? null,
      next_attempt_at_utc: raw.next_attempt_at_utc ?? null,
      effective_ready_at_utc: raw.effective_ready_at_utc ?? null,

      schedule: {
        scheduled_for_utc: raw.scheduled_for_utc ?? null,
        next_attempt_at_utc: raw.next_attempt_at_utc ?? null,
        effective_ready_at_utc: raw.effective_ready_at_utc ?? null,
        queue_state: raw.queue_state ?? null,
        is_scheduled: !!raw.is_scheduled
      },

      provider: {
        provider_message_id: raw.provider_message_id ?? null,
        last_error: raw.last_error ?? null,
        delivery_status: raw.delivery_status ?? null
      },

      raw
    };
  };

  const qs = new URLSearchParams();
  qs.set('recipient_kind', kind);
  qs.set('recipient_id', rid);
  qs.set('limit', String(limit < 1 ? 1 : limit > 500 ? 500 : limit));
  qs.set('offset', String(offset < 0 ? 0 : offset));

  const res = await authFetch(API(`/api/comms/by-recipient?${qs.toString()}`));
  const payload = await safeJson(res);

  if (!res.ok) {
    const msg =
      (payload && typeof payload === 'object' && (payload.error || payload.message))
        ? String(payload.error || payload.message)
        : 'Failed to load recipient communications';
    throw new Error(msg);
  }

  const items = Array.isArray(payload && payload.items) ? payload.items.map(normalizeItem) : [];

  return {
    ok: true,
    recipient_kind: String(payload && payload.recipient_kind ? payload.recipient_kind : kind),
    recipient_id: String(payload && payload.recipient_id ? payload.recipient_id : rid),
    limit: Number(payload && payload.limit != null ? payload.limit : qs.get('limit')),
    offset: Number(payload && payload.offset != null ? payload.offset : qs.get('offset')),
    total_count: Number(payload && payload.total_count != null ? payload.total_count : items.length),
    items
  };
}

