async function showAllRecords(section = currentSection){
  const sec = String(section || currentSection || '').trim();

  window.__listState = window.__listState || {};
  const st = (window.__listState[sec] ||= {
    page: 1,
    pageSize: 50,
    total: null,
    hasMore: false,
    filters: null,
    sort: { key: null, dir: 'asc' }
  });

  if (!st.sort || typeof st.sort !== 'object') {
    st.sort = { key: null, dir: 'asc' };
  }

  const replacementFilters = (typeof buildMergedSectionFilters === 'function')
    ? buildMergedSectionFilters(sec, {}, { mode: 'replace', reason: 'showAllRecords' })
    : null;

  st.page = 1;
  st.total = null;
  st.hasMore = false;
  st.filters = replacementFilters && Object.keys(replacementFilters).length ? { ...(replacementFilters || {}) } : null;

  const nextDatasetKey = (() => {
    try {
      return String(getSummaryFingerprint(sec) || '').trim();
    } catch {
      return '';
    }
  })();

  if (typeof resetSelectionForDataset === 'function') {
    resetSelectionForDataset(sec, nextDatasetKey, 'showAllRecords');
  } else if (typeof clearSelection === 'function') {
    clearSelection(sec);
  }

  try { currentSection = sec; } catch {}

  const rows = await loadSection();
  renderSummary(rows);

  try { renderTools(); } catch {}
}



// Optional alias if other code calls clearFilters()
function clearFilters(section = currentSection){
  return showAllRecords(section);
}


// ===================== NEW HELPERS (UI + data) =====================

// Cache for global roles
// Cache for global roles
let __GLOBAL_ROLE_CODES_CACHE__ = null;
let __GLOBAL_ROLE_CODES_CACHE_TS__ = 0;
function invalidateGlobalRoleOptionsCache(){
  __GLOBAL_ROLE_CODES_CACHE__ = null;
  __GLOBAL_ROLE_CODES_CACHE_TS__ = 0;
}

// Load and dedupe all role codes from client defaults across all clients
// 🔧 CHANGE: truly global roles list (de-duplicated across ALL clients), with a short TTL cache.
// Works even when there is no active client in context (e.g., Candidate create).


async function loadGlobalRoleOptions() {
  const now = Date.now();
  const TTL_MS = 60_000;

  // Prefer our global cache
  if (Array.isArray(window.__GLOBAL_ROLE_CODES_ALL__) &&
      (now - (window.__GLOBAL_ROLE_CODES_ALL_TS__ || 0) < TTL_MS)) {
    return window.__GLOBAL_ROLE_CODES_ALL__;
  }

  // Fallback to legacy '__fallback__' if it’s fresh
  if (window.__GLOBAL_ROLE_CODES_CACHE__ &&
      window.__GLOBAL_ROLE_CODES_CACHE__['__fallback__'] &&
      (now - (window.__GLOBAL_ROLE_CODES_CACHE_TS__?.['__fallback__'] || 0) < TTL_MS)) {
    const arr = window.__GLOBAL_ROLE_CODES_CACHE__['__fallback__'];
    window.__GLOBAL_ROLE_CODES_ALL__ = arr.slice();
    window.__GLOBAL_ROLE_CODES_ALL_TS__ = now;
    return arr;
  }

  // ✅ Single-request roles fetch (backend provides global unique roles)
  const roles = [];
  try {
    const resp = await authFetch(API('/api/roles/global'));
    if (resp && resp.ok) {
      const json = await resp.json().catch(() => ({}));

      const raw =
        Array.isArray(json) ? json :
        (json && Array.isArray(json.roles)) ? json.roles :
        (json && Array.isArray(json.items)) ? json.items :
        [];

      const set = new Set();
      for (const r of raw) {
        const s = String(r || '').trim();
        if (!s) continue;
        set.add(s);
      }
      roles.push(...Array.from(set).sort((a,b)=> a.localeCompare(b)));
    } else {
      const t = resp ? await resp.text().catch(() => '') : '';
      throw new Error(t || 'roles/global fetch failed');
    }
  } catch {
    // If the endpoint fails, fall back to empty list (caller UI handles)
  }

  const arr = roles;

  // Save to both the new global cache AND the legacy fallback keys
  window.__GLOBAL_ROLE_CODES_ALL__ = arr;
  window.__GLOBAL_ROLE_CODES_ALL_TS__ = now;

  window.__GLOBAL_ROLE_CODES_CACHE__    = window.__GLOBAL_ROLE_CODES_CACHE__    || Object.create(null);
  window.__GLOBAL_ROLE_CODES_CACHE_TS__ = window.__GLOBAL_ROLE_CODES_CACHE_TS__ || Object.create(null);
  window.__GLOBAL_ROLE_CODES_CACHE__['__fallback__']    = arr;
  window.__GLOBAL_ROLE_CODES_CACHE_TS__['__fallback__'] = now;

  return arr;
}



// Render roles editor into a container; updates modalCtx.rolesState
function renderRolesEditor(container, rolesState, allRoleOptions){
  // Detect read-only (view mode) from the active modal frame
  const fr = (window.__modalStack || [])[ (window.__modalStack || []).length - 1 ] || null;
  // ✅ Treat 'create' same as 'edit' (editable)
  const readOnly = !fr || !(fr.mode === 'edit' || fr.mode === 'create');

  // Local, mutable copy of available options so we can refresh after adds/removes
  let roleOptions = Array.isArray(allRoleOptions) ? allRoleOptions.slice() : [];

  function markDirty() {
    try {
      const stack = window.__modalStack || [];
      const top = stack[stack.length - 1];
      if (top) top.isDirty = true;
      try { window.dispatchEvent(new CustomEvent('modal-dirty')); }
      catch { try { window.dispatchEvent(new Event('modal-dirty')); } catch(_) {} }
    } catch (_) {}
  }

  container.innerHTML = `
    <div class="roles-editor">
      <div class="roles-add" ${readOnly ? 'style="display:none"' : ''}>
        <select id="rolesAddSelect">
          <option value="">Add role…</option>
          ${roleOptions.map(code => `<option value="${code}">${code}</option>`).join('')}
        </select>
        <button id="rolesAddBtn" type="button">Add</button>
      </div>
      <ul id="rolesList" class="roles-list"></ul>
    </div>
  `;

  const sel = container.querySelector('#rolesAddSelect');
  const btn = container.querySelector('#rolesAddBtn');
  const ul  = container.querySelector('#rolesList');

  const byCode = (code) => (rolesState || []).find(r => String(r.code) === String(code));

  function availableOptions(){
    const picked = new Set((rolesState||[]).map(x => x.code));
    return roleOptions.filter(code => !picked.has(code));
  }

  function refreshAddSelect(){
    if (!sel) return;
    const opts = ['<option value="">Add role…</option>']
      .concat(availableOptions().map(code => `<option value="${code}">${code}</option>`))
      .join('');
    sel.innerHTML = opts;
  }

  function renderList(){
    ul.innerHTML = '';
    const arr = (rolesState||[]).slice().sort((a,b)=> (a.rank||0) - (b.rank||0));

    arr.forEach((item, idx) => {
      const li = document.createElement('li');
      li.className = 'role-item';
      li.draggable = !readOnly;
      li.dataset.index = String(idx);

      li.innerHTML = `
        <span class="drag" title="Drag to reorder" style="cursor:${readOnly?'default':'grab'}">⋮⋮</span>
        <span class="rank">${idx+1}.</span>
        <span class="code">${item.code}</span>
        <input class="label" type="text" placeholder="Optional label…" value="${item.label || ''}" ${readOnly?'disabled':''}/>
        <button class="remove" type="button" title="Remove" ${readOnly?'disabled style="display:none"':''}>✕</button>
      `;

      if (!readOnly) {
        li.querySelector('.remove').onclick = () => {
          rolesState = (rolesState || []).filter(r => r.code !== item.code);
          rolesState.forEach((r,i)=> r.rank = i+1);
          rolesState = normaliseRolesForSave(rolesState);
          window.modalCtx.rolesState = rolesState;
          markDirty();
          renderList(); refreshAddSelect();
        };

        li.querySelector('.label').oninput = (e) => {
          const rec = byCode(item.code);
          if (rec) rec.label = e.target.value;
          window.modalCtx.rolesState = rolesState;
          // dirty state handled by global tracker
        };

        // Drag payload
        li.addEventListener('dragstart', (e) => {
          const from = li.dataset.index || String(idx);
          try { e.dataTransfer.setData('text/x-role-index', from); } catch {}
          try { e.dataTransfer.setData('text/plain', from); } catch {}
          if (e.dataTransfer) e.dataTransfer.effectAllowed = 'move';
          li.classList.add('dragging');
        });
        li.addEventListener('dragend', () => {
          li.classList.remove('dragging');
          ul.querySelectorAll('.over').forEach(n => n.classList.remove('over'));
        });
      }

      ul.appendChild(li);
    });
  }

  // Delegate DnD only when editable
  if (!readOnly) {
    ul.addEventListener('dragover', (e) => {
      e.preventDefault();
      const overLi = e.target && e.target.closest('li.role-item');
      ul.querySelectorAll('.over').forEach(n => n.classList.remove('over'));
      if (overLi) overLi.classList.add('over');
      if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
    });

    ul.addEventListener('drop', (e) => {
      e.preventDefault();
      const toLi = e.target && e.target.closest('li.role-item');
      if (!toLi) return;

      let from = NaN;
      try { from = parseInt(e.dataTransfer.getData('text/x-role-index'), 10); } catch {}
      if (isNaN(from)) {
        try { from = parseInt(e.dataTransfer.getData('text/plain'), 10); } catch {}
      }
      const to = parseInt(toLi.dataset.index, 10);
      if (!Number.isInteger(from) || !Number.isInteger(to) || from === to) return;

      // Reorder against current rank-sorted view
      const view = (rolesState||[]).slice().sort((a,b)=> (a.rank||0) - (b.rank||0));
      const [moved] = view.splice(from, 1);
      view.splice(to, 0, moved);

      view.forEach((r,i)=> r.rank = i+1);
      rolesState = normaliseRolesForSave(view);
      window.modalCtx.rolesState = rolesState;

      markDirty();
      renderList();
      refreshAddSelect();
    });
  }

  // Add role (only in edit/create)
  if (!readOnly && btn) {
    btn.onclick = () => {
      const code = sel.value;
      if (!code) return;
      if ((rolesState||[]).some(r => r.code === code)) return; // no duplicates
      const nextRank = ((rolesState||[]).length || 0) + 1;
      rolesState = [...(rolesState||[]), { code, rank: nextRank }];
      rolesState = normaliseRolesForSave(rolesState);
      window.modalCtx.rolesState = rolesState;
      markDirty();
      renderList(); refreshAddSelect();
    };
  }

  // Expose a tiny API for refreshing options live
  container.__rolesEditor = {
    updateOptions(newOptions){
      roleOptions = Array.isArray(newOptions) ? newOptions.slice() : [];
      refreshAddSelect();
    }
  };

  // Initial paint
  refreshAddSelect();
  renderList();
}


// Drop dups (by code), sort by rank, rewrite rank 1..N
function normaliseRolesForSave(roles){
  const out = [];
  const seen = new Set();
  (Array.isArray(roles) ? roles : []).forEach(r => {
    const code = String(r.code || '').trim();
    if (!code) return;
    if (seen.has(code)) return;
    seen.add(code);
    out.push({ code, rank: Number(r.rank) || 0, label: r.label ? String(r.label) : undefined });
  });
  out.sort((a,b)=> a.rank - b.rank);
  out.forEach((r,i)=> r.rank = i+1);
  return out;
}

async function listClientHospitals(clientId){
  if (!clientId) return [];
  const url = API(`/api/clients/${clientId}/hospitals`);
  const APILOG = (typeof window !== 'undefined' && !!window.__LOG_API) || (typeof __LOG_API !== 'undefined' && !!__LOG_API);
  if (APILOG) console.log('[listClientHospitals] → GET', url);
  const r = await authFetch(url);
  if (APILOG) console.log('[listClientHospitals] ←', r.status, r.ok);
  const list = await toList(r);
  if (APILOG) console.log('[listClientHospitals] parsed length', Array.isArray(list) ? list.length : -1);
  return list;
}

function formatYmdToNiceDate(ymd) {
  const s = String(ymd || '').trim();
  if (!s) return '';
  const parts = s.split('-');
  if (parts.length !== 3) return s;

  const [Y, M, D] = parts.map(Number);
  if (!Y || !M || !D) return s;

  // Use UTC so it doesn't shift with timezone
  const d = new Date(Date.UTC(Y, M - 1, D));
  const days   = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  const dayName = days[d.getUTCDay()];
  const dayNum  = d.getUTCDate();       // 1..31
  const month   = months[d.getUTCMonth()];
  const year    = d.getUTCFullYear();

  return `${dayName} ${dayNum} ${month} ${year}`;
}


function formatRolesSummary(roles){
  if (!Array.isArray(roles) || !roles.length) return '';
  const sorted = roles.slice().sort((a,b)=> (a.rank||0)-(b.rank||0));
  return sorted.map(r => `${ordinal(r.rank)} ${r.code}`).join(', ');
}

function ordinal(n){
  const s = ["th","st","nd","rd"], v = n % 100;
  return n + (s[(v-20)%10] || s[v] || s[0]);
}

// Basic clients list for dropdowns (id + name)
async function listClientsBasic(){
  const r = await authFetch(API('/api/clients'));
  const rows = await r.json().catch(()=>({items:[]}));
  const list = Array.isArray(rows?.items) ? rows.items : (Array.isArray(rows) ? rows : []);
  return list.map(x => ({ id: x.id, name: x.name })).filter(x => x.id && x.name);
}

// Candidate care-package selectors must not inherit the general dropdown's
// first-page limit. Keep this reader local to the override workflow.
async function readCandidateRatePages(path, params = {}, pageSize = 200) {
  const result = [], seen = new Set();
  for (let offset = 0; ; offset += pageSize) {
    const query = new URLSearchParams({ ...params, limit: String(pageSize), offset: String(offset) });
    const response = await authFetch(API(`${path}?${query}`));
    if (!response?.ok) throw new Error('Care-package choices could not be loaded.');
    const payload = await response.json();
    const rows = Array.isArray(payload) ? payload : payload?.items;
    if (!Array.isArray(rows)) throw new Error('Care-package choices could not be loaded.');
    let added = 0;
    for (const row of rows) {
      if (!row?.id || seen.has(String(row.id))) continue;
      seen.add(String(row.id)); result.push(row); added++;
    }
    if (rows.length < pageSize) return result;
    // Do not loop forever or present a silently truncated list if pagination
    // stops advancing (for example, an upstream service ignores offset).
    if (!added) throw new Error('Care-package choices could not be loaded.');
  }
}

async function listCandidateRateClients() {
  const clients = await readCandidateRatePages('/api/clients');
  return clients.map(row => ({ id: String(row.id), name: String(row.name || '') }))
    .filter(row => row.name).sort((a, b) => a.name.localeCompare(b.name, 'en-GB', { sensitivity: 'base' }));
}

async function loadCandidateRateClientChoices() {
  const [clients, rates] = await Promise.all([
    listCandidateRateClients(),
    readCandidateRatePages('/api/rates/client-defaults', {}, 500)
  ]);
  // Defined windows establish membership, including historical windows.
  // The existing enabled/date/role/band checks still govern applying a rate.
  const eligibleIds = new Set(rates.map(row => String(row.client_id || '')));
  return { clients, eligible: clients.filter(row => eligibleIds.has(row.id)) };
}

function wireCandidateRateClientSearch(input, results, selection, { editable, load, onChange }) {
  let choices = [], loading = true, failed = false, active = -1, matches = [], loadSeq = 0;
  const close = () => {
    results.hidden = true;
    input.setAttribute('aria-expanded', 'false');
    input.removeAttribute('aria-activedescendant');
  };
  const render = () => {
    if (!editable || !input.isConnected) return;
    const shouldOpen = document.activeElement === input;
    const query = input.value.trim().toLocaleLowerCase('en-GB');
    matches = choices.filter(row => row.name.toLocaleLowerCase('en-GB').includes(query));
    active = -1;
    input.removeAttribute('aria-activedescendant');
    results.innerHTML = '';
    if (loading || failed || !matches.length) {
      const status = document.createElement('div');
      status.className = 'ctms-contract-suggestion-status'; status.setAttribute('role', 'status');
      status.textContent = loading ? 'Loading clients…' : failed ? 'Clients could not be loaded.' : 'No matching clients with care package rates.';
      results.append(status);
      if (failed) {
        const retry = document.createElement('button');
        retry.type = 'button'; retry.className = 'btn'; retry.textContent = 'Try again';
        retry.onclick = () => { input.focus(); void reload(); };
        results.append(retry);
      }
    } else {
      matches.forEach((row, index) => {
        const option = document.createElement('button');
        option.type = 'button'; option.tabIndex = -1; option.className = 'ctms-contract-suggestion';
        option.id = `${results.id}-option-${index}`;
        option.setAttribute('role', 'option'); option.setAttribute('aria-selected', 'false');
        option.textContent = row.name;
        option.onclick = () => choose(index);
        results.append(option);
      });
    }
    if (shouldOpen) {
      results.hidden = false; input.setAttribute('aria-expanded', 'true');
    } else {
      close();
    }
  };
  const choose = index => {
    const row = matches[index];
    if (!row || loading || failed) return;
    input.value = row.name; selection.value = row.id;
    input.focus(); close(); onChange();
  };
  const reload = async () => {
    const seq = ++loadSeq;
    loading = true; failed = false; choices = []; render();
    try {
      const data = await load();
      if (seq !== loadSeq || !input.isConnected) return;
      choices = data.eligible;
      const selected = data.clients.find(row => row.id === selection.value);
      if (selected) input.value = selected.name;
    } catch {
      if (seq !== loadSeq || !input.isConnected) return;
      failed = true;
    }
    loading = false; render();
  };
  input.addEventListener('focus', render);
  input.addEventListener('input', () => {
    if (!editable) return;
    if (selection.value) { selection.value = ''; onChange(); }
    render();
  });
  input.addEventListener('keydown', event => {
    if (event.isComposing || results.hidden) return;
    if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(); }
    if ((event.key === 'ArrowDown' || event.key === 'ArrowUp') && matches.length && !loading && !failed) {
      event.preventDefault();
      active = Math.max(0, Math.min(matches.length - 1, active + (event.key === 'ArrowDown' ? 1 : -1)));
      results.querySelectorAll('[role="option"]').forEach((option, index) => {
        option.setAttribute('aria-selected', String(index === active));
        if (index === active) {
          input.setAttribute('aria-activedescendant', option.id);
          option.scrollIntoView({ block: 'nearest' });
        }
      });
    }
    if (event.key === 'Enter' && active >= 0) { event.preventDefault(); choose(active); }
    if (event.key === 'Tab') close();
  });
  results.addEventListener('pointerdown', event => {
    if (event.pointerType === 'mouse') event.preventDefault();
  });
  input.addEventListener('blur', () => setTimeout(() => {
    if (document.activeElement !== input && !results.contains(document.activeElement)) close();
  }, 150));
  void reload();
}

// ===== UK date helpers & lightweight picker =====

function formatIsoToUk(iso){ // 'YYYY-MM-DD' -> 'DD/MM/YYYY'
  if (!iso || typeof iso !== 'string') return '';
  const m = iso.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return '';
  return `${m[3]}/${m[2]}/${m[1]}`;
}

function parseUkDateToIso(ddmmyyyy){ // 'DD/MM/YYYY' -> 'YYYY-MM-DD' or null
  if (!ddmmyyyy || typeof ddmmyyyy !== 'string') return null;
  const m = ddmmyyyy.trim().match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (!m) return null;
  const d = parseInt(m[1],10), mo=parseInt(m[2],10), y=parseInt(m[3],10);
  if (mo<1||mo>12||d<1||d>31||y<1900||y>3000) return null;
  const dt = new Date(Date.UTC(y, mo-1, d));
  if (dt.getUTCFullYear()!==y || (dt.getUTCMonth()+1)!==mo || dt.getUTCDate()!==d) return null; // invalid date like 31/02
  const mm = String(mo).padStart(2,'0'), dd = String(d).padStart(2,'0');
  return `${y}-${mm}-${dd}`;
}

// Minimal calendar that sits above modals; ESC / outside closes; keyboard nav supported
function attachUkDatePicker(inputEl, opts) {
  if (!inputEl) return;
  inputEl.setAttribute('autocomplete', 'off');

  const safeParseUkDateToIso = (value) => {
    const s = String(value == null ? '' : value).trim();
    if (!s) return null;
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
    try {
      if (typeof parseUkDateToIso === 'function') {
        const iso = String(parseUkDateToIso(s) || '').trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(iso)) return iso;
      }
    } catch {}
    const m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
    return m ? `${m[3]}-${m[2]}-${m[1]}` : null;
  };

  const safeFormatIsoToUk = (value) => {
    const s = String(value == null ? '' : value).trim();
    if (!s) return '';
    try {
      if (typeof formatIsoToUk === 'function') {
        const out = String(formatIsoToUk(s) || '').trim();
        if (out) return out;
      }
    } catch {}
    const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    return m ? `${m[3]}/${m[2]}/${m[1]}` : s;
  };

  const setIso = (v) => {
    if (!v) return null;
    const s = String(v).trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
    const parsed = safeParseUkDateToIso(s);
    return parsed || s;
  };

  const isElementUsable = () => {
    try {
      if (!inputEl) return false;
      if (!inputEl.isConnected) return false;
      if (inputEl.disabled) return false;
      const cs = window.getComputedStyle ? window.getComputedStyle(inputEl) : null;
      if (cs) {
        if (cs.display === 'none') return false;
        if (cs.visibility === 'hidden') return false;
      }
      const rects = (typeof inputEl.getClientRects === 'function') ? inputEl.getClientRects() : null;
      if (rects && rects.length === 0) return false;
      return true;
    } catch {
      return false;
    }
  };

  if (opts && typeof opts === 'object') {
    if ('minDate' in opts) inputEl._minIso = setIso(opts.minDate);
    if ('maxDate' in opts) inputEl._maxIso = setIso(opts.maxDate);
  }

  if (inputEl.__ukdpBound) {
    try {
      if (!isElementUsable() && typeof inputEl.__ukdpClose === 'function') {
        inputEl.__ukdpClose();
      }
    } catch {}
    if (inputEl.__ukdpPortal) {
      try { inputEl.__ukdpRepaint && inputEl.__ukdpRepaint(); } catch {}
    }
    return;
  }

  const getMinIso = () => inputEl._minIso || null;
  const getMaxIso = () => inputEl._maxIso || null;

  let portal = null;
  let current = null;
  let ignoreOutsideUntil = 0;
  let openTimer = null;

  const getNow = () => {
    try {
      if (typeof performance !== 'undefined' && performance && typeof performance.now === 'function') {
        return performance.now();
      }
    } catch {}
    return Date.now();
  };

  const clearScheduledOpen = () => {
    try {
      if (openTimer != null) {
        clearTimeout(openTimer);
      }
    } catch {}
    openTimer = null;
  };

  const closeActiveGlobal = (exceptEl) => {
    try {
      const active = window.__ukdpActive;
      if (active && active.inputEl && active.inputEl !== exceptEl && typeof active.close === 'function') {
        active.close();
      }
    } catch {}
  };

  function renderCalendarHtml(year, month0, selectedUk) {
    const selectedIso = safeParseUkDateToIso(selectedUk || '') || '';
    const sel = selectedIso ? selectedIso.split('-').map(Number) : null;

    const first = new Date(Date.UTC(year, month0, 1));
    const startDow = first.getUTCDay();
    const daysInMonth = new Date(Date.UTC(year, month0 + 1, 0)).getUTCDate();
    const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

    let grid = '<div class="cal-head" style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">' +
      '<a href="#" class="nav-prev" aria-label="Previous month">‹</a>' +
      `<div class="title" style="font-weight:600">${monthNames[month0]} ${year}</div>` +
      '<a href="#" class="nav-next" aria-label="Next month">›</a>' +
      '</div>';

    grid += '<div class="cal-grid" style="display:grid;grid-template-columns:repeat(7,2em);gap:2px;justify-items:center;align-items:center">';
    ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].forEach((d) => { grid += `<div style="font-size:12px;color:#666">${d}</div>`; });

    for (let i = 0; i < startDow; i += 1) grid += '<div></div>';

    for (let d = 1; d <= daysInMonth; d += 1) {
      const iso = `${year}-${String(month0 + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isSel = sel && sel[0] === year && (sel[1] - 1) === month0 && sel[2] === d;
      const allowed = dateAllowed(iso);
      grid += `<button type="button" class="day${isSel ? ' selected' : ''}" data-y="${year}" data-m="${month0}" data-d="${d}"` +
              ` style="width:2em;height:2em;border:1px solid #ddd;border-radius:4px;${allowed ? 'background:#fff' : 'background:#f4f4f4;color:#aaa'}" ${allowed ? '' : 'disabled'}>${d}</button>`;
    }

    grid += '</div>';
    return grid;
  }

  function dateAllowed(iso) {
    const minIso = getMinIso();
    const maxIso = getMaxIso();
    if (minIso && iso < minIso) return false;
    if (maxIso && iso > maxIso) return false;
    return true;
  }

  function positionPortal() {
    if (!portal) return;
    if (!isElementUsable()) {
      closePicker();
      return;
    }

    const r = inputEl.getBoundingClientRect();

    let left = Math.max(8, r.left);
    let top = Math.max(8, r.top + r.height + 6);

    const viewportWidth =
      window.innerWidth ||
      document.documentElement.clientWidth ||
      0;

    const viewportHeight =
      window.innerHeight ||
      document.documentElement.clientHeight ||
      0;

    const portalWidth = portal.offsetWidth || 0;
    const portalHeight = portal.offsetHeight || 0;

    if (viewportWidth && portalWidth && (left + portalWidth) > (viewportWidth - 8)) {
      left = Math.max(8, viewportWidth - portalWidth - 8);
    }

    if (viewportHeight && portalHeight && (top + portalHeight) > (viewportHeight - 8)) {
      const aboveTop = r.top - portalHeight - 6;
      top = aboveTop >= 8 ? aboveTop : Math.max(8, viewportHeight - portalHeight - 8);
    }

    portal.style.left = `${left}px`;
    portal.style.top = `${top}px`;
  }

  function repaintPortal() {
    if (!portal || !current) return;
    portal.innerHTML = renderCalendarHtml(current.year, current.month, inputEl.value);
    positionPortal();
  }

  function navMonth(delta) {
    if (!current) return;
    current.month += delta;
    if (current.month < 0) {
      current.month = 11;
      current.year -= 1;
    }
    if (current.month > 11) {
      current.month = 0;
      current.year += 1;
    }
    repaintPortal();
  }

  function onPortalClick(e) {
    const t = e.target;
    if (t && typeof t.matches === 'function' && t.matches('.nav-prev')) {
      e.preventDefault();
      navMonth(-1);
      return;
    }
    if (t && typeof t.matches === 'function' && t.matches('.nav-next')) {
      e.preventDefault();
      navMonth(1);
      return;
    }

    const dayBtn = t && typeof t.closest === 'function' ? t.closest('button.day') : null;
    if (dayBtn && !dayBtn.disabled) {
      const y = Number(dayBtn.dataset.y);
      const m = Number(dayBtn.dataset.m);
      const d = Number(dayBtn.dataset.d);
      const iso = `${y}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      inputEl.value = safeFormatIsoToUk(iso);
      closePicker();
      inputEl.dispatchEvent(new Event('input', { bubbles: true }));
      inputEl.dispatchEvent(new Event('change', { bubbles: true }));
    }
  }

  function onOutsidePointerDown(e) {
    if (!portal) return;
    if (getNow() < ignoreOutsideUntil) return;
    const t = e.target;
    if (portal.contains(t) || t === inputEl) return;
    closePicker();
  }

  function onFocusIn(e) {
    if (!portal) return;
    if (getNow() < ignoreOutsideUntil) return;
    const t = e.target;
    if (portal.contains(t) || t === inputEl) return;
    closePicker();
  }

  function onKeyDown(e) {
    if (!portal) return;
    if (e.key === 'Escape') {
      e.preventDefault();
      closePicker();
    }
  }

  function onAnyScroll() {
    if (!portal) return;
    if (!isElementUsable()) {
      closePicker();
      return;
    }
    positionPortal();
  }

  function closePicker() {
    clearScheduledOpen();
    if (!portal) return;

    try { document.removeEventListener('pointerdown', onOutsidePointerDown, true); } catch {}
    try { document.removeEventListener('focusin', onFocusIn, true); } catch {}
    try { document.removeEventListener('keydown', onKeyDown, true); } catch {}
    try { window.removeEventListener('resize', positionPortal); } catch {}
    try { window.removeEventListener('scroll', onAnyScroll, true); } catch {}
    try { portal.removeEventListener('click', onPortalClick); } catch {}

    try { portal.remove(); } catch {}
    portal = null;
    inputEl.__ukdpPortal = null;

    try {
      if (window.__ukdpActive && window.__ukdpActive.inputEl === inputEl) {
        window.__ukdpActive = null;
      }
    } catch {}
  }

  function openPicker() {
    clearScheduledOpen();

    if (!isElementUsable()) {
      closePicker();
      return;
    }

    closeActiveGlobal(inputEl);

    if (portal) {
      repaintPortal();
      return;
    }

    let today = new Date();
    if (inputEl.value) {
      const iso = safeParseUkDateToIso(inputEl.value);
      if (iso) {
        const parts = iso.split('-').map(Number);
        today = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
      }
    }

    current = { year: today.getUTCFullYear(), month: today.getUTCMonth() };

    portal = document.createElement('div');
    inputEl.__ukdpPortal = portal;
    portal.className = 'uk-datepicker-portal';
    portal.style.position = 'fixed';
    portal.style.zIndex = '99999';
    portal.style.background = '#fff';
    portal.style.border = '1px solid #ccc';
    portal.style.borderRadius = '8px';
    portal.style.boxShadow = '0 8px 24px rgba(0,0,0,0.15)';
    portal.style.padding = '8px';

    portal.innerHTML = renderCalendarHtml(current.year, current.month, inputEl.value);
    document.body.appendChild(portal);
    positionPortal();

    portal.addEventListener('click', onPortalClick);
    window.addEventListener('resize', positionPortal);
    window.addEventListener('scroll', onAnyScroll, true);
    document.addEventListener('keydown', onKeyDown, true);

    ignoreOutsideUntil = getNow() + 160;
    setTimeout(() => {
      if (!portal) return;
      try { document.addEventListener('pointerdown', onOutsidePointerDown, true); } catch {}
      try { document.addEventListener('focusin', onFocusIn, true); } catch {}
    }, 0);

    try {
      window.__ukdpActive = {
        inputEl,
        close: closePicker
      };
    } catch {}
  }

  function scheduleOpen() {
    if (!isElementUsable()) {
      closePicker();
      return;
    }
    if (portal) {
      repaintPortal();
      return;
    }
    clearScheduledOpen();
    openTimer = setTimeout(() => {
      openTimer = null;
      openPicker();
    }, 0);
  }

  function onOpenTrigger(ev) {
    try {
      if (ev && ev.type === 'pointerdown') {
        if (typeof ev.button === 'number' && ev.button !== 0) return;
      }
    } catch {}
    scheduleOpen();
  }

  function destroyBinding() {
    clearScheduledOpen();
    closePicker();
    try { inputEl.removeEventListener('focus', onOpenTrigger); } catch {}
    try { inputEl.removeEventListener('click', onOpenTrigger); } catch {}
    try { inputEl.removeEventListener('pointerdown', onOpenTrigger); } catch {}
    try { delete inputEl.__ukdpBound; } catch {}
    try { delete inputEl.__ukdpPortal; } catch {}
    try { delete inputEl.__ukdpRepaint; } catch {}
    try { delete inputEl.__ukdpClose; } catch {}
    try { delete inputEl.__ukdpDestroy; } catch {}
    try { delete inputEl.setMinDate; } catch {}
    try { delete inputEl.setMaxDate; } catch {}
  }

  inputEl.setMinDate = (minDate) => {
    inputEl._minIso = setIso(minDate);
    if (!isElementUsable()) {
      closePicker();
      return;
    }
    if (inputEl.__ukdpPortal) {
      try { inputEl.__ukdpRepaint && inputEl.__ukdpRepaint(); } catch {}
    }
  };

  inputEl.setMaxDate = (maxDate) => {
    inputEl._maxIso = setIso(maxDate);
    if (!isElementUsable()) {
      closePicker();
      return;
    }
    if (inputEl.__ukdpPortal) {
      try { inputEl.__ukdpRepaint && inputEl.__ukdpRepaint(); } catch {}
    }
  };

  inputEl.addEventListener('focus', onOpenTrigger);
  inputEl.addEventListener('click', onOpenTrigger);
  inputEl.addEventListener('pointerdown', onOpenTrigger);

  inputEl.__ukdpBound = true;
  inputEl.__ukdpRepaint = repaintPortal;
  inputEl.__ukdpClose = closePicker;
  inputEl.__ukdpDestroy = destroyBinding;
}

function headersFromRows(rows){
  if (!rows.length) return [];
  const keys = new Set(Object.keys(rows[0]));
  rows.forEach(r=> Object.keys(r).forEach(k=> keys.add(k)));
  return [...keys];
}



/* ===== UK date/time formatter helpers (display only) =====
   - Date-only 'YYYY-MM-DD' -> 'DD/MM/YYYY'
   - UTC timestamps -> 'DD/MM/YYYY HHMMhrs' (Europe/London, no seconds)
*/
function formatUkDate(isoDateStr){
  if (!isoDateStr || typeof isoDateStr !== 'string') return isoDateStr;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(isoDateStr);
  if (!m) return isoDateStr;
  const [,y,mo,d] = m;
  return `${d}/${mo}/${y}`;
}

