const APPROVED_EXPENSE_ROUTE_LABELS = new Set([
  'Electronic Expense',
  'Manual Expense',
  'QR Expense',
  'Expense'
]);

function isTimesheetAdjustmentReversal(row) {
  const correctionId = String(row?.correction_id || '').trim();
  const correctionKind = String(row?.correction_kind || '').trim().toUpperCase();
  const correctionOrigin = String(row?.adjustment_origin || '').trim().toUpperCase();
  const correctionSource = String(row?.correction_source_system || '').trim().toUpperCase();
  return !!(
    correctionId &&
    correctionKind === 'CHANGED_HOURS_REVERSAL' &&
    correctionOrigin === 'IMPORT_CORRECTION' &&
    ['NHSP', 'HEALTHROSTER'].includes(correctionSource)
  );
}

function formatTimesheetSummaryRoute(row) {
  if (!row?.timesheet_id && row?.candidate_expense_reservation) return 'Expense claim';
  if (row?.is_expense_only === true) {
    const label = String(row?.display_route_label || '').trim();
    return APPROVED_EXPENSE_ROUTE_LABELS.has(label) ? label : 'Expense';
  }
  if (isTimesheetAdjustmentReversal(row)) return 'Timesheet Adjustment';
  return String(formatDisplayValue('route_type', row?.route_type) ?? '');
}

function mountTimesheetCandidateSummary(cell, row) {
  if (row?.office_submission_mode_label === 'Import' && row?.candidate_hours_received === true) {
    const badge = document.createElement('span');
    badge.className = 'pill pill-ok';
    badge.textContent = 'Hours Submitted';
    cell.replaceChildren(badge);
  } else if (!row?.timesheet_id && row?.candidate_expense_reservation) {
    cell.textContent = String(row.candidate_expense_reservation.label || 'Expense claim needs checking');
  } else if (!row?.timesheet_id && row?.candidate_expense_reservation_error) {
    cell.textContent = 'Claim status unavailable';
  } else if (row?.timesheet_id && typeof window !== 'undefined') {
    window.CloudTMSCandidateOfficeBridge?.mountSummaryBadge?.(cell, row);
  }
}

function formatDisplayValue(key, val){
  if (val === null || val === undefined || val === '') return '—';
  if (typeof val === 'boolean') return val ? 'Yes' : 'No';

  const normEnum = (s) => String(s || '').trim().replace(/-/g, '_').toUpperCase();

  const titleCaseEnum = (s) => {
    const raw = normEnum(s).replace(/_/g, ' ').toLowerCase();
    const tc = raw.replace(/\b\w/g, (c) => c.toUpperCase());

    // Preserve common acronyms
    return tc
      .replace(/\bNhsp\b/g, 'NHSP')
      .replace(/\bHr\b/g, 'HR')
      .replace(/\bNhs\b/g, 'NHS')
      .replace(/\bVat\b/g, 'VAT');
  };

  const friendlyProcessingStatus = (s) => {
    const up = normEnum(s);
    const map = {
      READY_FOR_INVOICE: 'Ready to Invoice',
      PENDING_AUTH: 'Processed',
      UNASSIGNED: 'Unassigned',
      RATE_MISSING: 'Rate Missing'
    };
    return map[up] || titleCaseEnum(up);
  };

  const friendlyRouteType = (s) => {
    const up = normEnum(s);
    const map = {
      WEEKLY_NHSP: 'Weekly NHSP',
      WEEKLY_NHSP_ADJUSTMENT: 'Weekly NHSP Adjustment',
      WEEKLY_HEALTHROSTER: 'Weekly HealthRoster',
      WEEKLY_ELECTRONIC: 'Weekly Electronic',
      DAILY_ELECTRONIC: 'Daily Electronic',
      WEEKLY_MANUAL: 'Weekly Manual',
      DAILY_MANUAL: 'Daily Manual',
      UNKNOWN: 'Unknown'
    };
    return map[up] || titleCaseEnum(up);
  };

  const friendlySheetScope = (s) => {
    const up = normEnum(s);
    if (up === 'WEEKLY') return 'Weekly';
    if (up === 'DAILY') return 'Daily';
    return titleCaseEnum(up);
  };

  const friendlySubmissionMode = (s) => {
    const up = normEnum(s);
    if (up === 'MANUAL') return 'Manual';
    if (up === 'ELECTRONIC') return 'Electronic';
    return titleCaseEnum(up);
  };

  const friendlyInvoiceStatus = (s) => {
    const up = normEnum(s);
    if (up === 'DRAFT') return 'Draft';
    if (up === 'ON_HOLD') return 'On Hold';
    if (up === 'ISSUED') return 'Issued';
    if (up === 'PAID') return 'Paid';
    return titleCaseEnum(up);
  };

  // Friendly enum display (must happen before date heuristics)
  const k = String(key || '').toLowerCase();
  if (k === 'processing_status' || k === 'summary_stage') {
    return friendlyProcessingStatus(val);
  }
  if (k === 'route_type') {
    return friendlyRouteType(val);
  }
  if (k === 'sheet_scope') {
    return friendlySheetScope(val);
  }
  if (k === 'submission_mode') {
    return friendlySubmissionMode(val);
  }
  if (k === 'status') {
    return friendlyInvoiceStatus(val);
  }

  if (typeof val === 'string'){
    // date-only?
    if (/^\d{4}-\d{2}-\d{2}$/.test(val)) return formatUkDate(val);
    // ISO-ish timestamp?
    if (/\d{4}-\d{2}-\d{2}T/.test(val))  return formatUkTimestampFromUtc(val);
  }

  // Heuristic by column name
  if (typeof key === 'string' && (
      key.endsWith('_at_utc') ||
      key === 'created_at' || key === 'updated_at' ||
      key.endsWith('_timestamp') || key.endsWith('_utc')
    )){
    return formatUkTimestampFromUtc(val);
  }

  return String(val);
}


// === UPDATED: Summary renders role summary for candidates (computed from JSON) ===

function renderAuditTable(content, rows){
  const items = Array.isArray(rows) ? rows : [];

  const displayVal = (key, val) => {
    try {
      return (typeof formatDisplayValue === 'function') ? formatDisplayValue(key, val) : (val ?? '—');
    } catch {
      return (val ?? '—');
    }
  };

  const summarizeJson = (v) => {
    if (v == null) return '—';
    try {
      const s = JSON.stringify(v);
      if (!s) return '—';
      return s.length > 140 ? `${s.slice(0, 137)}…` : s;
    } catch {
      const s = String(v ?? '');
      return s || '—';
    }
  };

  content.innerHTML = '';

  const wrap = document.createElement('div');
  wrap.className = 'picker-table-wrap';

  const tbl = document.createElement('table');
  tbl.className = 'grid';

  const thead = document.createElement('thead');
  const trh = document.createElement('tr');
  [
    'Time',
    'Action',
    'Actor',
    'Role',
    'Object',
    'Object ID',
    'Reason',
    'Changes'
  ].forEach((label) => {
    const th = document.createElement('th');
    th.textContent = label;
    trh.appendChild(th);
  });
  thead.appendChild(trh);
  tbl.appendChild(thead);

  const tb = document.createElement('tbody');

  if (!items.length) {
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    td.colSpan = 8;
    td.className = 'mini';
    td.style.opacity = '0.75';
    td.textContent = 'No audit events found.';
    tr.appendChild(td);
    tb.appendChild(tr);
  } else {
    items.forEach((r) => {
      const tr = document.createElement('tr');
      tr.ondblclick = () => openAuditItem(r);

      const tdTime = document.createElement('td');
      tdTime.textContent = displayVal('ts_utc', r.ts_utc);
      tr.appendChild(tdTime);

      const tdAction = document.createElement('td');
      tdAction.innerHTML = `<span class="pill">${String(r.action || '—')}</span>`;
      tr.appendChild(tdAction);

      const tdActor = document.createElement('td');
      tdActor.textContent = displayVal('actor_display', r.actor_display);
      tr.appendChild(tdActor);

      const tdRole = document.createElement('td');
      tdRole.textContent = displayVal('actor_role_at_time', r.actor_role_at_time);
      tr.appendChild(tdRole);

      const tdObject = document.createElement('td');
      tdObject.textContent = displayVal('object_type', r.object_type);
      tr.appendChild(tdObject);

      const tdObjectId = document.createElement('td');
      tdObjectId.textContent = displayVal('object_id_text', r.object_id_text);
      tr.appendChild(tdObjectId);

      const tdReason = document.createElement('td');
      tdReason.textContent = displayVal('reason', r.reason);
      tr.appendChild(tdReason);

      const beforeSummary = summarizeJson(r.before_json);
      const afterSummary = summarizeJson(r.after_json);
      const changesText =
        (beforeSummary === '—' && afterSummary === '—')
          ? '—'
          : `Before: ${beforeSummary} • After: ${afterSummary}`;

      const tdChanges = document.createElement('td');
      tdChanges.textContent = changesText;
      tdChanges.title = changesText;
      tr.appendChild(tdChanges);

      tb.appendChild(tr);
    });
  }

  tbl.appendChild(tb);
  wrap.appendChild(tbl);
  content.appendChild(wrap);
}
async function apiListAuditEvents(opts = {}) {
  const src = (opts && typeof opts === 'object') ? opts : {};

  const toInt = (v, dflt) => {
    const n = Number(v);
    return Number.isFinite(n) ? Math.trunc(n) : dflt;
  };

  const limit = Math.min(500, Math.max(1, toInt(src.limit, 50)));
  const offset = Math.max(0, toInt(src.offset, 0));

  const search = String(src.search || src.q || '').trim();
  const action = String(src.action || '').trim();
  const objectType = String(src.object_type || src.objectType || '').trim();
  const actorDisplay = String(src.actor_display || src.actor || '').trim();
  const sortBy = String(src.sort_by || src.sortBy || 'ts_utc').trim();
  const sortDir = String(src.sort_dir || src.sortDir || 'desc').trim().toLowerCase();

  const qs = new URLSearchParams();
  qs.set('limit', String(limit));
  qs.set('offset', String(offset));
  if (search) qs.set('search', search);
  if (action) qs.set('action', action);
  if (objectType) qs.set('object_type', objectType);
  if (actorDisplay) qs.set('actor_display', actorDisplay);
  if (sortBy) qs.set('sort_by', sortBy);
  if (sortDir) qs.set('sort_dir', sortDir);

  const safeJson = async (res) => { try { return await res.json(); } catch { return null; } };

  const normalizeRow = (row) => {
    const raw = (row && typeof row === 'object') ? row : {};
    return {
      id: raw.id != null ? String(raw.id) : '',
      ts_utc: raw.ts_utc ?? null,
      actor_user_id: raw.actor_user_id != null ? String(raw.actor_user_id) : null,
      actor_display: raw.actor_display ?? null,
      actor_role_at_time: raw.actor_role_at_time ?? null,
      object_type: raw.object_type ?? null,
      object_id_text: raw.object_id_text ?? null,
      action: raw.action ?? null,
      before_json: (raw.before_json && typeof raw.before_json === 'object') ? raw.before_json : raw.before_json ?? null,
      after_json: (raw.after_json && typeof raw.after_json === 'object') ? raw.after_json : raw.after_json ?? null,
      reason: raw.reason ?? null,
      ip: raw.ip ?? null,
      user_agent: raw.user_agent ?? null,
      correlation_id: raw.correlation_id ?? null,
      raw
    };
  };

  const res = await authFetch(API(`/api/audit-events?${qs.toString()}`));
  const payload = await safeJson(res);

  if (!res.ok) {
    const msg =
      (payload && typeof payload === 'object' && (payload.error || payload.message))
        ? String(payload.error || payload.message)
        : 'Failed to load audit events';
    throw new Error(msg);
  }

  const rows =
    Array.isArray(payload) ? payload :
    (payload && Array.isArray(payload.items)) ? payload.items :
    (payload && Array.isArray(payload.rows)) ? payload.rows :
    [];

  return {
    ok: true,
    items: rows.map(normalizeRow),
    total_count:
      (payload && typeof payload.total_count === 'number') ? Number(payload.total_count) :
      (payload && typeof payload.count === 'number') ? Number(payload.count) :
      (payload && typeof payload.total === 'number') ? Number(payload.total) :
      null,
    limit:
      (payload && typeof payload.limit === 'number') ? Number(payload.limit) : limit,
    offset:
      (payload && typeof payload.offset === 'number') ? Number(payload.offset) : offset
  };
}

