    out.client_is_nhsp = toBool(out.client_is_nhsp);
    out.hr_validation_required_for_invoice = toBool(out.hr_validation_required_for_invoice);
    out.validation_pre_validated = toBool(out.validation_pre_validated);
    out.hr_validation_satisfied = toBool(out.hr_validation_satisfied);
    out.hr_validation_awaiting = toBool(out.hr_validation_awaiting);
    out.has_deviation_marker = toBool(out.has_deviation_marker);
