      is_hydrated: false,
      hydration_required: true,
      slim_context: true,
      profile: 'status_header',
      context_profile: 'status_header',
      header_loaded: true,
      header_only: true,
      editor_loaded: false,
      evidence_loaded: false,
      compare_loaded: false,
