              current_timesheet_id: suppressedTimesheetId || null,
              expected_timesheet_id: trimStr(suppressedActiveRow.expected_timesheet_id || suppressedTimesheetId || '') || null,
              contract_week_id: suppressedContractWeekId || null,
              summary_stage: suppressedActiveRow.summary_stage || null,
