      const rightPx = Math.max(400, total * (RIGHT_RAIL_PCT / 100));
      const minPctByPx = (MIN_LEFT_PX / total) * 100;
      const maxPctByPreview = ((total - rightPx - MIN_PREVIEW_PX) / total) * 100;
      const hardMin = Math.max(MIN_LEFT_PCT, minPctByPx);
      const hardMax = Math.min(MAX_LEFT_PCT, maxPctByPreview);
      const lower = Math.min(hardMin, hardMax);
      const upper = Math.max(hardMin, hardMax);
