  const dv = (st.bulkAuthoriseDockedEvidenceViewer && typeof st.bulkAuthoriseDockedEvidenceViewer === 'object') ? st.bulkAuthoriseDockedEvidenceViewer : {};
  if (!dv.open) return '';
