    const parts = raw.split('|');
    const tab = trimStr(parts[0] || '').toLowerCase();
    if (!tab) return '';
    const targetId = trimStr(parts[1] || '');
    const storageKey = trimStr(parts.slice(2).join('|') || '').replace(/^\/+/, '');
