    'same-row-status-refresh',
    'same-row refresh',
    'row patch apply',
    'successful same-row patch application',
    'post-save-refresh',
    'post-authorise-refresh',
    'post-authorize-refresh',
    'post-unauthorise-refresh',
    'post-unauthorize-refresh',
    'bulk-authorise-patch',
    'bulk-unauthorise-patch',
