      state: 'load-failed',
      template_id: trimStr((restored && restored.template_id) || ''),
      requested_template_id: tid,
      restored_to_clean: !!(restored && restored.restored_to_clean),
      error_message: String(e?.message || e || 'Could not load the selected template.')
