          const frag = document.createDocumentFragment();
          const beforeSpacer = createCaretSpacerTextNode();
          const afterSpacer = createCaretSpacerTextNode();
          frag.appendChild(beforeSpacer);
          frag.appendChild(node);
          frag.appendChild(afterSpacer);
