    state.pending_row_id = '';
    state.pending_page = null;
    state.reason = String(reason || 'reset');
    state.dataset_key = fp;
    state.sort_key = effectiveSort.key;
    state.sort_dir = effectiveSort.dir;

    if (!preserveActiveRow) state.active_row_id = '';
    if (!preserveFocus) state.has_focus = false;

