    id: weekId,
    contract_week_id: weekId,
    timesheet_id: null,
    submission_mode: '',
    submission_mode_snapshot: snap,
    processing_status: null,
    ready_to_pay: null,
    paid_at_utc: null,
    locked_by_invoice_id: null,
    locked_by_invoice_number: null,
    total_hours: null,
    total_pay_ex_vat: null,
