      'clear-all-lines',
      'clear-lines',
      'apply-schedule',
      'preview-schedule',
      'daily-preview',
      'daily-apply',
      'apply-daily-schedule',
      'preview-daily-schedule',
      'extra-shift-add',
      'extra-shift-remove',
      'weekly-line-add',
      'weekly-line-remove',
      'add-weekly-line',
      'remove-weekly-line',
      'add-line',
      'remove-line',
      'extra-break-add',
      'extra-break-remove',
      'segment-edit',
      'segment-save',
      'segment-reset',
      'segment-add',
      'segment-remove',
      'copy-line',
      'copy-shift',
      'paste-line',
      'paste-shift',
      'duplicate-line',
      'duplicate-shift',
      'delete-line',
      'delete-shift',
