async function commitContractCalendarStage(contractId) {
  const LOG_CAL = (typeof window.__LOG_CAL === 'boolean') ? window.__LOG_CAL : true;
  const L = (...a)=> { if (LOG_CAL) console.log('[CAL][commit]', ...a); };
  const W = (...a)=> { if (LOG_CAL) console.warn('[CAL][commit]', ...a); };
  const E = (...a)=> { if (LOG_CAL) console.error('[CAL][commit]', ...a); };

  // ✅ NEW: UI helper
  const showUnplanSummary = (resp, opts = {}) => {
    try {
      const blocked = Array.isArray(resp?.blocked_weeks) ? resp.blocked_weeks : [];

      let msg = '';
      if (!blocked.length) {
        msg = (opts.removeAll)
          ? `All unsubmitted weeks were removed successfully.`
          : `Calendar updated successfully.`;
      } else {
        const statusLabel = (b) => {
          if (b?.paid) return 'PAID';
          if (b?.invoiced) return 'INVOICED';
          if (b?.authorised) return 'AUTHORISED';
          if (b?.tsfin_processing_status) return String(b.tsfin_processing_status).toUpperCase();
          if (b?.contract_week_status) return String(b.contract_week_status).toUpperCase();
          return 'HAS_TIMESHEET';
        };

        const lines = blocked
          .slice(0, 12)
          .map(b => `• W/E ${String(b.week_ending_date || '')} (${statusLabel(b)})`)
          .join('\n');

        msg =
          (opts.removeAll)
            ? `Unsubmitted weeks were removed, but ${blocked.length} week(s) were kept because they already have a timesheet:\n\n${lines}`
            : `Some dates could not be removed because a timesheet already exists (${blocked.length} week(s)):\n\n${lines}`;

        if (blocked.length > 12) msg += `\n\n…and ${blocked.length - 12} more.`;
      }

      if (typeof showModalHint === 'function') {
        showModalHint(msg, blocked.length ? 'warn' : 'ok');
      } else if (typeof window.__toast === 'function') {
        window.__toast(blocked.length ? 'Removed (some weeks kept)' : 'Removed');
      } else {
        alert(msg);
      }
    } catch {}
  };

  const { addRanges, removeRanges, additionals, removeAll } = buildPlanRangesFromStage(contractId);
  L('BEGIN', { contractId, addRanges, removeRanges, additionals, removeAll });

  // If "remove all" is staged, we only perform the single bulk unplan and exit.
  if (removeAll) {
    let resp = null;

    if (removeRanges.length) {
      const payload = {
        when_timesheet_exists: 'skip',
        empty_week_action: 'delete',
        ranges: removeRanges
      };
      L('DELETE /plan-ranges (removeAll)', payload);
      try {
        resp = await contractsUnplanRanges(contractId, payload);
        L('DELETE /plan-ranges ←', resp);
      } catch (err) {
        E('unplan-ranges (removeAll) failed', err);
        throw err;
      }
    } else {
      L('removeAll=true but no removeRanges built');
    }

    // ✅ NEW: show message
    if (resp) showUnplanSummary(resp, { removeAll: true });

    clearContractCalendarStageState(contractId);
    L('DONE: stage cleared for', contractId);
    return { ok: true, detail: 'calendar saved', removedAll: true, unplan_result: resp || null };
  }

  // Otherwise, proceed with normal sequence: adds → removes → additionals.
  if (addRanges.length) {
    const payload = {
      extend_contract_window: true,
      ranges: addRanges
    };
    L('POST /plan-ranges', payload);
    try {
      const resp = await contractsPlanRanges(contractId, payload);
      L('POST /plan-ranges ←', resp);
      if (!resp || typeof resp !== 'object') W('plan-ranges returned unexpected response', resp);
    } catch (err) {
      E('plan-ranges failed', err);
      throw err;
    }
  } else {
    L('No addRanges to commit');
  }

  if (removeRanges.length) {
    const payload = {
      when_timesheet_exists: 'skip',
      empty_week_action: 'cancel',
      ranges: removeRanges
    };
    L('DELETE /plan-ranges', payload);
    try {
      const resp = await contractsUnplanRanges(contractId, payload);
      L('DELETE /plan-ranges ←', resp);

      // ✅ NEW: show message if blocked weeks exist
      if (resp) showUnplanSummary(resp, { removeAll: false });

    } catch (err) {
      E('unplan-ranges failed', err);
      throw err;
    }
  } else {
    L('No removeRanges to commit');
  }

  if (additionals.length) {
    L('Committing additional weeks…', { count: additionals.length });
    for (const g of additionals) {
      try {
        L('Create additional for baseWeekId', g.baseWeekId, 'dates=', g.dates);
        const addRow = await contractWeekCreateAdditional(g.baseWeekId);
        L('additional created ←', addRow);
        const payload = { add: g.dates.map(d => ({ date: d })), merge: 'append' };
        L('PATCH /contract-weeks/:id/plan', { week_id: addRow.id, payload });
        const resp = await contractWeekPlanPatch(addRow.id, payload);
        L('PATCH /contract-weeks/:id/plan ←', resp);
      } catch (err) {
        E('additional week flow failed', err);
        throw err;
      }
    }
  } else {
    L('No additional week patches to commit');
  }

  clearContractCalendarStageState(contractId);
  L('DONE: stage cleared for', contractId);
  return { ok: true, detail: 'calendar saved', removedAll: false };
}



function openContractDuplicateStudio(contractId) {
  const source = { ...(window.modalCtx?.data || {}) };
  const payMethod = String(source.pay_method_snapshot || 'PAYE').trim().toUpperCase();
  const payMethodAvailable = ['PAYE', 'UMBRELLA'].includes(payMethod);
  const payMethodLabel = payMethod === 'UMBRELLA' ? 'Umbrella' : 'PAYE';
  const rootId = `contractDuplicateStudio_${Date.now()}_${Math.random().toString(36).slice(2)}`;
  const state = {
    count: 1,
    slots: [{ candidate_id:null, candidate_name:'', candidate_meta:'' }],
    rows: [],
    query: '',
    job: '',
    city: '',
    sort: 'last_name',
    direction: 1,
    loading: false,
    error: '',
    requestSerial: 0
  };

  const esc = (value) => escapeHtml(String(value ?? ''));
  const displayCandidate = (row) => {
    const first = String(row?.first_name || '').trim();
    const last = String(row?.last_name || '').trim();
    return `${last}${last && first ? ', ' : ''}${first}`.trim() || String(row?.display_name || row?.name || 'Candidate');
  };
  const candidateMeta = (row) => [
    row?.primary_job_title || row?.roles_display || '',
    row?.city || row?.town || ''
  ].map(v => String(v || '').trim()).filter(Boolean).join(' · ');

  const resizeSlots = (count) => {
    const next = Math.max(1, Math.min(10, Number(count) || 1));
    state.count = next;
    while (state.slots.length < next) state.slots.push({ candidate_id:null, candidate_name:'', candidate_meta:'' });
    if (state.slots.length > next) state.slots.length = next;
  };

  const filteredRows = () => {
    const jobNeedle = state.job.trim().toLowerCase();
    const cityNeedle = state.city.trim().toLowerCase();
    const rows = state.rows.filter((row) => {
      const job = String(row?.primary_job_title || row?.roles_display || '').toLowerCase();
      const city = String(row?.city || row?.town || '').toLowerCase();
      return (!jobNeedle || job.includes(jobNeedle)) && (!cityNeedle || city.includes(cityNeedle));
    });
    const key = state.sort;
    return rows.sort((a, b) => String(a?.[key] || '').localeCompare(String(b?.[key] || ''), undefined, { sensitivity:'base' }) * state.direction);
  };

  const bodyHtml = () => {
    const sourceDates = `${formatIsoToUk(source.start_date) || source.start_date || '—'} – ${formatIsoToUk(source.end_date) || source.end_date || '—'}`;
    const assigned = new Set(state.slots.map(slot => String(slot.candidate_id || '')).filter(Boolean));
    const rows = filteredRows();
    const arrow = (key) => state.sort === key ? (state.direction === 1 ? ' ↑' : ' ↓') : '';
    return `
      <div class="ctms-contract-duplicate-hero">
        <div><span class="ctms-policy-card__eyebrow">CONTRACT WORKFLOW</span><h2>Create matching vacancies</h2><p>${esc(source.client_name || 'Client')} · ${esc(source.role || 'Role')} · ${esc(sourceDates)}</p></div>
        <label class="ctms-contract-duplicate-count"><span>Contracts</span><input class="input" type="number" min="1" max="10" step="1" value="${state.count}" data-duplicate-count></label>
      </div>
      <div class="ctms-contract-duplicate-grid">
        <section class="ctms-contract-duplicate-pane" aria-labelledby="duplicateCandidateHeading">
          <header class="ctms-contract-duplicate-pane__head"><h3 id="duplicateCandidateHeading">Find candidates</h3><p>${esc(payMethodLabel)} candidates only. Tick a person to assign the next vacant copy.</p></header>
          <div class="ctms-contract-duplicate-filters">
            <input class="input" data-duplicate-query value="${esc(state.query)}" placeholder="Search name…" aria-label="Search candidate name">
            <input class="input" data-duplicate-job value="${esc(state.job)}" placeholder="Primary job title" aria-label="Filter by primary job title">
            <input class="input" data-duplicate-city value="${esc(state.city)}" placeholder="City" aria-label="Filter by city">
          </div>
          <div class="ctms-contract-duplicate-table-wrap">
            <table class="ctms-contract-duplicate-table">
              <thead><tr><th>Assign</th><th><button type="button" data-duplicate-sort="last_name">Surname${arrow('last_name')}</button></th><th><button type="button" data-duplicate-sort="first_name">First name${arrow('first_name')}</button></th><th><button type="button" data-duplicate-sort="primary_job_title">Primary job title${arrow('primary_job_title')}</button></th><th><button type="button" data-duplicate-sort="city">City${arrow('city')}</button></th></tr></thead>
              <tbody>
                ${state.loading ? `<tr><td colspan="5" class="hint">Searching candidates…</td></tr>` : ''}
                ${!state.loading && !rows.length ? `<tr><td colspan="5" class="hint">${state.query.trim().length < 2 ? 'Type at least 2 letters to search.' : 'No matching candidates.'}</td></tr>` : ''}
                ${rows.map(row => {
                  const id = String(row.id || row.candidate_id || '');
                  return `<tr><td><input type="checkbox" data-duplicate-candidate="${esc(id)}" ${assigned.has(id) ? 'checked' : ''} aria-label="Assign ${esc(displayCandidate(row))}"></td><td>${esc(row.last_name || '')}</td><td>${esc(row.first_name || '')}</td><td>${esc(row.primary_job_title || row.roles_display || '—')}</td><td>${esc(row.city || row.town || '—')}</td></tr>`;
                }).join('')}
              </tbody>
            </table>
          </div>
        </section>
        <section class="ctms-contract-duplicate-pane" aria-labelledby="duplicateVacancyHeading">
          <header class="ctms-contract-duplicate-pane__head"><h3 id="duplicateVacancyHeading">Contracts to create</h3><p>Unassigned copies are allowed. Nothing is created until you select Create contracts.</p></header>
          <div class="ctms-contract-duplicate-slots">
            ${state.slots.map((slot, index) => `<article class="ctms-contract-duplicate-slot"><span class="ctms-contract-duplicate-slot__number">${index + 1}</span><div><strong>${esc(slot.candidate_name || 'Unassigned vacancy')}</strong><span>${esc(slot.candidate_meta || (slot.candidate_id ? 'Candidate assigned' : 'Assign now or leave vacant'))}</span></div>${slot.candidate_id ? `<button type="button" class="btn btn-outline" data-duplicate-remove="${index}">Remove</button>` : ''}</article>`).join('')}
          </div>
        </section>
      </div>
      <div class="ma-error ${state.error ? 'is-visible' : ''}" role="alert">${esc(state.error)}</div>`;
  };

  let searchTimer = 0;
  const paint = () => {
    const root = document.getElementById(rootId);
    if (!root) return;
    root.innerHTML = bodyHtml();
    wire(root);
  };
  const fetchRows = async () => {
    const query = state.query.trim();
    if (!payMethodAvailable) { state.rows = []; state.loading = false; state.error = 'The source Contract pay method is unavailable. Reopen the Contract before duplicating.'; paint(); return; }
    if (query.length < 2) { state.rows = []; state.loading = false; paint(); return; }
    const serial = ++state.requestSerial;
    state.loading = true;
    state.error = '';
    paint();
    try {
      const params = new URLSearchParams({ format:'picker', q:query, page:'1', page_size:'25', pay_method:payMethod });
      const response = await authFetch(API(`/api/search/candidates?${params.toString()}`));
      if (!response?.ok) throw new Error('Candidate search is temporarily unavailable.');
      const payload = await response.json();
      if (serial !== state.requestSerial) return;
      state.rows = Array.isArray(payload) ? payload : (Array.isArray(payload?.items) ? payload.items : (Array.isArray(payload?.rows) ? payload.rows : []));
    } catch (error) {
      if (serial !== state.requestSerial) return;
      state.rows = [];
      state.error = error?.message || 'Candidate search is temporarily unavailable.';
    } finally {
      if (serial === state.requestSerial) { state.loading = false; paint(); }
    }
  };
  const dirty = () => {
    const frame = window.__getModalFrame?.();
    if (frame?.kind === 'contract-duplicate-studio') { frame.isDirty = true; frame._updateButtons?.(); }
  };
  const wire = (root) => {
    root.querySelector('[data-duplicate-count]')?.addEventListener('change', (event) => { resizeSlots(event.target.value); dirty(); paint(); });
    root.querySelector('[data-duplicate-query]')?.addEventListener('input', (event) => { state.query = event.target.value; clearTimeout(searchTimer); searchTimer = setTimeout(fetchRows, 260); });
    root.querySelector('[data-duplicate-job]')?.addEventListener('input', (event) => { state.job = event.target.value; paint(); });
    root.querySelector('[data-duplicate-city]')?.addEventListener('input', (event) => { state.city = event.target.value; paint(); });
    root.querySelectorAll('[data-duplicate-sort]').forEach(button => button.addEventListener('click', () => { const key = button.dataset.duplicateSort; if (state.sort === key) state.direction *= -1; else { state.sort = key; state.direction = 1; } paint(); }));
    root.querySelectorAll('[data-duplicate-remove]').forEach(button => button.addEventListener('click', () => { const index = Number(button.dataset.duplicateRemove); if (state.slots[index]) state.slots[index] = { candidate_id:null, candidate_name:'', candidate_meta:'' }; dirty(); paint(); }));
    root.querySelectorAll('[data-duplicate-candidate]').forEach(box => box.addEventListener('change', () => {
      const id = String(box.dataset.duplicateCandidate || '');
      const existing = state.slots.findIndex(slot => String(slot.candidate_id || '') === id);
      if (!box.checked && existing >= 0) state.slots[existing] = { candidate_id:null, candidate_name:'', candidate_meta:'' };
      if (box.checked && existing < 0) {
        const vacancy = state.slots.findIndex(slot => !slot.candidate_id);
        if (vacancy < 0) { state.error = 'All contract copies are assigned. Increase the number of contracts or remove an assignment.'; paint(); return; }
        const row = state.rows.find(candidate => String(candidate.id || candidate.candidate_id || '') === id);
        state.slots[vacancy] = { candidate_id:id, candidate_name:displayCandidate(row), candidate_meta:candidateMeta(row) };
      }
      state.error = '';
      dirty();
      paint();
    }));
  };

  const save = async () => {
    state.error = '';
    const conflicts = [];
    for (const slot of state.slots.filter(item => item.candidate_id)) {
      const overlap = await checkContractOverlap({ candidate_id:slot.candidate_id, start_date:source.start_date, end_date:source.end_date, ignore_contract_id:null });
      if (overlap?.has_overlap) conflicts.push(`${slot.candidate_name} is already booked between ${formatIsoToUk(source.start_date)} and ${formatIsoToUk(source.end_date)}.`);
    }
    if (conflicts.length) {
      const answer = await openUiConfirmModal({ title:'Existing bookings found', message:`${conflicts.join('\n')}\n\nDo you wish to proceed anyway?`, confirm_label:'Create anyway', cancel_label:'Review assignments', confirm_class:'btn btn-primary', kind:'contract-duplicate-overlap' });
      if (!answer?.confirmed) return false;
    }
    const result = await duplicateContract(contractId, {
      count: state.count,
      assignments: state.slots.map(slot => slot.candidate_id || null),
      expected_source_updated_at: source.updated_at || null,
      request_key: `contract-duplicate:${crypto.randomUUID()}`
    });
    if (!result?.ok) { state.error = result?.message || 'The matching contracts could not be created.'; paint(); return false; }
    window.__toast?.(`${result.count || state.count} matching contract${(result.count || state.count) === 1 ? '' : 's'} created`);
    try { await renderAll(); } catch {}
    return { ok:true, saved:result };
  };

  const wireLiveRoot = () => {
    const root = document.getElementById(rootId);
    if (root) wire(root);
  };
  showModal('Duplicate Contract', [{ key:'duplicate', title:'Assign candidates' }], () => `<div id="${rootId}" class="tabc ctms-contract-duplicate-studio">${bodyHtml()}</div>`, save, true, wireLiveRoot, { kind:'contract-duplicate-studio', noParentGate:true, forceEdit:true, runOnRender:true, primaryLabel:'Create contracts', dirtyClosePolicy:'confirm-discard-close' });
  setTimeout(wireLiveRoot, 0);
}

async function duplicateContract(contractId, { count, assignments = [], expected_source_updated_at = null, request_key = null } = {}) {
  const n = Number(count || 1);
  if (!Number.isInteger(n) || n < 1 || n > 10) {
    return { ok: false, message: 'count must be an integer between 1 and 10' };
  }

  try {
    const url = API(`/api/contracts/${encodeURIComponent(contractId)}/duplicate`);
    const res = await authFetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ count: n, assignments, expected_source_updated_at, request_key })
    });

    // Non-2xx → try to surface a useful error
    if (!res.ok) {
      let msg = `Duplicate failed (${res.status})`;
      try {
        const txt = await res.text();
        if (txt) msg = txt;
      } catch {}
      return { ok: false, message: msg };
    }

    let data = null;
    try {
      data = await res.json();
    } catch {
      data = null;
    }

    // Backend returns: { source_contract_id, count, duplicates: [...] }
    return {
      ok: true,
      ...(data || {}),
    };
  } catch (e) {
    return {
      ok: false,
      message: e?.message || 'Duplicate failed'
    };
  }
}














































































// ================== Timesheet helpers ==================

async function fetchTimesheetDetails(timesheetId) {
  const LOGM = (typeof window.__LOG_MODAL === 'boolean') ? window.__LOG_MODAL : false;
  const L    = (...a) => { if (LOGM) console.log('[TS][DETAILS]', ...a); };
  const GC   = (label) => { if (LOGM) console.groupCollapsed('[TS][DETAILS]', label); };
  const GE   = () => { if (LOGM) console.groupEnd(); };

  if (!timesheetId) {
    throw new Error('fetchTimesheetDetails: timesheetId is required');
  }

  const encId = encodeURIComponent(timesheetId);
  const url   = API(`/api/timesheets/${encId}/details`);
  GC('request');
  L('→ GET', { url, timesheetId });

  let res;
  try {
    res = await authFetch(url);
  } catch (err) {
    L('network error', { url, error: err });
    GE();
    throw err;
  }

  const text = await res.text().catch(() => '');
  let json = null;
  try { json = text ? JSON.parse(text) : {}; } catch { json = null; }

  if (!res.ok) {
    const msg =
      (json && typeof json === 'object' && (json.message || json.error))
        ? String(json.message || json.error)
        : (text || `Timesheet details failed (${res.status})`);

    const err = new Error(msg);
    err.status = res.status;
    err.body = text || '';
    err.json = json;
    L('server error', { status: res.status, bodyPreview: (text || '').slice(0, 400), json });
    GE();
    throw err;
  }

  // If parse failed but HTTP was OK, treat as empty object (defensive)
  if (!json || typeof json !== 'object') json = {};

  const timesheet   = json.timesheet  || null;
  const tsfin       = json.tsfin      || null;
  const validations = Array.isArray(json.validations) ? json.validations : [];
  const shifts      = Array.isArray(json.shifts)      ? json.shifts      : [];

  // ✅ Preserve authoritative payment-state payload returned by /details.
  // This is the only source the Timesheet modal payment badges/summary should use.
  const pay_state = (json.pay_state && typeof json.pay_state === 'object' && !Array.isArray(json.pay_state))
    ? json.pay_state
    : null;

  const invoice_no_by_invoice_id = (
    json.invoice_no_by_invoice_id &&
    typeof json.invoice_no_by_invoice_id === 'object' &&
    !Array.isArray(json.invoice_no_by_invoice_id)
  )
    ? { ...json.invoice_no_by_invoice_id }
    : {};

  const segment_snoozes = Array.isArray(json.segment_snoozes)
    ? json.segment_snoozes
    : [];

  const normaliseNullableString = (value) => {
    if (value == null) return null;
    const s = String(value).trim();
    return s || null;
  };

  // ✅ Rotation resolution metadata from backend
  const booking_id             = json.booking_id || (timesheet ? (timesheet.booking_id || null) : null);
  const requested_timesheet_id = json.requested_timesheet_id || timesheetId;
  const current_timesheet_id   =
    json.current_timesheet_id ||
    (timesheet ? (timesheet.timesheet_id || null) : null) ||
    timesheetId;

  const current_version =
    (json.current_version != null)
      ? json.current_version
      : (timesheet ? (timesheet.version ?? null) : null);

  const was_stale = !!json.was_stale;

  // Derive invoice breakdown + segments
  const ib   = tsfin && tsfin.invoice_breakdown_json && typeof tsfin.invoice_breakdown_json === 'object'
    ? tsfin.invoice_breakdown_json
    : null;

  const mode = ib && typeof ib.mode === 'string' ? ib.mode : null;
  const rawSegments = (ib && Array.isArray(ib.segments)) ? ib.segments : [];

  // Normalise segments:
  // - keep segment_id stable if backend provides one
  // - else create a stable fallback based on booking_id + index (NOT timesheet id)
  const segments = rawSegments.map((seg, idx) => {
    const s = (seg && typeof seg === 'object') ? { ...seg } : {};
    const existingId = (s.segment_id != null) ? String(s.segment_id).trim() : '';
    const fallbackId = `seg:${booking_id || 'noBooking'}:${idx}`;
    s.segment_id = existingId || fallbackId;
    s.exclude_from_pay = !!s.exclude_from_pay;
    return s;
  });

  const isSegments = (mode === 'SEGMENTS');

  // ✅ Pass-through + include resolver metadata
  const detail = {
    timesheet,
    tsfin,
    validations,
    shifts,
    segments,
    daily_processing: json.daily_processing || null,
    invoiceBreakdown: ib,
    isSegmentsMode: isSegments,
    invoice_no_by_invoice_id,

    // Convenience: surface key fields that backend already returned
    sheet_scope: json.sheet_scope || (timesheet ? (timesheet.sheet_scope || null) : null),
    qr_status: json.qr_status || (timesheet ? (timesheet.qr_status || null) : null),
    qr_generated_at: json.qr_generated_at || null,
    qr_scanned_at: json.qr_scanned_at || null,
    manual_pdf_r2_key: json.manual_pdf_r2_key || (timesheet ? (timesheet.manual_pdf_r2_key || null) : null),

    ready_to_pay: (typeof json.ready_to_pay === 'boolean') ? json.ready_to_pay : null,

    contract_week_id: json.contract_week_id || null,
    contract_week: json.contract_week || null,
    policy: json.policy || null,
    action_flags: (json.action_flags && typeof json.action_flags === 'object') ? json.action_flags : null,
    weekly_source_presentation: (json.weekly_source_presentation && typeof json.weekly_source_presentation === 'object')
      ? json.weekly_source_presentation
      : null,
    weekly_source_operational_category: json.weekly_source_operational_category || null,
    weekly_source_processing_reason: json.weekly_source_processing_reason || null,

    // ✅ Authoritative payment-state payload for Overview + Financials tabs.
    // Do not reconstruct or fall back to summary-cache economics here.
    pay_state,
    segment_snoozes,
    is_advanced: json.is_advanced === true,
    can_unadvance: json.can_unadvance === true,
    advanced_consumed_by_batch_id: normaliseNullableString(json.advanced_consumed_by_batch_id),
    is_snoozed: json.is_snoozed === true,
    snooze_until_date: normaliseNullableString(json.snooze_until_date),
    snooze_is_indefinite: json.snooze_is_indefinite === true,
    snooze_note: normaliseNullableString(json.snooze_note),

    // ✅ Rotation metadata for callers (openTimesheet + guarded writes)
    booking_id,
    requested_timesheet_id,
    current_timesheet_id,
    current_version,
    was_stale
  };

  // A successful exact current status read clears only this native window's unknown Retry state.
  const dailyRequest=window.modalCtx?._dailyProcessingRequestState;
  if(dailyRequest && window.modalCtx?.entity==='timesheets'
    && String(window.modalCtx?.data?.timesheet_id||'').toLowerCase()===String(timesheetId).toLowerCase()
    && dailyRequest.key===SESSION?.user?.id+':'+window.modalCtx.openToken+':'+window.modalCtx.data.timesheet_id+':'+timesheet?.version
    && window.CloudTMSBpayNextOffice?.dailyProcessingState?.(detail)?.key !== 'UNAVAILABLE'
    && window.CloudTMSBpayNextOffice?.dailyProcessingState?.(detail)
    && detail.daily_processing?.status!=='UNAVAILABLE'
    && ['NONE','PENDING','FAILED'].includes(detail.daily_processing?.status)
    && detail.timesheet?.is_current===true && detail.was_stale===false
    && String(detail.current_timesheet_id).toLowerCase()===String(timesheetId).toLowerCase()){
      dailyRequest.unknown=false;
      if(dailyRequest.result?.startsWith('Could not '))dailyRequest.result='';
    }

  L('parsed payload snapshot', {
    hasTimesheet: !!timesheet,
    hasTsfin: !!tsfin,
    validationsCount: validations.length,
    shiftsCount: shifts.length,
    segmentsCount: segments.length,
    mode,
    sheet_scope: detail.sheet_scope,
    qr_status: detail.qr_status,

    ready_to_pay: detail.ready_to_pay,
    hasPolicy: !!detail.policy,
    hasActionFlags: !!detail.action_flags,
    contract_week_id: detail.contract_week_id || null,
    hasContractWeek: !!detail.contract_week,

    hasPayState: !!detail.pay_state,
    pay_state_ok: detail.pay_state ? detail.pay_state.ok === true : false,
    paid_status: detail.pay_state ? (detail.pay_state.paid_status || null) : null,
    hasPaidTotals: !!(detail.pay_state && detail.pay_state.paid_totals && typeof detail.pay_state.paid_totals === 'object'),
    paid_to_date_ex_vat: detail.pay_state && detail.pay_state.paid_totals
      ? detail.pay_state.paid_totals.paid_to_date_ex_vat
      : null,
    adjusted_outstanding_ex_vat: detail.pay_state && detail.pay_state.adjusted
      ? detail.pay_state.adjusted.outstanding_ex_vat
      : null,
    adjusted_reserved_ex_vat: detail.pay_state && detail.pay_state.adjusted
      ? detail.pay_state.adjusted.reserved_ex_vat
      : null,
    adjusted_net_delta_ex_vat: detail.pay_state && detail.pay_state.adjusted
      ? detail.pay_state.adjusted.net_delta_ex_vat
      : null,
    segmentSnoozesCount: detail.segment_snoozes.length,
    is_advanced: detail.is_advanced,
    can_unadvance: detail.can_unadvance,
    is_snoozed: detail.is_snoozed,
    invoiceNoMapKeys: Object.keys(detail.invoice_no_by_invoice_id || {}).length,

    booking_id: detail.booking_id,
    requested_timesheet_id: detail.requested_timesheet_id,
    current_timesheet_id: detail.current_timesheet_id,
    current_version: detail.current_version,
    was_stale: detail.was_stale
  });

  GE();
  return detail;
}


async function fetchTimesheetSourceRows(timesheetId, opts = {}) {
  const LOGM = (typeof window.__LOG_MODAL === 'boolean') ? window.__LOG_MODAL : false;
  const L    = (...a) => { if (LOGM) console.log('[TS][SOURCE]', ...a); };
  const GC   = (label) => { if (LOGM) console.groupCollapsed('[TS][SOURCE]', label); };
  const GE   = () => { if (LOGM) console.groupEnd(); };

  if (!timesheetId) {
    throw new Error('fetchTimesheetSourceRows: timesheetId is required');
  }

  const scopeRaw = (opts.scope || 'all').toLowerCase();
  const scope    = scopeRaw === 'shift' ? 'shift' : 'all';
  const shiftId  = scope === 'shift' ? (opts.shiftId || opts.shift_id || '') : '';
  const includeExcluded = !!opts.includeExcluded || !!opts.include_excluded;

  // ✅ NEW: optional filter to fetch only a specific import batch
  const importId = String(opts.importId || opts.import_id || '').trim();

  const qp = new URLSearchParams();
  qp.set('scope', scope);
  if (scope === 'shift' && shiftId) qp.set('shift_id', String(shiftId));
  if (includeExcluded) qp.set('include_excluded', 'true');
  if (importId) qp.set('import_id', importId);

  const encId = encodeURIComponent(timesheetId);
  const url   = API(`/api/timesheets/${encId}/source-print?${qp.toString()}`);

  GC('request');
  L('→ GET', { url, timesheetId, scope, shiftId: shiftId || null, includeExcluded, importId: importId || null });

  let res;
  try {
    res = await authFetch(url);
  } catch (err) {
    L('network error', { url, error: err });
    GE();
    throw err;
  }

  let json;
  try {
    const text = await res.text();
    if (!res.ok) {
      L('server error', { status: res.status, bodyPreview: text.slice(0, 400) });
      GE();
      throw new Error(text || `Source rows failed (${res.status})`);
    }
    json = text ? JSON.parse(text) : {};
  } catch (err) {
    L('parse error', { status: res.status, error: err });
    GE();
    throw err;
  }

  const imports = Array.isArray(json.imports) ? json.imports : [];
  const summary = imports.map(i => ({
    source_system: i.source_system,
    import_id: i.import_id,
    header_rows: Array.isArray(i.header_rows) ? i.header_rows.length : 0,
    header_columns: Array.isArray(i.header_columns) ? i.header_columns.length : 0,
    rows: Array.isArray(i.rows) ? i.rows.length : 0
  }));

  L('RESULT', {
    timesheet_id: json.timesheet_id || timesheetId,
    scope: json.scope || scope,
    includes_excluded: json.includes_excluded ?? includeExcluded,
    importsCount: imports.length,
    importsSummary: summary
  });
  GE();
  return json;
}





async function fetchTimesheetRelated(timesheetId, options = {}) {
  const LOGM = (typeof window.__LOG_MODAL === 'boolean') ? window.__LOG_MODAL : false;
  const L    = (...a) => { if (LOGM) console.log('[TS][RELATED]', ...a); };
  const GC   = (label) => { if (LOGM) console.groupCollapsed('[TS][RELATED]', label); };
  const GE   = () => { if (LOGM) console.groupEnd(); };

  const opts = (options && typeof options === 'object' && !Array.isArray(options)) ? options : {};
  const tsId = String(timesheetId || '').trim();
  if (!tsId) {
    throw new Error('fetchTimesheetRelated: timesheetId is required');
  }

  const backgroundMode = opts.background === true || opts.lazy === true;
  const mutationSequence = Number(opts.mutationSequence ?? opts.mutation_sequence ?? opts.lifecycleSequence ?? opts.lifecycle_sequence ?? 0) || 0;
  const expectedTimesheetId = String(opts.expected_timesheet_id || opts.expectedTimesheetId || opts.current_timesheet_id || opts.currentTimesheetId || tsId || '').trim();

  if (typeof window !== 'undefined') {
    window.__timesheetRelatedRefreshQueue = window.__timesheetRelatedRefreshQueue || {};
  }

  const isStaleRelatedResult = () => {
    try {
      const mc = window.modalCtx && typeof window.modalCtx === 'object' ? window.modalCtx : null;
      if (!mc || mc.entity !== 'timesheets') return false;
      const liveId = String(mc.data?.current_timesheet_id || mc.data?.timesheet_id || mc.data?.id || '').trim();
      if (expectedTimesheetId && liveId && expectedTimesheetId !== liveId) return true;
      if (mutationSequence > 0) {
        const liveSeq = (typeof readTimesheetLifecycleMutationSequence === 'function')
          ? readTimesheetLifecycleMutationSequence(mc)
          : (Number(mc.__timesheetLifecycleMutationSeq || mc.__timesheetLatestLifecycleMutationSeq || 0) || 0);
        if (liveSeq > mutationSequence) return true;
      }
      return false;
    } catch {
      return false;
    }
  };

  const emptyRelated = {
    counts: {},
    candidate: null,
    client: null,
    invoices: [],
    invoice: null,
    invoice_no_by_invoice_id: {},
    umbrella: null,
    contract: null,
    series: []
  };

  const queueKey = tsId;
  const existingQueued = window.__timesheetRelatedRefreshQueue && window.__timesheetRelatedRefreshQueue[queueKey];
  if (existingQueued && existingQueued.promise && opts.__background_worker !== true) {
    const existingMutationSequence = Number(existingQueued.mutation_sequence || 0) || 0;
    const replaceOlderBackgroundRefresh = !!(backgroundMode && mutationSequence > existingMutationSequence);
    if (backgroundMode && !replaceOlderBackgroundRefresh) return existingQueued.promise;
    try {
      if (existingQueued.timer) clearTimeout(existingQueued.timer);
      delete window.__timesheetRelatedRefreshQueue[queueKey];
    } catch {}
  }

  if (backgroundMode && opts.__background_worker !== true) {
    try {
      const mc = window.modalCtx && typeof window.modalCtx === 'object' ? window.modalCtx : null;
      if (mc && mc.entity === 'timesheets') {
        mc.timesheetRelatedStale = true;
        mc.timesheetRelatedRefreshing = true;
        if (typeof markTimesheetLazyRefreshBadge === 'function') {
          markTimesheetLazyRefreshBadge(mc, 'related', {
            stale: true,
            refreshing: true,
            background: true,
            mutationSequence
          });
        }
      }
    } catch {}

    const scheduledAt = Date.now();
    const queueToken = `${scheduledAt}:${Math.random().toString(36).slice(2)}`;
    let timer = null;
    const promise = new Promise((resolve) => {
      const delay = Math.max(0, Math.min(Number(opts.debounce_ms ?? opts.debounceMs ?? 75) || 75, 500));
      timer = setTimeout(() => {
        Promise.resolve(fetchTimesheetRelated(tsId, { ...opts, background: false, lazy: false, __background_worker: true }))
          .then(resolve)
          .catch((err) => resolve({ ...emptyRelated, ok: false, error: String(err?.message || err || ''), stale_discarded: isStaleRelatedResult() }))
          .finally(() => {
            try {
              if (window.__timesheetRelatedRefreshQueue?.[queueKey]?.token === queueToken) {
                delete window.__timesheetRelatedRefreshQueue[queueKey];
              }
            } catch {}
          });
      }, delay);
    });
    window.__timesheetRelatedRefreshQueue[queueKey] = {
      promise,
      timer,
      token: queueToken,
      started_at: scheduledAt,
      mutation_sequence: mutationSequence || null
    };
    return promise;
  }

  GC('fetchTimesheetRelated');
  L('START', { timesheetId: tsId, background: backgroundMode, mutationSequence: mutationSequence || null });

  // 1) Get counts first so the public behaviour and count-driven eligibility stay unchanged.
  let counts = {};
  try {
    counts = await fetchRelatedCounts('timesheet', tsId) || {};
    L('counts', counts);
  } catch (err) {
    L('fetchRelatedCounts failed, proceeding with empty counts', err);
    counts = {};
  }

  if (isStaleRelatedResult()) {
    GE();
    return { ...emptyRelated, ok: false, stale_discarded: true, timesheet_id: tsId, reason: 'STALE_AFTER_COUNTS' };
  }

  const toInt = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? Math.max(0, Math.trunc(n)) : 0;
  };

  // Normalize count keys (backend may emit singular/plural aliases)
  const countCandidate = toInt(counts.candidate ?? counts.candidates ?? 0);
  const countClient    = toInt(counts.client    ?? counts.clients    ?? 0);
  const countInvoice   = toInt(counts.invoice   ?? counts.invoices   ?? counts.invoice_count ?? 0);
  const countUmbrella  = toInt(counts.umbrella  ?? counts.umbrellas  ?? 0);
  const countContract  = toInt(counts.contract  ?? counts.contracts  ?? 0);
  const countSeries    = toInt(counts.series    ?? 0);

  const out = {
    counts,
    candidate: null,
    client:    null,
    invoices: [],
    invoice: null,
    invoice_no_by_invoice_id: {},
    umbrella:  null,
    contract:  null,
    series:    []
  };

  // Helper to safely fetch related items (tolerate both list shapes).
  // It must never throw: one failed related request must not block the rest.
  const safeFetch = async (typeKey, label) => {
    try {
      if (isStaleRelatedResult()) return [];
      const res = await fetchRelated('timesheet', tsId, typeKey);
      if (isStaleRelatedResult()) return [];
      // tolerate both shapes: array OR {items,total}
      const items = Array.isArray(res?.items) ? res.items : (Array.isArray(res) ? res : []);
      L(`related[${label}]`, { count: items.length, sample: items[0] || null });
      return items;
    } catch (err) {
      L(`related[${label}] failed`, err);
      return [];
    }
  };

  // 2) After counts are known, launch every eligible related request concurrently.
  const jobs = [];
  if (countCandidate > 0) jobs.push({ slot: 'candidate', promise: safeFetch('candidate', 'candidate') });
  if (countClient > 0)    jobs.push({ slot: 'client',    promise: safeFetch('client', 'client') });
  if (countInvoice > 0)   jobs.push({ slot: 'invoice',   promise: safeFetch('invoice', 'invoice') });
  if (countUmbrella > 0)  jobs.push({ slot: 'umbrella',  promise: safeFetch('umbrella', 'umbrella') });
  if (countContract > 0)  jobs.push({ slot: 'contract',  promise: safeFetch('contract', 'contract') });
  if (countSeries > 0)    jobs.push({ slot: 'series',    promise: safeFetch('series', 'series') });

  const results = await Promise.all(jobs.map(async (job) => {
    const items = await job.promise;
    return { slot: job.slot, items: Array.isArray(items) ? items : [] };
  }));

  if (isStaleRelatedResult()) {
    GE();
    return { ...emptyRelated, ok: false, stale_discarded: true, timesheet_id: tsId, reason: 'STALE_AFTER_RELATED_LISTS' };
  }

  for (const result of results) {
    const slot = result.slot;
    const items = Array.isArray(result.items) ? result.items : [];

    if (slot === 'candidate') {
      out.candidate = items[0] || null;
      continue;
    }

    if (slot === 'client') {
      out.client = items[0] || null;
      continue;
    }

    if (slot === 'invoice') {
      out.invoices = items;
      out.invoice  = out.invoices[0] || null; // back-compat only
      const map = {};
      for (const it of out.invoices) {
        if (!it || typeof it !== 'object') continue;
        const iid = (it.invoice_id != null ? String(it.invoice_id) : '') || (it.id != null ? String(it.id) : '');
        if (!iid) continue;
        const ino = (it.invoice_no != null && String(it.invoice_no).trim()) ? String(it.invoice_no).trim() : '';
        if (ino) map[iid] = ino;
      }
      out.invoice_no_by_invoice_id = map;
      continue;
    }

    if (slot === 'umbrella') {
      out.umbrella = items[0] || null;
      continue;
    }

    if (slot === 'contract') {
      out.contract = items[0] || null;
      continue;
    }

    if (slot === 'series') {
      out.series = items;
      continue;
    }
  }

  try {
    const mc = window.modalCtx && typeof window.modalCtx === 'object' ? window.modalCtx : null;
    if (mc && mc.entity === 'timesheets' && !isStaleRelatedResult()) {
      mc.timesheetRelatedStale = false;
      mc.timesheetRelatedRefreshing = false;
      if (mc.__timesheetLazyTabBadges?.related) {
        mc.__timesheetLazyTabBadges.related.refreshing = false;
        mc.__timesheetLazyTabBadges.related.stale = false;
        mc.__timesheetLazyTabBadges.related.settled_at = Date.now();
      }
    }
  } catch {}

  L('RESULT', {
    hasCandidate: !!out.candidate,
    hasClient: !!out.client,
    invoiceCount: out.invoices.length,
    hasUmbrella: !!out.umbrella,
    hasContract: !!out.contract,
    seriesCount: out.series.length,
    invoiceNoMapKeys: Object.keys(out.invoice_no_by_invoice_id || {}).length
  });
  GE();
  return out;
}

// NEW: Electronic signatures evidence viewer
// Expects backend evidence item with preview_mode: 'SIGNATURES' and meta/meta_json containing booking_id,
// authorised_at_server, auth_name, auth_job_title, and (optionally) worked/weekly details.
async function openTimesheetEvidenceViewerSignatures(ev) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][EVIDENCE][SIG_VIEW]');
  GC('openTimesheetEvidenceViewerSignatures');

  if (!ev || typeof ev !== 'object') {
    GE();
    throw new Error('Evidence item is required.');
  }

  const mc = window.modalCtx || {};
  const ts = mc?.timesheetDetails?.timesheet || null;

  const meta =
    (ev && typeof ev.meta === 'object' && ev.meta) ? ev.meta :
    (ev && typeof ev.meta_json === 'object' && ev.meta_json) ? ev.meta_json :
    {};

  const bookingId = meta.booking_id ? String(meta.booking_id).trim() : '';
  if (!bookingId) {
    GE();
    throw new Error('Electronic evidence missing booking_id.');
  }

  const version = (meta.version != null && Number.isFinite(Number(meta.version))) ? Number(meta.version) : null;

  const authName = meta.auth_name ? String(meta.auth_name) : '';
  const authJob  = meta.auth_job_title ? String(meta.auth_job_title) : '';
  const authAt   = meta.authorised_at_server ? String(meta.authorised_at_server) : (ev.created_at ? String(ev.created_at) : '');

  const fmtUkDateTime = (iso) => {
    if (!iso) return '—';
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return String(iso);
    try {
      return d.toLocaleString('en-GB', {
        timeZone: 'Europe/London',
        weekday: 'short',
        day: '2-digit',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        hour12: false
      });
    } catch {
      return d.toISOString();
    }
  };

  // Shift summary: prefer loaded timesheetDetails, fallback to meta fields.
  const scope = String((ts?.sheet_scope || meta.sheet_scope || '')).toUpperCase();
  const summaryLines = [];

  if (scope === 'DAILY') {
    const s = (ts?.worked_start_iso || meta.worked_start_iso) ? String(ts?.worked_start_iso || meta.worked_start_iso) : '';
    const e = (ts?.worked_end_iso || meta.worked_end_iso) ? String(ts?.worked_end_iso || meta.worked_end_iso) : '';
    const bs = (ts?.break_start_iso || meta.break_start_iso) ? String(ts?.break_start_iso || meta.break_start_iso) : '';
    const be = (ts?.break_end_iso || meta.break_end_iso) ? String(ts?.break_end_iso || meta.break_end_iso) : '';
    const bm = (ts?.break_minutes != null ? ts.break_minutes : meta.break_minutes) != null
      ? String(ts?.break_minutes != null ? ts.break_minutes : meta.break_minutes)
      : '';

    if (s && e) summaryLines.push(`Worked: ${s} → ${e}`);
    if (bs && be) summaryLines.push(`Break: ${bs} → ${be}`);
    else if (bm) summaryLines.push(`Break minutes: ${bm}`);
  } else if (scope === 'WEEKLY') {
    const we = (ts?.week_ending_date || meta.week_ending_date) ? String(ts?.week_ending_date || meta.week_ending_date) : '';
    if (we) summaryLines.push(`Week ending: ${we}`);

    const sched = Array.isArray(ts?.actual_schedule_json) ? ts.actual_schedule_json :
                  Array.isArray(meta.actual_schedule_json) ? meta.actual_schedule_json :
                  null;
    if (Array.isArray(sched) && sched.length > 0) summaryLines.push(`Shifts: ${sched.length}`);
  }

  // Presign signature URLs (batch)
  let nurseUrl = null;
  let authUrl = null;

  try {
    const presRes = await authFetch(API('/signatures/presign-get/batch'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        items: [
          { booking_id: bookingId, which: 'nurse', ...(version != null ? { version } : {}) },
          { booking_id: bookingId, which: 'authoriser', ...(version != null ? { version } : {}) }
        ],
        expires_seconds: 600
      })
    });

    const presTxt = await presRes.text().catch(() => '');
    if (!presRes.ok) throw new Error(presTxt || 'Failed to presign signature URLs');

    const presJson = presTxt ? JSON.parse(presTxt) : {};
    const links = Array.isArray(presJson.links) ? presJson.links : [];

    nurseUrl = (links.find(x => String(x?.which || '') === 'nurse') || {}).get_url || null;
    authUrl  = (links.find(x => String(x?.which || '') === 'authoriser') || {}).get_url || null;
  } catch (e) {
    // We still render modal with metadata; panels will show Not available.
    try { window.__toast && window.__toast(e?.message || 'Failed to load signatures'); } catch {}
  }

  const title = `Electronic evidence ${String((ts?.timesheet_id || mc?.data?.timesheet_id || '')).slice(0, 8)}…`;

  const bodyHtml = `
    <div class="tabc">
      <svg aria-hidden="true" focusable="false" width="0" height="0" style="position:absolute;overflow:hidden;">
        <filter id="ctms-signature-ink-filter" color-interpolation-filters="sRGB">
          <feColorMatrix type="matrix" values="
            0 0 0 0 0.0902
            0 0 0 0 0.2471
            0 0 0 0 0.4588
            -0.2126 -0.7152 -0.0722 1 0
          "/>
        </filter>
      </svg>
      <div class="card">
        <div class="row">
          <label>Authorised at server</label>
          <div class="controls">
            <span class="mini">${escapeHtml(fmtUkDateTime(authAt))}</span>
          </div>
        </div>
        <div class="row">
          <label>Authoriser</label>
          <div class="controls">
            <span class="mini">${escapeHtml([authName, authJob].filter(Boolean).join(' — ') || '—')}</span>
          </div>
        </div>
        <div class="row">
          <label>Shift details</label>
          <div class="controls">
            <div class="mini" style="opacity:.9;">
              ${summaryLines.length ? summaryLines.map(x => `<div>${escapeHtml(x)}</div>`).join('') : '—'}
            </div>
          </div>
        </div>
      </div>

      <div class="card" style="margin-top:10px;">
        <div class="row">
          <label>Signatures</label>
          <div class="controls" style="display:flex; gap:12px; flex-wrap:wrap;">
            <div style="flex:1; min-width:240px;">
              <div class="mini" style="opacity:.85; margin-bottom:6px;">Candidate signature</div>
          ${nurseUrl
  ? `
    <div class="ctms-evidence-signature-sheet">
       <img
         src="${nurseUrl}"
         alt="Candidate signature"
         class="ctms-evidence-signature-ink"
       />
    </div>
  `
  : `<div class="mini" style="opacity:.85;">Not available</div>`}

            </div>

            <div style="flex:1; min-width:240px;">
              <div class="mini" style="opacity:.85; margin-bottom:6px;">Manager signature</div>
            ${authUrl
  ? `
    <div class="ctms-evidence-signature-sheet">
       <img
         src="${authUrl}"
         alt="Manager signature"
         class="ctms-evidence-signature-ink"
       />
    </div>
  `
  : `<div class="mini" style="opacity:.85;">Not available</div>`}

            </div>
          </div>
        </div>
      </div>
    </div>
  `;

  showModal(
    title,
    [{ key: 'view', title: 'Evidence' }],
    () => bodyHtml,
    async () => ({ ok: true }),
    false,
    undefined,
    {
      kind: 'timesheet-evidence-signatures',
      frameEntity: 'timesheet-evidence',
      noParentGate: true,
      forceEdit: true
    }
  );

  GE();
}

function persistTimesheetExpensesDomToModalState(options = {}) {
  const isDomRoot = (value) => !!(
    value &&
    typeof value === 'object' &&
    typeof value.querySelectorAll === 'function'
  );
  const isPlainObject = (value) => !!(
    value &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    !isDomRoot(value)
  );

  const looksTimesheetCtxLike = (value) => !!(
    value &&
    typeof value === 'object' &&
    !isDomRoot(value) &&
    (
      String(value.entity || '').trim().toLowerCase() === 'timesheets' ||
      value.timesheetDetails ||
      value.timesheetState ||
      (value.data && typeof value.data === 'object' && (value.data.timesheet_id || value.data.contract_week_id)) ||
      (value.row && typeof value.row === 'object' && (value.row.timesheet_id || value.row.contract_week_id))
    )
  );

  let opts = isPlainObject(options) ? { ...options } : {};
  const optionsCtx = looksTimesheetCtxLike(options) ? options : null;
  if (isDomRoot(options)) {
    opts = { ...(isPlainObject(arguments[1]) ? arguments[1] : {}), root: options };
  }

  const ctx = resolveTimesheetExpensesModalCtx(opts.ctx || opts.modalCtx || opts.timesheetCtx || optionsCtx || null);
  const root = opts.root || opts.domRoot || opts.container || (typeof document !== 'undefined' ? document.getElementById('modalBody') : null);
  const collected = collectTimesheetExpensesDraftFromDom(root, { ...opts, ctx });
  if (!collected || !collected.ok) {
    return {
      ok: false,
      reason: collected?.reason || 'NOT_COLLECTED',
      ctx,
      state: ctx?.timesheetState || null,
      draft: null,
      dirty: false,
      inputCount: collected?.inputCount || 0,
      fieldCount: collected?.fieldCount || 0
    };
  }
  const committed = commitTimesheetExpensesDraftToModalState(ctx, collected.draft, {
    ...opts,
    explicitFields: collected.explicitFields || [],
    explicitDomValues: collected.explicitDomValues || {}
  });
  return {
    ...committed,
    inputCount: collected.inputCount,
    fieldCount: collected.fieldCount,
    explicitFields: collected.explicitFields || [],
    source: opts.source || ''
  };
}




// ======== Timesheet tab helpers ========

function getTsLoggers(ns) {
  const LOGM = (typeof window.__LOG_MODAL === 'boolean') ? window.__LOG_MODAL : false;
  return {
    LOGM,
    L:  (...a) => { if (LOGM) console.log(ns, ...a); },
    GC: (label) => { if (LOGM) console.groupCollapsed(ns, label); },
    GE: () => { if (LOGM) console.groupEnd(); }
  };
}


function normaliseTimesheetCtx(ctx) {
  const baseCtx = ctx || {};
  const mc = window.modalCtx || {};

  // Summary row from v_timesheets_summary
  const row =
    baseCtx.row ||
    baseCtx.data ||
    mc.data ||
    {};

  // Details from fetchTimesheetDetails / fetchTimesheetWorkbenchDetails
  const details =
    baseCtx.details ||
    mc.timesheetDetails ||
    {
      timesheet: null,
      tsfin: null,
      validations: [],
      shifts: [],
      segments: [],
      isSegmentsMode: false,
      invoiceBreakdown: null,
      sheet_scope: row.sheet_scope || null,
      qr_status: row.qr_status || null,

      // carry-through ready_to_pay so Overview can use it even without TSFIN
      ready_to_pay: (typeof row.ready_to_pay === 'boolean') ? row.ready_to_pay : null,

      // keep optional enriched fields consistent with fetchTimesheetDetails()
      contract_week_id: row.contract_week_id || null,
      contract_week: null,
      policy: null,
      action_flags: null
    };

  // if details didn't include ready_to_pay (older backend), fall back to row
  if (typeof details.ready_to_pay !== 'boolean' && typeof row.ready_to_pay === 'boolean') {
    details.ready_to_pay = row.ready_to_pay;
  }

  // Related entities from fetchTimesheetRelated
  const related =
    baseCtx.related ||
    mc.timesheetRelated ||
    {
      counts: {},
      candidate: null,
      client: null,
      invoice: null,
      umbrella: null,
      contract: null,
      series: []
    };

  // Timesheet-ui state (staging for future Save)
  if (!mc.timesheetState || typeof mc.timesheetState !== 'object') {
    mc.timesheetState = {
      reference: null,
      payHoldDesired: null,
      payHoldReason: '',
      markPaid: false,
      segmentOverrides: {},
      nhspDeferrals: {},
      additionalRates: {},

      weeklyLinesByDate: null,
      extraShiftCount: 0,
      weekly_line_clipboard: null,

      scheduleHasErrors: false,
      scheduleErrorsByDate: {},

      // Expenses always present (stable shape)
      expensesDraft: null,
      expensesBaseline: null,

      // Evidence always present (stable shape)
      evidence: [],

      // internal marker to avoid re-seeding on every render
      __expensesSeededFromTsfinCols: false
    };
  } else {
    if (!mc.timesheetState.additionalRates || typeof mc.timesheetState.additionalRates !== 'object') {
      mc.timesheetState.additionalRates = {};
    }

    const wlb = mc.timesheetState.weeklyLinesByDate;
    if (typeof wlb === 'undefined') {
      mc.timesheetState.weeklyLinesByDate = null;
    } else if (wlb === null) {
      // keep as unseeded sentinel
    } else if (typeof wlb !== 'object' || Array.isArray(wlb)) {
      mc.timesheetState.weeklyLinesByDate = null;
      mc.timesheetState.__weeklyLinesSeedKey = '';
      mc.timesheetState.__weeklyLinesSeedHash = '';
    } else {
      try {
        if (Object.keys(wlb).length === 0) {
          mc.timesheetState.weeklyLinesByDate = null;
          mc.timesheetState.__weeklyLinesSeedKey = '';
          mc.timesheetState.__weeklyLinesSeedHash = '';
        }
      } catch {}
    }

    if (!Number.isFinite(Number(mc.timesheetState.extraShiftCount))) {
      mc.timesheetState.extraShiftCount = 0;
    } else {
      mc.timesheetState.extraShiftCount = Number(mc.timesheetState.extraShiftCount);
    }
    if (!Object.prototype.hasOwnProperty.call(mc.timesheetState, 'weekly_line_clipboard')) {
      mc.timesheetState.weekly_line_clipboard = null;
    }

    if (typeof mc.timesheetState.scheduleHasErrors !== 'boolean') {
      mc.timesheetState.scheduleHasErrors = false;
    }
    if (!mc.timesheetState.scheduleErrorsByDate || typeof mc.timesheetState.scheduleErrorsByDate !== 'object') {
      mc.timesheetState.scheduleErrorsByDate = {};
    }

    if (!mc.timesheetState.expensesDraft || typeof mc.timesheetState.expensesDraft !== 'object') {
      mc.timesheetState.expensesDraft = null;
    }
    if (!mc.timesheetState.expensesBaseline || typeof mc.timesheetState.expensesBaseline !== 'object') {
      mc.timesheetState.expensesBaseline = null;
    }
    if (!Array.isArray(mc.timesheetState.evidence)) {
      mc.timesheetState.evidence = [];
    }
    if (typeof mc.timesheetState.__expensesSeededFromTsfinCols !== 'boolean') {
      mc.timesheetState.__expensesSeededFromTsfinCols = false;
    }
  }

  const state = mc.timesheetState;

  // Ensure modalCtx has these attached for other code to use
  window.modalCtx = mc;
  if (!mc.timesheetDetails) mc.timesheetDetails = details;
  if (!mc.timesheetRelated) mc.timesheetRelated = related;

  // ─────────────────────────────────────────────────────────────
  // Evidence state normalization
  // - carry staged contract-week evidence or real evidence into one stable shape
  // ─────────────────────────────────────────────────────────────
  const incomingEvidence =
    Array.isArray(baseCtx.evidence) ? baseCtx.evidence :
    Array.isArray(details?.evidence) ? details.evidence :
    (details?.staged_evidence && Array.isArray(details.staged_evidence)) ? details.staged_evidence :
    (details?.stagedEvidence && Array.isArray(details.stagedEvidence)) ? details.stagedEvidence :
    (details?.staged_evidence_items && Array.isArray(details.staged_evidence_items)) ? details.staged_evidence_items :
    (details?.stagedEvidenceItems && Array.isArray(details.stagedEvidenceItems)) ? details.stagedEvidenceItems :
    null;

  if (Array.isArray(incomingEvidence)) {
    if (!timesheetStateEvidenceDirty(state)) {
      state.evidence = incomingEvidence.map((ev) => {
        const out = { ...(ev || {}) };

        if (typeof out.system !== 'boolean') out.system = false;
        if (typeof out.can_delete !== 'boolean') out.can_delete = !out.system;
        if (typeof out.can_reclassify !== 'boolean') out.can_reclassify = !out.system;
        if (typeof out.can_return_to_queue !== 'boolean') out.can_return_to_queue = !out.system;

        if (!out.uploaded_at_utc && out.created_at) out.uploaded_at_utc = out.created_at;
        if (!out.filename && out.display_name) out.filename = out.display_name;

        return out;
      });
    } else if (!Array.isArray(state.evidence)) {
      state.evidence = [];
    }
  } else if (!Array.isArray(state.evidence)) {
    state.evidence = [];
  }

  // ─────────────────────────────────────────────────────────────
  // Expenses draft/baseline
  // - Weekly unprocessed planned/manual uses contract_weeks.totals_json.expenses_draft first
  // - Real rows continue to seed from TSFIN numeric columns
  // - expenses_description is treated as notes/meta only
  // ─────────────────────────────────────────────────────────────
  const tsfinLocal = (details && details.tsfin && typeof details.tsfin === 'object') ? details.tsfin : null;
  const tsLocal = (details && details.timesheet && typeof details.timesheet === 'object') ? details.timesheet : {};
  const contractWeek = (details && details.contract_week && typeof details.contract_week === 'object') ? details.contract_week : {};

  const hasRealTs =
    !!(tsLocal && (tsLocal.timesheet_id || tsLocal.current_timesheet_id)) ||
    !!(details && (details.current_timesheet_id || details.requested_timesheet_id || details.timesheet_id)) ||
    !!(row && (row.current_timesheet_id || row.timesheet_id)) ||
    !!(mc.data && (mc.data.current_timesheet_id || mc.data.timesheet_id));

  const sheetScope = String(details?.sheet_scope || row?.sheet_scope || tsLocal?.sheet_scope || '').toUpperCase();
  const isPlannedWeeklyManual =
    !hasRealTs &&
    sheetScope === 'WEEKLY' &&
    !!(details?.contract_week_id || contractWeek?.id || row?.contract_week_id);

  const defaultDraft = {
    mileage_units: 0,
    mileage_pay_rate: null,
    mileage_charge_rate: null,
    travel_pay: 0,
    travel_charge: 0,
    accommodation_pay: 0,
    accommodation_charge: 0,
    other_pay: 0,
    other_charge: 0,
    note: ''
  };

  const num0 = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
  };

  const rateOrNull = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  };

  const safeJsonParse = (v) => {
    if (v == null) return null;
    if (typeof v === 'object') return v;
    const s = String(v).trim();
    if (!s) return null;
    try { return JSON.parse(s); } catch { return null; }
  };

  const extractNote = (desc) => {
    if (desc == null) return '';
    if (typeof desc === 'string') {
      const s = desc.trim();
      if (!s) return '';
      try {
        const j = JSON.parse(s);
        if (j && typeof j === 'object') {
          const n1 = (typeof j.note === 'string') ? j.note.trim() : '';
          const n2 = (!n1 && typeof j.notes === 'string') ? j.notes.trim() : '';
          return n1 || n2 || '';
        }
      } catch {}
      return s;
    }
    if (typeof desc === 'object') {
      const n1 = (typeof desc.note === 'string') ? desc.note.trim() : '';
      const n2 = (!n1 && typeof desc.notes === 'string') ? desc.notes.trim() : '';
      return n1 || n2 || '';
    }
    return '';
  };

  const hasExpenseDraftPayload = (value) => {
    if (!value || typeof value !== 'object') return false;
    return [
      'mileage_units',
      'mileage_pay_rate',
      'mileage_charge_rate',
      'travel_pay',
      'travel_charge',
      'accommodation_pay',
      'accommodation_charge',
      'other_pay',
      'other_charge',
      'note',
      'notes'
    ].some((key) => Object.prototype.hasOwnProperty.call(value, key));
  };

  const cloneExpenseDraftSeed = (value) => {
    try { return JSON.parse(JSON.stringify(value || {})); } catch { return { ...(value || {}) }; }
  };

  const contractWeekTotalsJson = safeJsonParse(contractWeek?.totals_json) || {};
  const contractWeekTotalsHasExpensesDraft = !!(
    contractWeekTotalsJson &&
    typeof contractWeekTotalsJson === 'object' &&
    Object.prototype.hasOwnProperty.call(contractWeekTotalsJson, 'expenses_draft')
  );

  const explicitContractWeekExpensesDraft = contractWeekTotalsHasExpensesDraft
    ? safeJsonParse(contractWeekTotalsJson.expenses_draft)
    : null;
  const contractWeekExpenseDraftWasExplicit = !!(
    contractWeekTotalsHasExpensesDraft &&
    (explicitContractWeekExpensesDraft == null || typeof explicitContractWeekExpensesDraft === 'object')
  );

  const preservedContractWeekExpensesDraft = (() => {
    const sources = [
      state.contractWeekExpensesDraft,
      state.contract_week_expenses_draft,
      state.__contractWeekExpensesDraft,
      state.__contract_week_expenses_draft,
      state.expensesDraft,
      state.expensesBaseline
    ];
    for (const src of sources) {
      if (hasExpenseDraftPayload(src)) return src;
    }
    return null;
  })();

  const draftFromContractWeek = (() => {
    const sourceDraft = contractWeekExpenseDraftWasExplicit
      ? ((explicitContractWeekExpensesDraft && typeof explicitContractWeekExpensesDraft === 'object') ? explicitContractWeekExpensesDraft : {})
      : (isPlannedWeeklyManual && hasExpenseDraftPayload(preservedContractWeekExpensesDraft)
          ? preservedContractWeekExpensesDraft
          : null);
    if (!sourceDraft || typeof sourceDraft !== 'object') return null;

    return {
      mileage_units: num0(sourceDraft.mileage_units ?? 0),
      mileage_pay_rate: Number.isFinite(Number(sourceDraft.mileage_pay_rate)) ? Number(sourceDraft.mileage_pay_rate) : null,
      mileage_charge_rate: Number.isFinite(Number(sourceDraft.mileage_charge_rate)) ? Number(sourceDraft.mileage_charge_rate) : null,
      travel_pay: num0(sourceDraft.travel_pay ?? 0),
      travel_charge: num0(sourceDraft.travel_charge ?? 0),
      accommodation_pay: num0(sourceDraft.accommodation_pay ?? 0),
      accommodation_charge: num0(sourceDraft.accommodation_charge ?? 0),
      other_pay: num0(sourceDraft.other_pay ?? 0),
      other_charge: num0(sourceDraft.other_charge ?? 0),
      note: extractNote(sourceDraft.note ?? sourceDraft.notes ?? '')
    };
  })();

  if (isPlannedWeeklyManual && draftFromContractWeek && typeof draftFromContractWeek === 'object') {
    const clonedContractWeekDraft = cloneExpenseDraftSeed(draftFromContractWeek);
    state.contractWeekExpensesDraft = cloneExpenseDraftSeed(clonedContractWeekDraft);
    state.contract_week_expenses_draft = cloneExpenseDraftSeed(clonedContractWeekDraft);
    state.__contractWeekExpensesDraft = cloneExpenseDraftSeed(clonedContractWeekDraft);
    state.__contract_week_expenses_draft = cloneExpenseDraftSeed(clonedContractWeekDraft);

    if (!contractWeekExpenseDraftWasExplicit && details.contract_week && typeof details.contract_week === 'object') {
      try {
        const totals = safeJsonParse(details.contract_week.totals_json) || {};
        if (!Object.prototype.hasOwnProperty.call(totals, 'expenses_draft')) {
          details.contract_week.totals_json = {
            ...totals,
            expenses_draft: cloneExpenseDraftSeed(clonedContractWeekDraft)
          };
        }
      } catch {}
    }
  }

  const draftFromTsfinCols = (() => {
    if (!tsfinLocal) return { ...defaultDraft };

    return {
      mileage_units: num0(tsfinLocal.mileage_units ?? 0),
      mileage_pay_rate: rateOrNull(tsfinLocal.mileage_pay_rate),
      mileage_charge_rate: rateOrNull(tsfinLocal.mileage_charge_rate),

      travel_pay: num0(tsfinLocal.travel_pay_ex_vat ?? 0),
      travel_charge: num0(tsfinLocal.travel_charge_ex_vat ?? 0),

      accommodation_pay: num0(tsfinLocal.accommodation_pay_ex_vat ?? 0),
      accommodation_charge: num0(tsfinLocal.accommodation_charge_ex_vat ?? 0),

      other_pay: num0(tsfinLocal.other_pay_ex_vat ?? 0),
      other_charge: num0(tsfinLocal.other_charge_ex_vat ?? 0),

      note: extractNote(tsfinLocal.expenses_description)
    };
  })();

  const hasRealTsfinExpenseAuthority = !!(hasRealTs && tsfinLocal);

  const preferredDraftSeed =
    hasRealTsfinExpenseAuthority
      ? draftFromTsfinCols
      : ((isPlannedWeeklyManual && draftFromContractWeek && typeof draftFromContractWeek === 'object')
          ? draftFromContractWeek
          : draftFromTsfinCols);

  const hasAuthoritativeExpenseSeed = !!(
    hasRealTsfinExpenseAuthority ||
    (isPlannedWeeklyManual && contractWeekExpenseDraftWasExplicit)
  );

  const expensesDirty = timesheetStateExpensesDirty(state);

  const sameCoreNumbers = (a, b) => {
    const keys = [
      'mileage_units',
      'travel_pay', 'travel_charge',
      'accommodation_pay', 'accommodation_charge',
      'other_pay', 'other_charge'
    ];
    for (const k of keys) {
      if (num0(a?.[k]) !== num0(b?.[k])) return false;
    }
    if (rateOrNull(a?.mileage_pay_rate) !== rateOrNull(b?.mileage_pay_rate)) return false;
    if (rateOrNull(a?.mileage_charge_rate) !== rateOrNull(b?.mileage_charge_rate)) return false;
    if (String(a?.note ?? '').trim() !== String(b?.note ?? '').trim()) return false;
    return true;
  };

  const cloneDraftForState = (value) => cloneExpenseDraftSeed(value || defaultDraft);
  const normaliseExpenseSeedForState = (value) => {
    const raw = {
      ...defaultDraft,
      ...((value && typeof value === 'object') ? value : {})
    };
    if (typeof normaliseTimesheetExpensesDraft === 'function') {
      try {
        return normaliseTimesheetExpensesDraft(raw, {
          row,
          details,
          tsfin: tsfinLocal || {},
          state,
          context: mc
        });
      } catch {}
    }
    return raw;
  };

  const preferredDraftForState = normaliseExpenseSeedForState(preferredDraftSeed || defaultDraft);
  const existingDraftIsObject = !!(state.expensesDraft && typeof state.expensesDraft === 'object');
  const existingBaselineIsObject = !!(state.expensesBaseline && typeof state.expensesBaseline === 'object');
  const existingDraftMatchesBaseline = !!(
    existingDraftIsObject &&
    existingBaselineIsObject &&
    sameCoreNumbers(state.expensesDraft, state.expensesBaseline)
  );

  if (!existingDraftIsObject) {
    state.expensesDraft = cloneDraftForState(preferredDraftForState);
    state.__expensesSeededFromTsfinCols = !!hasRealTsfinExpenseAuthority;
  } else {
    for (const k of Object.keys(defaultDraft)) {
      if (!Object.prototype.hasOwnProperty.call(state.expensesDraft, k)) {
        state.expensesDraft[k] = defaultDraft[k];
      }
    }

    if (
      preferredDraftForState &&
      hasAuthoritativeExpenseSeed &&
      !expensesDirty &&
      (!existingBaselineIsObject || existingDraftMatchesBaseline)
    ) {
      state.expensesDraft = cloneDraftForState(preferredDraftForState);
      state.expensesBaseline = cloneDraftForState(preferredDraftForState);
      state.__expensesSeededFromTsfinCols = !!hasRealTsfinExpenseAuthority;
    }
  }

  if (!state.expensesBaseline || typeof state.expensesBaseline !== 'object') {
    if (!expensesDirty) {
      state.expensesBaseline = cloneDraftForState(state.expensesDraft);
    }
  } else if (!expensesDirty) {
    for (const k of Object.keys(defaultDraft)) {
      if (!Object.prototype.hasOwnProperty.call(state.expensesBaseline, k)) {
        state.expensesBaseline[k] = defaultDraft[k];
      }
    }
  }

  const policyLike = (value) => !!(
    value &&
    typeof value === 'object' &&
    (
      Object.prototype.hasOwnProperty.call(value, 'canEditExpenses') ||
      Object.prototype.hasOwnProperty.call(value, 'canOpenExpenses') ||
      Object.prototype.hasOwnProperty.call(value, 'expenseStorageTarget') ||
      Object.prototype.hasOwnProperty.call(value, 'expense_storage_target')
    )
  );
  const editDomains = (() => {
    const sources = [
      baseCtx.timesheetEditDomains,
      baseCtx.editDomains,
      baseCtx.policy,
      mc.timesheetEditDomains,
      mc.editDomains,
      mc.policy,
      details.timesheetEditDomains,
      details.editDomains,
      details.edit_domains,
      details.action_flags
    ];
    for (const src of sources) {
      if (policyLike(src)) return src;
    }
    return null;
  })();
  if (editDomains && !mc.timesheetEditDomains) mc.timesheetEditDomains = editDomains;
  const expenseStorageTarget = String(
    editDomains?.expenseStorageTarget ||
    editDomains?.expense_storage_target ||
    mc.expenseStorageTarget ||
    mc.expense_storage_target ||
    row.expenseStorageTarget ||
    row.expense_storage_target ||
    details.expenseStorageTarget ||
    details.expense_storage_target ||
    ''
  ).trim().toUpperCase() || null;

  return {
    row,
    details,
    related,
    state,
    policy: editDomains,
    editDomains,
    timesheetEditDomains: editDomains,
    expenseStorageTarget,
    expense_storage_target: expenseStorageTarget
  };
}



function renderTimesheetEvidenceTab(ctx) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][EVIDENCE]');
  const { row, details, state } = normaliseTimesheetCtx(ctx);
  GC('render');

  const ts = details.timesheet || {};
  const tsId = row.timesheet_id || ts.timesheet_id || '';

  const firstEvidenceArray = (...values) => {
    const arrays = [];
    for (const value of values) {
      if (Array.isArray(value)) {
        arrays.push(value);
      }
    }
    const nonEmpty = arrays.find((list) => list.length > 0);
    return nonEmpty || arrays[0] || [];
  };

  const modalCtxEvidence = (typeof window !== 'undefined' && window.modalCtx && typeof window.modalCtx === 'object')
    ? window.modalCtx
    : {};

  const evList = firstEvidenceArray(
    state.evidence,
    details.evidence,
    row.evidence,
    state.contractWeekStagedEvidence,
    state.contract_week_staged_evidence,
    state.stagedEvidence,
    state.staged_evidence,
    details.contractWeekStagedEvidence,
    details.contract_week_staged_evidence,
    details.stagedEvidence,
    details.staged_evidence,
    row.contractWeekStagedEvidence,
    row.contract_week_staged_evidence,
    row.stagedEvidence,
    row.staged_evidence,
    modalCtxEvidence?.timesheetState?.evidence,
    modalCtxEvidence?.timesheetState?.contractWeekStagedEvidence,
    modalCtxEvidence?.timesheetState?.contract_week_staged_evidence,
    modalCtxEvidence?.timesheetDetails?.evidence,
    modalCtxEvidence?.timesheetDetails?.contractWeekStagedEvidence,
    modalCtxEvidence?.timesheetDetails?.contract_week_staged_evidence,
    modalCtxEvidence?.contractWeekStagedEvidence,
    modalCtxEvidence?.contract_week_staged_evidence,
    modalCtxEvidence?.stagedEvidence
  );
  const boolish = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on');
  };
  const upper = (v) => String(v == null ? '' : v).trim().toUpperCase();
  const routeType = upper(row.route_type || details.route_type || state.route_type || ts.route_type || details?.timesheet?.route_type || '');
  const basis = upper(details?.tsfin?.basis || row.basis || state.basis || details?.timesheet?.basis || '');
  const routeFamily = upper(row.route_family || details.route_family || state.route_family || details?.timesheet?.route_family || '');
  const noTimesheetRequired = boolish(
    details?.effective?.client_no_timesheet_required ??
    row.client_no_timesheet_required ??
    details.client_no_timesheet_required ??
    state.client_no_timesheet_required ??
    details?.timesheet?.client_no_timesheet_required
  );
  const importAuthoritative = !!(
    boolish(row.is_import_authoritative) ||
    boolish(details.is_import_authoritative) ||
    boolish(state.is_import_authoritative) ||
    routeFamily === 'IMPORT_AUTHORITATIVE' ||
    routeType === 'WEEKLY_NHSP' ||
    basis === 'NHSP' ||
    basis === 'HEALTHROSTER_SELF_BILL' ||
    (routeType === 'WEEKLY_HEALTHROSTER' && noTimesheetRequired)
  );
  const positiveEvidencePermission = !!(
    row.can_manage_evidence === true ||
    details.can_manage_evidence === true ||
    state.can_manage_evidence === true ||
    details.route_evidence_editable === true ||
    state.route_evidence_editable === true ||
    state?.meta?.route_evidence_editable === true ||
    details?.evidence_meta?.route_evidence_editable === true ||
    state?.evidence_meta?.route_evidence_editable === true
  );
  const policy = (typeof classifyTimesheetEditDomains === 'function')
    ? classifyTimesheetEditDomains({
        row,
        details,
        timesheet: ts,
        tsfin: details?.tsfin,
        contract_week: details?.contract_week,
        contract_week_id: row.contract_week_id || details.contract_week_id || details?.contract_week?.id || null,
        state,
        ctx
      })
    : null;
  const expenseStorageTarget = policy ? String(policy.expenseStorageTarget || '').trim().toUpperCase() : '';
  const expenseEvidenceStorageTarget = policy ? String(policy.expenseEvidenceStorageTarget || '').trim().toUpperCase() : '';
  const policyAllowsEvidence = policy ? (policy.canManageExpenseEvidence === true && (expenseEvidenceStorageTarget === 'TIMESHEET_EVIDENCE' || expenseEvidenceStorageTarget === 'CONTRACT_WEEK_STAGED_EVIDENCE')) : null;
  const canManageEvidence = policy
    ? !!(
        policyAllowsEvidence &&
        !boolish(row.is_view_only) &&
        !boolish(details.is_view_only) &&
        !boolish(details.evidence_document_locked) &&
        !boolish(row.evidence_document_locked)
      )
    : !!(
        !importAuthoritative &&
        !boolish(row.is_view_only) &&
        !boolish(details.is_view_only) &&
        !boolish(details.evidence_document_locked) &&
        !boolish(row.evidence_document_locked) &&
        positiveEvidencePermission
      );
  const authorised = policy ? !!policy.isAuthorised : !!boolish(row.is_authorised || ts.is_authorised || details?.tsfin?.authorised_at_utc || ts.authorised_at_utc);
  const lockReason = String(details.evidence_lock_reason || row.evidence_lock_reason || '').trim();
  const isProtectedEvidence = (ev) => {
    const kindU = upper(ev?.kind || ev?.staged_kind || '');
    const meta = (ev?.meta_json && typeof ev.meta_json === 'object') ? ev.meta_json : {};
    const sourceText = [
      ev?.source_system,
      ev?.source_badge,
      ev?.provenance,
      ev?.origin,
      meta.source_system,
      meta.source_badge,
      meta.provenance,
      meta.origin
    ].map(upper).filter(Boolean).join('|');
    return !!(
      boolish(ev?.system) ||
      boolish(ev?.is_system) ||
      boolish(ev?.is_view_only) ||
      boolish(ev?.protected) ||
      boolish(ev?.is_protected) ||
      boolish(ev?.from_import) ||
      boolish(meta.from_import) ||
      !!ev?.import_id ||
      !!meta.import_id ||
      kindU === 'AUTHORISATION' ||
      kindU === 'SYSTEM' ||
      kindU === 'NHSP' ||
      kindU === 'HEALTHROSTER' ||
      kindU === 'IMPORT' ||
      sourceText.includes('NHSP') ||
      sourceText.includes('HEALTHROSTER') ||
      sourceText.includes('IMPORT')
    );
  };

  L('renderEvidenceTab', { tsId, evidenceCount: evList.length });
  GE();

  const getUploadedDt = (ev) => {
    return ev?.uploaded_at_utc || ev?.uploaded_at || ev?.created_at || ev?.staged_at_utc || null;
  };

  const formatEvidenceDate = (iso) => {
    if (!iso) return '—';
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return String(iso);

    try {
      const s = d.toLocaleDateString('en-GB', {
        timeZone: 'Europe/London',
        weekday: 'short',
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      });
      return String(s).replace(',', '').replace(/\s+/g, ' ').trim();
    } catch {
      return d.toISOString().slice(0, 10);
    }
  };

  const formatEvidenceTime = (iso) => {
    if (!iso) return '—';
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return '—';

    try {
      const t = d.toLocaleTimeString('en-GB', {
        timeZone: 'Europe/London',
        hour: '2-digit',
        minute: '2-digit',
        hour12: false
      });
      const clean = String(t).replace(/\s+/g, '').trim();
      return clean ? `${clean}hrs` : '—';
    } catch {
      const hhmm = d.toISOString().slice(11, 16);
      return hhmm ? `${hhmm}hrs` : '—';
    }
  };

  const isDeletable = (ev) => {
    if (ev && typeof ev.can_delete === 'boolean') return !!ev.can_delete;
    if (ev && typeof ev.system === 'boolean') return !ev.system;
    return false;
  };

  const isReturnable = (ev) => {
    if (ev && typeof ev.can_return_to_queue === 'boolean') return !!ev.can_return_to_queue;
    return false;
  };

  const isManageable = (ev) => {
    const canReclassify = !!(ev && typeof ev.can_reclassify === 'boolean' ? ev.can_reclassify : false);
    const canReturn = isReturnable(ev);
    return !!(canReclassify || canReturn);
  };

  const typeLabel = (ev) => {
    const k = String(ev?.kind || '').trim().toUpperCase();
    if (!k) return 'Unknown';

    const map = {
      TIMESHEET: 'Timesheet',
      MILEAGE: 'Mileage',
      TRAVEL: 'Travel',
      ACCOMMODATION: 'Accommodation',
      OTHER: 'Other',
      QR: 'QR',
      PDF: 'PDF',
      ELECTRONIC_SIGNATURES: 'Electronic signatures',
      HEALTHROSTER: 'HealthRoster',
      NHSP: 'NHSP',
      AUTHORISATION: 'Timesheet Authorisation'
    };

    return map[k] || (k.charAt(0) + k.slice(1).toLowerCase());
  };

  const filenameLabel = (ev) => {
    const k = String(ev?.kind || '').trim().toUpperCase();
    if (k === 'AUTHORISATION') return '—';

    const fn = String(ev?.filename || '').trim();
    if (fn) return fn;

    const dn = String(ev?.display_name || '').trim();
    if (dn) return dn;

    const sk = String(ev?.storage_key || ev?.download_storage_key || '').trim();
    if (sk) {
      const parts = sk.split('/');
      const base = parts[parts.length - 1] || '';
      return base || '—';
    }
    return '—';
  };

  const uploadedByLabel = (ev) => {
    const k = String(ev?.kind || '').trim().toUpperCase();
    if (k === 'AUTHORISATION') {
      const actor =
        (ev?.meta_json && typeof ev.meta_json === 'object' && ev.meta_json.actor_display != null)
          ? String(ev.meta_json.actor_display).trim()
          : '';
      return actor || 'System';
    }

    const stagedBy =
      (ev && typeof ev.staged_by_display === 'string' && ev.staged_by_display.trim())
        ? ev.staged_by_display.trim()
        : null;

    if (stagedBy) return stagedBy;

    const by =
      (ev && typeof ev.uploaded_by_display === 'string' && ev.uploaded_by_display.trim())
        ? ev.uploaded_by_display.trim()
        : (ev && typeof ev.created_by_display === 'string' && ev.created_by_display.trim())
          ? ev.created_by_display.trim()
          : null;

    if (by) return by;

    const isSystem = !!ev?.system;
    if (isSystem) return 'System';

    return '—';
  };

  const sourceLabel = (ev) => {
    const explicit =
      (ev && typeof ev.source_badge === 'string' && ev.source_badge.trim())
        ? ev.source_badge.trim()
        : (ev?.meta_json && typeof ev.meta_json === 'object' && typeof ev.meta_json.source_label === 'string' && ev.meta_json.source_label.trim())
          ? ev.meta_json.source_label.trim()
          : (ev?.meta_json && typeof ev.meta_json === 'object' && typeof ev.meta_json.source_badge === 'string' && ev.meta_json.source_badge.trim())
            ? ev.meta_json.source_badge.trim()
            : '';

    if (explicit) return explicit;

    const kindU = String(ev?.kind || '').trim().toUpperCase();
    if (kindU === 'AUTHORISATION') return 'System';
    if (ev?.system) return 'System';
    if (ev?.is_staged_context) return 'Staged';
    return 'Attached';
  };

  const approvalLabel = (ev) => {
    const meta = (ev?.meta_json && typeof ev.meta_json === 'object') ? ev.meta_json : {};
    if (
      boolish(ev?.approved) || boolish(ev?.is_approved) ||
      boolish(meta.approved) || boolish(meta.is_approved) ||
      ev?.approved_at_utc || ev?.authorised_at_utc ||
      meta.approved_at_utc || meta.authorised_at_utc
    ) return 'Approved';

    const projection = details?.candidate_office_projection || row?.candidate_office_projection || {};
    const workflow = projection?.workflow || {};
    const approval = projection?.manager_approval || {};
    const currentWorkflowId = String(workflow.workflow_id || workflow.id || '').trim();
    const evidenceWorkflowId = String(
      ev?.candidate_workflow_id || meta.candidate_workflow_id || ''
    ).trim();
    const currentGeneration = Number(workflow.generation);
    const evidenceGeneration = Number(
      ev?.candidate_workflow_generation ?? meta.candidate_workflow_generation
    );
    const exactWorkflow = !!(
      currentWorkflowId && evidenceWorkflowId && currentWorkflowId === evidenceWorkflowId &&
      (!Number.isFinite(currentGeneration) || !Number.isFinite(evidenceGeneration) || currentGeneration === evidenceGeneration)
    );
    if (exactWorkflow && upper(approval.state) === 'APPROVED') return 'Approved';
    if (upper(ev?.kind || ev?.staged_kind) === 'AUTHORISATION') return 'Approved';
    return 'Not approved yet';
  };

  const evidenceIsHistorical = (ev) => {
    const meta = (ev?.meta_json && typeof ev.meta_json === 'object') ? ev.meta_json : {};
    const stateText = upper(ev?.state || ev?.status || meta.state || meta.status);
    return ev?.is_current === false || boolish(ev?.historical) || boolish(meta.historical) ||
      !!ev?.archived_at_utc || !!ev?.withdrawn_at_utc || !!ev?.superseded_at_utc ||
      !!ev?.superseded_by_id || ['HISTORICAL', 'WITHDRAWN', 'SUPERSEDED', 'RETIRED'].includes(stateText);
  };
  const currentEvidenceList = evList.filter((ev) => !evidenceIsHistorical(ev));

  const pageCountLabel = (ev) => {
    const direct =
      (ev?.page_count != null && Number.isFinite(Number(ev.page_count)))
        ? Number(ev.page_count)
        : (ev?.pdf_page_count != null && Number.isFinite(Number(ev.pdf_page_count)))
          ? Number(ev.pdf_page_count)
          : null;

    if (direct != null && direct > 0) return String(direct);

    const meta = (ev?.meta_json && typeof ev.meta_json === 'object') ? ev.meta_json : {};
    const metaCount =
      (meta.page_count != null && Number.isFinite(Number(meta.page_count)))
        ? Number(meta.page_count)
        : (meta.pdf_page_count != null && Number.isFinite(Number(meta.pdf_page_count)))
          ? Number(meta.pdf_page_count)
          : null;

    if (metaCount != null && metaCount > 0) return String(metaCount);
    return '—';
  };

  const hasDownloadableKey = (ev) => {
    const k1 = (ev?.download_storage_key != null) ? String(ev.download_storage_key).trim() : '';
    const k2 = (ev?.storage_key != null) ? String(ev.storage_key).trim() : '';
    return !!((k1 || k2) && (k1 || k2).replace(/^\/+/, '').trim());
  };

  const rowsHtml = currentEvidenceList.length
    ? currentEvidenceList.map(ev => {
        const id = (ev && ev.id != null) ? String(ev.id) : '';
        const system = !!ev?.system;
        const protectedEvidence = isProtectedEvidence(ev);
        const canDelete = !protectedEvidence && isDeletable(ev) && canManageEvidence;
        const canReturn = isReturnable(ev);
        const canManage = isManageable(ev);

        const dt = getUploadedDt(ev);
        const uploadedDate = escapeHtml(formatEvidenceDate(dt));
        const uploadedTime = escapeHtml(formatEvidenceTime(dt));

        const fileName = escapeHtml(filenameLabel(ev));
        const type = escapeHtml(typeLabel(ev));
        const uploadedBy = escapeHtml(uploadedByLabel(ev));
        const src = escapeHtml(sourceLabel(ev));
        const approval = approvalLabel(ev);
        const pageCount = escapeHtml(pageCountLabel(ev));

        const kindU = String(ev?.kind || '').trim().toUpperCase();
        const isAuthorisationRow = (kindU === 'AUTHORISATION');
        const assetState = String(ev?.asset_state || '').trim();
        const assetOperationId = String(ev?.asset_operation_id || ev?.asset_operation?.operation_id || '').trim();
        const timesheetDocumentState = String(ev?.timesheet_document_state || '').trim();
        const documentOperationId = String(
          ev?.timesheet_document_operation_id
          || ev?.document_operation_id
          || ev?.timesheet_document_operation?.operation_id
          || ''
        ).trim();
        const asyncProcessingHtml = (
          typeof window.isInvoiceAsyncUiEnabled === 'function'
          && window.isInvoiceAsyncUiEnabled()
          && typeof window.renderTimesheetEvidenceProcessingState === 'function'
          && (assetState || assetOperationId || timesheetDocumentState || documentOperationId)
        ) ? window.renderTimesheetEvidenceProcessingState({
          asset_state: assetState || 'QUEUED',
          asset_error: ev?.asset_error || ev?.asset_error_code || null,
          asset_operation_id: assetOperationId || null,
          asset_operation: ev?.asset_operation || null,
          timesheet_document_state: timesheetDocumentState || 'NOT_READY',
          timesheet_document_operation: ev?.timesheet_document_operation || null
        }) : '';

        const viewBtn = isAuthorisationRow
          ? ''
          : `
            <button type="button"
                    class="btn mini subtle"
                    style="background:transparent;border:1px solid rgba(255,255,255,.18);"
                    data-evidence-view="${escapeHtml(id)}">
              View
            </button>
          `;

        const manageBtn = (!isAuthorisationRow && canManageEvidence && !protectedEvidence && canManage)
          ? `
            <button type="button"
                    class="btn mini subtle"
                    style="background:transparent;border:1px solid rgba(255,255,255,.18);"
                    data-evidence-manage="${escapeHtml(id)}">
              Manage
            </button>
          `
          : '';

         const returnBtn = (canReturn && canManageEvidence && !protectedEvidence)
          ? `
            <button type="button"
                    class="btn mini subtle"
                    style="background:transparent;border:1px solid rgba(255,255,255,.18);"
                    data-evidence-return="${escapeHtml(id)}">
              Return to queue
            </button>
          `
          : '';

        const dlBtn = (!isAuthorisationRow && hasDownloadableKey(ev))
          ? `
            <button type="button"
                    class="btn mini subtle"
                    style="background:transparent;border:1px solid rgba(255,255,255,.18);"
                    onclick="window.__tsEvidenceDownload && window.__tsEvidenceDownload('${escapeHtml(id)}')">
              Download
            </button>
          `
          : '';

        const delBtn = canDelete
          ? `
            <button type="button"
                    class="btn mini subtle danger"
                    style="background:transparent;border:1px solid rgba(255,80,80,.35);"
                    data-evidence-remove="${escapeHtml(id)}">
              Delete
            </button>
          `
          : '';

        return `
          <tr data-evidence-id="${escapeHtml(id)}"
              data-timesheet-id="${escapeHtml(tsId)}"
              data-asset-state="${escapeHtml(assetState)}"
              data-asset-operation-id="${escapeHtml(assetOperationId)}"
              data-timesheet-document-state="${escapeHtml(timesheetDocumentState)}"
              data-document-operation-id="${escapeHtml(documentOperationId)}"
              class="${system ? 'system-evidence' : ''}">
            <td data-ctms-label="Evidence"><strong class="ctms-evidence-title">${fileName}</strong><span class="ctms-evidence-meta">${type} · Pages ${pageCount}</span></td>
            <td data-ctms-label="Source">
              <span class="pill">${src}</span>
            </td>
            <td data-ctms-label="Approval"><span class="pill ${approval === 'Approved' ? 'pill-ok' : 'pill-warn'}">${escapeHtml(approval)}</span></td>
            <td data-ctms-label="Uploaded"><strong class="ctms-evidence-uploaded">${uploadedDate}${uploadedTime === '—' ? '' : ` · ${uploadedTime}`}</strong><span class="ctms-evidence-meta">${uploadedBy}</span></td>
            <td data-ctms-label="Actions" style="text-align:right;">
              <div class="ctms-evidence-actions">
                ${viewBtn}
                ${manageBtn}
                ${returnBtn}
                ${dlBtn}
                ${delBtn}
              </div>
              ${asyncProcessingHtml ? `<div style="white-space:normal;text-align:left;">${asyncProcessingHtml}</div>` : ''}
            </td>
          </tr>
        `;
      }).join('')
    : `
      <tr>
        <td colspan="5" class="mini" style="opacity:.85;">No evidence uploaded yet.</td>
      </tr>
    `;

  const tableHtml = `
    <div class="scrollable-evidence" style="max-height:380px; overflow-y:auto;">
      <table class="ts-evidence-table ctms-timesheet-evidence-table" style="width:100%; border-collapse:collapse;">
        <thead>
          <tr>
            <th style="text-align:left;">Evidence</th>
            <th style="text-align:left;">Source</th>
            <th style="text-align:left;">Approval</th>
            <th style="text-align:left;">Uploaded</th>
            <th style="text-align:right;">Actions</th>
          </tr>
        </thead>
        <tbody>${rowsHtml}</tbody>
      </table>
    </div>
  `;

  const policyEvidenceReason = policy ? String(policy.expenseEvidenceDisabledReason || policy.expensesDisabledReason || '') : '';
  const plannedEvidenceGuidance = expenseEvidenceStorageTarget === 'CONTRACT_WEEK_STAGED_EVIDENCE'
    ? 'Evidence can be uploaded for this unprocessed week because expenses are being saved as a draft.'
    : '';
  const protectedEvidenceGuidance = policy?.requiresAdditionalManualForExpenses
    ? 'Evidence cannot be uploaded directly for this source row. Use Add Additional Manual if expenses need to be claimed.'
    : '';
  const lockBanner = policy
    ? (canManageEvidence ? plannedEvidenceGuidance : (protectedEvidenceGuidance || policyEvidenceReason || 'Evidence cannot be uploaded for this row because it does not have a supported expenses draft target.'))
    : (importAuthoritative
        ? 'Import source evidence is review-only. Use an additional manual timesheet for expenses or extra supporting items.'
        : (authorised
            ? 'Payment values are locked because this timesheet is authorised. Evidence files can still be managed if the row is not invoice/document locked.'
            : (lockReason ? `Evidence changes are locked: ${escapeHtml(lockReason)}` : '')));
  const hasTimesheetEvidence = currentEvidenceList.some((ev) => String(ev?.kind || ev?.staged_kind || '').trim().toUpperCase() === 'TIMESHEET');

  return `
    <div class="tabc ts-evidence-tab"
         data-ts-drop-zone-root="evidence"
         style="height:100%; display:flex; flex-direction:column;">
      <div style="display:flex;gap:8px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin-bottom:8px;">
        <div class="mini" style="opacity:.9;">${lockBanner ? lockBanner : 'Evidence file actions do not unlock hours, rates, pay, charge, mileage, travel, accommodation, or other financial values.'}</div>
        ${canManageEvidence ? `
          <button type="button" class="btn btn-outline" data-evidence-add="1" data-evidence-upload="1">Add evidence</button>
        ` : ''}
      </div>
      ${hasTimesheetEvidence ? `
        <div class="mini" style="margin-bottom:8px;opacity:.92;">
          To use a different timesheet image, delete this file or return it to the queue first, then add the new file.
        </div>
      ` : ''}

      <div class="card" style="flex:1; overflow:hidden;">
        <div class="row">
          <label>Current Evidence</label>
          <div class="controls" style="width:100%;">
            ${tableHtml}
          </div>
        </div>
      </div>

      <div class="mini" style="margin-top:10px; opacity:.85; text-align:center;">
        ${canManageEvidence ? 'Drag a PDF or image anywhere inside this tab to upload new evidence.' : escapeHtml(protectedEvidenceGuidance || policyEvidenceReason || 'Evidence cannot be uploaded for this row because it does not have a supported expenses draft target.')}
      </div>

    </div>
  `;
}
// Utility: map route_type / status to pill CSS classes
function classifyTimesheetPill(kind, value) {
  const v = String(value || '').toUpperCase();
  switch (kind) {
    case 'stage':
      if (v === 'PAID') return 'pill pill-ok';
      if (v === 'INVOICED') return 'pill pill-info';
      if (v === 'READY_FOR_INVOICE') return 'pill pill-info';
      if (v === 'READY_FOR_HR') return 'pill pill-info';
      if (v === 'PENDING_AUTH') return 'pill pill-warn';
      if (v === 'UNPROCESSED') return 'pill pill-warn';
      if (v === 'PROCESSED') return 'pill pill-info';
      if (v === 'NEEDS_ATTENTION') return 'pill pill-bad';
      return 'pill pill-muted';

    case 'route':
      if (v.startsWith('WEEKLY_NHSP')) return 'pill pill-nhsp';
      if (v === 'WEEKLY_HEALTHROSTER') return 'pill pill-hr';
      if (v.startsWith('WEEKLY')) return 'pill pill-weekly';
      if (v.startsWith('DAILY')) return 'pill pill-daily';
      return 'pill pill-muted';

    case 'scope':
      return (v === 'WEEKLY')
        ? 'pill pill-weekly'
        : (v === 'DAILY' ? 'pill pill-daily' : 'pill pill-muted');

    case 'mode':
      return (v === 'ELECTRONIC')
        ? 'pill pill-elec'
        : (v === 'MANUAL' ? 'pill pill-manual' : 'pill pill-muted');

    default:
      return 'pill pill-muted';
  }
}
function computeRequiresTimesheetAuthorisation(details, row) {
  const ts = (details && details.timesheet) ? details.timesheet : {};
  const tsfin = (details && details.tsfin) ? details.tsfin : {};

  const authorisedAt =
    (ts && ts.authorised_at_server) ||
    (row && row.authorised_at_server) ||
    null;

  const authorised = !!authorisedAt;

  const procStatusRaw =
    (tsfin && tsfin.processing_status) ||
    (details && details.processing_status) ||
    (row && row.processing_status) ||
    '';

  const procStatus = String(procStatusRaw || '').toUpperCase();

  const policy =
    (details && details.policy) ||
    (details && details.tsfin_policy) ||
    {};

  const boolish = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on');
  };

  // ✅ Prefer contract-resolved effective flags from the SUMMARY ROW
  // ✅ Fallback to policy using boolish (not !!) to avoid "false" -> true
  const requiresHr =
    (row && Object.prototype.hasOwnProperty.call(row, 'client_requires_hr'))
      ? boolish(row.client_requires_hr)
      : boolish(policy && policy.requires_hr);

  const autoprocessHr =
    (row && Object.prototype.hasOwnProperty.call(row, 'client_autoprocess_hr'))
      ? boolish(row.client_autoprocess_hr)
      : boolish(policy && policy.autoprocess_hr);

  const requires =
    (procStatus === 'PENDING_AUTH') ||
    (requiresHr && !autoprocessHr && procStatus === 'READY_FOR_HR');

  const showAwaitingBadge = requires && !authorised;

  return { requires, authorised, showAwaitingBadge };
}

function computeTimesheetProcessingState(details, row) {
  const ts = (details && details.timesheet) ? details.timesheet : {};
  const tsfin = (details && details.tsfin) ? details.tsfin : {};

  const authInfo = (typeof computeRequiresTimesheetAuthorisation === 'function')
    ? computeRequiresTimesheetAuthorisation(details, row)
    : { requires: false, authorised: false, showAwaitingBadge: false };

  const requiresAuth = !!authInfo.requires;
  const authorised = !!authInfo.authorised;

  const invoiced =
    !!((tsfin && tsfin.locked_by_invoice_id) || (row && row.locked_by_invoice_id));

  const paid =
    !!((tsfin && tsfin.paid_at_utc) || (row && row.paid_at_utc));

  const hasRealTs =
    !!((ts && ts.timesheet_id) || (row && row.timesheet_id));

  const upper = (v) => String(v || '').trim().toUpperCase();

  const backendLifecycle =
    upper(
      (tsfin && tsfin.processing_status) ||
      (row && row.processing_status) ||
      (row && row.tools_stage) ||
      (row && row.summary_stage) ||
      ''
    );

  // Priority order (must be mutually exclusive)
  if (requiresAuth && !authorised) {
    return { key: 'PROCESSED', label: 'Processed' };
  }

  if (authorised && invoiced && paid) {
    return { key: 'AUTH_INVOICED_PAID', label: 'Authorised, Invoiced & Paid' };
  }

  if (authorised && invoiced && !paid) {
    return { key: 'AUTH_INVOICED_NOT_PAID', label: 'Authorised, Invoiced but not yet Paid' };
  }

  if (authorised && paid && !invoiced) {
    return { key: 'AUTH_PAID_NOT_INVOICED', label: 'Authorised, Paid but not yet Invoiced' };
  }

  if (authorised && !invoiced && !paid) {
    return { key: 'AUTH_NOT_INVOICED_NOT_PAID', label: 'Authorised, not invoiced, not paid' };
  }

  if (invoiced && !authorised) {
    return { key: 'INVOICED', label: 'Invoiced' };
  }

  if (paid && !authorised) {
    return { key: 'PAID', label: 'Paid' };
  }

  if (hasRealTs && backendLifecycle === 'UNPROCESSED') {
    return { key: 'UNPROCESSED', label: 'Unprocessed' };
  }

  if (!hasRealTs) {
    return { key: 'UNPROCESSED', label: 'Unprocessed' };
  }

  if (hasRealTs && backendLifecycle) {
    return { key: 'PROCESSED', label: 'Processed' };
  }

  return { key: 'PROCESSED', label: 'Processed' };
}

async function openTimesheetEvidenceViewerExisting(evidenceItem) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][EVIDENCE][VIEWER]');
  GC('openTimesheetEvidenceViewerExisting');
  const viewerOptions = (arguments[1] && typeof arguments[1] === 'object') ? arguments[1] : {};

  if (!evidenceItem || typeof evidenceItem !== 'object') {
    GE();
    throw new Error('Evidence item is required.');
  }

  const expenseEvidenceItems = Array.isArray(viewerOptions?.evidenceItems)
    ? viewerOptions.evidenceItems.filter(item => item && typeof item === 'object')
    : [];
  const expenseEvidenceIndex = Math.max(0, Math.min(
    Number.isFinite(Number(viewerOptions?.evidenceIndex)) ? Number(viewerOptions.evidenceIndex) : 0,
    Math.max(0, expenseEvidenceItems.length - 1)
  ));
  const expenseCategory = viewerOptions?.expenseCategory && typeof viewerOptions.expenseCategory === 'object'
    ? viewerOptions.expenseCategory
    : null;
  const expenseCategoryKey = String(viewerOptions?.expenseCategoryKey || expenseCategory?.category || evidenceItem.kind || '').trim().toUpperCase();
  const isExpenseCategoryViewer = !!(expenseCategory && expenseCategoryKey && expenseEvidenceItems.length);

   const mc = window.modalCtx || {};
  const tsId =
    mc.data?.timesheet_id ||
    (mc.timesheetDetails && mc.timesheetDetails.timesheet && mc.timesheetDetails.timesheet.timesheet_id) ||
    null;

  const contractWeekId =
    mc.data?.contract_week_id ||
    mc.timesheetDetails?.contract_week_id ||
    mc.timesheetDetails?.contract_week?.id ||
    null;

  if (!tsId && !contractWeekId) {
    GE();
    throw new Error('Timesheet context missing; cannot view evidence.');
  }

  const isPlannedWeekContext = !tsId && !!contractWeekId;

  const tsIdNow = () =>
    window.modalCtx?.data?.timesheet_id ||
    window.modalCtx?.timesheetDetails?.timesheet?.timesheet_id ||
    null;

  const weekIdNow = () =>
    window.modalCtx?.data?.contract_week_id ||
    window.modalCtx?.timesheetDetails?.contract_week_id ||
    window.modalCtx?.timesheetDetails?.contract_week?.id ||
    null;

  const expectedNow = () =>
    window.modalCtx?.timesheetMeta?.expected_timesheet_id ||
    tsIdNow();

  const handleMovedInViewer = async (err, label) => {
    const st = err?.status ?? null;
    const j  = err?.json || null;

    if (isPlannedWeekContext) {
      return false;
    }

    if (!(st === 409 && j && j.error === 'TIMESHEET_MOVED' && j.current_timesheet_id)) {
      return false;
    }

    const newId = String(j.current_timesheet_id);

    try {
      window.modalCtx ||= {};
      window.modalCtx.data ||= {};
      window.modalCtx.timesheetMeta ||= {};

      window.modalCtx.data.timesheet_id = newId;
      window.modalCtx.data.id = newId;
      window.modalCtx.timesheetMeta.expected_timesheet_id = newId;
    } catch {}

    try {
      const fresh = await fetchTimesheetDetails(newId);
      window.modalCtx.timesheetDetails = fresh;
    } catch {}

    try {
      if (typeof refreshTimesheetEvidenceIntoModalState === 'function') {
        await refreshTimesheetEvidenceIntoModalState(newId);
      }
    } catch {}

    try {
      if (typeof refreshTimesheetsSummaryAfterRotation === 'function') {
        refreshTimesheetsSummaryAfterRotation(newId);
      }
    } catch {}

    try { window.__toast && window.__toast('This timesheet changed while you were editing; review and try again.'); } catch {}

    try { document.getElementById('btnCloseModal')?.click(); } catch {}

    return true;
  };

  const evidenceId = evidenceItem.id != null ? String(evidenceItem.id) : '';
  const previewMode = String(evidenceItem.preview_mode || evidenceItem.preview_kind || '').trim().toUpperCase();
  const isCandidateHoursPack = previewMode === 'CANDIDATE_HOURS_SUBMISSION';

  const isSystem =
    (typeof evidenceItem.system === 'boolean') ? evidenceItem.system : String(evidenceId).startsWith('SYS:');

  const isViewOnly = !!evidenceItem.is_view_only;

  const canDelete = !isExpenseCategoryViewer && !isViewOnly && (
    (typeof evidenceItem.can_delete === 'boolean')
      ? evidenceItem.can_delete
      : !isSystem
  );

  const canReturnToQueue = !isExpenseCategoryViewer && !isViewOnly && (
    (typeof evidenceItem.can_return_to_queue === 'boolean')
      ? evidenceItem.can_return_to_queue
      : false
  );

  const canonicalKinds = ['TIMESHEET', 'MILEAGE', 'TRAVEL', 'ACCOMMODATION', 'OTHER'];

  const canEditType = !isExpenseCategoryViewer && !isViewOnly && (
    (typeof evidenceItem.can_reclassify === 'boolean')
      ? evidenceItem.can_reclassify
      : (!isSystem && canonicalKinds.includes(String(evidenceItem.kind || '').trim().toUpperCase()))
  );

  const kind = (evidenceItem.kind != null) ? String(evidenceItem.kind) : 'Evidence';
  const dtRaw = evidenceItem.uploaded_at_utc || evidenceItem.uploaded_at || evidenceItem.created_at || evidenceItem.staged_at_utc || null;

  const fmtUkDateTime = (iso) => {
    if (!iso) return '—';
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return String(iso);
    try {
      return d.toLocaleString('en-GB', {
        timeZone: 'Europe/London',
        weekday: 'short',
        day: '2-digit',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        hour12: false
      });
    } catch {
      return d.toISOString();
    }
  };

  const presignDownload = async (key) => {
    const cleanKey = String(key || '').trim().replace(/^\/+/, '');
    const res = await authFetch(API('/api/files/presign-download'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ key: cleanKey })
    });
    const text = await res.text().catch(() => '');
    if (!res.ok) throw new Error(text || 'Failed to presign download URL');
    const json = text ? JSON.parse(text) : {};
    const url = json.url || json.signed_url || null;
    if (!url) throw new Error('No URL returned from presign-download');
    return url;
  };

  // ─────────────────────────────────────────────────────────────
  // IMPORT TABLE preview (raw table: multi-row header_rows + raw_columns)
  // ─────────────────────────────────────────────────────────────
  if (previewMode === 'IMPORT_TABLE') {
    const importId =
      (evidenceItem?.meta_json && evidenceItem.meta_json.import_id != null && String(evidenceItem.meta_json.import_id).trim())
        ? String(evidenceItem.meta_json.import_id).trim()
        : (() => {
            // Fallback: parse import id from SYS:*:* id (backend uses SYS:<kind>:<importId>)
            const s = String(evidenceId || '');
            const parts = s.split(':');
            return (parts.length >= 3) ? String(parts[parts.length - 1]) : null;
          })();

    if (!importId) {
      GE();
      throw new Error('Import evidence is missing import_id.');
    }

    const tsIdForPrint = tsIdNow() || tsId;

    // fetch rows (scoped to this import_id)
    const res = await authFetch(
      API(`/api/timesheets/${encodeURIComponent(String(tsIdForPrint))}/source-print?import_id=${encodeURIComponent(String(importId))}&include_excluded=true`)
    );
    const txt = await res.text().catch(() => '');
    if (!res.ok) {
      GE();
      throw new Error(txt || 'Failed to load import rows');
    }
    const json = txt ? JSON.parse(txt) : {};
    const imports = Array.isArray(json.imports) ? json.imports : [];
    const imp = imports.find(x => String(x?.import_id) === String(importId)) || imports[0] || null;

    const headerRowsRaw = Array.isArray(imp?.header_rows) ? imp.header_rows : [];
    const headerColsRaw = Array.isArray(imp?.header_columns) ? imp.header_columns : [];
    const rows = Array.isArray(imp?.rows) ? imp.rows : [];

    // Normalise headers:
    // - Prefer header_rows (multi-row). Preserve blanks (do NOT drop).
    // - Else fallback to single-row header_columns.
    let headerRows = [];
    if (Array.isArray(headerRowsRaw) && headerRowsRaw.length) {
      headerRows = headerRowsRaw.map(r => (Array.isArray(r) ? r : []));
    } else if (Array.isArray(headerColsRaw) && headerColsRaw.length) {
      headerRows = [headerColsRaw];
    } else {
      headerRows = [];
    }

    // Column count:
    // max(header_rows widths) -> else header_columns length -> else first row raw_columns length -> else 0
    let colCount = 0;
    for (const r of headerRows) {
      if (Array.isArray(r) && r.length > colCount) colCount = r.length;
    }
    if (colCount === 0 && Array.isArray(headerColsRaw) && headerColsRaw.length) colCount = headerColsRaw.length;
    if (colCount === 0 && Array.isArray(rows?.[0]?.raw_columns)) colCount = rows[0].raw_columns.length;

    if (!Number.isFinite(colCount) || colCount < 0) colCount = 0;

    // Pad header rows to colCount with blanks (preserve alignment)
    const headerRowsPadded = headerRows.map(r =>
      Array.from({ length: colCount }, (_, i) => (i < (r?.length || 0) ? r[i] : ''))
    );

    // ─────────────────────────────────────────────────────────────
    // Formatting helpers (match PDF renderer behaviour)
    // ─────────────────────────────────────────────────────────────
    const pad2 = (n) => String(n).padStart(2, '0');

    const toNum = (v) => {
      if (typeof v === 'number') return Number.isFinite(v) ? v : null;
      const s = String(v ?? '').trim();
      if (!s) return null;
      const n = Number(s);
      return Number.isFinite(n) ? n : null;
    };

    const excelSerialToDmy = (v) => {
      const n = toNum(v);
      if (n == null) return String(v ?? '');
      if (n < 20000 || n > 90000) return String(v ?? '');
      const base = Date.UTC(1899, 11, 30, 0, 0, 0, 0);
      const ms = base + Math.round(n) * 86400000;
      if (!Number.isFinite(ms)) return String(v ?? '');
      const d = new Date(ms);
      if (Number.isNaN(d.getTime())) return String(v ?? '');
      return `${pad2(d.getUTCDate())}/${pad2(d.getUTCMonth() + 1)}/${d.getUTCFullYear()}`;
    };

    // ✅ Hardened:
    // - For fraction-of-day values (0..2) => HH:MM
    // - For Excel serial date-time values (allowSerial=true) => use fractional part for HH:MM
    // - For duration columns (total/hours) we keep allowSerial=false
    const excelFracToHHMM = (v, allowSerial) => {
      const n = toNum(v);
      if (n == null) {
        const s = String(v ?? '').trim();
        if (/^\d{1,2}:\d{2}(:\d{2})?$/.test(s)) {
          const parts = s.split(':');
          const hh = pad2(Number(parts[0]) || 0);
          const mm = pad2(Number(parts[1]) || 0);
          return `${hh}:${mm}`;
        }
        return String(v ?? '');
      }

      if (n < 0) return String(v ?? '');

      // fraction-of-day (supports durations up to 48h)
      if (n <= 2) {
        const mins = Math.round(n * 1440);
        const hh = Math.floor(mins / 60);
        const mm = mins % 60;
        return `${pad2(hh)}:${pad2(mm)}`;
      }

      // Serial date-time: fractional part (clock time only)
      if (allowSerial === true && n > 2 && n < 90000) {
        const frac = n - Math.floor(n);
        if (frac >= 0 && frac <= 1) {
          const mins = Math.round(frac * 1440);
          const hh = Math.floor(mins / 60);
          const mm = mins % 60;
          return `${pad2(hh)}:${pad2(mm)}`;
        }
      }

      return String(v ?? '');
    };

    // ✅ Improved break handling:
    // - If 0 < n < 1 => Excel day-fraction => minutes = n * 1440
    // - Else assume minutes and round to int
    // - If HH:MM(/:SS) string => convert to minutes
    const fmtBreakMins = (v) => {
      const n = toNum(v);
      if (n == null) {
        const s = String(v ?? '').trim();
        if (/^\d{1,2}:\d{2}(:\d{2})?$/.test(s)) {
          const parts = s.split(':');
          const hh = Number(parts[0]) || 0;
          const mm = Number(parts[1]) || 0;
          const mins = (hh * 60) + mm;
          return String(Math.round(mins));
        }
        return String(v ?? '');
      }
      if (n > 0 && n < 1) return String(Math.round(n * 1440));
      return String(Math.round(n));
    };

    const fmtMoney = (v) => {
      if (typeof v === 'string') {
        const s = v.trim();
        if (s && Number.isFinite(Number(s))) return s; // preserve numeric strings like "50.7"
        return String(v ?? '');
      }
      const n = toNum(v);
      if (n == null) return String(v ?? '');
      return n.toFixed(2);
    };

    const normH = (s) => String(s || '').trim().toLowerCase().replace(/\s+/g, ' ');

    // Determine per-column meaning using headers (prefer header_rows bottom-up, else header_columns)
    const labelAt = (i) => {
      for (let r = headerRowsPadded.length - 1; r >= 0; r--) {
        const row = headerRowsPadded[r];
        if (!Array.isArray(row)) continue;
        const v = (i < row.length) ? String(row[i] ?? '').trim() : '';
        if (v) return v;
      }
      if (Array.isArray(headerColsRaw) && i < headerColsRaw.length) {
        const v2 = String(headerColsRaw[i] ?? '').trim();
        if (v2) return v2;
      }
      return '';
    };

    // ✅ UPDATED: column kind detection
    // - From/To/Start/End => time (clock time, allowSerial=true)
    // - Total/Hours => time (duration, allowSerial=false) so Excel fractions show HH:MM
    // - Any Break => break duration (except break start/end which are time)
    // colKinds[i] = { kind: 'text'|'date'|'time'|'break'|'money', allowSerial: boolean }
    const colKinds = [];
    for (let i = 0; i < colCount; i++) {
      const hn = normH(labelAt(i));
      let kind = 'text';
      let allowSerial = false;

      if (hn.includes('date')) {
        kind = 'date';
      } else {
        const isClockTimeHeader =
          hn === 'from' || hn === 'to' ||
          hn === 'start' || hn === 'end' ||
          hn === 'from time' || hn === 'to time' || hn === 'start time' || hn === 'end time' ||
          hn.endsWith(' from') || hn.endsWith(' to') || hn.endsWith(' start') || hn.endsWith(' end') ||
          hn.endsWith(' from time') || hn.endsWith(' to time') || hn.endsWith(' start time') || hn.endsWith(' end time');

        const isDurationHeader =
          hn === 'total' ||
          hn === 'hours' ||
          hn === 'hrs' ||
          hn === 'hours worked' ||
          hn === 'actual hours' ||
          hn === 'total hours' ||
          hn.startsWith('hours ') ||
          hn.endsWith(' hours');

        if (isClockTimeHeader) {
          kind = 'time';
          allowSerial = true;
        } else if (isDurationHeader) {
          kind = 'time';
          allowSerial = false;
        } else if (hn.includes('break')) {
          if (hn.includes('start') || hn.includes('end')) {
            kind = 'time';
            allowSerial = true;
          } else {
            kind = 'break';
          }
        } else if (hn === 'commission' || hn.includes('commission') || hn === 'total cost' || hn.includes('total cost')) {
          kind = 'money';
        }
      }

      colKinds.push({ kind, allowSerial });
    }

    // Download key
    const downloadKeyRaw =
      (evidenceItem.storage_key != null && String(evidenceItem.storage_key).trim())
        ? String(evidenceItem.storage_key).trim()
        : (evidenceItem.file_key != null && String(evidenceItem.file_key).trim())
          ? String(evidenceItem.file_key).trim()
          : (evidenceItem.download_storage_key != null && String(evidenceItem.download_storage_key).trim())
            ? String(evidenceItem.download_storage_key).trim()
            : (evidenceItem.r2_key != null && String(evidenceItem.r2_key).trim())
              ? String(evidenceItem.r2_key).trim()
              : (evidenceItem.storageKey != null && String(evidenceItem.storageKey).trim())
                ? String(evidenceItem.storageKey).trim()
                : (evidenceItem.fileKey != null && String(evidenceItem.fileKey).trim())
                  ? String(evidenceItem.fileKey).trim()
                  : (evidenceItem.downloadStorageKey != null && String(evidenceItem.downloadStorageKey).trim())
                    ? String(evidenceItem.downloadStorageKey).trim()
                    : (evidenceItem.r2Key != null && String(evidenceItem.r2Key).trim())
                      ? String(evidenceItem.r2Key).trim()
                      : '';

    const downloadKey = downloadKeyRaw.replace(/^\/+/, '').trim();

    const commonWrapStyle = `
      <style>
        .ts-import-wrap {
          max-height:520px;
          overflow:auto;
          border:1px solid var(--line);
          border-radius:8px;
          background:#000;
        }
        table.ts-import-table {
          width:100%;
          border-collapse:collapse;
        }
        table.ts-import-table th,
        table.ts-import-table td {
          padding:6px 8px;
          vertical-align:top;
          border:1px solid rgba(255,255,255,.16);
        }
        table.ts-import-table thead th {
          background:#0f0f0f;
          position:sticky;
          z-index:5;
          border:1px solid rgba(255,255,255,.22);
          text-align:left;
          white-space:normal;
        }
        table.ts-import-table td {
          white-space:normal;
        }
      </style>
    `;

    const mkTableRawImport = () => {
      const hdrRows =
        (headerRowsPadded.length && colCount > 0)
          ? headerRowsPadded
          : (colCount > 0 ? [Array.from({ length: colCount }, (_, i) => `Column ${i + 1}`)] : []);

      const head = hdrRows.length
        ? `
          <thead>
            ${hdrRows.map((rowArr, rowIdx) => `
              <tr>
                ${rowArr.map((cell, colIdx) => {
                  const topPx = rowIdx * 32;
                  const z = 10 - rowIdx;
                  const v = (cell == null) ? '' : String(cell);
                  return `<th style="top:${topPx}px; z-index:${z};">${escapeHtml(v)}</th>`;
                }).join('')}
              </tr>
            `).join('')}
          </thead>
        `
        : '';

      const body = rows.length
        ? rows.map((r) => {
            const raw = Array.isArray(r?.raw_columns) ? r.raw_columns : [];
            const cells = [];
            for (let i = 0; i < colCount; i++) {
              const v0 = (i < raw.length) ? raw[i] : '';
              const meta = colKinds[i] || { kind: 'text', allowSerial: false };
              const k = meta.kind || 'text';

              let out = '';
              if (k === 'date') out = excelSerialToDmy(v0);
              else if (k === 'time') out = excelFracToHHMM(v0, meta.allowSerial === true);
              else if (k === 'break') out = fmtBreakMins(v0);
              else if (k === 'money') out = fmtMoney(v0);
              else out = String(v0 ?? '');

              cells.push(`<td>${escapeHtml(out)}</td>`);
            }
            return `<tr>${cells.join('')}</tr>`;
          }).join('')
        : `<tr><td colspan="${escapeHtml(String(Math.max(colCount, 1)))}" style="padding:10px; opacity:.85;">No rows found for this import.</td></tr>`;

      return `
        ${commonWrapStyle}
        <div class="ts-import-wrap">
          <table class="ts-import-table">
            ${head}
            <tbody>${body}</tbody>
          </table>
        </div>
      `;
    };

    const title = `Import evidence ${String(tsIdForPrint).slice(0, 8)}…`;
    const dlBtnId = `tsImportDl_${Date.now()}_${Math.random().toString(36).slice(2)}`;

    const downloadBtn = downloadKey
      ? `<button type="button"
                 id="${dlBtnId}"
                 class="pill"
                 style="cursor:pointer;border:1px solid var(--line);background:transparent;color:inherit;padding:6px 10px;border-radius:999px;">
           Download full file
         </button>`
      : `<span class="mini" style="opacity:.85;">No downloadable import file key</span>`;

    const rowsMatched = Array.isArray(rows) ? rows.length : 0;
    const sourceLabel = String(imp?.source_system || evidenceItem.kind || 'IMPORT');
    const headerRowsCount = Array.isArray(headerRowsRaw) ? headerRowsRaw.length : 0;

    const bodyHtml = `
      <div class="tabc">
        <div class="card">
          <div class="row">
            <label>Source</label>
            <div class="controls">
              <span class="mini">${escapeHtml(sourceLabel)}</span>
              <div class="mini" style="opacity:.75; margin-top:2px;">
                Raw import view (no derived columns)
              </div>
            </div>
          </div>
          <div class="row">
            <label>Rows matched</label>
            <div class="controls">
              <span class="mini">${escapeHtml(String(rowsMatched))}</span>
            </div>
          </div>
          <div class="row">
            <label>Header rows</label>
            <div class="controls">
              <span class="mini">${escapeHtml(String(headerRowsCount || (headerColsRaw.length ? 1 : 0)))}</span>
            </div>
          </div>
          <div class="row">
            <label>Date</label>
            <div class="controls">
              <span class="mini">${escapeHtml(fmtUkDateTime(dtRaw))}</span>
            </div>
          </div>
          <div class="row">
            <label>Download</label>
            <div class="controls">
              ${downloadBtn}
            </div>
          </div>
        </div>

        <div class="card" style="margin-top:10px;">
          <div class="row">
            <label>Rows (this timesheet only)</label>
            <div class="controls">
              ${mkTableRawImport()}
            </div>
          </div>
        </div>
      </div>
    `;

    showModal(
      title,
      [{ key: 'view', title: 'Evidence' }],
      () => bodyHtml,
      async () => ({ ok: true }),
      false,
      undefined,
      {
        kind: 'timesheet-evidence-viewer',
        frameEntity: 'timesheet-evidence',
        noParentGate: true,
        forceEdit: true
      }
    );

    // Wire download (best-effort)
    try {
      if (downloadKey) {
        const wire = async () => {
          const btn = document.getElementById(dlBtnId);
          if (!btn || btn.__wired) return;
          btn.__wired = true;
          btn.addEventListener('click', async () => {
            try {
              const u = await presignDownload(downloadKey);
              window.open(u, '_blank', 'noopener,noreferrer');
            } catch (e) {
              try { window.__toast && window.__toast(e?.message || 'Download failed'); } catch {}
            }
          });
        };
        try { requestAnimationFrame(() => requestAnimationFrame(wire)); } catch { wire(); }
      }
    } catch {}

    GE();
    return;
  }

  // ─────────────────────────────────────────────────────────────
  // SIGNATURES preview (Electronic submission evidence)
  // ─────────────────────────────────────────────────────────────
  if (previewMode === 'SIGNATURES') {
    const meta = (evidenceItem && evidenceItem.meta_json && typeof evidenceItem.meta_json === 'object')
      ? evidenceItem.meta_json
      : {};

    const bookingId = meta.booking_id ? String(meta.booking_id) : '';
    if (!bookingId) {
      GE();
      throw new Error('Electronic evidence missing booking_id.');
    }

    const version = (meta.version != null && Number.isFinite(Number(meta.version))) ? Number(meta.version) : null;

    // Presign signature GETs
    const presRes = await authFetch(API('/signatures/presign-get/batch'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        items: [
          { booking_id: bookingId, which: 'nurse', ...(version != null ? { version } : {}) },
          { booking_id: bookingId, which: 'authoriser', ...(version != null ? { version } : {}) }
        ],
        expires_seconds: 600
      })
    });

    const presTxt = await presRes.text().catch(() => '');
    if (!presRes.ok) {
      GE();
      throw new Error(presTxt || 'Failed to presign signature URLs');
    }

    const presJson = presTxt ? JSON.parse(presTxt) : {};
    const links = Array.isArray(presJson.links) ? presJson.links : [];

    const nurseUrl = (links.find(x => String(x?.which || '') === 'nurse') || {}).get_url || null;
    const authUrl  = (links.find(x => String(x?.which || '') === 'authoriser') || {}).get_url || null;

    const authName = meta.auth_name ? String(meta.auth_name) : '';
    const authJob  = meta.auth_job_title ? String(meta.auth_job_title) : '';
    const authAt   = meta.authorised_at_server ? String(meta.authorised_at_server) : (dtRaw ? String(dtRaw) : '');

    const scope = String(meta.sheet_scope || '').toUpperCase();
    const summaryLines = [];

    if (scope === 'DAILY') {
      const s = meta.worked_start_iso ? String(meta.worked_start_iso) : '';
      const e = meta.worked_end_iso ? String(meta.worked_end_iso) : '';
      const bs = meta.break_start_iso ? String(meta.break_start_iso) : '';
      const be = meta.break_end_iso ? String(meta.break_end_iso) : '';
      const bm = (meta.break_minutes != null) ? String(meta.break_minutes) : '';
      if (s && e) summaryLines.push(`Worked: ${s} → ${e}`);
      if (bs && be) summaryLines.push(`Break: ${bs} → ${be}`);
      else if (bm) summaryLines.push(`Break minutes: ${bm}`);
    } else if (scope === 'WEEKLY') {
      const we = meta.week_ending_date ? String(meta.week_ending_date) : '';
      if (we) summaryLines.push(`Week ending: ${we}`);
      const sched = meta.actual_schedule_json;
      if (Array.isArray(sched) && sched.length > 0) summaryLines.push(`Shifts: ${sched.length}`);
    }

    const title = `Electronic evidence ${String(tsId).slice(0, 8)}…`;

    const bodyHtml = `
      <div class="tabc">
        <div class="card">
          <div class="row">
            <label>Authorised at server</label>
            <div class="controls">
              <span class="mini">${escapeHtml(fmtUkDateTime(authAt))}</span>
            </div>
          </div>
          <div class="row">
            <label>Authoriser</label>
            <div class="controls">
              <span class="mini">${escapeHtml([authName, authJob].filter(Boolean).join(' — ') || '—')}</span>
            </div>
          </div>
          <div class="row">
            <label>Shift summary</label>
            <div class="controls">
              <div class="mini" style="opacity:.9;">
                ${summaryLines.length ? summaryLines.map(x => `<div>${escapeHtml(x)}</div>`).join('') : '—'}
              </div>
            </div>
          </div>
        </div>

        <div class="card" style="margin-top:10px;">
          <div class="row">
            <label>Signatures</label>
            <div class="controls" style="display:flex; gap:12px; flex-wrap:wrap;">
              <div style="flex:1; min-width:240px;">
                <div class="mini" style="opacity:.85; margin-bottom:6px;">Candidate signature</div>
                ${nurseUrl
                  ? `<div class="ctms-evidence-signature-sheet"><img src="${nurseUrl}" alt="Candidate signature" /></div>`
                  : `<div class="mini" style="opacity:.85;">Not available</div>`}
              </div>

              <div style="flex:1; min-width:240px;">
                <div class="mini" style="opacity:.85; margin-bottom:6px;">Manager signature</div>
                ${authUrl
                  ? `<div class="ctms-evidence-signature-sheet"><img src="${authUrl}" alt="Manager signature" /></div>`
                  : `<div class="mini" style="opacity:.85;">Not available</div>`}
              </div>
            </div>
          </div>
        </div>
      </div>
    `;

    showModal(
      title,
      [{ key: 'view', title: 'Evidence' }],
      () => bodyHtml,
      async () => ({ ok: true }),
      false,
      undefined,
      {
        kind: 'timesheet-evidence-viewer',
        frameEntity: 'timesheet-evidence',
        noParentGate: true,
        forceEdit: true
      }
    );

    GE();
    return;
  }

  // ─────────────────────────────────────────────────────────────
  // Default: PDF/file preview
  // ─────────────────────────────────────────────────────────────
  const storageKeyRaw =
    (evidenceItem.storage_key != null && String(evidenceItem.storage_key).trim())
      ? String(evidenceItem.storage_key).trim()
      : (evidenceItem.file_key != null && String(evidenceItem.file_key).trim())
        ? String(evidenceItem.file_key).trim()
        : (evidenceItem.download_storage_key != null && String(evidenceItem.download_storage_key).trim())
          ? String(evidenceItem.download_storage_key).trim()
          : (evidenceItem.r2_key != null && String(evidenceItem.r2_key).trim())
            ? String(evidenceItem.r2_key).trim()
            : (evidenceItem.storageKey != null && String(evidenceItem.storageKey).trim())
              ? String(evidenceItem.storageKey).trim()
              : (evidenceItem.fileKey != null && String(evidenceItem.fileKey).trim())
                ? String(evidenceItem.fileKey).trim()
                : (evidenceItem.downloadStorageKey != null && String(evidenceItem.downloadStorageKey).trim())
                  ? String(evidenceItem.downloadStorageKey).trim()
                  : (evidenceItem.r2Key != null && String(evidenceItem.r2Key).trim())
                    ? String(evidenceItem.r2Key).trim()
                    : '';
  if (!storageKeyRaw && !isCandidateHoursPack) {
    GE();
    throw new Error('Evidence item missing file key.');
  }
  const storageKey = storageKeyRaw.replace(/^\/+/, '');

  const tsIdForPdf = String(tsIdNow() || tsId);
  const evidenceIdUpper = String(evidenceId || '').trim().toUpperCase();

  // ✅ If this is the SYSTEM-GENERATED timesheet PDF, do NOT presign storage_key directly.
  // Route via getTimesheetPdfUrl(timesheetId) so the backend can ensure a non-dirty PDF.
  const isSystemGeneratedTimesheetPdf =
    isSystem && (
      evidenceIdUpper.startsWith('SYS:PDF:GENERATED') ||
      evidenceIdUpper.startsWith('SYS:PDF:CURRENT') ||
      String(storageKey || '').replace(/^\/+/, '').trim() === `docs-pdf/timesheets/ts_${tsIdForPdf}.pdf`
    );

  L('ENTRY', {
    tsId,
    evidenceId,
    storageKeyRaw,
    storageKey,
    kind,
    canDelete,
    canEditType,
    dt: dtRaw,
    previewMode: previewMode || 'PDF',
    isSystemGeneratedTimesheetPdf
  });

  // signedUrl must be a STRING URL. Resolve ordinary file URLs after the
  // viewer shell is visible so the first View click always has an immediate
  // response, even when the presign request is slow.
  let signedUrl = null;
  let signedUrlPromise = null;
  let previewResponsePromise = null;

  if (isSystemGeneratedTimesheetPdf) {
    try {
      if (typeof window.openTimesheetDocumentV8 !== 'function') {
        GE();
        throw new Error('The V8 Timesheet document viewer is not available.');
      }
      await window.openTimesheetDocumentV8(tsIdForPdf);
      GE();
      return;
    } catch (err) {
      if (await handleMovedInViewer(err, 'evidence-viewer-open-sys-pdf')) {
        GE();
        return;
      }
      GE();
      throw err;
    }
  } else if (isCandidateHoursPack) {
    const eventId = String(evidenceItem.candidate_hours_event_id || '').trim();
    if (!/^[0-9a-f]{8}-[0-9a-f-]{27,}$/i.test(eventId) || !tsIdForPdf) {
      GE();
      throw new Error('Signed candidate hours evidence identity is missing.');
    }
    previewResponsePromise = authFetch(API(
      '/api/timesheets/' + encodeURIComponent(tsIdForPdf) +
      '/candidate-hours-evidence/' + encodeURIComponent(eventId)
    ));
  } else {
    signedUrlPromise = presignDownload(storageKey);
  }

  const instanceId = `ts-ev-view-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const iframeId    = `${instanceId}-iframe`;
  const previewStatusId = `${instanceId}-preview-status`;
  const downloadLinkId = `${instanceId}-download`;
  const deleteBtnId = `${instanceId}-delete`;
  const previousBtnId = `${instanceId}-previous`;
  const nextBtnId = `${instanceId}-next`;
  const zoomOutBtnId = `${instanceId}-zoom-out`;
  const zoomInBtnId = `${instanceId}-zoom-in`;
  const zoomLabelId = `${instanceId}-zoom-label`;
  const previewViewportId = `${instanceId}-preview-viewport`;
  const previewCanvasId = `${instanceId}-preview-canvas`;
  const rejectExpenseBtnId = `${instanceId}-reject-expense`;
  const selId       = `${instanceId}-type`;
  const otherId     = `${instanceId}-other`;
  const contextIdForTitle = tsIdNow() || weekIdNow() || tsId || contractWeekId || '';
  const expenseCategoryLabel = String(expenseCategory?.label || expenseCategoryKey || 'Expense').trim();
  const title = isExpenseCategoryViewer
    ? `${expenseCategoryLabel} evidence`
    : `Evidence ${String(contextIdForTitle).slice(0, 8)}…`;

  const kindTrim = String(kind || '').trim();
  const kindUpper = kindTrim.toUpperCase();

  const kindToUi = (k) => {
    const u = String(k || '').trim().toUpperCase();
    if (u === 'TIMESHEET') return 'Timesheet';
    if (u === 'MILEAGE') return 'Mileage';
    if (u === 'TRAVEL') return 'Travel';
    if (u === 'ACCOMMODATION') return 'Accommodation';
    if (u === 'OTHER') return 'Other';
    return 'Other';
  };

  const uiToKind = (label) => {
    const v = String(label || '').trim().toUpperCase();

    if (v === 'TIMESHEET') return 'TIMESHEET';
    if (v === 'MILEAGE') return 'MILEAGE';
    if (v === 'TRAVEL') return 'TRAVEL';
    if (v === 'ACCOMMODATION') return 'ACCOMMODATION';
    if (v === 'OTHER') return 'OTHER';

    return 'OTHER';
  };

  const initialSelect = kindToUi(kindUpper);

  const typeControlHtml = isExpenseCategoryViewer ? `
    <div class="row">
      <label>Expense</label>
      <div class="controls"><strong>${escapeHtml(expenseCategoryLabel)}</strong></div>
    </div>
    <div class="row">
      <label>Manager Approval</label>
      <div class="controls"><span class="candidate-office-badge candidate-office-badge--${['success', 'danger', 'warning', 'info'].includes(String(expenseCategory?.status?.tone || '').toLowerCase()) ? String(expenseCategory.status.tone).toLowerCase() : 'neutral'}">${escapeHtml(expenseCategory?.status?.label || 'Not approved yet')}</span></div>
    </div>
    <div class="row">
      <label>File</label>
      <div class="controls"><span class="mini">${escapeHtml(String(expenseEvidenceIndex + 1))} of ${escapeHtml(String(expenseEvidenceItems.length))}</span></div>
    </div>
  ` : canEditType ? `
    <div class="row">
      <label>Evidence Type</label>
      <div class="controls" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
        <select
          id="${selId}"
          class="input"
          style="min-width:220px;color-scheme:dark;"
        >
          <option value="Timesheet" ${initialSelect === 'Timesheet' ? 'selected' : ''}>Timesheet</option>
          <option value="Mileage" ${initialSelect === 'Mileage' ? 'selected' : ''}>Mileage</option>
          <option value="Travel" ${initialSelect === 'Travel' ? 'selected' : ''}>Travel</option>
          <option value="Accommodation" ${initialSelect === 'Accommodation' ? 'selected' : ''}>Accommodation</option>
          <option value="Other" ${initialSelect === 'Other' ? 'selected' : ''}>Other</option>
        </select>
        <span class="mini" style="opacity:.85;">Change type then click Save.</span>
        <div class="mini" style="margin-top:4px;opacity:.75;">
          Only <strong>Timesheet / Mileage / Travel / Accommodation / Other</strong> are valid evidence types.
        </div>
      </div>
    </div>
  ` : `
    <div class="row">
      <label>Evidence Type</label>
      <div class="controls">
        <span class="mini">${escapeHtml(kindTrim || 'Evidence')}</span>
        <div class="mini" style="margin-top:4px;opacity:.85;">
          ${isViewOnly ? 'This evidence item is view-only in this route.' : (isSystem ? 'System evidence cannot be re-typed.' : 'This evidence item cannot be edited.')}
        </div>
      </div>
    </div>
  `;

  const bodyHtml = `
    <div class="tabc">
      <div class="card">
        ${typeControlHtml}
        <div class="row">
          <label>Date Uploaded</label>
          <div class="controls">
            <span class="mini">${escapeHtml(fmtUkDateTime(dtRaw))}</span>
          </div>
        </div>
        <div class="row">
          <label>Download</label>
          <div class="controls">
             <a class="pill"
                id="${downloadLinkId}"
               aria-disabled="true"
               style="display:inline-block;border:1px solid var(--line);background:transparent;color:inherit;padding:6px 10px;border-radius:999px;text-decoration:none;opacity:.7;pointer-events:none;">
              Preparing preview…
            </a>
          </div>
        </div>
      </div>

      <div class="card ctms-expense-evidence-viewer" style="margin-top:10px;">
        <div class="row">
          <label>Preview</label>
          <div class="controls">
            ${isExpenseCategoryViewer ? `
              <div class="ctms-expense-evidence-toolbar">
                <div class="ctms-expense-evidence-navigation" aria-label="Evidence file navigation">
                  <button type="button" id="${previousBtnId}" class="btn btn-outline" ${expenseEvidenceIndex <= 0 ? 'disabled' : ''}>Previous</button>
                  <span>${escapeHtml(String(expenseEvidenceIndex + 1))} of ${escapeHtml(String(expenseEvidenceItems.length))}</span>
                  <button type="button" id="${nextBtnId}" class="btn btn-outline" ${expenseEvidenceIndex >= expenseEvidenceItems.length - 1 ? 'disabled' : ''}>Next</button>
                </div>
                <div class="ctms-expense-evidence-zoom" aria-label="Evidence zoom controls">
                  <button type="button" id="${zoomOutBtnId}" class="btn btn-outline" aria-label="Zoom out">−</button>
                  <span id="${zoomLabelId}">100%</span>
                  <button type="button" id="${zoomInBtnId}" class="btn btn-outline" aria-label="Zoom in">+</button>
                </div>
              </div>
            ` : ''}
            <div id="${previewViewportId}" class="ctms-expense-evidence-preview${isExpenseCategoryViewer ? ' ctms-expense-evidence-preview--scoped' : ''}">
              <div id="${previewCanvasId}" class="ctms-expense-evidence-preview__canvas">
                <div id="${previewStatusId}" class="mini ctms-expense-evidence-preview__status" role="status" aria-live="polite">Preparing preview…</div>
                <iframe id="${iframeId}" title="Evidence preview" class="ctms-expense-evidence-preview__frame"></iframe>
              </div>
            </div>

             ${isExpenseCategoryViewer ? `
              <div class="ctms-expense-evidence-actions">
                <button type="button" id="${rejectExpenseBtnId}" class="btn btn-warn candidate-office-expense-reject">Reject ${escapeHtml(expenseCategoryLabel)}</button>
              </div>
            ` : (canDelete || canReturnToQueue) ? `
              <div style="margin-top:10px;display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
                ${canReturnToQueue ? `
                  <button type="button"
                          id="${instanceId}-return"
                          class="pill"
                          style="cursor:pointer;border:1px solid var(--line);background:transparent;color:inherit;padding:6px 10px;border-radius:999px;">
                    Return to queue
                  </button>
                ` : ''}
                ${canDelete ? `
                  <button type="button"
                          id="${deleteBtnId}"
                          class="pill pill-warn"
                          style="cursor:pointer;border:1px solid var(--line);background:transparent;color:inherit;padding:6px 10px;border-radius:999px;">
                    Delete evidence
                  </button>
                ` : ''}
                <span class="mini" style="opacity:.85;">
                  ${canReturnToQueue && canDelete
                    ? 'Return to queue detaches this file. Delete permanently removes it.'
                    : (canReturnToQueue
                        ? 'This will detach the evidence and place the file back in the queue.'
                        : 'This will permanently remove this evidence item.')}
                </span>
              </div>
            ` : `
              <div class="mini" style="margin-top:10px;opacity:.85;">
                This evidence item cannot be changed in this route.
              </div>
            `}
          </div>
        </div>
      </div>
    </div>
  `;

  let previewObjectUrl = null;
  let __tsDelPrev = null;
  const __hideTsDelete = () => {
    try {
      const b = document.getElementById('btnTsDeleteTimesheet');
      if (!b) return;
      if (__tsDelPrev == null) __tsDelPrev = b.style.display;
      b.style.display = 'none';
    } catch {}
  };
  __hideTsDelete();

  const onDismiss = () => {
    if (previewObjectUrl) {
      try { URL.revokeObjectURL(previewObjectUrl); } catch {}
      previewObjectUrl = null;
    }
    try {
      const b = document.getElementById('btnTsDeleteTimesheet');
      if (b) b.style.display = (__tsDelPrev != null ? __tsDelPrev : '');
    } catch {}

    try {
      const st = (window.__modalStack && Array.isArray(window.__modalStack)) ? window.__modalStack : null;
      const fr = (st && st.length) ? st[st.length - 1] : null;
      if (fr && fr.entity === 'timesheets') fr.currentTabKey = isExpenseCategoryViewer ? 'expenses' : 'evidence';
    } catch {}
  };

  const onSave = async () => {
    const { LOGM, L, GC, GE } = getTsLoggers('[TS][EVIDENCE][VIEWER][SAVE]');
    GC('onSave (evidence viewer)');

    if (!canEditType) {
      GE();
      return { ok: true };
    }

    try {
        const sel = document.getElementById(selId);
      const selVal = sel ? String(sel.value || '').trim() : '';

      let newKind = uiToKind(selVal);

      if (!newKind) {
        alert('Please select an evidence type.');
        GE();
        return { ok: false };
      }

      newKind = String(newKind || '').trim().toUpperCase();

      if (!newKind) {
        alert('Please select an evidence type.');
        GE();
        return { ok: false };
      }

      if (String(newKind) === String(kindTrim).trim().toUpperCase()) {
        GE();
        return { ok: true };
      }

      const enc = encodeURIComponent;

      if (isPlannedWeekContext) {
        const currentWeekId = weekIdNow();
        if (!currentWeekId) throw new Error('Contract week id missing.');

        await apiPatchJson(
          `/api/contract-weeks/${enc(currentWeekId)}/staged-evidence/${enc(evidenceId)}`,
          { kind: newKind }
        );

        try {
          if (typeof refreshTimesheetEvidenceIntoModalState === 'function') {
            await refreshTimesheetEvidenceIntoModalState(currentWeekId);
          }
        } catch {}

        if (window.__toast) window.__toast('Evidence type updated');

        GE();
        return { ok: true };
      }

      const idNow = tsIdNow();
      if (!idNow) throw new Error('Timesheet id missing.');

      await apiPatchJson(
        `/api/timesheets/${enc(idNow)}/evidence/${enc(evidenceId)}`,
        { expected_timesheet_id: expectedNow(), kind: newKind }
      );

      try {
        if (typeof refreshTimesheetEvidenceIntoModalState === 'function') {
          await refreshTimesheetEvidenceIntoModalState(idNow);
        }
      } catch {}

      if (window.__toast) window.__toast('Evidence type updated');

      GE();
      return { ok: true };
    } catch (err) {
      if (await handleMovedInViewer(err, 'evidence-viewer-save')) {
        GE();
        return { ok: false };
      }

      const msg = String(err?.message || 'Failed to update evidence type.');
      if (/invoiced|paid|locked/i.test(msg)) {
        try { window.__toast && window.__toast(msg); } catch {}
      } else {
        alert(msg);
      }

      L('update kind failed', err);
      GE();
      return { ok: false };
    }
  };

  showModal(
    title,
    [{ key: 'view', title: 'Evidence' }],
    () => bodyHtml,
    onSave,
    false,
    undefined,
    {
      kind: 'timesheet-evidence-viewer',
      frameEntity: 'timesheet-evidence',
      noParentGate: true,
      forceEdit: true,
      showSave: !isExpenseCategoryViewer,
      showApply: false,
      onDismiss
    }
  );


  const viewerFrameToken = (() => {
    try {
      const st = Array.isArray(window.__modalStack) ? window.__modalStack : [];
      return st.length ? String(st[st.length - 1]?._token || '') : '';
    } catch {
      return '';
    }
  })();

  try { requestAnimationFrame(() => __hideTsDelete()); } catch {}
  try {
    const openConfirm = async (opts) => {
      if (typeof openUiConfirmModal === 'function') {
        return await openUiConfirmModal(opts || {});
      }
      return window.confirm(String(opts?.message || opts?.body || 'Are you sure?'));
    };

    if (isExpenseCategoryViewer) {
      let zoomPercent = 100;
      const reopenAt = async (nextIndex) => {
        const boundedIndex = Math.max(0, Math.min(Number(nextIndex), expenseEvidenceItems.length - 1));
        if (boundedIndex === expenseEvidenceIndex) return;
        const nextItem = expenseEvidenceItems[boundedIndex];
        const closed = typeof closeCurrentModalFrameSafely === 'function'
          ? closeCurrentModalFrameSafely({ expectedKind: 'timesheet-evidence-viewer' })
          : false;
        if (!closed) return;
        await Promise.resolve();
        await openTimesheetEvidenceViewerExisting(nextItem, { ...viewerOptions, evidenceIndex: boundedIndex });
      };
      const hydrateExpenseViewer = () => {
        const applyZoom = () => {
          const frame = document.getElementById(iframeId);
          const canvas = document.getElementById(previewCanvasId);
          const label = document.getElementById(zoomLabelId);
          const viewport = document.getElementById(previewViewportId);
          const baseHeight = Number(viewport?.clientHeight || 520);
          const scale = zoomPercent / 100;
          if (canvas) {
            canvas.style.width = `${Math.max(100, zoomPercent)}%`;
            canvas.style.height = `${Math.round(baseHeight * Math.max(1, scale))}px`;
          }
          if (frame) {
            frame.style.width = scale >= 1 ? `${100 / scale}%` : '100%';
            frame.style.height = `${baseHeight}px`;
            frame.style.transform = `scale(${scale})`;
          }
          if (label) label.textContent = `${zoomPercent}%`;
        };

        const previous = document.getElementById(previousBtnId);
        if (previous && !previous.__candidateOfficeExpensePreviousWired) {
          previous.__candidateOfficeExpensePreviousWired = true;
          previous.addEventListener('click', () => { void reopenAt(expenseEvidenceIndex - 1); });
        }
        const next = document.getElementById(nextBtnId);
        if (next && !next.__candidateOfficeExpenseNextWired) {
          next.__candidateOfficeExpenseNextWired = true;
          next.addEventListener('click', () => { void reopenAt(expenseEvidenceIndex + 1); });
        }
        const zoomOut = document.getElementById(zoomOutBtnId);
        if (zoomOut && !zoomOut.__candidateOfficeExpenseZoomWired) {
          zoomOut.__candidateOfficeExpenseZoomWired = true;
          zoomOut.addEventListener('click', () => {
            zoomPercent = Math.max(50, zoomPercent - 25);
            applyZoom();
          });
        }
        const zoomIn = document.getElementById(zoomInBtnId);
        if (zoomIn && !zoomIn.__candidateOfficeExpenseZoomWired) {
          zoomIn.__candidateOfficeExpenseZoomWired = true;
          zoomIn.addEventListener('click', () => {
            zoomPercent = Math.min(200, zoomPercent + 25);
            applyZoom();
          });
        }

        const rejectExpense = document.getElementById(rejectExpenseBtnId);
        if (rejectExpense && !rejectExpense.__candidateOfficeExpenseRejectWired) {
          rejectExpense.__candidateOfficeExpenseRejectWired = true;
          rejectExpense.addEventListener('click', async () => {
            if (rejectExpense.disabled) return;
            rejectExpense.disabled = true;
            try {
              const bridge = window.CloudTMSCandidateOfficeBridge;
              if (!bridge || typeof bridge.runExpenseCategoryAction !== 'function') {
                throw new Error('The current expense action is unavailable. Refresh the Timesheet and try again.');
              }
              await bridge.runExpenseCategoryAction({
                context: { ...(viewerOptions.expenseActionContext || {}), expenseEvidenceViewer: true },
                expenseComponentId: viewerOptions.expenseComponentId || expenseCategory?.expense_component_id,
                trigger: rejectExpense
              });
            } catch (error) {
              try { window.__toast?.(String(error?.message || 'The expense could not be rejected.')); } catch {}
            } finally {
              if (rejectExpense.isConnected) rejectExpense.disabled = false;
              requestAnimationFrame(hydrateExpenseViewer);
            }
          });
        }

        if (signedUrl) {
          const link = document.getElementById(downloadLinkId);
          if (link) {
            link.href = signedUrl;
            link.target = '_blank';
            link.rel = 'noopener noreferrer';
            link.removeAttribute('aria-disabled');
            link.style.opacity = '';
            link.style.pointerEvents = '';
            link.textContent = 'Download';
          }
        }
        if (previewObjectUrl) {
          const frame = document.getElementById(iframeId);
          const status = document.getElementById(previewStatusId);
          if (frame) {
            frame.style.display = 'block';
            frame.src = previewObjectUrl;
          }
          if (status) status.style.display = 'none';
        }
        applyZoom();
      };
      hydrateExpenseViewer();
    }

    if (canDelete) {
      const delBtn = document.getElementById(deleteBtnId);
      if (delBtn && !delBtn.__tsEvDelWired) {
        delBtn.__tsEvDelWired = true;

        delBtn.addEventListener('click', async () => {
          const ok = await openConfirm({
            title: 'Delete evidence?',
            message: 'This will permanently remove this evidence item.'
          });
          if (!ok) return;

          try {
            const enc = encodeURIComponent;

            if (isPlannedWeekContext) {
              const currentWeekId = weekIdNow();
              if (!currentWeekId) throw new Error('Contract week id missing.');

              await apiDeleteJson(
                `/api/contract-weeks/${enc(currentWeekId)}/staged-evidence/${enc(evidenceId)}`
              );

              try {
                if (typeof refreshTimesheetEvidenceIntoModalState === 'function') {
                  await refreshTimesheetEvidenceIntoModalState(currentWeekId);
                }
              } catch {}

              if (window.__toast) window.__toast('Evidence removed');
              try { document.getElementById('btnCloseModal')?.click(); } catch {}
              return;
            }

            const idNow = tsIdNow();
            if (!idNow) throw new Error('Timesheet id missing.');

            await apiDeleteJson(
              `/api/timesheets/${enc(idNow)}/evidence/${enc(evidenceId)}`,
              { expected_timesheet_id: expectedNow() }
            );

            try {
              if (typeof refreshTimesheetEvidenceIntoModalState === 'function') {
                await refreshTimesheetEvidenceIntoModalState(idNow);
              }
            } catch {}

            if (window.__toast) window.__toast('Evidence removed');

            try { document.getElementById('btnCloseModal')?.click(); } catch {}
          } catch (err) {
            if (await handleMovedInViewer(err, 'evidence-viewer-delete')) return;

            const msg = String(err?.message || 'Failed to delete evidence item.');
            if (/invoiced|paid|locked/i.test(msg)) {
              try { window.__toast && window.__toast(msg); } catch {}
              return;
            }

            L('delete from viewer failed', err);
            alert(msg);
          }
        });
      }
    }

    if (canReturnToQueue) {
      const returnBtn = document.getElementById(`${instanceId}-return`);
      if (returnBtn && !returnBtn.__tsEvReturnWired) {
        returnBtn.__tsEvReturnWired = true;

        returnBtn.addEventListener('click', async () => {
          const ok = await openConfirm({
            title: 'Return evidence to queue?',
            message: 'This will detach the evidence and place the file back in the queue.'
          });
          if (!ok) return;

          try {
            const enc = encodeURIComponent;

            if (isPlannedWeekContext) {
              const currentWeekId = weekIdNow();
              if (!currentWeekId) throw new Error('Contract week id missing.');

              await apiPostJson(
                `/api/contract-weeks/${enc(currentWeekId)}/staged-evidence/${enc(evidenceId)}/return-to-queue`,
                {}
              );

              try {
                if (typeof refreshTimesheetEvidenceIntoModalState === 'function') {
                  await refreshTimesheetEvidenceIntoModalState(currentWeekId);
                }
              } catch {}

              if (window.__toast) window.__toast('Evidence returned to queue');
              try { document.getElementById('btnCloseModal')?.click(); } catch {}
              return;
            }

            const idNow = tsIdNow();
            if (!idNow) throw new Error('Timesheet id missing.');

            await apiPostJson(
              `/api/timesheets/${enc(idNow)}/evidence/${enc(evidenceId)}/return-to-queue`,
              { expected_timesheet_id: expectedNow() }
            );

            try {
              if (typeof refreshTimesheetEvidenceIntoModalState === 'function') {
                await refreshTimesheetEvidenceIntoModalState(idNow);
              }
            } catch {}

            if (window.__toast) window.__toast('Evidence returned to queue');
            try { document.getElementById('btnCloseModal')?.click(); } catch {}
          } catch (err) {
            if (await handleMovedInViewer(err, 'evidence-viewer-return')) return;

            const msg = String(err?.message || 'Failed to return evidence to queue.');
            if (/invoiced|paid|locked/i.test(msg)) {
              try { window.__toast && window.__toast(msg); } catch {}
              return;
            }

            L('return-to-queue from viewer failed', err);
            alert(msg);
          }
        });
      }
    }
  } catch (e) {
    L('viewer wiring failed (non-fatal)', e);
  }

  try {
    signedUrl = signedUrlPromise ? await signedUrlPromise : null;
    const previewResponse = previewResponsePromise
      ? await previewResponsePromise
      : await fetch(signedUrl, {
          method: 'GET',
          credentials: 'omit',
          cache: 'no-store'
        });
    if (!previewResponse.ok) throw new Error('EVIDENCE_PREVIEW_DOWNLOAD_FAILED');
    const previewBlob = await previewResponse.blob();
    if (!previewBlob.size) throw new Error('EVIDENCE_PREVIEW_EMPTY');
    previewObjectUrl = URL.createObjectURL(previewBlob);

    const liveViewer = (() => {
      try {
        const st = Array.isArray(window.__modalStack) ? window.__modalStack : [];
        const top = st.length ? st[st.length - 1] : null;
        return !!(top && String(top._token || '') === viewerFrameToken);
      } catch {
        return false;
      }
    })();

    if (liveViewer) {
      const link = document.getElementById(downloadLinkId);
      const iframe = document.getElementById(iframeId);
      const status = document.getElementById(previewStatusId);

      if (link) {
        link.href = signedUrl || previewObjectUrl;
        if (!signedUrl) link.download = String(evidenceItem.filename || 'candidate-submitted-hours.pdf');
        link.target = '_blank';
        link.rel = 'noopener noreferrer';
        link.removeAttribute('aria-disabled');
        link.style.opacity = '';
        link.style.pointerEvents = '';
        link.textContent = 'Download';
      }

      if (iframe) {
        iframe.style.display = 'block';
        iframe.src = previewObjectUrl;
      }

      if (status) status.style.display = 'none';
    }
  } catch (err) {
    const status = document.getElementById(previewStatusId);
    if (status) {
      status.textContent = 'The preview could not be loaded. Close this window and try again.';
      status.setAttribute('data-tone', 'err');
    }
    GE();
    throw err;
  }

  GE();
}

function showNextTimesheetSnoozeResult(message,error=false){
 const host=document.getElementById('modalBody');if(!host)return;let line=host.querySelector('[data-next-timesheet-snooze-result]');if(!line){line=document.createElement('p');line.className='ws-notice';line.setAttribute('data-next-timesheet-snooze-result','');line.setAttribute('data-next-live-copy','');host.prepend(line);}line.textContent=message;line.setAttribute('role',error?'alert':'status');
}
async function openNextTimesheetPaymentSnooze(input={}){
 const ownerClient=bankingNextOwnerClient(),actor=SESSION?.user?.id,parent=currentFrame();
 if(!ownerClient){showNextTimesheetSnoozeResult('Could not check payment settings; try again.',true);return {handled:true,result:null};}
 try{await ownerClient.qualify('timesheet:snooze:'+crypto.randomUUID());if(SESSION?.user?.id!==actor||currentFrame()!==parent)return {handled:true,result:null};
  const owner=ownerClient.peek();if(owner?.active_owner==='LEGACY')return {handled:false,result:null};if(owner?.active_owner!=='NEXT'||!window.CloudTMSBpayNextSnooze)throw Error();
  const mc=window.modalCtx??{},row=mc.data??{},details=mc.timesheetDetails??{},candidate=mc.timesheetRelated?.candidate??{},ts=details.timesheet??{};
  const scope={candidate_id:String(input.candidate_id??input.candidateId??candidate.id??candidate.candidate_id??row.candidate_id??'').toLowerCase(),physical_timesheet_id:String(input.timesheet_id??input.timesheetId??row.timesheet_id??row.id??'').toLowerCase(),physical_timesheet_version:String(ts.version??details.current_version??row.version??''),scope_kind:'WHOLE_TIMESHEET',snooze_kind:'TIMESHEET_PAYMENT'};
  const child=window.CloudTMSBpayNextSnooze.open({document,window,actorId:actor,api:API,authFetch,currentActorId:()=>SESSION?.user?.id??null,ownerReady:()=>ownerClient.peek()?.active_owner==='NEXT'&&ownerClient.peek()?.owner_epoch===owner.owner_epoch,showReadWindow:window.CloudTMSBpayNextUi.createStandardWindowAdapter({document,window,showModal,closeModal})},
   {scope,clear:input.clear===true,label:'Timesheet payment',candidateLabel:input.candidate_display_name??candidate.display_name??row.candidate_name,clientLabel:input.client_name??mc.timesheetRelated?.client?.name??row.client_name,dateLabel:(ts.week_ending_date??row.week_ending_date)?'Week ending '+String(ts.week_ending_date??row.week_ending_date).split('-').reverse().join('/'):null});
  return {handled:true,result:await child.done};
 }catch{if(SESSION?.user?.id===actor&&currentFrame()===parent)showNextTimesheetSnoozeResult('Could not open the snooze; try again.',true);return {handled:true,result:null};}
}
async function openTimesheetPaymentSnoozeModal(input = {}) {
  const next=await openNextTimesheetPaymentSnooze(input);if(next.handled)return next.result;
  const enc = (typeof escapeHtml === 'function')
    ? escapeHtml
    : (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
      }[c]));

  const toText = (v) => String(v == null ? '' : v).trim();
  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

  const mc = (window.modalCtx && typeof window.modalCtx === 'object') ? window.modalCtx : null;
  const dataRow = (mc && mc.data && typeof mc.data === 'object') ? mc.data : {};
  const details = (mc && mc.timesheetDetails && typeof mc.timesheetDetails === 'object') ? mc.timesheetDetails : {};
  const related = (mc && mc.timesheetRelated && typeof mc.timesheetRelated === 'object') ? mc.timesheetRelated : {};
  const candidateObj = (related && related.candidate && typeof related.candidate === 'object') ? related.candidate : {};

  const timesheetId = toText(
    input.timesheet_id ||
    input.timesheetId ||
    dataRow.timesheet_id ||
    dataRow.id
  );

  if (!timesheetId || !uuidRe.test(timesheetId)) {
    try {
      if (typeof window.__toast === 'function') window.__toast('A valid Timesheet id is required.');
      else alert('A valid Timesheet id is required.');
    } catch {}
    return null;
  }

  const candidateId = toText(
    input.candidate_id ||
    input.candidateId ||
    candidateObj.id ||
    candidateObj.candidate_id ||
    dataRow.candidate_id
  );
  if (!uuidRe.test(candidateId)) {
    try {
      if (typeof window.__toast === 'function') window.__toast('The Timesheet candidate could not be verified. Refresh the Timesheet and try again.');
      else alert('The Timesheet candidate could not be verified. Refresh the Timesheet and try again.');
    } catch {}
    return null;
  }

  const requestSnoozeValidation = async (validationPhase, snoozeUntilDate = null) => {
    const result = await apiPostJson('/api/banking/pay/snooze/validate', {
      candidate_id: candidateId,
      timesheet_id: timesheetId,
      segment_id: null,
      segment_stable_key: null,
      snooze_kind: 'TIMESHEET_PAYMENT',
      snooze_until_date: snoozeUntilDate || null,
      validation_phase: String(validationPhase || '').trim().toUpperCase()
    });
    return (result && typeof result === 'object' && !Array.isArray(result)) ? result : {};
  };

  const confirmSnoozeWarning = async (validationResult) => {
    const result = (validationResult && typeof validationResult === 'object') ? validationResult : {};
    if (result.warning_required !== true) return true;
    const message = toText(result.warning_message);
    if (!message) return false;
    if (typeof openUiConfirmModal === 'function') {
      const response = await openUiConfirmModal({
        title: 'Confirm Snooze',
        message,
        confirm_label: 'OK',
        cancel_label: 'Cancel',
        confirm_class: 'btn btn-primary',
        cancel_class: 'btn btn-outline'
      });
      return !!(response && response.confirmed === true);
    }
    try { return !!window.confirm(message); } catch { return false; }
  };

  let resolvedRateAcknowledgementToken = null;
  let payRunAcknowledgementToken = null;
  let londonCurrentDate = '';
  let preOpenWarningRequired = false;

  const payStateSrc = (input.pay_state && typeof input.pay_state === 'object')
    ? input.pay_state
    : ((mc && mc.timesheetPayState && typeof mc.timesheetPayState === 'object') ? mc.timesheetPayState : {});

  const hasExistingSnooze = !!payStateSrc.is_snoozed;
  try {
    const preOpenValidation = await requestSnoozeValidation('PRE_OPEN', null);
    londonCurrentDate = toText(preOpenValidation.london_current_date);
    preOpenWarningRequired = preOpenValidation.warning_required === true;
    if (preOpenWarningRequired) {
      if (!(await confirmSnoozeWarning(preOpenValidation))) return null;
      const token = toText(preOpenValidation.acknowledgement_token);
      if (!uuidRe.test(token)) throw new Error('CloudTMS could not record the resolved-rate confirmation.');
      resolvedRateAcknowledgementToken = token;
    }
  } catch (validationError) {
    const message = toText(validationError?.json?.message || validationError?.message || validationError)
      || 'CloudTMS could not validate this Snooze. Refresh the Timesheet and try again.';
    try {
      if (typeof window.__toast === 'function') window.__toast(message);
      else alert(message);
    } catch {}
    return null;
  }

  const currentSnoozeUntil = toText(
    input.snooze_until_date ||
    payStateSrc.snooze_until_date
  );
  const currentSnoozeIsIndefinite = !!(
    input.snooze_is_indefinite === true ||
    payStateSrc.snooze_is_indefinite === true
  );
  const currentSnoozeNote = toText(
    input.snooze_note ||
    payStateSrc.snooze_note
  );

  const candidateName = toText(
    input.candidate_display_name ||
    candidateObj.display_name ||
    [candidateObj.first_name, candidateObj.last_name].filter(Boolean).join(' ') ||
    dataRow.candidate_name ||
    dataRow.display_name
  ) || 'Candidate';

  const clientName = toText(
    input.client_name ||
    (related.client && related.client.name) ||
    dataRow.client_name
  ) || '—';

  const referenceNumber = toText(
    input.reference_number ||
    dataRow.reference_number ||
    details.reference_number ||
    details.ref_num ||
    details.timesheet?.reference_number ||
    details.timesheet?.ref_num
  );

  const weekEndingDate = toText(
    input.week_ending_date ||
    details.timesheet?.week_ending_date ||
    dataRow.week_ending_date
  );

  const formatIsoToUkLocal = (ymd) => {
    const s = toText(ymd);
    if (!s) return '—';
    try {
      if (typeof formatIsoToUk === 'function') return String(formatIsoToUk(s) || '—');
    } catch {}
    const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (m) return `${m[3]}/${m[2]}/${m[1]}`;
    return s;
  };

  const parseUkOrIsoDate = (raw) => {
    const s = toText(raw);
    if (!s) return null;
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
    const m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
    if (m) return `${m[3]}-${m[2]}-${m[1]}`;
    return null;
  };

  const instanceId = `ts_snooze_${Date.now()}_${Math.random().toString(36).slice(2)}`;
  const dateId = `${instanceId}_date`;
  const indefiniteId = `${instanceId}_indefinite`;
  const clearId = `${instanceId}_clear`;
  const noteId = `${instanceId}_note`;
  const currentStateId = `${instanceId}_state`;

  const initialDateIso = currentSnoozeIsIndefinite ? '' : currentSnoozeUntil;
  const initialDateUk = initialDateIso ? formatIsoToUkLocal(initialDateIso) : '';

  return await new Promise((resolve) => {
    let settled = false;
    let confirmed = false;
    let actionResult = null;

    const finish = (val) => {
      if (settled) return;
      settled = true;
      resolve(val);
    };

    const updateFieldState = () => {
      try {
        const dateEl = document.getElementById(dateId);
        const indefiniteEl = document.getElementById(indefiniteId);
        const clearEl = document.getElementById(clearId);
        const noteEl = document.getElementById(noteId);
        const stateEl = document.getElementById(currentStateId);

        if (!dateEl || !indefiniteEl || !noteEl || !stateEl) return;

        const clearChecked = !!(clearEl && clearEl.checked);
        const indefiniteChecked = !!indefiniteEl.checked;

        dateEl.disabled = clearChecked || indefiniteChecked;
        noteEl.disabled = false;

        if (clearChecked) {
          stateEl.textContent = 'This will remove the current timesheet payment snooze.';
        } else if (indefiniteChecked) {
          stateEl.textContent = 'This payment will be snoozed indefinitely and removed from live pay preview until managed later.';
        } else if (toText(dateEl.value)) {
          stateEl.textContent = `This payment will stay visible but excluded until ${toText(dateEl.value)}.`;
        } else {
          stateEl.textContent = 'Choose a date or switch to an indefinite snooze.';
        }
      } catch {}
    };

    showModal(
      hasExistingSnooze ? 'Manage payment snooze' : 'Snooze payment',
      [{ key: 'main', label: 'Snooze' }],
      () => `
        <div class="form">
          <div class="card" style="padding:12px;">
            <div class="row">
              <label>Candidate</label>
              <div class="controls">
                <div style="font-weight:700;">${enc(candidateName)}</div>
                <div class="mini" style="opacity:.8;margin-top:4px;">
                  Client: <span class="mono">${enc(clientName)}</span>
                  ${referenceNumber ? ` • Reference: <span class="mono">${enc(referenceNumber)}</span>` : ''}
                  ${weekEndingDate ? ` • Week ending: <span class="mono">${enc(formatIsoToUkLocal(weekEndingDate))}</span>` : ''}
                </div>
              </div>
            </div>

            <div class="row">
              <label>Current snooze</label>
              <div class="controls">
                <div class="mini">
                  ${
                    hasExistingSnooze
                      ? (currentSnoozeIsIndefinite
                          ? 'Indefinite snooze'
                          : `Snoozed until ${enc(formatIsoToUkLocal(currentSnoozeUntil))}`)
                      : 'No active snooze'
                  }
                </div>
                ${
                  currentSnoozeNote
                    ? `<div class="mini" style="opacity:.8;margin-top:4px;">Current note: ${enc(currentSnoozeNote)}</div>`
                    : ''
                }
              </div>
            </div>
          </div>

          ${
            hasExistingSnooze
              ? `
                <div class="row">
                  <label>Remove current snooze</label>
                  <div class="controls">
                    <label class="mini" style="display:flex;gap:8px;align-items:center;cursor:pointer;">
                      <input type="checkbox" id="${clearId}">
                      Clear the current snooze
                    </label>
                  </div>
                </div>
              `
              : ''
          }

          <div class="row">
            <label>Snooze until</label>
            <div class="controls">
              <input
                id="${dateId}"
                class="input"
                type="text"
                placeholder="DD/MM/YYYY"
                data-uk-date="1"
                value="${enc(initialDateUk)}"
              />
              <div class="hint mini">Leave blank only if you are using an indefinite snooze.</div>
            </div>
          </div>

          <div class="row">
            <label>Indefinite</label>
            <div class="controls">
              <label class="mini" style="display:flex;gap:8px;align-items:center;cursor:pointer;">
                <input type="checkbox" id="${indefiniteId}" ${currentSnoozeIsIndefinite ? 'checked' : ''}>
                Snooze indefinitely
              </label>
            </div>
          </div>

          <div class="row">
            <label>Note / reason</label>
            <div class="controls">
              <textarea
                id="${noteId}"
                class="input"
                rows="5"
                placeholder="Optional note or reason…"
                style="width:100%;min-height:120px;"
              >${enc(currentSnoozeNote)}</textarea>
            </div>
          </div>

          <div class="row">
            <label>Status</label>
            <div class="controls">
              <div id="${currentStateId}" class="mini" style="opacity:.85;"></div>
            </div>
          </div>
        </div>
      `,
      async () => {
        const dateEl = document.getElementById(dateId);
        const indefiniteEl = document.getElementById(indefiniteId);
        const clearEl = document.getElementById(clearId);
        const noteEl = document.getElementById(noteId);

        const clearRequested = !!(clearEl && clearEl.checked);
        const indefinite = !!(indefiniteEl && indefiniteEl.checked);
        const note = toText(noteEl?.value || '') || null;
        const rawDate = toText(dateEl?.value || '');
        const untilIso = rawDate ? parseUkOrIsoDate(rawDate) : null;

        if (clearRequested) {
          if (typeof openUiConfirmModal === 'function') {
            const confirmRes = await openUiConfirmModal({
              title: 'Clear payment snooze?',
              message: 'This will remove the current snooze from this timesheet payment.',
              confirm_label: 'Clear snooze',
              cancel_label: 'Cancel',
              confirm_class: 'btn btn-warn',
              cancel_class: 'btn btn-outline'
            });
            if (!(confirmRes && confirmRes.confirmed === true)) {
              return { ok: false };
            }
          }

          const result = await apiPostJson(
            `/api/timesheets/${encodeURIComponent(timesheetId)}/snooze-payment/clear`,
            {}
          );

          confirmed = true;
          actionResult = {
            ok: true,
            action: 'clear',
            timesheet_id: timesheetId,
            result: result
          };
          return { ok: true };
        }

        if (!indefinite && !untilIso) {
          try {
            if (typeof window.__toast === 'function') window.__toast('Enter a snooze-until date or choose an indefinite snooze.');
            else alert('Enter a snooze-until date or choose an indefinite snooze.');
          } catch {}
          return { ok: false };
        }

        if (preOpenWarningRequired && !resolvedRateAcknowledgementToken) {
          const refreshedPreOpenValidation = await requestSnoozeValidation('PRE_OPEN', null);
          preOpenWarningRequired = refreshedPreOpenValidation.warning_required === true;
          if (preOpenWarningRequired) {
            if (!(await confirmSnoozeWarning(refreshedPreOpenValidation))) return { ok: false };
            const token = toText(refreshedPreOpenValidation.acknowledgement_token);
            if (!uuidRe.test(token)) {
              try {
                if (typeof window.__toast === 'function') window.__toast('CloudTMS could not record the resolved-rate confirmation. Refresh the Timesheet and try again.');
              } catch {}
              return { ok: false };
            }
            resolvedRateAcknowledgementToken = token;
          }
        }

        let preSaveValidation = null;
        try {
          preSaveValidation = await requestSnoozeValidation('PRE_SAVE', indefinite ? null : untilIso);
        } catch (validationError) {
          const message = toText(validationError?.json?.message || validationError?.message || validationError)
            || 'CloudTMS could not validate this Snooze. Refresh the Timesheet and try again.';
          try {
            if (typeof window.__toast === 'function') window.__toast(message);
            else alert(message);
          } catch {}
          return { ok: false };
        }

        payRunAcknowledgementToken = null;
        if (preSaveValidation.warning_required === true) {
          if (!(await confirmSnoozeWarning(preSaveValidation))) return { ok: false };
          const token = toText(preSaveValidation.acknowledgement_token);
          if (!uuidRe.test(token)) {
            try {
              if (typeof window.__toast === 'function') window.__toast('CloudTMS could not record the pay-run confirmation. Refresh the Timesheet and try again.');
            } catch {}
            return { ok: false };
          }
          payRunAcknowledgementToken = token;
        }

        let result = null;
        try {
          result = await apiPostJson(
            `/api/timesheets/${encodeURIComponent(timesheetId)}/snooze-payment`,
            {
              snooze_until_date: indefinite ? null : untilIso,
              note: note,
              resolved_rate_acknowledgement_token: resolvedRateAcknowledgementToken,
              pay_run_acknowledgement_token: payRunAcknowledgementToken
            }
          );
        } catch (saveError) {
          const errorPayload = (saveError?.json && typeof saveError.json === 'object' && !Array.isArray(saveError.json)) ? saveError.json : {};
          const errorCode = toText(errorPayload.error_code || errorPayload.error).toUpperCase();
          if (errorCode === 'SNOOZE_CONFIRMATION_REQUIRED' || errorCode === 'SNOOZE_CONFIRMATION_STALE') {
            const confirmationType = toText(errorPayload.confirmation_type).toUpperCase();
            if (confirmationType === 'RESOLVED_RATE') {
              preOpenWarningRequired = true;
              resolvedRateAcknowledgementToken = null;
            }
            payRunAcknowledgementToken = null;
          }
          const message = toText(errorPayload.message || saveError?.message || saveError)
            || 'CloudTMS could not update this payment Snooze. Refresh the Timesheet and try again.';
          try {
            if (typeof window.__toast === 'function') window.__toast(message);
            else alert(message);
          } catch {}
          return { ok: false };
        }

        confirmed = true;
        actionResult = {
          ok: true,
          action: 'upsert',
          timesheet_id: timesheetId,
          result: result
        };
        return { ok: true };
      },
      false,
      null,
      {
        kind: 'timesheet-payment-snooze',
        noParentGate: true,
        forceEdit: true,
        showSave: true,
        showApply: false,
        onDismiss: () => finish(confirmed ? actionResult : null)
      }
    );

    try {
      setTimeout(() => {
        try {
          const dateEl = document.getElementById(dateId);
          const indefiniteEl = document.getElementById(indefiniteId);
          const clearEl = document.getElementById(clearId);

          if (dateEl && typeof attachUkDatePicker === 'function') {
            attachUkDatePicker(dateEl, londonCurrentDate ? { minDate: londonCurrentDate } : {});
          }

          if (indefiniteEl && !indefiniteEl.__tsWired) {
            indefiniteEl.__tsWired = true;
            indefiniteEl.addEventListener('change', updateFieldState);
          }

          if (clearEl && !clearEl.__tsWired) {
            clearEl.__tsWired = true;
            clearEl.addEventListener('change', updateFieldState);
          }

          updateFieldState();

          if (dateEl && !currentSnoozeIsIndefinite && !currentSnoozeUntil) {
            dateEl.focus();
          } else {
            const noteEl = document.getElementById(noteId);
            if (noteEl) noteEl.focus();
          }
        } catch {}
      }, 0);
    } catch {}
  });
}

function wireTimesheetOverviewFinanceActions(rootArg = null) {
  const root = rootArg || document.getElementById('modalBody');
  if (!root) return { ok: false, error: 'modalBody not found' };

  const mc = (window.modalCtx && typeof window.modalCtx === 'object') ? window.modalCtx : null;
  if (!mc || String(mc.entity || '') !== 'timesheets') return { ok: false, error: 'timesheet modal context not available' };

  const toast = (msg) => {
    try {
      if (typeof window.__toast === 'function') window.__toast(String(msg || '').trim());
      else alert(String(msg || '').trim());
    } catch {}
  };

  const logTrace = (step, extra = {}) => {
    try {
      console.log('[TS][TRACE][OVERVIEW_FINANCE]', {
        step,
        modal_id: String(window.modalCtx?.data?.id || '').trim() || null,
        modal_timesheet_id: String(window.modalCtx?.data?.timesheet_id || '').trim() || null,
        modal_for_id: String(window.modalCtx?.formState?.__forId || '').trim() || null,
        expected_timesheet_id: String(window.modalCtx?.timesheetMeta?.expected_timesheet_id || '').trim() || null,
        ...(extra || {})
      });
    } catch {}
  };

  const handleMoved = async (err, label) => {
    try {
      if (typeof tsHandleMoved409Modal === 'function') {
        return await tsHandleMoved409Modal(err, {
          tabKey: 'overview',
          toast: 'This timesheet changed while you were editing; review and try again.',
          label: label || 'timesheet-action'
        });
      }
    } catch {}
    return false;
  };

  const getTopFrame = () => {
    try {
      return (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
    } catch {
      return null;
    }
  };

  const getTimesheetId = () => {
    return String(
      (window.modalCtx && window.modalCtx.data && (window.modalCtx.data.timesheet_id || window.modalCtx.data.id)) ||
      ''
    ).trim();
  };

  const getExpectedTimesheetId = () => {
    return String(
      (window.modalCtx && window.modalCtx.timesheetMeta && window.modalCtx.timesheetMeta.expected_timesheet_id) ||
      getTimesheetId() ||
      ''
    ).trim();
  };

  const getPayState = () => {
    const ps = (window.modalCtx && window.modalCtx.timesheetPayState && typeof window.modalCtx.timesheetPayState === 'object')
      ? window.modalCtx.timesheetPayState
      : null;
    return ps || {};
  };

  const getCandidateDisplayName = () => {
    const related = (window.modalCtx && window.modalCtx.timesheetRelated && typeof window.modalCtx.timesheetRelated === 'object')
      ? window.modalCtx.timesheetRelated
      : {};
    const candidate = (related.candidate && typeof related.candidate === 'object') ? related.candidate : {};
    const row = (window.modalCtx && window.modalCtx.data && typeof window.modalCtx.data === 'object') ? window.modalCtx.data : {};

    return String(
      candidate.display_name ||
      [candidate.first_name, candidate.last_name].filter(Boolean).join(' ') ||
      row.candidate_name ||
      row.display_name ||
      'Candidate'
    ).trim();
  };

  const getClientName = () => {
    const related = (window.modalCtx && window.modalCtx.timesheetRelated && typeof window.modalCtx.timesheetRelated === 'object')
      ? window.modalCtx.timesheetRelated
      : {};
    const client = (related.client && typeof related.client === 'object') ? related.client : {};
    const row = (window.modalCtx && window.modalCtx.data && typeof window.modalCtx.data === 'object') ? window.modalCtx.data : {};

    return String(client.name || row.client_name || '—').trim() || '—';
  };

  const getReferenceNumber = () => {
    const details = (window.modalCtx && window.modalCtx.timesheetDetails && typeof window.modalCtx.timesheetDetails === 'object')
      ? window.modalCtx.timesheetDetails
      : {};
    const ts = (details.timesheet && typeof details.timesheet === 'object') ? details.timesheet : {};
    const row = (window.modalCtx && window.modalCtx.data && typeof window.modalCtx.data === 'object') ? window.modalCtx.data : {};

    return String(
      row.reference_number ||
      details.reference_number ||
      details.ref_num ||
      ts.reference_number ||
      ts.ref_num ||
      ''
    ).trim();
  };

  const getWeekEndingDate = () => {
    const details = (window.modalCtx && window.modalCtx.timesheetDetails && typeof window.modalCtx.timesheetDetails === 'object')
      ? window.modalCtx.timesheetDetails
      : {};
    const ts = (details.timesheet && typeof details.timesheet === 'object') ? details.timesheet : {};
    const row = (window.modalCtx && window.modalCtx.data && typeof window.modalCtx.data === 'object') ? window.modalCtx.data : {};

    return String(ts.week_ending_date || row.week_ending_date || '').trim();
  };

  const mergeReturnedPayState = (result) => {
    const ps = result && result.pay_state && typeof result.pay_state === 'object'
      ? result.pay_state
      : null;
    if (!ps) return;

    if (!window.modalCtx.timesheetDetails) window.modalCtx.timesheetDetails = {};
    window.modalCtx.timesheetDetails.pay_state = ps;
    window.modalCtx.timesheetPayState = ps;

    const statusRaw = String(ps.paid_status || '').trim().toUpperCase();
    const allowedStatuses = new Set(['PAID', 'PARTIALLY_PAID', 'PROCESSING', 'ADVANCED', 'UNPAID']);
    const status = allowedStatuses.has(statusRaw) ? statusRaw : 'UNPAID';
    const isAdvanced = !!(ps.is_advanced === true || ps.advanced_any === true);
    const paidAt = ps.paid_at_utc ? String(ps.paid_at_utc).trim() : '';
    const adjusted = (ps.adjusted && typeof ps.adjusted === 'object') ? ps.adjusted : null;
    const netDelta = adjusted ? Number(adjusted.net_delta_ex_vat || 0) : null;
    const consumedByBatchId = ps.advanced_consumed_by_batch_id != null && String(ps.advanced_consumed_by_batch_id).trim()
      ? String(ps.advanced_consumed_by_batch_id).trim()
      : null;
    const consumedAtUtc = ps.advanced_consumed_at_utc != null && String(ps.advanced_consumed_at_utc).trim()
      ? String(ps.advanced_consumed_at_utc).trim()
      : null;
    const advancedBatchStatus = ps.advanced_batch_status != null && String(ps.advanced_batch_status).trim()
      ? String(ps.advanced_batch_status).trim()
      : null;
    const advanceStatus = ps.advance_status != null && String(ps.advance_status).trim()
      ? String(ps.advance_status).trim()
      : (isAdvanced ? 'ADVANCED' : 'NOT_ADVANCED');

    if (window.modalCtx.data && typeof window.modalCtx.data === 'object') {
      window.modalCtx.data.pay_status_code = status;
      window.modalCtx.data.pay_paid_at_utc = paidAt || null;

      if (Number.isFinite(netDelta)) {
        window.modalCtx.data.net_delta_ex_vat = netDelta;
      }

      window.modalCtx.data.is_advanced = isAdvanced;
      window.modalCtx.data.advanced_any = isAdvanced;
      window.modalCtx.data.advance_status = advanceStatus;
      window.modalCtx.data.advanced_consumed_by_batch_id = consumedByBatchId;
      window.modalCtx.data.advanced_consumed_at_utc = consumedAtUtc;
      window.modalCtx.data.advanced_batch_status = advancedBatchStatus;

      if (!isAdvanced) {
        window.modalCtx.data.advanced_override_id = null;
        window.modalCtx.data.advance_override_id = null;
        window.modalCtx.data.timesheet_payment_override_id = null;
        window.modalCtx.data.payment_override_id = null;
      }

      if (status === 'PAID') window.modalCtx.data.pay_icon_code = 'COIN';
      else if (status === 'PARTIALLY_PAID') window.modalCtx.data.pay_icon_code = 'HALF_COIN';
      else if (status === 'PROCESSING' || status === 'ADVANCED' || isAdvanced) window.modalCtx.data.pay_icon_code = 'CLOCK';
      else window.modalCtx.data.pay_icon_code = 'NONE';
    }
  };

 const refreshOverviewOnly = async () => {
  const idNow = getTimesheetId();
  if (!idNow) return null;

  logTrace('refreshOverviewOnly-enter', {
    id_now: idNow
  });

  try {
    if (typeof refreshTimesheetModalFinanceState === 'function') {
      logTrace('refreshOverviewOnly-before-coordinated-refresh', {
        id_now: idNow
      });
      await refreshTimesheetModalFinanceState(idNow, {
        silent: true,
        structural: false,
        skipSummaryRefresh: true,
        skipTabRefresh: true,
        refreshMode: 'overview_only'
      });
      logTrace('refreshOverviewOnly-after-coordinated-refresh', {
        id_now: idNow
      });

      try {
        const fr = getTopFrame();
        if (fr && fr.entity === 'timesheets' && typeof fr._updateButtons === 'function') {
          fr._updateButtons();
        }
      } catch {}

      return true;
    }
  } catch {}

  try {
    if (typeof ensureTsRefreshAndRepaintOverview === 'function') {
      const refreshFn = ensureTsRefreshAndRepaintOverview();
      if (typeof refreshFn === 'function') {
        const fr = getTopFrame();
        const tabKey = (fr && fr.currentTabKey) ? fr.currentTabKey : 'overview';
        logTrace('refreshOverviewOnly-before-overview-refresh', {
          id_now: idNow,
          tab_key: tabKey
        });
        await refreshFn(tabKey);
        logTrace('refreshOverviewOnly-after-overview-refresh', {
          id_now: idNow,
          tab_key: tabKey
        });
        return true;
      }
    }
  } catch {}

  try {
    const fr = getTopFrame();
    if (fr && fr.entity === 'timesheets' && typeof fr.setTab === 'function') {
      await fr.setTab(fr.currentTabKey || 'overview');
      if (typeof fr._updateButtons === 'function') fr._updateButtons();
    }
  } catch {}

  return true;
};


  const buildSnoozeSeed = () => {
    const ps = getPayState();
    return {
      timesheet_id: getTimesheetId(),
      candidate_display_name: getCandidateDisplayName(),
      client_name: getClientName(),
      reference_number: getReferenceNumber(),
      week_ending_date: getWeekEndingDate(),
      pay_state: ps,
      snooze_until_date: ps && ps.snooze_until_date ? ps.snooze_until_date : null,
      snooze_is_indefinite: !!(ps && ps.snooze_is_indefinite === true),
      snooze_note: ps && ps.snooze_note ? ps.snooze_note : ''
    };
  };

  const advancePaymentBtn = root.querySelector('button[data-ts-action="advance-payment"]');
  const unadvancePaymentBtn = root.querySelector('button[data-ts-action="unadvance-payment"]');
  const snoozePaymentBtn = root.querySelector('button[data-ts-action="snooze-payment"]');
  const manageSnoozePaymentBtn = root.querySelector('button[data-ts-action="manage-snooze-payment"]');
  const clearSnoozePaymentBtn = root.querySelector('button[data-ts-action="clear-snooze-payment"]');

  if (advancePaymentBtn && !advancePaymentBtn.__tsFinanceWired) {
    advancePaymentBtn.__tsFinanceWired = true;
    advancePaymentBtn.addEventListener('click', async () => {
      const reason = await promptAdvancePaymentReason();
      if (!reason) return;

      advancePaymentBtn.__tsBusy = true;
      advancePaymentBtn.disabled = true;

      try {
        const idNow = getTimesheetId();
        if (!idNow) throw new Error('Timesheet id missing; cannot advance payment.');

        const result = await apiPostJson(
          `/api/timesheets/${encodeURIComponent(idNow)}/advance-payment`,
          {
            override_reason: reason,
            expected_timesheet_id: getExpectedTimesheetId() || idNow
          }
        );

        mergeReturnedPayState(result);
        await refreshOverviewOnly();

        const warningLines = (typeof formatAdvancePaymentWarnings === 'function')
          ? formatAdvancePaymentWarnings(result?.warnings)
          : [];

        const msgLines = [
          'This timesheet has been marked to be advanced in the next eligible pay run.',
          ...(warningLines.length ? ['', 'Advisory:', ...warningLines] : [])
        ].filter(Boolean);

        await showAdvancePaymentMessage('Advance this payment', msgLines.join('\n'));
      } catch (err) {
        try {
          if (await handleMoved(err, 'advance-payment')) return;
        } finally {
          advancePaymentBtn.__tsBusy = false;
          advancePaymentBtn.disabled = false;
        }

        const errJson = (err && typeof err === 'object' && err.json && typeof err.json === 'object')
          ? err.json
          : null;

        if (err?.status === 409 && errJson && errJson.error === 'NO_TIMESHEETS_READY_FOR_DRAFT') {
          const lines = [
            String(errJson.message || 'Timesheet calculations are still processing. Please try again shortly.').trim()
          ];
          if (errJson.last_error) {
            lines.push('', `Last error: ${String(errJson.last_error).trim()}`);
          }
          await showAdvancePaymentMessage('Advance this payment', lines.join('\n'));
          return;
        }

        const msg =
          (errJson && (errJson.message || errJson.error))
            ? String(errJson.message || errJson.error)
            : String(err?.message || 'Failed to advance this payment.');

        await showAdvancePaymentMessage('Advance this payment', msg);
        return;
      }

      advancePaymentBtn.__tsBusy = false;
      advancePaymentBtn.disabled = false;
    });
  }

  if (unadvancePaymentBtn && !unadvancePaymentBtn.__tsFinanceWired) {
    unadvancePaymentBtn.__tsFinanceWired = true;
    unadvancePaymentBtn.addEventListener('click', async () => {
      unadvancePaymentBtn.__tsBusy = true;
      unadvancePaymentBtn.disabled = true;

      try {
        const idNow = getTimesheetId();
        if (!idNow) throw new Error('Timesheet id missing; cannot clear advance.');

        const result = await apiPostJson(
          `/api/timesheets/${encodeURIComponent(idNow)}/unadvance-payment`,
          {
            clear_reason: 'Cleared from timesheet overview',
            expected_timesheet_id: getExpectedTimesheetId() || idNow
          }
        );

        mergeReturnedPayState(result);
        await refreshOverviewOnly();

        const msg = String(
          result?.message ||
          (result?.already_cleared
            ? 'This timesheet is not currently marked as advanced.'
            : 'This timesheet advance has been cleared.')
        ).trim();

        await showAdvancePaymentMessage('Unadvance this payment', msg);
      } catch (err) {
        try {
          if (await handleMoved(err, 'unadvance-payment')) return;
        } finally {
          unadvancePaymentBtn.__tsBusy = false;
          unadvancePaymentBtn.disabled = false;
        }

        const errJson = (err && typeof err === 'object' && err.json && typeof err.json === 'object')
          ? err.json
          : null;

        if (err?.status === 409 && errJson && errJson.error === 'TIMESHEET_ADVANCE_ALREADY_BATCHED') {
          const msg = String(
            errJson.message ||
            'This timesheet advance has already been batched and cannot be cleared here.'
          ).trim();
          await showAdvancePaymentMessage('Unadvance this payment', msg);
          return;
        }

        const msg =
          (errJson && (errJson.message || errJson.error))
            ? String(errJson.message || errJson.error)
            : String(err?.message || 'Failed to clear this timesheet advance.');

        await showAdvancePaymentMessage('Unadvance this payment', msg);
        return;
      }

      unadvancePaymentBtn.__tsBusy = false;
      unadvancePaymentBtn.disabled = false;
    });
  }

  const bindSnoozeBtn = (btn) => {
    if (!btn || btn.__tsFinanceWired) return;

    btn.__tsFinanceWired = true;
    btn.addEventListener('click', async () => {
      try {
        const result = await openTimesheetPaymentSnoozeModal(buildSnoozeSeed());
        if (!result || result.ok !== true) return;

        await refreshOverviewOnly();
        if(result.next===true){showNextTimesheetSnoozeResult(result.message??'Snooze updated.');return;}

        if (result.action === 'clear') {
          toast('Timesheet payment snooze cleared.');
        } else {
          const payload = (result.result && typeof result.result === 'object') ? result.result : {};
          const untilIso = String(payload.snooze_until_date || '').trim();
          if (untilIso) toast(`Timesheet payment snoozed until ${untilIso}.`);
          else toast('Timesheet payment snoozed indefinitely.');
        }
      } catch (err) {
        try {
          if (await handleMoved(err, 'snooze-payment')) return;
        } catch {}

        const errJson = (err && typeof err === 'object' && err.json && typeof err.json === 'object')
          ? err.json
          : null;

        const msg =
          (errJson && (errJson.message || errJson.error))
            ? String(errJson.message || errJson.error)
            : String(err?.message || 'Failed to update timesheet payment snooze.');

        toast(msg);
      }
    });
  };

  bindSnoozeBtn(snoozePaymentBtn);
  bindSnoozeBtn(manageSnoozePaymentBtn);

  if (clearSnoozePaymentBtn && !clearSnoozePaymentBtn.__tsFinanceWired) {
    clearSnoozePaymentBtn.__tsFinanceWired = true;
    clearSnoozePaymentBtn.addEventListener('click', async () => {
      clearSnoozePaymentBtn.__tsBusy = true;
      clearSnoozePaymentBtn.disabled = true;

      try {
        const next=await openNextTimesheetPaymentSnooze({...buildSnoozeSeed(),clear:true});if(next.handled){if(next.result?.ok){await refreshOverviewOnly();showNextTimesheetSnoozeResult(next.result.message??'Snooze removed.');}return;}
        if (typeof openUiConfirmModal === 'function') {
          const confirmRes = await openUiConfirmModal({
            title: 'Clear payment snooze?',
            message: 'This will remove the current timesheet payment snooze.',
            confirm_label: 'Clear snooze',
            cancel_label: 'Cancel',
            confirm_class: 'btn btn-warn',
            cancel_class: 'btn btn-outline'
          });
          if (!(confirmRes && confirmRes.confirmed === true)) {
            return;
          }
        }

        const idNow = getTimesheetId();
        if (!idNow) throw new Error('Timesheet id missing; cannot clear payment snooze.');

        await apiPostJson(
          `/api/timesheets/${encodeURIComponent(idNow)}/snooze-payment/clear`,
          {}
        );

        await refreshOverviewOnly();
        toast('Timesheet payment snooze cleared.');
      } catch (err) {
        try {
          if (await handleMoved(err, 'clear-snooze-payment')) return;
        } catch {}

        const errJson = (err && typeof err === 'object' && err.json && typeof err.json === 'object')
          ? err.json
          : null;

        const msg =
          (errJson && (errJson.message || errJson.error))
            ? String(errJson.message || errJson.error)
            : String(err?.message || 'Failed to clear timesheet payment snooze.');

        toast(msg);
      } finally {
        clearSnoozePaymentBtn.__tsBusy = false;
        clearSnoozePaymentBtn.disabled = false;
      }
    });
  }

  return { ok: true };
}



/* CloudTMS Retention Marker / Unprocess handover
 * Installed original amended because no candidate frontend body was supplied.
 * Complete final replacement extracted from and verified against the integrated final main.js.
 */


function renderTimesheetOverviewTab(ctx) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][OVERVIEW]');
  const { row, details, related, state } = normaliseTimesheetCtx(ctx);

  GC('render');

  const ts    = details.timesheet || {};
  const tsfin = details.tsfin     || {};
  const dailyStatusForOverview = SESSION?.user?.role==='admin' && bankingNextOwnerClient()?.peek()?.active_owner==='NEXT'
    ? window.CloudTMSBpayNextOffice?.dailyProcessingState?.(details) : null;
  const cw    = details.contract_week || {};
  const rCand = related.candidate || {};
  const rCli  = related.client    || {};
  const rCtr  = related.contract  || {};
  const successfulHealthRosterValidation = getSuccessfulHealthRosterValidation(details);

  const actionFlags = (details.action_flags && typeof details.action_flags === 'object')
    ? details.action_flags
    : {};
  const weeklySourcePresentationApi = (typeof window !== 'undefined') ? window.CloudTMSWeeklySourcePresentationV1 : null;
  const weeklySourcePresentationHost = weeklySourcePresentationApi && typeof weeklySourcePresentationApi.findHostPayload === 'function'
    ? weeklySourcePresentationApi.findHostPayload([details, row, ts, ctx])
    : null;
  const weeklySourcePresentationVm = weeklySourcePresentationHost && typeof weeklySourcePresentationApi.buildViewModel === 'function'
    ? weeklySourcePresentationApi.buildViewModel(weeklySourcePresentationHost)
    : null;
  const clientSourceAuthorityOverview = weeklySourcePresentationVm?.mount === true && weeklySourcePresentationVm.authority === 'CLIENT_SYSTEM';

  const candidateOfficeProjectionUiReady = !!(
    typeof window !== 'undefined' &&
    window.CloudTMSCandidateOfficeBridge?.capabilities?.authority_applies === true &&
    window.CloudTMSCandidateOfficeBridge?.capabilities?.permissions?.view_candidate_state === true &&
    window.CloudTMSCandidateOfficeBridge?.capabilities?.surfaces?.simple_timesheet === true
  );

  const baseSummary = (window.modalCtx && window.modalCtx.data && typeof window.modalCtx.data === 'object')
    ? window.modalCtx.data
    : {};

  const policy = (details && details.policy && typeof details.policy === 'object') ? details.policy : {};

  const hydration = (
    (ctx && ctx.hydration && typeof ctx.hydration === 'object')
      ? ctx.hydration
      : ((window.modalCtx && window.modalCtx.timesheetHydration && typeof window.modalCtx.timesheetHydration === 'object')
          ? window.modalCtx.timesheetHydration
          : {})
  );
  const detailsArePlaceholder = !!(details && (details.__placeholder || details.__loading));
  const openingDetailsPending = !!(
    detailsArePlaceholder ||
    hydration.detailsLoading === true ||
    (hydration.fastOpen === true && hydration.detailsLoaded !== true && !hydration.detailsError)
  );
  const detailsLoading = openingDetailsPending;
  const hasOwnNonBlank = (obj, key) => !!(
    obj &&
    typeof obj === 'object' &&
    Object.prototype.hasOwnProperty.call(obj, key) &&
    obj[key] != null &&
    String(obj[key]).trim() !== ''
  );

  const boolish = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on');
  };

  const suppressActionButtons = !!(
    boolish(ctx?.suppress_action_buttons) ||
    boolish(ctx?.suppress_timesheet_action_buttons) ||
    boolish(ctx?.bulk_authorise_mode) ||
    boolish(state?.suppressActionButtons) ||
    boolish(state?.suppress_action_buttons) ||
    boolish(state?.bulkAuthoriseMode) ||
    boolish(state?.bulk_authorise_mode) ||
    boolish(row?.suppress_action_buttons) ||
    boolish(row?.bulk_authorise_mode)
  );

  const archivedAtUtcForOverview = String(
    row?.archived_at_utc || details?.archived_at_utc || ts?.archived_at_utc || actionFlags?.archived_at_utc || baseSummary?.archived_at_utc || ''
  ).trim();
  const isArchivedOverview = !!(
    archivedAtUtcForOverview || boolish(row?.is_archived) || boolish(details?.is_archived) || boolish(ts?.is_archived) ||
    boolish(actionFlags?.is_archived) || String(baseSummary?.summary_stage || baseSummary?.tools_stage || '').trim().toUpperCase() === 'ARCHIVED'
  );

  const sheetScopeRawForOverview = (
    details.sheet_scope ||
    ts.sheet_scope ||
    baseSummary.sheet_scope ||
    row.sheet_scope ||
    ''
  );
  const hasExplicitScopeSummary = !!(
    (!detailsArePlaceholder && (hasOwnNonBlank(details, 'sheet_scope') || hasOwnNonBlank(ts, 'sheet_scope'))) ||
    hasOwnNonBlank(baseSummary, 'sheet_scope') ||
    hasOwnNonBlank(row, 'sheet_scope')
  );
  const sheetScope = (detailsLoading && !hasExplicitScopeSummary)
    ? ''
    : String(sheetScopeRawForOverview || '').toUpperCase();

  // ✅ planned weeks use canonical submission_mode_snapshot first (not stale row.submission_mode)
  const cwModeSnapshotRaw =
    String(
      details.cw_submission_mode_snapshot ||
      cw.submission_mode_snapshot ||
      baseSummary.submission_mode_snapshot ||
      row.submission_mode_snapshot ||
      ''
    );
  const hasExplicitModeSnapshotSummary = !!(
    (!detailsArePlaceholder && (hasOwnNonBlank(details, 'cw_submission_mode_snapshot') || hasOwnNonBlank(cw, 'submission_mode_snapshot'))) ||
    hasOwnNonBlank(baseSummary, 'submission_mode_snapshot') ||
    hasOwnNonBlank(row, 'submission_mode_snapshot')
  );
  const cwModeSnapshot = (detailsLoading && !hasExplicitModeSnapshotSummary)
    ? ''
    : cwModeSnapshotRaw.toUpperCase();

  // ✅ Timesheet identity for "has real timesheet?" must NOT use details.current_timesheet_id
  // (it can be stale after unprocess and would incorrectly hide planned-week actions).
  // Keep details.current_timesheet_id only as informational/debug.
  const tsId =
    ts.timesheet_id ||
    baseSummary.timesheet_id ||
    row.timesheet_id ||
    null;

  const resolvedCurrentTimesheetId =
    details.current_timesheet_id ||
    null;

  // ✅ define effective mode (real TS mode if TS exists; otherwise planned-week snapshot)
  const hasTsNow   = !!tsId;
  const hasExplicitSubmissionModeSummary = !!(
    (!detailsArePlaceholder && hasOwnNonBlank(ts, 'submission_mode')) ||
    hasOwnNonBlank(baseSummary, 'submission_mode') ||
    hasOwnNonBlank(row, 'submission_mode')
  );
  const subModeTsRaw = String(ts.submission_mode || baseSummary.submission_mode || row.submission_mode || '');
  const subModeTs  = (detailsLoading && !hasExplicitSubmissionModeSummary) ? '' : subModeTsRaw.toUpperCase();
  const subModeEff = hasTsNow ? subModeTs : cwModeSnapshot;

  // keep existing variable name used elsewhere in this function
  const subMode = subModeEff;

  const enc = escapeHtml;

  const candidateName =
    (rCand.display_name && enc(rCand.display_name)) ||
    (row.candidate_name && enc(row.candidate_name)) ||
    (row.occupant_key_norm && enc(row.occupant_key_norm)) ||
    (rCand.first_name || rCand.last_name
      ? enc([rCand.first_name, rCand.last_name].filter(Boolean).join(' '))
      : 'Not yet assigned to a candidate');

  const assignedCandidateId = String(
    rCand.id ||
    rCand.candidate_id ||
    rCtr.candidate_id ||
    details.candidate_id ||
    ts.candidate_id ||
    cw.candidate_id ||
    baseSummary.candidate_id ||
    row.candidate_id ||
    ''
  ).trim();
  const hasAssignedCandidate = !!assignedCandidateId;

  const clientName =
    (rCli.name && enc(rCli.name)) ||
    (rCtr.display_site && enc(rCtr.display_site)) ||
    (row.client_name && enc(row.client_name)) ||
    (row.client_id ? enc(row.client_id) : 'Unknown client');

  const jobTitle =
    (rCtr.role && enc(rCtr.role)) ||
    (row.job_title_norm && enc(row.job_title_norm)) ||
    null;

  const band =
    (rCtr.band && String(rCtr.band).trim()) ||
    (row.band && String(row.band).trim()) ||
    null;

  const weYmd = ts.week_ending_date || row.week_ending_date || null;

  const fmtYmdToDmy = (ymd) => {
    if (!ymd || typeof ymd !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(ymd)) return enc(ymd || '');
    const [y, m, d] = ymd.split('-');
    return `${d}-${m}-${y}`;
  };

  const fmtDow = (ymd) => {
    if (!ymd) return '';
    const d = new Date(`${ymd}T00:00:00Z`);
    if (Number.isNaN(d.getTime())) return '';
    return d.toLocaleDateString('en-GB', { weekday: 'short', timeZone: 'Europe/London' });
  };

  const fmtUtcToUk = (iso) => {
    try {
      if (!iso) return '';
      const d = new Date(String(iso));
      if (Number.isNaN(d.getTime())) return String(iso || '');
      const fmt = new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Europe/London',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });
      return fmt.format(d).replace(',', '');
    } catch {
      return String(iso || '');
    }
  };

  const fmtMoney = (v) => {
    const n = Number(v);
    if (!Number.isFinite(n)) return '0.00';
    return (Math.round(n * 100) / 100).toFixed(2);
  };

  const hasTsfin = !!(
    tsfin &&
    (tsfin.timesheet_id || tsfin.total_hours != null || tsfin.total_pay_ex_vat != null || tsfin.processing_status)
  );

  const hasContractWeek = !!(details.contract_week_id || cw.id || row.contract_week_id);
  const isPlannedOnly   = !hasTsfin && hasContractWeek && !tsId;
  const isPlannedWeeklyRow = (sheetScope === 'WEEKLY') && !tsId && hasContractWeek;

  // ✅ planned weeks must NOT read stale row.processing_status when canonical detail exists
  const stageRaw = hasTsfin
    ? (String(tsfin.processing_status || baseSummary.processing_status || row.processing_status || '').toUpperCase() || null)
    : null;

  const summaryStageRaw =
    String(
      details.summary_stage ||
      cw.summary_stage ||
      baseSummary.summary_stage ||
      row.summary_stage ||
      ''
    ).toUpperCase();

  const toolsStageRaw =
    String(details.tools_stage || baseSummary.tools_stage || row.tools_stage || '').toUpperCase();

  const hasExplicitLifecycleSummary = !!(
    (!detailsArePlaceholder && (hasOwnNonBlank(tsfin, 'processing_status') || hasOwnNonBlank(details, 'summary_stage') || hasOwnNonBlank(details, 'tools_stage') || hasOwnNonBlank(cw, 'summary_stage'))) ||
    hasOwnNonBlank(baseSummary, 'processing_status') ||
    hasOwnNonBlank(baseSummary, 'summary_stage') ||
    hasOwnNonBlank(baseSummary, 'tools_stage') ||
    hasOwnNonBlank(row, 'processing_status') ||
    hasOwnNonBlank(row, 'summary_stage') ||
    hasOwnNonBlank(row, 'tools_stage')
  );

  const backendUnprocessed =
    !!(
      (!detailsLoading || hasExplicitLifecycleSummary) &&
      (
        stageRaw === 'UNPROCESSED' ||
        stageRaw === 'UNASSIGNED' ||
        (!stageRaw && (
          summaryStageRaw === 'UNPROCESSED' ||
          toolsStageRaw === 'UNPROCESSED'
        ))
      )
    );

  const modalInvoiceState = (typeof deriveTimesheetModalInvoicingState === 'function')
    ? deriveTimesheetModalInvoicingState({ row, details, related, state })
    : {
        state: 'UNKNOWN',
        hasAnyInvoiceLock: !!(tsfin.locked_by_invoice_id || row.locked_by_invoice_id),
        hasWholeInvoiceLock: !!(tsfin.locked_by_invoice_id || row.locked_by_invoice_id),
        totalSegments: 0,
        lockedSegments: 0,
        unlockedSegments: 0,
        invoiceIds: [],
        invoiceNoById: {},
        issueStage: '',
        lockedInvoiceStatus: ''
      };

  const isPaid     = !!(tsfin.paid_at_utc || row.paid_at_utc);
  const isInvoiced = !!(modalInvoiceState.hasWholeInvoiceLock || tsfin.locked_by_invoice_id || row.locked_by_invoice_id);

  // Candidate payment status alone must not lock hours/route amendment actions.
  // Invoice locks remain hard content locks.
  const locked     = isInvoiced;

  // Sheet-level pay hold (NOT line-level)
  const payOnHold  = !!(tsfin.pay_on_hold ?? row.pay_on_hold);

  const readyToPay =
    (typeof details.ready_to_pay === 'boolean') ? details.ready_to_pay :
    (typeof row.ready_to_pay === 'boolean')     ? row.ready_to_pay :
    false;

  // Total hours (used for QR-friendly messaging)
  const totalHoursNum = Number(tsfin.total_hours ?? row.total_hours ?? 0);
  const hasHours = Number.isFinite(totalHoursNum) && totalHoursNum > 0;

  // ─────────────────────────────────────────────────────────────
  // ✅ Import-authoritative detection must prefer canonical detail first
  // ─────────────────────────────────────────────────────────────
  const routeType =
    String(
      details.route_type ||
      cw.route_type ||
      policy.route_type ||
      baseSummary.route_type ||
      row.route_type ||
      row.routeType ||
      ''
    ).toUpperCase();
  const expenseOnlyForOverview = boolish(
    details.is_expense_only ??
    baseSummary.is_expense_only ??
    row.is_expense_only
  );

  const noTimesheetRequired =
    (details && Object.prototype.hasOwnProperty.call(details, 'no_timesheet_required'))
      ? boolish(details.no_timesheet_required)
      : (cw && Object.prototype.hasOwnProperty.call(cw, 'no_timesheet_required'))
        ? boolish(cw.no_timesheet_required)
        : (policy && Object.prototype.hasOwnProperty.call(policy, 'no_timesheet_required'))
          ? boolish(policy.no_timesheet_required)
          : (Object.prototype.hasOwnProperty.call(baseSummary, 'client_no_timesheet_required'))
            ? boolish(baseSummary.client_no_timesheet_required)
            : (row && Object.prototype.hasOwnProperty.call(row, 'client_no_timesheet_required'))
              ? boolish(row.client_no_timesheet_required)
              : false;

  const routeFamilyForOverview = String(
    details.route_family ||
    details.effective?.route_family ||
    actionFlags.route_family ||
    cw.route_family ||
    baseSummary.route_family ||
    row.route_family ||
    ''
  ).toUpperCase();

  const routeSubfamilyForOverview = String(
    details.route_subfamily ||
    details.effective?.route_subfamily ||
    actionFlags.route_subfamily ||
    cw.route_subfamily ||
    baseSummary.route_subfamily ||
    row.route_subfamily ||
    ''
  ).toUpperCase();

  const underlyingFamilyForOverview = String(
    details.underlying_channel_family ||
    details.effective?.underlying_channel_family ||
    actionFlags.underlying_channel_family ||
    cw.underlying_channel_family ||
    baseSummary.underlying_channel_family ||
    row.underlying_channel_family ||
    ''
  ).toUpperCase();

  const canonicalManualNonQrRoute = [
    routeFamilyForOverview,
    routeSubfamilyForOverview,
    underlyingFamilyForOverview
  ].includes('MANUAL_NON_QR');
  const canonicalQrRoute = !canonicalManualNonQrRoute && [
    routeFamilyForOverview,
    routeSubfamilyForOverview,
    underlyingFamilyForOverview
  ].includes('QR');

  const additionalSeqForOverview = Number(
    details.additional_seq ??
    details.contract_week_additional_seq ??
    details.effective?.additional_seq ??
    actionFlags.additional_seq ??
    cw.additional_seq ??
    baseSummary.additional_seq ??
    baseSummary.contract_week_additional_seq ??
    row.additional_seq ??
    row.contract_week_additional_seq ??
    0
  ) || 0;

  const effectiveAdjustmentForOverview = !!(
    boolish(ts.is_adjustment) ||
    boolish(cw.is_adjustment) ||
    boolish(details.is_adjustment) ||
    boolish(details.effective?.is_adjustment) ||
    boolish(actionFlags.is_adjustment) ||
    boolish(row.is_adjustment) ||
    boolish(baseSummary.is_adjustment) ||
    additionalSeqForOverview > 0 ||
    routeType.includes('_ADJUSTMENT')
  );

  const manualAdditionalForOverview = !!(
    (routeType === 'WEEKLY_NHSP_ADJUSTMENT' || routeType === 'WEEKLY_HEALTHROSTER_ADJUSTMENT' || routeType === 'WEEKLY_MANUAL_ADJUSTMENT' || routeType.includes('_ADJUSTMENT') || additionalSeqForOverview > 0) &&
    (
      effectiveAdjustmentForOverview ||
      additionalSeqForOverview > 0 ||
      routeFamilyForOverview === 'MANUAL_NON_QR' ||
      routeSubfamilyForOverview === 'MANUAL_NON_QR' ||
      underlyingFamilyForOverview === 'MANUAL_NON_QR' ||
      cwModeSnapshot === 'MANUAL' ||
      subModeEff === 'MANUAL'
    )
  );

  const importAuthoritative =
    !manualAdditionalForOverview &&
    (
      (routeType === 'WEEKLY_NHSP') ||
      (routeType === 'WEEKLY_NHSP_ADJUSTMENT') ||
      (routeType === 'WEEKLY_HEALTHROSTER' && noTimesheetRequired === true)
    );

  const routeTypeForDisplay = (() => {
    if (!isPlannedWeeklyRow) return routeType || '';
    if (importAuthoritative) return routeType || '';

    if (cwModeSnapshot === 'MANUAL') return 'WEEKLY_MANUAL';
    if (cwModeSnapshot === 'ELECTRONIC') return 'WEEKLY_ELECTRONIC';

    return routeType || '';
  })();

  const routeDisplayForDisplay = (() => {
    if (expenseOnlyForOverview) {
      return String(
        details.display_route_label ||
        baseSummary.display_route_label ||
        row.display_route_label ||
        'Expense'
      ).trim();
    }
    if (!isPlannedWeeklyRow) {
      return String(
        details.route_display ||
        cw.route_display ||
        baseSummary.route_display ||
        row.route_display ||
        ''
      ).trim();
    }

    if (importAuthoritative) {
      return String(
        details.route_display ||
        cw.route_display ||
        baseSummary.route_display ||
        row.route_display ||
        ''
      ).trim();
    }

    if (cwModeSnapshot === 'MANUAL') return 'Weekly Manual';
    if (cwModeSnapshot === 'ELECTRONIC') return 'Weekly Electronic';

    return String(
      details.route_display ||
      cw.route_display ||
      baseSummary.route_display ||
      row.route_display ||
      ''
    ).trim();
  })();

  if (LOGM) {
    L('canonical route/state snapshot', {
      clicked_row: {
        route_type: String(row.route_type || row.routeType || '').toUpperCase() || null,
        route_display: String(row.route_display || '').trim() || null,
        summary_stage: String(row.summary_stage || '').toUpperCase() || null,
        submission_mode_snapshot: String(row.submission_mode_snapshot || '').toUpperCase() || null
      },
      canonical_detail: {
        route_type: String(details.route_type || cw.route_type || policy.route_type || '').toUpperCase() || null,
        route_display: String(details.route_display || cw.route_display || '').trim() || null,
        summary_stage: String(details.summary_stage || cw.summary_stage || '').toUpperCase() || null,
        submission_mode_snapshot: String(details.cw_submission_mode_snapshot || cw.submission_mode_snapshot || '').toUpperCase() || null,
        no_timesheet_required: (
          (details && Object.prototype.hasOwnProperty.call(details, 'no_timesheet_required'))
            ? boolish(details.no_timesheet_required)
            : (cw && Object.prototype.hasOwnProperty.call(cw, 'no_timesheet_required'))
              ? boolish(cw.no_timesheet_required)
              : (policy && Object.prototype.hasOwnProperty.call(policy, 'no_timesheet_required'))
                ? boolish(policy.no_timesheet_required)
                : null
        )
      },
      effective: {
        route_type: routeTypeForDisplay || routeType || null,
        route_display: routeDisplayForDisplay || null,
        summary_stage: summaryStageRaw || null,
        sub_mode: subModeEff || null,
        import_authoritative: importAuthoritative,
        manual_additional: manualAdditionalForOverview,
        no_timesheet_required: noTimesheetRequired,
        planned_weekly: isPlannedWeeklyRow
      }
    });
  }

  // ─────────────────────────────────────────────────────────────
  // Other policy flags (still used for authorisation fallback only)
  // ─────────────────────────────────────────────────────────────

  // ✅ NEW: adjustment safety flag (defence-in-depth)
  // Must include contract-week additional/manual truth so source import semantics do not leak onto add-additional rows.
  const isAdjustment = effectiveAdjustmentForOverview || manualAdditionalForOverview;

  const requiresHr =
    (row && Object.prototype.hasOwnProperty.call(row, 'client_requires_hr'))
      ? boolish(row.client_requires_hr)
      : (policy && Object.prototype.hasOwnProperty.call(policy, 'requires_hr'))
        ? boolish(policy.requires_hr)
        : false;

  const autoprocessHr =
    (row && Object.prototype.hasOwnProperty.call(row, 'client_autoprocess_hr'))
      ? boolish(row.client_autoprocess_hr)
      : (policy && Object.prototype.hasOwnProperty.call(policy, 'autoprocess_hr'))
        ? boolish(policy.autoprocess_hr)
        : false;

  let authInfo = { requires: false, authorised: false, showAwaitingBadge: false };
  if (typeof computeRequiresTimesheetAuthorisation === 'function') {
    try {
      const x = computeRequiresTimesheetAuthorisation(details, row);
      if (x && typeof x === 'object') authInfo = { ...authInfo, ...x };
    } catch {}
  } else {
    const authorisedAt = ts.authorised_at_server || row.authorised_at_server || null;
    const authorised   = !!authorisedAt;
    const requiresAuth =
      (stageRaw === 'PENDING_AUTH') ||
      (requiresHr && !autoprocessHr && stageRaw === 'READY_FOR_HR');
    authInfo = { requires: requiresAuth, authorised, showAwaitingBadge: (requiresAuth && !authorised) };
  }

  const isManualOnly = !!actionFlags.is_manual_only;

   // ─────────────────────────────────────────────────────────────
  // ✅ NEW: backend pay-state (single source of truth for pay-status UI)
  // ─────────────────────────────────────────────────────────────
  const payState = (details && details.pay_state && typeof details.pay_state === 'object')
    ? details.pay_state
    : ((details && details.payState && typeof details.payState === 'object')
        ? details.payState
        : null);

  const payStateOk = !!(payState && typeof payState === 'object' && payState.ok === true);

  const payCounts = (payState && payState.counts && typeof payState.counts === 'object')
    ? payState.counts
    : {};

  const payAdjusted = (payState && payState.adjusted && typeof payState.adjusted === 'object')
    ? payState.adjusted
    : {};

  const payHover = (payState && payState.hover && typeof payState.hover === 'object')
    ? payState.hover
    : {};

  const payStatePaidStatus = String(payState?.paid_status || '').trim().toUpperCase();
  const payStateIsAdvanced = !!(payState?.is_advanced === true || payState?.advanced_any === true);
  const payStateCanUnadvance = !!(payState?.can_unadvance === true);
  const payStateAdvancedConsumedByBatchId = String(payState?.advanced_consumed_by_batch_id || '').trim();
  const payStateIsSnoozed = !!(payState?.is_snoozed === true);
  const payStateSnoozeUntilDate = String(payState?.snooze_until_date || '').trim();
  const payStateSnoozeIsIndefinite = !!(payState?.snooze_is_indefinite === true);
  const payStateSnoozeNote = String(payState?.snooze_note || '').trim();
  const payStateProcessingAny = !!payState?.processing_any;
  const backendCanAdvancePayment = actionFlags.can_advance_payment === true;
  const backendCanUnadvancePayment = actionFlags.can_unadvance_payment === true;
  const backendCanSnoozePayment = actionFlags.can_snooze_payment === true;
  const backendCanClearPaymentSnooze = actionFlags.can_clear_payment_snooze === true;

  const payTotals = (payState && payState.paid_totals && typeof payState.paid_totals === 'object')
    ? payState.paid_totals
    : {};
  const payStatePaidToDateRaw = Number(payTotals?.paid_to_date_ex_vat);
  const payStatePaidAmount = Number.isFinite(payStatePaidToDateRaw)
    ? Math.max(payStatePaidToDateRaw, 0)
    : 0;

  const payStatePaidAtUtc = payTotals?.last_paid_at_utc || payState?.paid_at_utc || null;
  const payStatePaidAtLabelUk =
    String(payState?.paid_at_label_uk || '').trim() ||
    (payStatePaidAtUtc ? fmtUtcToUk(payStatePaidAtUtc) : '');

  const payAdjustedPill = String(payAdjusted?.pill || '').trim().toUpperCase();
  const payAdjustedMessage = String(payAdjusted?.message || '').trim();
  const payAdjustedNetDeltaRaw = Number(payAdjusted?.net_delta_ex_vat);
  const payAdjustedOutstandingRaw = Number(payAdjusted?.outstanding_ex_vat);
  const payAdjustedReservedRaw = Number(payAdjusted?.reserved_ex_vat);
  const payAdjustedNetDelta = Number.isFinite(payAdjustedNetDeltaRaw) ? payAdjustedNetDeltaRaw : 0;
  const payAdjustedOutstanding = Number.isFinite(payAdjustedOutstandingRaw) ? Math.max(payAdjustedOutstandingRaw, 0) : 0;
  const payAdjustedReserved = Number.isFinite(payAdjustedReservedRaw) ? Math.max(payAdjustedReservedRaw, 0) : 0;
  const payStateHasActiveReservation = !!(payStateOk && payAdjustedReserved > 0);
  const payStateHasOutstanding = !!(payStateOk && payAdjustedOutstanding > 0);
  const payStateIsOverpaid = !!(payStateOk && payAdjustedNetDelta < 0);
  const payStateReservationCoversAdjustment = !!(
    payStateOk &&
    payStateHasActiveReservation &&
    payAdjustedNetDelta > 0 &&
    payAdjustedReserved >= payAdjustedNetDelta &&
    payAdjustedOutstanding <= 0
  );

  const effectivePaidStatus = (() => {
    if (!payStateOk) return isPaid ? 'PAID' : 'UNPAID';
    if (payStatePaidStatus === 'PROCESSING' || payStateProcessingAny) return 'PROCESSING';
    if (payStateHasActiveReservation) return payStatePaidAmount > 0 ? 'PARTIALLY_PAID' : 'RESERVED';
    if (payStateHasOutstanding && payStatePaidAmount > 0) return 'PARTIALLY_PAID';
    if (payStatePaidAmount > 0) return 'PAID';
    if (payStatePaidStatus === 'PARTIALLY_PAID') return 'PARTIALLY_PAID';
    if (payStatePaidStatus === 'PAID') return 'PAID';
    return 'UNPAID';
  })();
  const isEffectivelyPaid = effectivePaidStatus === 'PAID';
  const isEffectivelyPartPaid = effectivePaidStatus === 'PARTIALLY_PAID';
  const isEffectivelyProcessing = effectivePaidStatus === 'PROCESSING' || payStateProcessingAny;

  const lifecycleAuthorisedAtServer = (
    details.authorised_at_server ||
    details.authorisedAtServer ||
    ts.authorised_at_server ||
    ts.authorisedAtServer ||
    baseSummary.authorised_at_server ||
    row.authorised_at_server ||
    null
  );
  const lifecycleAuthorisedAtUtc = (
    tsfin.authorised_at_utc ||
    tsfin.authorisedAtUtc ||
    details.authorised_at_utc ||
    details.authorisedAtUtc ||
    baseSummary.authorised_at_utc ||
    row.authorised_at_utc ||
    null
  );
  const lifecycleRevokedAt = (
    details.revoked_at ||
    details.revokedAt ||
    ts.revoked_at ||
    ts.revokedAt ||
    baseSummary.revoked_at ||
    row.revoked_at ||
    null
  );
  const lifecycleProcessingStatus = String(stageRaw || '').trim().toUpperCase();
  const lifecycleIsPaymentAuthorised = !!(
    hasTsfin &&
    !lifecycleRevokedAt &&
    lifecycleProcessingStatus !== 'PENDING_AUTH' &&
    (
      lifecycleProcessingStatus === 'READY_FOR_INVOICE' ||
      lifecycleProcessingStatus === 'READY_FOR_PAYMENT' ||
      lifecycleProcessingStatus === 'AUTHORISED_FOR_PAYMENT' ||
      lifecycleProcessingStatus === 'AUTHORISED'
    ) &&
    (lifecycleAuthorisedAtServer || lifecycleAuthorisedAtUtc || authInfo.authorised === true)
  );
  const lifecycleAuthorisedForActionGating = !!(
    hasTsNow &&
    !lifecycleRevokedAt &&
    (
      boolish(actionFlags.is_authorised) ||
      boolish(actionFlags.authorised) ||
      boolish(details.is_authorised) ||
      boolish(details.authorised) ||
      boolish(baseSummary.is_authorised) ||
      boolish(baseSummary.authorised) ||
      !!lifecycleAuthorisedAtServer ||
      !!lifecycleAuthorisedAtUtc ||
      authInfo.authorised === true
    )
  );
  const modalLifecycleCtxForActions = (
    window.modalCtx &&
    typeof window.modalCtx === 'object'
  ) ? window.modalCtx : {};
  const trustedLifecycleForActions = (
    modalLifecycleCtxForActions.__timesheetLifecycleTrusted &&
    typeof modalLifecycleCtxForActions.__timesheetLifecycleTrusted === 'object'
  ) ? modalLifecycleCtxForActions.__timesheetLifecycleTrusted : {};
  const trustedLifecycleActionSignature = String(
    trustedLifecycleForActions.signature ||
    trustedLifecycleForActions.backend_row_signature ||
    trustedLifecycleForActions.mutation_row_signature ||
    trustedLifecycleForActions.row_signature ||
    trustedLifecycleForActions.expected_row_signature ||
    ''
  ).trim();
  const trustedLifecycleActionTimesheetId = String(
    trustedLifecycleForActions.timesheet_id ||
    trustedLifecycleForActions.current_timesheet_id ||
    ''
  ).trim();
  const lifecyclePermissionSurfaceReadyForActions = !hasTsNow || !!(
    modalLifecycleCtxForActions.__timesheetLifecycleCriticalStateIncomplete !== true &&
    modalLifecycleCtxForActions.__timesheetLifecyclePermissionStateComplete === true &&
    modalLifecycleCtxForActions.__timesheetLifecyclePriorityBadgesComplete === true &&
    trustedLifecycleForActions.trusted === true &&
    !!trustedLifecycleActionSignature &&
    (!trustedLifecycleActionTimesheetId || trustedLifecycleActionTimesheetId === String(tsId || ''))
  );
  const sourceTimesheetActionsBlocked = !!(
    hasTsNow &&
    (
      isArchivedOverview ||
      lifecycleAuthorisedForActionGating ||
      !lifecyclePermissionSurfaceReadyForActions
    )
  );
  const showAuthorisedForPaymentStageBadge = !!lifecycleIsPaymentAuthorised;

  const showAdvancePaymentAction =
    !!tsId &&
    hasTsfin &&
    !sourceTimesheetActionsBlocked &&
    backendCanAdvancePayment;

  const showUnadvancePaymentAction =
    !!tsId &&
    hasTsfin &&
    !sourceTimesheetActionsBlocked &&
    backendCanUnadvancePayment;

  const showSnoozePaymentAction =
    !!tsId &&
    hasTsfin &&
    !sourceTimesheetActionsBlocked &&
    (backendCanSnoozePayment || backendCanClearPaymentSnooze);

  // ─────────────────────────────────────────────────────────────
  // ✅ Invoice issuing delay badge (SEGMENTS mode, matches SQL rule)
  // + ✅ Line-level pay hold badge (SEGMENTS mode, matches SQL: seg.exclude_from_pay)
  // ─────────────────────────────────────────────────────────────
  let invoiceDelayBadge = null; // { label, cls, title } | null
  let payLineHoldBadge  = null; // { label, cls, title } | null

  try {
    let inv = tsfin.invoice_breakdown_json ?? null;
    if (typeof inv === 'string') {
      try { inv = JSON.parse(inv); } catch { inv = null; }
    }

    const mode = String(inv?.mode || '').toUpperCase();
    const segs = Array.isArray(inv?.segments) ? inv.segments : [];

    const addDaysYmd = (ymd, deltaDays) => {
      if (!ymd || typeof ymd !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(ymd)) return null;
      const [yy, mm, dd] = ymd.split('-').map(Number);
      const dt = new Date(Date.UTC(yy, mm - 1, dd));
      dt.setUTCDate(dt.getUTCDate() + Number(deltaDays || 0));
      return dt.toISOString().slice(0, 10);
    };

    const weekStartMondayYmd = (ymd) => {
      if (!ymd || typeof ymd !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(ymd)) return null;
      const [yy, mm, dd] = ymd.split('-').map(Number);
      const dt = new Date(Date.UTC(yy, mm - 1, dd));
      const jsDow = dt.getUTCDay();
      const monIndex = (jsDow + 6) % 7;
      dt.setUTCDate(dt.getUTCDate() - monIndex);
      return dt.toISOString().slice(0, 10);
    };

    const baselineWeekStart =
      (weYmd && /^\d{4}-\d{2}-\d{2}$/.test(String(weYmd))) ? addDaysYmd(String(weYmd), -6) : null;

    if (hasTsfin && mode === 'SEGMENTS' && segs.length) {
      const delayedSegs = segs.filter(seg => {
        if (!seg || typeof seg !== 'object') return false;

        const lockedIdRaw = seg.invoice_locked_invoice_id;
        const lockedId = (lockedIdRaw == null) ? '' : String(lockedIdRaw).trim();

        const targetRaw = seg.invoice_target_week_start;
        const target = (targetRaw == null) ? '' : String(targetRaw).trim();

        const segDateRaw = seg.date;
        const segDate = (segDateRaw == null) ? '' : String(segDateRaw).trim();

        const baseStart = baselineWeekStart || weekStartMondayYmd(segDate);

        const hasLocked = !!lockedId;
        const hasTarget = !!target;

        if (hasLocked) return false;
        if (!hasTarget) return false;
        if (!baseStart) return false;

        return target !== baseStart;
      });

      if (delayedSegs.length) {
        const allDelayed = (delayedSegs.length === segs.length);
        invoiceDelayBadge = {
          label: allDelayed ? 'Whole Invoice is Delayed' : 'Some Invoice Issuing Delays',
          cls:   allDelayed ? 'pill-bad' : 'pill-warn',
          title: allDelayed
            ? `All ${segs.length} segment(s) are delayed from their baseline invoice week.`
            : `${delayedSegs.length} of ${segs.length} segment(s) are delayed from their baseline invoice week.`
        };
      }

      const heldSegs = segs.filter(seg => {
        if (!seg || typeof seg !== 'object') return false;
        return boolish(seg.exclude_from_pay);
      });

      if (heldSegs.length) {
        const allHeld = (heldSegs.length === segs.length);
        payLineHoldBadge = {
          label: allHeld ? 'All Pay on hold' : 'Some Pay on hold',
          cls:   allHeld ? 'pill-bad' : 'pill-warn',
          title: allHeld
            ? `All ${segs.length} segment(s) are excluded from pay.`
            : `${heldSegs.length} of ${segs.length} segment(s) are excluded from pay.`
        };
      }
    }
  } catch {}

  // ─────────────────────────────────────────────────────────────
  // Stage badges + tooltips
  // ─────────────────────────────────────────────────────────────
  const stageBadges = [];
  const seenStage   = new Set();

  const makeStageBadgeHtml = (label, cls, title) => {
    const key = String(label || '').trim();
    if (!key) return '';
    return `<span class="pill ${cls || 'pill-info'}" style="font-weight:600;"${title ? ` title="${enc(title)}"` : ''}>${enc(key)}</span>`;
  };

  const archivedFinancialStageLabels = new Set([
    'PAID', 'PART PAID', 'PARTLY PAID', 'PARTIALLY PAID', 'ADVANCED', 'OVERPAID', 'UNDERPAID',
    'PAY OUTSTANDING', 'PAYMENT OUTSTANDING', 'INVOICED', 'PARTLY INVOICED', 'INVOICE PAID'
  ]);
  const stageAllowedWhenArchived = (label) => {
    if (!isArchivedOverview) return true;
    const key = String(label || '').trim().toUpperCase();
    return key === 'ARCHIVED' || key === 'WITHDRAWN' || archivedFinancialStageLabels.has(key);
  };

  const addStage = (label, cls, title) => {
    const key = String(label || '').trim();
    if (!key || !stageAllowedWhenArchived(key)) return;
    if (seenStage.has(key)) return;
    seenStage.add(key);
    stageBadges.push(makeStageBadgeHtml(key, cls, title));
  };

  const prependStage = (label, cls, title) => {
    const key = String(label || '').trim();
    if (!key || !stageAllowedWhenArchived(key)) return;
    if (seenStage.has(key)) return;
    seenStage.add(key);
    const html = makeStageBadgeHtml(key, cls, title);
    if (isArchivedOverview && !['ARCHIVED', 'WITHDRAWN'].includes(key.toUpperCase())) stageBadges.push(html);
    else stageBadges.unshift(html);
  };

  if (isArchivedOverview) {
    prependStage('Withdrawn', 'pill-bad', 'This timesheet is archived. Operational lifecycle actions are unavailable until it is unarchived.');
  }

  if (showAuthorisedForPaymentStageBadge) {
    prependStage(
      'Authorised for Payment',
      'pill-ok',
      'This timesheet is authorised for payment.'
    );
  }

  if (successfulHealthRosterValidation) {
    addStage(
      'Validated',
      'pill-ok',
      'HealthRoster has successfully validated the stored timesheet hours and references.'
    );
  }

  // Authoritative pay-state badges. Payment money is driven from pay_state paid_totals/adjusted,
  // not component-count diagnostics, and all payment badges stay in the Stage row.
  if (payStateOk) {
    const paidAmountLabel = `£${fmtMoney(payStatePaidAmount)} ex VAT`;
    const reservedAmountLabel = `£${fmtMoney(payAdjustedReserved)} ex VAT`;
    const outstandingAmountLabel = `£${fmtMoney(payAdjustedOutstanding)} ex VAT`;

    if (effectivePaidStatus === 'PAID' && !payStateHasActiveReservation) {
      addStage(
        'Paid',
        'pill-ok',
        `${payStatePaidAtLabelUk ? `Paid at ${payStatePaidAtLabelUk}. ` : ''}Amount paid: ${paidAmountLabel}.`
      );
    } else if (effectivePaidStatus === 'PARTIALLY_PAID') {
      const hoverParts = [];
      hoverParts.push(`${paidAmountLabel} has been paid to date.`);
      if (payStatePaidAtLabelUk) hoverParts.push(`Last paid ${payStatePaidAtLabelUk}.`);
      if (payStateHasActiveReservation) hoverParts.push(`${reservedAmountLabel} is reserved for payment.`);
      hoverParts.push(`Amount still owed: ${outstandingAmountLabel}.`);

      addStage(
        'Partly Paid',
        'pill-warn',
        hoverParts.join(' ')
      );
    }

    if (effectivePaidStatus === 'PROCESSING' || payStateProcessingAny) {
      addStage(
        'Payment in progress',
        'pill-info',
        'Payment execution/processing is in progress and has not yet settled/finalised.'
      );
    }

    if (payStateIsOverpaid) {
      addStage(
        'Overpaid',
        'pill-bad',
        `Current overpaid position: £${fmtMoney(Math.abs(payAdjustedNetDelta))} ex VAT.`
      );
    }

    if (payStateHasActiveReservation) {
      addStage(
        'Payment Reserved',
        'pill-ok',
        payStateReservationCoversAdjustment
          ? `${reservedAmountLabel} is reserved for the outstanding adjustment. No unreserved amount is currently owed.`
          : `${reservedAmountLabel} is reserved for payment.`
      );
    }

    if (payStateHasOutstanding && (payStatePaidAmount > 0 || payStateHasActiveReservation)) {
      addStage(
        'Pay Outstanding',
        'pill-warn',
        `${outstandingAmountLabel} remains outstanding and is not currently reserved.`
      );
    }

    if (
      effectivePaidStatus === 'UNPAID' &&
      !payStateHasActiveReservation &&
      !payStateProcessingAny &&
      payStatePaidAmount <= 0
    ) {
      addStage(
        'Unpaid',
        'pill-bad',
        'No settled or reserved candidate payment is currently recorded for this timesheet.'
      );
    }

    if (payStateIsAdvanced) {
      addStage(
        'Advanced',
        'pill-bad',
        payStateAdvancedConsumedByBatchId
          ? `This Advance Pay marker has already been consumed by pay batch ${payStateAdvancedConsumedByBatchId}.`
          : 'This timesheet is marked for Advance Pay and will be included in the next eligible Banking Pay preview.'
      );
    }
  }

  // ✅ NEW: Reference blocker pill (Option A: DB emits these exact strings into issue_codes)
  // Show at most one (DB should already guarantee this; we apply precedence defensively).
  try {
    const rawCodes =
      Array.isArray(row?.issue_codes) ? row.issue_codes :
      (Array.isArray(details?.issue_codes) ? details.issue_codes : []);

    const codes = rawCodes.map(x => String(x || '').trim()).filter(Boolean);

    const REF_PRECEDENCE = [
      'Refs (Invoice and Issue Blocked)',
      'Refs (Invoicing Blocked)',
      'Refs (Issue Invoice Blocked)'
    ];

    let refChosen = '';
    for (const k of REF_PRECEDENCE) {
      if (codes.includes(k)) { refChosen = k; break; }
    }

    if (refChosen) {
      const title =
        (refChosen === 'Refs (Invoice and Issue Blocked)')
          ? 'Reference numbers are missing. This blocks both creating invoices and issuing invoices until references are added.'
          : (refChosen === 'Refs (Invoicing Blocked)')
            ? 'Reference numbers are missing. This blocks creating invoices until references are added.'
            : 'Reference numbers are missing. Invoices can be created, but cannot be issued until references are added.';

      addStage(refChosen, 'pill-bad', title);
    }
  } catch {}

  // ✅ backend lifecycle truth for unprocessed:
  // - real-row UNPROCESSED must show as Unprocessed
  // - legacy UNASSIGNED remains mapped to Unprocessed
  // - planned rows with no TSFIN remain Unprocessed
  if (hasTsfin && backendUnprocessed) {
    addStage(
      'Unprocessed',
      'pill-info',
      (stageRaw === 'UNASSIGNED')
        ? 'This timesheet has been reset or currently has no valid hours recorded yet. Enter/submit hours to continue.'
        : 'This is a real timesheet row but it is currently unprocessed. Save/process hours to continue.'
    );
  } else if (!hasTsfin && !dailyStatusForOverview && (!detailsLoading || hasExplicitLifecycleSummary || isPlannedOnly)) {
    addStage(
      'Unprocessed',
      'pill-info',
      'This timesheet is unprocessed. No real hours have been entered yet (the Lines tab shows the default contract schedule until you enter actual hours).'
    );
  } else if (!hasTsfin && detailsLoading) {
    addStage(
      'Loading timesheet state…',
      'pill-info',
      'Canonical timesheet details are still loading. Lifecycle badges will update when the current details arrive.'
    );
  }

  if (importAuthoritative && (row.candidate_hours_received === true || baseSummary.candidate_hours_received === true)) {
    addStage('Candidate Hours Received', 'pill-ok', 'The candidate signed and submitted hours for comparison. Final source hours remain authoritative.');
  }

  // ─────────────────────────────────────────────────────────────
  // ✅ Invoice issuance overlay (server-authoritative from SUMMARY row)
  // Rules:
  //  - Only apply if timesheet is invoiced AND locked_invoice_status exists
  //  - Invoice Paid takes precedence and suppresses the separate "Paid" stage
  //  - Otherwise show Invoiced (Issued) / Invoiced (Not issued); else fall back to "Invoiced"
  // ─────────────────────────────────────────────────────────────
  const lockedInvoiceStatus =
    String(
      modalInvoiceState.lockedInvoiceStatus ||
      ((row && Object.prototype.hasOwnProperty.call(row, 'locked_invoice_status'))
        ? (row.locked_invoice_status ?? '')
        : '')
    ).trim().toUpperCase();

  const hasLockedInvoiceStatus = !!(lockedInvoiceStatus || modalInvoiceState.issueStage);
  const invoicePaid = modalInvoiceState.state === 'INVOICE_PAID' || (hasLockedInvoiceStatus && (lockedInvoiceStatus === 'PAID'));
  const invoiceIssued = modalInvoiceState.state === 'INVOICED_ISSUED' || (hasLockedInvoiceStatus && (lockedInvoiceStatus === 'ISSUED' || lockedInvoiceStatus === 'PAID'));
  const invoicePartly = modalInvoiceState.state === 'PARTIALLY_INVOICED';
  const invoiceFully = !!(
    modalInvoiceState.state === 'FULLY_INVOICED' ||
    modalInvoiceState.state === 'WHOLE_INVOICED' ||
    modalInvoiceState.state === 'INVOICED_ISSUED' ||
    modalInvoiceState.state === 'INVOICED_NOT_ISSUED'
  );

  if (invoicePaid) {
    addStage('Invoice Paid', 'pill-ok', 'This timesheet is on an invoice that has been marked as paid.');
  } else {
    // Candidate payment badges are rendered only from authoritative pay_state above.
    // Do not fall back to legacy tsfin.paid_at_utc / summary cache for payment state.
    if (invoicePartly) {
      const total = Number(modalInvoiceState.totalSegments || 0);
      const lockedCount = Number(modalInvoiceState.lockedSegments || 0);
      const title = (Number.isFinite(total) && total > 0 && Number.isFinite(lockedCount) && lockedCount > 0)
        ? `${lockedCount} of ${total} line(s)/segment(s) have been invoiced.`
        : 'Some timesheet lines/segments have been invoiced and others have not.';
      addStage('Partly invoiced', 'pill-warn', title);
    }

    if ((isInvoiced || invoiceFully) && (!invoicePartly || modalInvoiceState.hasWholeInvoiceLock)) {
      if (hasLockedInvoiceStatus) {
        if (invoiceIssued) {
          addStage('Invoiced (Issued)', 'pill-warn', 'This timesheet is invoiced and the invoice has been issued.');
        } else {
          addStage('Invoiced (Not issued)', 'pill-warn', 'This timesheet is invoiced but the invoice has not been issued yet.');
        }
      } else {
        addStage('Invoiced', 'pill-warn', 'This timesheet has been invoiced and is locked for changes.');
      }
    }
  }

  // READY_FOR_INVOICE is the internal lifecycle state for payment authorisation.
  // The user-facing Overview/Stage badge is rendered first as “Authorised for Payment” above.
  if (hasTsfin && stageRaw === 'READY_FOR_HR') {
    addStage('Ready for HR', 'pill-info', 'This timesheet is authorised and requires HealthRoster validation before it can be invoiced.');
  }

  if (hasTsfin && stageRaw === 'RATE_MISSING') {
    addStage(
      'Rate Missing',
      'pill-bad',
      'Rates are missing for one or more hour buckets used by this timesheet. Add the missing rates before continuing (in some cases you may need to correct the contract and reprocess/recreate unprocessed weeks).'
    );
  }
  if (hasTsfin && stageRaw === 'PAY_CHANNEL_MISSING') {
    addStage('Pay Channel Missing', 'pill-bad', 'The pay channel for this candidate is missing. Set the candidate pay method/channel before continuing.');
  }

  if (authInfo.showAwaitingBadge) {
    addStage('Processed', 'pill-warn', 'Processing is complete. This timesheet is awaiting Office Authorise.');
  }

  if (payOnHold) {
    addStage('Pay on hold', 'pill-bad', 'Pay is on hold for this timesheet. Remove the hold to allow payment.');
  }

  if (
    readyToPay &&
    !payOnHold &&
    !isEffectivelyPaid &&
    !isEffectivelyPartPaid &&
    !isEffectivelyProcessing &&
    !payStateIsAdvanced &&
    !payStateHasActiveReservation &&
    !payStateIsOverpaid
  ) {
    addStage('Ready to Pay', 'pill-ok', 'This timesheet is ready to be included in the next pay run.');
  }

  if (invoiceDelayBadge && invoiceDelayBadge.label) {
    addStage(invoiceDelayBadge.label, invoiceDelayBadge.cls, invoiceDelayBadge.title);
  }
  if (payLineHoldBadge && payLineHoldBadge.label) {
    addStage(payLineHoldBadge.label, payLineHoldBadge.cls, payLineHoldBadge.title);
  }

  // Candidate submission lifecycle—including every QR Pack stage—is owned
  // exclusively by the canonical Candidate Office projection. Historic QR
  // columns are neither presentation authority nor Office action authority.

  if (isManualOnly) {
    addStage(
      'Candidate submission disabled',
      'pill-warn',
      lifecycleAuthorisedForActionGating
        ? 'Candidate submission is disabled for this authorised timesheet. Unauthorise the timesheet before re-enabling electronic or QR submission.'
        : 'Candidate submission is disabled for this timesheet. Where the backend confirms eligibility, use “Enable Electronic Submission” or “Enable QR submission”.'
    );
  }

  const STAGES_WITH_FRIENDLY_BADGE = new Set([
    'READY_FOR_INVOICE',
    'READY_FOR_HR',
    'RATE_MISSING',
    'PAY_CHANNEL_MISSING',
    'AWAITING_MANUAL_SIGNATURE',
    'UNASSIGNED'
  ]);

  if (hasTsfin && stageRaw && !STAGES_WITH_FRIENDLY_BADGE.has(stageRaw) && stageRaw !== 'UNPROCESSED') {
    if (stageRaw !== 'PENDING_AUTH') addStage(stageRaw, 'pill-info');
  }

  if (!stageBadges.length && !dailyStatusForOverview) {
    if (detailsLoading) {
      addStage('Loading timesheet state…', 'pill-info', 'Canonical timesheet details are still loading. Lifecycle badges will update when the current details arrive.');
    } else {
      addStage('Unknown', 'pill-info', 'No stage could be determined for this timesheet.');
    }
  }

  // ─────────────────────────────────────────────────────────────
  // Route label (stable; never show action text here)
  // ─────────────────────────────────────────────────────────────
  const routeLabel = (() => {
    if (expenseOnlyForOverview) return routeDisplayForDisplay || 'Expense';
    if (canonicalQrRoute) return 'QR';

    if (sheetScope === 'WEEKLY') {
      if (manualAdditionalForOverview) return 'Manual';
      if (routeTypeForDisplay === 'WEEKLY_NHSP' || routeTypeForDisplay === 'WEEKLY_NHSP_ADJUSTMENT') return 'NHSP';
      if (routeTypeForDisplay === 'WEEKLY_HEALTHROSTER') {
        return noTimesheetRequired ? 'HealthRoster (no timesheets)' : 'HealthRoster (timesheets required)';
      }

      if (isPlannedWeeklyRow) {
        if (cwModeSnapshot === 'MANUAL') return 'Manual';
        if (cwModeSnapshot === 'ELECTRONIC') return 'Electronic';
      }

      if (routeTypeForDisplay === 'WEEKLY_ELECTRONIC') return 'Electronic';
      if (routeTypeForDisplay === 'WEEKLY_MANUAL') return 'Manual';
    }

    if (subModeEff === 'ELECTRONIC') return 'Electronic';
    if (subModeEff === 'MANUAL') return 'Manual';
    return detailsLoading ? 'Loading…' : 'Manual';
  })();

  const routeTitle = (() => {
    if (weeklySourcePresentationVm?.mount === true) {
      if (weeklySourcePresentationVm.render_mode === 'UNAVAILABLE') {
        return weeklySourcePresentationVm.unavailable_reason || 'Refresh this Timesheet before continuing.';
      }
      if (weeklySourcePresentationVm.authority === 'CLIENT_SYSTEM') {
        return 'Client-provided hours are used for this Timesheet. Existing files remain available to view.';
      }
      if (weeklySourcePresentationVm.authority === 'SIGNED_TIMESHEET') {
        return 'The completed signed Timesheet decides the hours. Client system hours are used for checks and references.';
      }
    }
    if (routeLabel === 'QR') {
      return 'This timesheet is on the QR-only route. Candidate Submission shows the current QR Pack lifecycle.';
    }

    if (routeLabel === 'Electronic') {
      return isPlannedWeeklyRow
        ? 'Weekly planned row is currently in Electronic mode.'
        : 'Hours and signatures are submitted electronically by the candidate via the app. The candidate can also choose to complete a QR Timesheet if they prefer.';
    }

    if (routeLabel === 'Manual') {
      return isPlannedWeeklyRow
        ? 'Weekly planned row is currently in Manual mode.'
        : (
            isManualOnly
              ? 'Manual (candidate submission disabled). Admin will manage hours and evidence manually. To involve the candidate again you must explicitly re-enable submission.'
              : 'Manual (admin-managed). Admin can adjust hours/schedule internally; use an eligible server-owned submission action to involve the candidate again.'
          );
    }

    if (routeLabel.startsWith('HealthRoster')) {
      return noTimesheetRequired
        ? 'HealthRoster is authoritative and no weekly timesheet is required. Imported/source evidence is view-only here; use additional manual or unprocess flows where allowed.'
        : 'HealthRoster is used and a weekly timesheet is required for evidence/processing.';
    }

    if (routeLabel === 'NHSP') {
      return 'NHSP is the authoritative source for this week. Imported/source evidence is view-only here; use additional manual or unprocess flows where allowed.';
    }
    return '';
  })();

  const routePillClass =
    openingDetailsPending ? 'pill-info' :
    (routeLabel === 'Manual') ? 'pill-manual' :
    (routeLabel === 'Electronic') ? 'pill-elec' :
    'pill-info';

  const scopeLabel =
    openingDetailsPending ? 'Loading…' :
    (sheetScope === 'WEEKLY') ? 'Weekly' :
    (sheetScope === 'DAILY')  ? 'Daily'  :
    (sheetScope ? sheetScope : (detailsLoading ? 'Loading…' : 'Unknown'));

  const scopePillClass =
    openingDetailsPending ? 'pill-info' :
    (sheetScope === 'WEEKLY') ? 'pill-weekly' :
    (sheetScope === 'DAILY')  ? 'pill-daily'  :
    'pill-info';

  const stageBadgesForDisplay = openingDetailsPending
    ? [
        `<span class="pill pill-info" style="font-weight:600;" title="${enc('Canonical timesheet details are still loading. Lifecycle badges will update when the current details arrive.')}">${enc('Loading timesheet state…')}</span>`
      ]
    : stageBadges;
  const routeLabelForDisplay = openingDetailsPending ? 'Loading…' : routeLabel;
  const routeTitleForDisplay = openingDetailsPending
    ? 'Canonical timesheet details are still loading. Route and scope badges will update when the current details arrive.'
    : routeTitle;
  const headerHtml = `
    <div class="card">
      <div class="row">
        <label>Timesheet</label>
        <div class="controls">
          <div style="font-size:15px;font-weight:600;margin-bottom:2px;">${candidateName}</div>
          <div class="mini">Client: ${clientName}</div>
          <div class="mini">
            ${
              weYmd
                ? `Week ending: ${row.__bpayNextExactPhysicalId ? weYmd.split('-').reverse().join('/') : fmtDow(weYmd)+' '+fmtYmdToDmy(weYmd)}`
                : '<span class="mini">Week ending: Unknown</span>'
            }
          </div>
          <div class="mini">
            ${
              jobTitle
                ? (band ? `${jobTitle} (Band ${enc(band)})` : jobTitle)
                : (band ? `Band ${enc(band)}` : '<span class="mini">No job title</span>')
            }
          </div>
        </div>
      </div>
    </div>
  `;

  const badgeBtnStyle = 'cursor:pointer;border:1px solid var(--line);background:transparent;color:inherit;padding:6px 10px;border-radius:999px;';

  const advanceBtnHtml = (!suppressActionButtons && showAdvancePaymentAction)
    ? `
      <button
        type="button"
        class="pill pill-info"
        style="${badgeBtnStyle}"
        data-ts-action="advance-payment"
        title="${enc('Only the outstanding unpaid difference will be advanced.')}"
      >
        Advance outstanding adjustment
      </button>
    `
    : '';

  const unadvanceBtnHtml = (!suppressActionButtons && showUnadvancePaymentAction)
    ? `
      <button
        type="button"
        class="pill pill-info"
        style="${badgeBtnStyle}"
        data-ts-action="unadvance-payment"
        title="${enc('Cancel Advance Pay for this timesheet before batching.')}"
      >
        Cancel Advance Pay
      </button>
    `
    : '';

  const snoozeBtnHtml = (!suppressActionButtons && showSnoozePaymentAction)
    ? `
      <button
        type="button"
        class="pill pill-info"
        style="${badgeBtnStyle}"
        data-ts-action="${payStateIsSnoozed ? 'manage-snooze-payment' : 'snooze-payment'}"
        title="${enc(payStateIsSnoozed ? 'Manage the current payment snooze for this timesheet.' : 'Snooze this timesheet payment.')}"
      >
        ${enc(payStateIsSnoozed ? 'Manage snooze' : 'Snooze payment')}
      </button>
    `
    : '';

  const paymentActionButtonsHtml = [advanceBtnHtml, unadvanceBtnHtml, snoozeBtnHtml]
    .filter(Boolean)
    .join('');

  const actionsHtml = (() => {
    if (suppressActionButtons) return '';

    const btns = [];

    if (paymentActionButtonsHtml) btns.push(paymentActionButtonsHtml);

    const canAllowQrAgain   = !!actionFlags.can_allow_qr_again;
    const canAllowElecAgain = !!actionFlags.can_allow_electronic_again;
    const canSwitchToManual = !!actionFlags.can_switch_to_manual;
    const canConvertQrToManualOnly = !!actionFlags.can_convert_qr_to_manual_only;
    const candidateOfficeRouteUiReady = candidateOfficeProjectionUiReady &&
      window.CloudTMSCandidateOfficeBridge.capabilities.permissions.change_route === true;

    const weekId =
      details.contract_week_id ||
      cw.id ||
      row.contract_week_id ||
      null;

    const isWeekly = (sheetScope === 'WEEKLY');
    const isDaily  = (sheetScope === 'DAILY');

    // Source-authority expenses use only the explicit server-owned action.
    // All other Weekly and Daily rows retain the existing additional-timesheet journey.
    const weeklyAdditionalTimesheetAllowed = weeklySourcePresentationVm?.mount === true
      ? weeklySourcePresentationVm.add_additional_expense_timesheet_allowed === true
      : true;
    if (hasAssignedCandidate && isWeekly && weekId) {
      if (weeklyAdditionalTimesheetAllowed) {
        const title = clientSourceAuthorityOverview
          ? 'Create a separate expense Timesheet without changing the client-provided work hours.'
          : 'Create an additional manual adjustment timesheet for this week (use for expenses or corrections without altering the original sheet).';
        btns.push(`
          <button type="button" class="pill pill-info" style="${badgeBtnStyle}" data-ts-action="add-additional-manual" title="${enc(title)}">
            ${clientSourceAuthorityOverview ? 'Add additional expense timesheet' : 'Add additional manual timesheet'}
          </button>
        `);
      }
    }
    if (hasAssignedCandidate && isDaily && tsId) {
      const title = 'Create an additional manual daily timesheet for this shift (use for expenses or corrections without altering the original sheet).';
      btns.push(`
        <button type="button" class="pill pill-info" style="${badgeBtnStyle}" data-ts-action="add-additional-manual" title="${enc(title)}">
          Add additional manual timesheet
        </button>
      `);
    }

    const isPlannedWeeklyManual =
      isWeekly &&
      !tsId &&
      !!weekId &&
      !locked &&
      (cwModeSnapshot === 'MANUAL');

    const isPlannedWeeklyElectronic =
      isWeekly &&
      !tsId &&
      !!weekId &&
      !locked &&
      (cwModeSnapshot === 'ELECTRONIC');

    const isWeeklyElectronicWithTs =
      isWeekly &&
      !!tsId &&
      !locked &&
      (subModeEff === 'ELECTRONIC');

    const isDailyElectronicWithTs =
      isDaily &&
      !!tsId &&
      !locked &&
      (subModeEff === 'ELECTRONIC');

    // ✅ Adjustment and lifecycle safety: never mutate the source route while the
    // timesheet is authorised, archived, or its permission surface is not trusted.
    if (hasAssignedCandidate && !isAdjustment && !sourceTimesheetActionsBlocked) {

      if (!importAuthoritative && (isPlannedWeeklyElectronic || (candidateOfficeRouteUiReady && canSwitchToManual && (isWeeklyElectronicWithTs || isDailyElectronicWithTs)))) {
        const title = 'Switch this timesheet into admin-managed Manual mode so you can adjust hours/schedule internally.';
        btns.push(`
          <button type="button" class="pill pill-info" style="${badgeBtnStyle}" data-ts-action="switch-manual" title="${enc(title)}">
            Convert to Manual
          </button>
        `);
      }

      if (!importAuthoritative && isPlannedWeeklyManual) {
        const title = 'Switch this planned manual week back to Electronic (read-only) behaviour.';
        btns.push(`
          <button type="button" class="pill pill-info" style="${badgeBtnStyle}" data-ts-action="switch-electronic-planned" title="${enc(title)}">
            Switch week back to electronic
          </button>
        `);
      }

      // A live Candidate QR workflow may be converted only when the canonical
      // Office action contract expressly permits the manual-only transition.
      if (candidateOfficeRouteUiReady && tsId && !locked && canConvertQrToManualOnly) {
        const title = 'Convert to Manual (candidate submission disabled). Admin will manage hours and evidence manually from this point.';
        btns.push(`
          <button type="button" class="pill pill-info" style="${badgeBtnStyle}" data-ts-action="qr-convert-manual-only" title="${enc(title)}">
            Convert to Manual
          </button>
        `);
      }

      if (candidateOfficeRouteUiReady && !importAuthoritative && tsId && !locked && isManualOnly && canAllowQrAgain && !canAllowElecAgain) {
        const title = 'Make this timesheet eligible for QR submission again. A QR Pack is created later by the normal Candidate workflow when the server has the required current submission facts.';
        btns.push(`
          <button type="button" class="pill pill-info" style="${badgeBtnStyle}" data-ts-action="allow-qr-again" title="${enc(title)}">
            Enable QR submission
          </button>
        `);
      }

      if (candidateOfficeRouteUiReady && !importAuthoritative && tsId && !locked && isManualOnly && canAllowElecAgain) {
        const title = 'Make this Manual timesheet eligible for Electronic submission again. This is available only where the backend confirms Electronic eligibility.';
        btns.push(`
          <button type="button" class="pill pill-info" style="${badgeBtnStyle}" data-ts-action="allow-electronic-again" title="${enc(title)}">
            Enable Electronic Submission
          </button>
        `);
      }
    }

    const FOOTER_ONLY_ACTION_RE =
      /data-ts-action="(?:delete-permanent|delete-manual-reopen)"/i;

    const safeBtns = btns.filter(html => !FOOTER_ONLY_ACTION_RE.test(String(html || '')));

    if (!safeBtns.length) return candidateOfficeProjectionUiReady ? '' : `<span class="mini">No actions available.</span>`;
    return `<div style="display:flex;flex-wrap:wrap;gap:8px;">${safeBtns.join('')}</div>`;
  })();

  // ✅ NEW: delete-policy badge (backend-authoritative; does not change existing route text)
  const dp =
    (window.modalCtx && window.modalCtx.timesheetDeletePreview && typeof window.modalCtx.timesheetDeletePreview === 'object')
      ? window.modalCtx.timesheetDeletePreview
      : null;

  const dpKind = String((dp && dp.kind) ? dp.kind : '').toUpperCase();
  const dpEligible = (dp && typeof dp.eligible === 'boolean') ? dp.eligible : false;
  const dpDecision = String((dp && dp.decision) ? dp.decision : '').toUpperCase();
  const dpArchiveRequired = !!(
    dpDecision === 'ARCHIVE_REQUIRED' ||
    boolish(dp && dp.archive_required)
  );

  const deletePolicyBadgeHtml = (() => {
    if (manualAdditionalForOverview && dpKind === 'WEEKLY_CHAIN_DELETE_PARENT') {
      const t = expenseOnlyForOverview
        ? 'Delete preview is unsafe for this expense because it is returning a parent-chain delete. Refresh the delete preview before deleting.'
        : 'Delete preview is unsafe for this manual additional adjustment because it is returning a parent-chain delete. Refresh the delete preview before deleting.';
      return `<span class="pill pill-bad" style="font-weight:600;" title="${enc(t)}">${enc(expenseOnlyForOverview ? 'Expense – delete preview unsafe' : 'Manual adjustment – delete preview unsafe')}</span>`;
    }

    if (manualAdditionalForOverview && dpKind === 'WEEKLY_MANUAL_ADJUSTMENT_DELETE') {
      if (dpEligible) {
        const t = expenseOnlyForOverview
          ? 'This expense can be deleted without deleting the source timesheet.'
          : 'This manual additional adjustment can be deleted without deleting the source/parent timesheet.';
        return `<span class="pill pill-ok" style="font-weight:600;" title="${enc(t)}">${enc(expenseOnlyForOverview ? 'Expense – Can Delete' : 'Manual adjustment – Can Delete')}</span>`;
      }

      const reasons =
        (dp && Array.isArray(dp.blocked_reasons) && dp.blocked_reasons.length)
          ? dp.blocked_reasons
              .map(r => (r && r.message) ? String(r.message) : '')
              .filter(Boolean)
              .join(' ')
          : '';

      const t = reasons
        ? `Can't delete yet. ${reasons}`
        : (expenseOnlyForOverview
            ? "Can't delete yet. This expense is locked, invoiced, paid, or otherwise not eligible."
            : "Can't delete yet. This manual additional adjustment is locked, invoiced, paid, or otherwise not eligible.");

      return `<span class="pill pill-bad" style="font-weight:600;" title="${enc(t)}">${enc(expenseOnlyForOverview ? "Expense – Can't delete yet" : "Manual adjustment – Can't delete yet")}</span>`;
    }

    if (dpKind === 'IMPORT_CHILD_ADJUSTMENT') {
      const t = 'This is an NHSP/HR child adjustment and cannot be deleted directly. Delete must be performed via the parent timesheet (if eligible).';
      return `<span class="pill pill-bad" style="font-weight:600;" title="${enc(t)}">${enc("Adjustment – Can't Delete")}</span>`;
    }

    if (dpKind === 'WEEKLY_CHAIN_DELETE_PARENT') {
      const weeklyParentLabel = isAdjustment ? 'Parent Adjustment' : 'Weekly timesheet';

      if (dpArchiveRequired) {
        const t = isAdjustment
          ? 'This parent adjustment has retained financial history and cannot be permanently deleted. Use Archive instead.'
          : 'This weekly timesheet has retained financial history and cannot be permanently deleted. Use Archive instead.';
        return `<span class="pill pill-warn" style="font-weight:600;" title="${enc(t)}">${enc(`${weeklyParentLabel} – Archive required`)}</span>`;
      }

      if (dpEligible) {
        const t = isAdjustment
          ? 'This is an adjustment parent and can be deleted when the complete weekly chain is safe.'
          : 'This weekly timesheet can be deleted when the complete weekly chain is safe.';
        return `<span class="pill pill-ok" style="font-weight:600;" title="${enc(t)}">${enc(`${weeklyParentLabel} – Can Delete`)}</span>`;
      }

      const reasonRows = [
        ...(dp && Array.isArray(dp.blocked_reasons) ? dp.blocked_reasons : []),
        ...(dp && Array.isArray(dp.blockers) ? dp.blockers : [])
      ];
      const reasons = Array.from(new Set(
        reasonRows
          .map(r => (r && r.message) ? String(r.message).trim() : '')
          .filter(Boolean)
      )).join(' ');

      const t = reasons
        ? `Can't delete yet. ${reasons}`
        : (isAdjustment
            ? "Can't delete yet. This adjustment parent or a related row is locked, invoiced, paid, or otherwise not eligible."
            : "Can't delete yet. This weekly timesheet or a related row is locked, invoiced, paid, or otherwise not eligible.");

      return `<span class="pill pill-bad" style="font-weight:600;" title="${enc(t)}">${enc(`${weeklyParentLabel} – Can't delete yet`)}</span>`;
    }

    return '';
  })();

  const deletePolicyBadgeHtmlForDisplay = openingDetailsPending ? '' : deletePolicyBadgeHtml;

  const candidateOfficeIdentityRow = tsId ? {
    ...baseSummary,
    ...row,
    candidate_office_projection_not_applicable:
      details.candidate_office_projection_not_applicable === true ||
      details.effective?.candidate_office_projection_not_applicable === true ||
      details.timesheet?.candidate_office_projection_not_applicable === true ||
      details.contract_week?.candidate_office_projection_not_applicable === true ||
      row.candidate_office_projection_not_applicable === true ||
      baseSummary.candidate_office_projection_not_applicable === true,
    timesheet_id: tsId,
    current_timesheet_id: tsId,
    contract_week_id: details.contract_week_id || cw.id || row.contract_week_id || null,
    expected_row_signature:
      row.backend_row_signature || row.mutation_row_signature || row.row_signature ||
      details.backend_row_signature || details.mutation_row_signature || details.row_signature ||
      baseSummary.backend_row_signature || baseSummary.mutation_row_signature || baseSummary.row_signature || null
  } : null;
  const candidateOfficeSlot = (variant) => (
    candidateOfficeIdentityRow &&
    typeof window !== 'undefined' && window.CloudTMSCandidateOfficeBridge &&
    typeof window.CloudTMSCandidateOfficeBridge.slotHtml === 'function'
  ) ? window.CloudTMSCandidateOfficeBridge.slotHtml('SIMPLE_TIMESHEET', candidateOfficeIdentityRow, { variant }) : '';
  const candidateStageHtml = candidateOfficeSlot('stage');
  const candidateOverviewHtml = candidateOfficeSlot('overview');
  const candidateActionsHtml = candidateOfficeSlot('actions');

  const routeActionsRowHtml = (suppressActionButtons || openingDetailsPending || (!actionsHtml && !candidateActionsHtml))
    ? ''
    : `
      <div class="row" data-view-only="true">
        <label>Actions</label>
        <div class="controls" style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;">
          ${actionsHtml}
          ${candidateActionsHtml}
        </div>
      </div>
    `;

  const routeHtml = `
    <div class="card" style="margin-top:10px;">
      ${stageBadgesForDisplay.length ? `<div class="row">
        <label>Stage</label>
        <div class="controls" style="display:flex;flex-wrap:wrap;gap:6px;">
          ${stageBadgesForDisplay.join('')}
        </div>
      </div>` : ''}

      <div class="row">
        <label>${dailyStatusForOverview ? 'Timesheet type' : 'Route'}</label>
        <div class="controls" style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;">
          ${deletePolicyBadgeHtmlForDisplay}
          <span class="pill ${routePillClass}" style="font-weight:600;" ${routeTitleForDisplay ? `title="${enc(routeTitleForDisplay)}"` : ''}>${enc(routeLabelForDisplay)}</span>
          <span class="pill ${scopePillClass}" style="font-weight:600;">${enc(scopeLabel)}</span>
        </div>
      </div>

      ${dailyStatusForOverview ? '<div class="row" data-view-only="true"><label>Daily Timesheet</label><div class="controls bpay-next-daily-notice" data-daily-processing hidden></div></div>' : ''}
      ${candidateOverviewHtml ? `<div data-view-only="true">${candidateOverviewHtml}</div>` : ''}

      ${routeActionsRowHtml}
    </div>
  `;

  GE();

  return `
    <div class="tabc">
      ${headerHtml}
      ${routeHtml}
    </div>
  `;
}


async function handleHrRotaFileDrop(file) {
  const summaryEl = document.getElementById('hrRotaImportSummary');
  if (summaryEl) {
    summaryEl.textContent = 'Preparing HR rota daily import…';
  }

  try {
    // Ensure modalCtx/importsState exist
    window.modalCtx = window.modalCtx || {};
    window.modalCtx.importsState = window.modalCtx.importsState || {};
    const st = window.modalCtx.importsState;

    // 0) Always ask user to confirm the client (HealthRoster clients only)
    let clientId = '';
    let clientName = '';

    {
      let items = [];
      try {
        const res = await authFetch(API('/api/healthroster/autoprocess/clients'));
        const text = await res.text();
        if (!res.ok) throw new Error(text || `Failed to load HealthRoster clients (${res.status})`);
        const json = text ? JSON.parse(text) : {};
        items = Array.isArray(json.items) ? json.items : [];
      } catch (e) {
        console.error('[IMPORTS][HR_ROTA] failed to load clients', e);
        await showImportFlowNotice(e?.message || 'Failed to load HealthRoster clients for daily import.', {
          title: 'HealthRoster clients unavailable'
        });
        return;
      }

      if (!items.length) {
        await showImportFlowNotice('No HealthRoster Daily clients are configured.', {
          title: 'No eligible clients'
        });
        return;
      }

      const enc = (typeof escapeHtml === 'function')
        ? escapeHtml
        : (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({
            '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
          }[c]));

      const defaultId = st.hrRotaClientId ? String(st.hrRotaClientId).trim() : '';
      const optionsHtml = items.map((c) => {
        const id = String(c.client_id || '').trim();
        const name = String(c.client_name || '').trim();
        const sel = (defaultId && id === defaultId) ? ' selected' : '';
        return `<option value="${enc(id)}"${sel}>${enc(name || id)}</option>`;
      }).join('');

      const picked = await new Promise((resolve) => {
        let done = false;
        const resolveOnce = (v) => { if (done) return; done = true; resolve(v); };

        if (typeof showModal !== 'function') {
          // Fallback: if showModal missing, just resolve null
          resolveOnce(null);
          return;
        }

        showModal(
          'Select HealthRoster client (daily validation)',
          [{ key: 'main', label: 'Select client' }],
          (k) => {
            if (k !== 'main') return '';
            return `
              <div style="display:block;">
                <div class="row">
                  <label>Client</label>
                  <div class="controls">
                    <select class="input" id="hrRotaClientSelect">
                      <option value="">-- choose a client --</option>
                      ${optionsHtml}
                    </select>
                  </div>
                </div>
                <div class="hint" style="grid-column:1/-1">
                  This client will be used for parsing and validating this HealthRoster daily export.
                  Close this dialog to cancel the import.
                </div>
              </div>
            `;
          },
          async () => {
            const sel = document.getElementById('hrRotaClientSelect');
            if (!sel || !sel.value) {
              await showImportFlowNotice('Please select a client to continue.', { title: 'Choose a client' });
              return false; // keep modal open
            }
            const cid = String(sel.value || '').trim();
            const cname = (sel.options && sel.selectedIndex >= 0)
              ? String(sel.options[sel.selectedIndex].textContent || '').trim()
              : '';

            resolveOnce({ clientId: cid, clientName: cname });
            return true; // close modal
          },
          false,
          null,
          {
            kind: 'hr-rota-client-picker',
            noParentGate: true,
            onDismiss: () => resolveOnce(null),
            showSave: true
          }
        );
      });

      if (!picked || !picked.clientId) {
        throw new Error('Daily import cancelled (no client selected).');
      }

      clientId = String(picked.clientId).trim();
      clientName = String(picked.clientName || '').trim();

      st.hrRotaClientId = clientId;
      st.hrRotaClientName = clientName;
    }

    if (summaryEl) {
      summaryEl.textContent =
        `Client: ${clientName || clientId} — uploading HR rota daily file to storage…`;
    }

    // 1) Upload file to R2
    const { fileKey, filename } = await uploadImportFileToR2(file);

    if (summaryEl) {
      summaryEl.textContent = 'Registering HR rota daily import and parsing workbook…';
    }

    // 2) Call parse endpoint with JSON
    const res = await authFetch(API('/api/imports/hr-rota/parse'), {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        file_r2_key: fileKey,
        original_name: filename,
        client_id: clientId,
        tz_assumption: 'Europe/London'
      })
    });
    const text = await res.text();
    if (!res.ok) {
      throw new Error(text || `HR rota daily import upload failed (${res.status})`);
    }

    let parsed;
    try { parsed = text ? JSON.parse(text) : {}; } catch { parsed = {}; }
    const importId = parsed.import_id || parsed.id || null;
    if (!importId) {
      throw new Error('HR rota daily import did not return an import_id.');
    }

    if (summaryEl) {
      summaryEl.textContent =
        `File uploaded. Loading HR rota classification for import ${importId}…`;
    }

    // 3) Fetch preview / classification
    const previewRes  = await authFetch(API(`/api/imports/hr-rota/${encodeURIComponent(importId)}/preview`));
    const previewText = await previewRes.text();
    if (!previewRes.ok) {
      throw new Error(previewText || `HR rota daily preview failed (${previewRes.status})`);
    }

    let summaryState;
    try { summaryState = previewText ? JSON.parse(previewText) : {}; } catch { summaryState = {}; }

    // 4) Persist into modalCtx and render summary modal
    window.modalCtx = window.modalCtx || {};
    window.modalCtx.importsState = window.modalCtx.importsState || {};
    window.modalCtx.importsState.hrRota = {
      import_id: importId,
      summary: summaryState
    };

    const total =
      (summaryState.summary && typeof summaryState.summary.total_rows === 'number')
        ? summaryState.summary.total_rows
        : Array.isArray(summaryState.rows) ? summaryState.rows.length : 0;

    if (summaryEl) {
      summaryEl.textContent =
        `Import ${importId} (${clientName || clientId}): ${total} rows parsed.`;
    }

    if (typeof renderImportSummaryModal === 'function') {
      renderImportSummaryModal('HR_ROTA_DAILY', summaryState);
    } else {
      console.warn('[IMPORTS] renderImportSummaryModal is not defined; HR rota summary not shown.');
    }
  } catch (err) {
    console.error('[IMPORTS][HR_ROTA] handleHrRotaFileDrop failed', err);
    if (summaryEl) {
      summaryEl.textContent =
        `HR rota daily import failed: ${err?.message || 'Unknown error'}`;
    }
    await showImportFlowNotice(err?.message || 'HealthRoster Daily import failed.', {
      title: 'HealthRoster Daily import failed'
    });
  }
}


async function postHrRotaResolveMappings(importId, payload) {
  const LOG = (typeof window.__LOG_IMPORTS === 'boolean') ? window.__LOG_IMPORTS : true;
  const L   = (...a) => { if (LOG) console.log('[IMPORTS][HR_ROTA][RESOLVE]', ...a); };

  if (!importId) {
    throw new Error('Missing importId for postHrRotaResolveMappings');
  }

  const body = payload || {};

  const candidate_mappings = Array.isArray(body.candidate_mappings) ? body.candidate_mappings : [];
  const client_aliases     = Array.isArray(body.client_aliases)     ? body.client_aliases     : [];

  // ✅ optional timesheet target mappings (hr_row_id → selected target id)
  const role_mappings =
    Array.isArray(body.role_mappings) ? body.role_mappings :
    Array.isArray(body.timesheet_target_mappings) ? body.timesheet_target_mappings :
    Array.isArray(body.roleMappings) ? body.roleMappings :
    [];

  // ✅ NEW: durable grade → role mappings (client_id is derived server-side from the import)
  const grade_role_mappings =
    Array.isArray(body.grade_role_mappings) ? body.grade_role_mappings :
    Array.isArray(body.gradeRoleMappings) ? body.gradeRoleMappings :
    [];

  if (!candidate_mappings.length && !client_aliases.length && !role_mappings.length && !grade_role_mappings.length) {
    L('no mappings to send; returning early', { importId });
    return {
      ok: true,
      candidate_mappings_applied: 0,
      client_aliases_applied: 0,
      role_mappings_applied: 0,
      grade_role_mappings_applied: 0
    };
  }

  if (typeof authFetch !== 'function' || typeof API !== 'function') {
    throw new Error('authFetch/API helper missing in postHrRotaResolveMappings');
  }

  const url = `/api/imports/hr-rota/${encodeURIComponent(importId)}/resolve-conflicts`;

  const aliasDebug = client_aliases.map(a => ({
    client_id: a?.client_id || null,
    hr_row_ids: Array.isArray(a?.hr_row_ids) ? a.hr_row_ids : [],
    hospital_norm: a?.hospital_norm || null
  }));

  const roleDebug = role_mappings.map(r => ({
    hr_row_id: r?.hr_row_id || null,
    target_id: r?.target_id || r?.timesheet_target_id || r?.timesheet_id || null
  }));

  const gradeDebug = grade_role_mappings.map(g => ({
    incoming_grade_norm: g?.incoming_grade_norm || g?.grade_norm || g?.grade || null,
    role_code: g?.role_code || g?.role || null,
    band_norm: g?.band_norm || g?.band || null
  }));

  L('posting HR rota resolve-conflicts', {
    importId,
    url: API(url),
    candidate_mappings_count: candidate_mappings.length,
    client_aliases_count: client_aliases.length,
    role_mappings_count: role_mappings.length,
    grade_role_mappings_count: grade_role_mappings.length,
    client_aliases_debug: aliasDebug,
    role_mappings_debug: roleDebug,
    grade_role_mappings_debug: gradeDebug
  });

  // ✅ Only include keys that exist (tight payload, matches new backend contract)
  const postBody = {};
  if (candidate_mappings.length) postBody.candidate_mappings = candidate_mappings;
  if (client_aliases.length)     postBody.client_aliases = client_aliases;
  if (role_mappings.length)      postBody.role_mappings = role_mappings;
  if (grade_role_mappings.length) postBody.grade_role_mappings = grade_role_mappings;

  const res = await authFetch(API(url), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(postBody)
  });

  const text = await res.text().catch(() => '');
  if (!res.ok) {
    const msg = text || `HR rota resolve-conflicts failed (${res.status})`;
    throw new Error(msg);
  }

  let json = {};
  try { json = text ? JSON.parse(text) : {}; } catch {}

  L('resolve-conflicts OK', json);
  return json;
}


async function applyHrRotaValidation(importId, email_actions = [], invalidation_actions = []) {
  const LOG = (typeof window.__LOG_IMPORTS === 'boolean') ? window.__LOG_IMPORTS : true;
  const L   = (...a) => { if (LOG) console.log('[IMPORTS][HR_ROTA][APPLY]', ...a); };

  if (!importId) {
    throw new Error('Missing importId for applyHrRotaValidation');
  }

  if (typeof authFetch !== 'function' || typeof API !== 'function') {
    throw new Error('authFetch/API helper missing in applyHrRotaValidation');
  }

  const emailActions = Array.isArray(email_actions) ? email_actions : [];
  const invalidActions = Array.isArray(invalidation_actions) ? invalidation_actions : [];

  // Minimal hygiene: remove completely empty objects
  const cleanedEmailActions = emailActions
    .filter(x => x && typeof x === 'object' && !Array.isArray(x))
    .map(x => ({
      timesheet_id: (x.timesheet_id != null) ? String(x.timesheet_id).trim() : null,
      issue_fingerprint: (x.issue_fingerprint != null) ? String(x.issue_fingerprint).trim() : null,
      reason_code: (x.reason_code != null) ? String(x.reason_code).trim() : null,
      hr_row_id: (x.hr_row_id != null) ? String(x.hr_row_id).trim() : null,
      staff_norm: (x.staff_norm != null) ? String(x.staff_norm).trim() : null,
      hospital_norm: (x.hospital_norm != null) ? String(x.hospital_norm).trim() : null,
      work_date: (x.work_date != null) ? String(x.work_date).trim() : null,
      alternative_email: (x.alternative_email != null && String(x.alternative_email).trim())
        ? String(x.alternative_email).trim()
        : null
    }))
    .filter(x => !!x.timesheet_id && !!x.issue_fingerprint);

  const cleanedInvalidActions = invalidActions
    .filter(x => x && typeof x === 'object' && !Array.isArray(x))
    .map(x => ({
      timesheet_id: (x.timesheet_id != null) ? String(x.timesheet_id).trim() : null,
      comparison_key: (x.comparison_key != null) ? String(x.comparison_key).trim() : null,
      invalidate: (x.invalidate === false || String(x.invalidate).toLowerCase() === 'false') ? false : true
    }))
    .filter(x => !!x.timesheet_id && !!x.comparison_key);

  const url = `/api/imports/hr-rota/${encodeURIComponent(importId)}/apply`;

  L('posting apply', {
    importId,
    url: API(url),
    email_actions_count: cleanedEmailActions.length,
    invalidation_actions_count: cleanedInvalidActions.length
  });

  const res = await authFetch(API(url), {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      email_actions: cleanedEmailActions,
      invalidation_actions: cleanedInvalidActions
    })
  });

  const text = await res.text().catch(() => '');
  if (!res.ok) {
    throw new Error(text || `HR rota daily apply failed (${res.status})`);
  }

  let json = {};
  try { json = text ? JSON.parse(text) : {}; } catch {}

  L('apply OK', json);
  return json;
}

async function switchContractWeekToManual(weekId) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][CW-SWITCH-MANUAL]');
  GC('switchContractWeekToManual');

  if (!weekId) {
    GE();
    throw new Error('switchContractWeekToManual: weekId is required');
  }

  const encId = encodeURIComponent(weekId);
  const url   = API(`/api/contract-weeks/${encId}/switch-mode`);

  L('REQUEST', { url, weekId });

  let res, text;
  try {
    res  = await authFetch(url, { method: 'POST' });
    text = await res.text();
  } catch (err) {
    L('network error', err);
    GE();
    throw err;
  }

  if (!res.ok) {
    L('server error', { status: res.status, bodyPreview: text.slice(0, 400) });
    GE();
    throw new Error(text || `Failed to switch contract week ${weekId} to manual`);
  }

  let json = {};
  try {
    json = text ? JSON.parse(text) : {};
  } catch (err) {
    L('parse error', err);
  }

  L('RESULT', json);
  GE();
  return json;
}





function isUnfundedSourceAuthoritativeRootFinance(rowLike, detailsLike) {
  const row = rowLike && typeof rowLike === 'object' ? rowLike : {};
  const details = detailsLike && typeof detailsLike === 'object' ? detailsLike : {};
  const tsfin = details.tsfin && typeof details.tsfin === 'object' ? details.tsfin : {};
  const upper = (value) => String(value == null ? '' : value).trim().toUpperCase();
  const truthy = (value) => value === true || value === 1 || upper(value) === 'TRUE';
  const route = upper(row.route_type || details.route_type || details.timesheet?.route_type);
  const basis = upper(tsfin.basis || row.basis || details.timesheet?.basis);
  const family = upper(row.route_family || details.route_family || details.timesheet?.route_family);
  const noTimesheetRequired = truthy(details.effective?.client_no_timesheet_required ?? row.client_no_timesheet_required ?? details.client_no_timesheet_required ?? details.contract_week?.no_timesheet_required);
  const adjustment = truthy(details.is_adjustment) || truthy(row.is_adjustment) || truthy(details.timesheet?.is_adjustment) || Number(details.additional_seq ?? row.additional_seq ?? 0) > 0 || route.includes('ADJUSTMENT');
  const sourceRoot = !adjustment && (
    truthy(row.is_import_authoritative) || truthy(details.is_import_authoritative) ||
    family === 'IMPORT_AUTHORITATIVE' || route === 'WEEKLY_NHSP' || basis === 'NHSP' ||
    basis === 'HEALTHROSTER_SELF_BILL' || (route === 'WEEKLY_HEALTHROSTER' && noTimesheetRequired)
  );
  // A candidate-submitted Timesheet can exist before its source-derived TSFIN row.
  // The Timesheet ID alone is not financial authority.
  return sourceRoot && !tsfin.id;
}

function renderTimesheetFinanceTab(ctx) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][FINANCE]');
  const { row, details, related, state } = normaliseTimesheetCtx(ctx);

  GC('render');
  const ts    = details.timesheet || {};
  const tsfin = details.tsfin     || {};
  const enc   = escapeHtml;

  // Candidate-entered hours on a source-authoritative root are comparison
  // evidence. Until a current financial snapshot exists, there is no payable
  // bucket or monetary preview to show in this tab.
  if (isUnfundedSourceAuthoritativeRootFinance(row, details)) {
    GE();
    return '<div class="tabc"><div class="card"><strong>Final source hours not yet available</strong><p class="mini">The candidate\'s submitted hours are available in Lines as evidence. Pay, charge and margin will appear when final source hours have been imported and processed.</p></div></div>';
  }

  const fmtMoney = (v) =>
    isNaN(Number(v)) ? '—' : `£${(Math.round(Number(v) * 100) / 100).toFixed(2)}`;

  const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const nOrNull = (v) => (v != null && Number.isFinite(Number(v))) ? Number(v) : null;
  const trimStr = (v) => String(v == null ? '' : v).trim();
  const parseMaybeJson = (value) => {
    if (value && typeof value === 'object') return value;
    if (typeof value === 'string') {
      try {
        const parsed = JSON.parse(value);
        return (parsed && typeof parsed === 'object') ? parsed : null;
      } catch {
        return null;
      }
    }
    return null;
  };
  const unwrapPreviewPayload = (value) => {
    const src = (value && typeof value === 'object') ? value : null;
    if (!src) return null;
    if (src.ok === true && src.data && typeof src.data === 'object') return src.data;
    return src;
  };
  const extractAuthoritativeTotals = (payloadLike) => {
    const payload = unwrapPreviewPayload(payloadLike);
    if (!payload || typeof payload !== 'object') return null;
    const candidates = [
      payload,
      (payload.totals && typeof payload.totals === 'object') ? payload.totals : null,
      (payload.finance && typeof payload.finance === 'object') ? payload.finance : null,
      (payload.finance && payload.finance.totals && typeof payload.finance.totals === 'object') ? payload.finance.totals : null,
      (payload.snapshot && typeof payload.snapshot === 'object') ? payload.snapshot : null
    ].filter(Boolean);
    for (const candidate of candidates) {
      const pay = nOrNull(candidate.total_pay_ex_vat);
      const charge = nOrNull(candidate.total_charge_ex_vat);
      const margin = nOrNull(candidate.margin_ex_vat);
      if (pay != null && charge != null && margin != null) {
        return {
          total_pay_ex_vat: pay,
          total_charge_ex_vat: charge,
          margin_ex_vat: margin
        };
      }
    }
    return null;
  };
  const extractPayMethod = (payloadLike, fallback = '') => {
    const payload = unwrapPreviewPayload(payloadLike);
    const raw =
      payload?.pay_method ??
      payload?.payMethod ??
      payload?.finance?.pay_method ??
      payload?.finance?.payMethod ??
      payload?.snapshot?.pay_method ??
      payload?.meta?.pay_method ??
      fallback;
    return trimStr(raw);
  };
  const extractRateSourceHint = (payloadLike) => {
    const payload = unwrapPreviewPayload(payloadLike);
    if (!payload || typeof payload !== 'object') return '';
    const explicit = trimStr(
      payload.rate_source_hint ??
      payload.finance?.rate_source_hint ??
      payload.meta?.rate_source_hint ??
      payload.source_hint ??
      ''
    );
    if (explicit) return explicit;
    const refs = parseMaybeJson(payload.rate_source_refs_json) || parseMaybeJson(payload.finance?.rate_source_refs_json) || parseMaybeJson(payload.snapshot?.rate_source_refs_json);
    if (!refs) return '';
    const pickFirst = (...vals) => {
      for (const value of vals) {
        const s = trimStr(value);
        if (s) return s;
      }
      return '';
    };
    const paySourceKind = pickFirst(
      refs.pay_source_kind,
      refs.kind,
      refs.source_kind,
      refs.pay?.source_kind,
      refs.pay?.kind,
      refs.source?.pay_source_kind,
      refs.source?.kind,
      refs.source?.source_kind
    );
    const overrideId = pickFirst(
      refs.override_id,
      refs.pay_override_id,
      refs.pay?.override_id,
      refs.source?.override_id
    );
    const defaultId = pickFirst(
      refs.default_id,
      refs.pay_default_id,
      refs.pay?.default_id,
      refs.source?.default_id
    );
    const parts = [];
    if (paySourceKind) parts.push(`Pay source: ${paySourceKind}`);
    if (overrideId) parts.push(`Override ${overrideId}`);
    else if (defaultId) parts.push(`Default ${defaultId}`);
    return parts.join(' • ');
  };
  const renderDailySummaryTable = (title, totals, payMethod, rateSourceHint, note) => {
    if (!totals) {
      return `
        <div class="card" style="margin-top:10px;">
          <div class="row">
            <label>${enc(title)}</label>
            <div class="controls">
              <span class="mini">${enc(note || 'Finance unavailable.')}</span>
            </div>
          </div>
        </div>
      `;
    }
    return `
      <div class="card" style="margin-top:10px;">
        <div class="row">
          <label>${enc(title)}</label>
          <div class="controls">
            <table class="grid mini">
              <thead>
                <tr>
                  <th style="width:240px">Category</th>
                  <th style="width:160px">Value</th>
                </tr>
              </thead>
              <tbody>
                <tr><td>Pay (ex VAT)</td><td>${fmtMoney(totals.total_pay_ex_vat)}</td></tr>
                <tr><td>Charge (ex VAT)</td><td>${fmtMoney(totals.total_charge_ex_vat)}</td></tr>
                <tr><td>Margin (ex VAT)</td><td>${fmtMoney(totals.margin_ex_vat)}</td></tr>
                ${payMethod ? `<tr><td>Pay method</td><td>${enc(payMethod)}</td></tr>` : ''}
                ${rateSourceHint ? `<tr><td>Rate source</td><td>${enc(rateSourceHint)}</td></tr>` : ''}
              </tbody>
            </table>
            ${note ? `<div class="mini" style="margin-top:6px;color:rgba(255,255,255,0.7)">${enc(note)}</div>` : ''}
          </div>
        </div>
      </div>
    `;
  };

  const buildPaymentSummaryHtml = ({ includeTitle = true } = {}) => {
    const payState = (details && details.pay_state && typeof details.pay_state === 'object' && !Array.isArray(details.pay_state))
      ? details.pay_state
      : ((details && details.payState && typeof details.payState === 'object' && !Array.isArray(details.payState)) ? details.payState : null);

    if (!payState || payState.ok !== true) return '';

    const paidTotals = (payState.paid_totals && typeof payState.paid_totals === 'object' && !Array.isArray(payState.paid_totals))
      ? payState.paid_totals
      : null;
    const adjusted = (payState.adjusted && typeof payState.adjusted === 'object' && !Array.isArray(payState.adjusted))
      ? payState.adjusted
      : null;

    const readOwnMoney = (obj, key) => {
      if (!obj || typeof obj !== 'object' || !Object.prototype.hasOwnProperty.call(obj, key)) return null;
      const n = Number(obj[key]);
      return Number.isFinite(n) ? n : null;
    };

    const paidToDateExVat = readOwnMoney(paidTotals, 'paid_to_date_ex_vat');
    const outstandingExVatRaw = readOwnMoney(adjusted, 'outstanding_ex_vat');
    const reservedExVatRaw = readOwnMoney(adjusted, 'reserved_ex_vat');
    const netDeltaExVatRaw = readOwnMoney(adjusted, 'net_delta_ex_vat');

    if (paidToDateExVat == null || outstandingExVatRaw == null || netDeltaExVatRaw == null) {
      return '';
    }

    const reservedExVat = Math.max(reservedExVatRaw == null ? 0 : reservedExVatRaw, 0);
    const amountStillOwedExVat = Math.max(outstandingExVatRaw, 0);
    const amountOverpaidExVat = Math.abs(Math.min(netDeltaExVatRaw, 0));

    const rows = [
      ['Amount Paid', paidToDateExVat],
      ...(reservedExVat > 0 ? [['Payment Reserved', reservedExVat]] : []),
      ['Amount still owed', amountStillOwedExVat],
      ...(amountOverpaidExVat > 0 ? [['Amount Overpaid', amountOverpaidExVat]] : [])
    ];

    return `
      <div style="margin-top:10px;">
        ${includeTitle ? '<div class="mini" style="font-weight:700;margin-bottom:4px;">Payment Summary</div>' : ''}
        <table class="grid mini">
          <thead>
            <tr>
              <th style="width:240px">Payment item</th>
              <th style="width:160px">Pay (ex VAT)</th>
            </tr>
          </thead>
          <tbody>
            ${rows.map(([label, value]) => `<tr><td>${enc(label)}</td><td>${fmtMoney(value)}</td></tr>`).join('')}
          </tbody>
        </table>
      </div>
    `;
  };

  const sheetScope = String(details.sheet_scope || row.sheet_scope || ts.sheet_scope || '').toUpperCase();
  const subMode = String(ts.submission_mode || row.submission_mode || '').toUpperCase();
  const mc = window.modalCtx || {};
  const st = mc.timesheetState || state || {};
  const isDailyManual = (sheetScope === 'DAILY' && subMode === 'MANUAL');

  if (isDailyManual) {
    const previewState = (st.__dailyFinancePreview && typeof st.__dailyFinancePreview === 'object') ? st.__dailyFinancePreview : null;
    const previewPayload = (previewState?.data && typeof previewState.data === 'object') ? previewState.data : null;
    const previewTotals = extractAuthoritativeTotals(previewPayload);
    const previewPayMethod = extractPayMethod(previewPayload, '');
    const previewRateSourceHint = extractRateSourceHint(previewPayload);
    const previewStatus = trimStr(previewState?.status || '');
    const previewMessage = trimStr(previewState?.message || '');
    const previewNote = (() => {
      if (previewStatus === 'loading') return 'Refreshing daily finance preview…';
      if (previewStatus === 'invalid') return previewMessage || 'Fix the highlighted daily shift/break fields in Lines to refresh preview.';
      if (previewStatus === 'error') return previewMessage || 'Daily finance preview unavailable.';
      if (previewStatus === 'ready') return previewMessage || '';
      return 'No daily finance preview yet.';
    })();

    const savedTotals = {
      total_pay_ex_vat: nOrNull(tsfin.total_pay_ex_vat),
      total_charge_ex_vat: nOrNull(tsfin.total_charge_ex_vat),
      margin_ex_vat: nOrNull(tsfin.margin_ex_vat)
    };
    const savedTotalsComplete = (savedTotals.total_pay_ex_vat != null && savedTotals.total_charge_ex_vat != null && savedTotals.margin_ex_vat != null)
      ? savedTotals
      : null;
    const savedPayMethod = trimStr(tsfin.pay_method || ts.pay_method || '');
    const savedRateSourceHint = extractRateSourceHint({ snapshot: { rate_source_refs_json: tsfin.rate_source_refs_json || null } });

    GE();
    const paymentSummaryCardHtml = (() => {
      const html = buildPaymentSummaryHtml({ includeTitle: false });
      if (!html) return '';
      return `
        <div class="card" style="margin-top:10px;">
          <div class="row">
            <label>Payment Summary</label>
            <div class="controls">${html}</div>
          </div>
        </div>
      `;
    })();

    return `
      <div class="tabc">
        ${renderDailySummaryTable(
          'Saved snapshot',
          savedTotalsComplete,
          savedPayMethod,
          savedRateSourceHint,
          savedTotalsComplete ? '' : 'No saved finance totals available yet.'
        )}
        ${renderDailySummaryTable(
          'Current preview',
          previewTotals,
          previewPayMethod,
          previewRateSourceHint,
          previewNote
        )}
        ${paymentSummaryCardHtml}
      </div>
    `;
  }

  // ─────────────────────────────────────────────────────────────
  // ERNI-aware margin helpers (UI must not "recompute margin wrong")
  // - Prefer server-provided tsfin.margin_ex_vat where available
  // - For per-bucket display, compute pay-cost inc ERNI when policy says so
  // ─────────────────────────────────────────────────────────────
  const pctToMultiplier = (pctMaybe) => {
    let p = Number(pctMaybe);
    if (!Number.isFinite(p) || p <= 0) return 1;
    if (p > 1) p = p / 100;
    const m = 1 + p;
    return (Number.isFinite(m) && m > 0) ? m : 1;
  };

  const getErniCtxFromPolicy = (policyObj, payMethodUpper) => {
    const pol = (policyObj && typeof policyObj === 'object') ? policyObj : {};
    const applyTo = String(pol.apply_erni_to || 'PAYE_ONLY').toUpperCase();
    const erniPct = (pol.erni_pct != null) ? Number(pol.erni_pct) : NaN;

    const erniMult = pctToMultiplier(erniPct);
    const applies =
      (applyTo === 'ALL') ||
      (applyTo === 'PAYE_ONLY' && payMethodUpper === 'PAYE');

    return { applies: !!applies, erni_pct: Number.isFinite(erniPct) ? erniPct : null, erni_mult: erniMult };
  };

  const payMethodUpper = String(tsfin.pay_method || ts.pay_method || '').toUpperCase();
  const policySnap = tsfin.policy_snapshot_json || null;
  const erniCtx = getErniCtxFromPolicy(policySnap, payMethodUpper);

  const applyErniToPayEx = (payEx) => {
    const p = Number(payEx || 0);
    if (!Number.isFinite(p)) return 0;
    return erniCtx.applies ? (p * erniCtx.erni_mult) : p;
  };

  // ─────────────────────────────────────────────────────────────
  // Staged Expenses/Mileage (live preview before Save)
  // Source of truth for "live preview" = modal state (expensesDraft)
  // In view mode it matches TSFIN because normaliseTimesheetCtx seeds it from TSFIN.
  // ─────────────────────────────────────────────────────────────
  const expDraft = (st.expensesDraft && typeof st.expensesDraft === 'object')
    ? st.expensesDraft
    : {
        mileage_units: 0,
        travel_pay: 0, travel_charge: 0,
        accommodation_pay: 0, accommodation_charge: 0,
        other_pay: 0, other_charge: 0
      };

  const travelPay = round2(expDraft.travel_pay || 0);
  const travelChg = round2(expDraft.travel_charge || 0);
  const accomPay  = round2(expDraft.accommodation_pay || 0);
  const accomChg  = round2(expDraft.accommodation_charge || 0);
  const otherPay  = round2(expDraft.other_pay || 0);
  const otherChg  = round2(expDraft.other_charge || 0);

  const expensesPayLive   = round2(travelPay + accomPay + otherPay);
  const expensesChargeLive= round2(travelChg + accomChg + otherChg);
  const expensesMarginLive= round2(expensesChargeLive - expensesPayLive);

  const mileagePayRate    = (tsfin.mileage_pay_rate != null) ? Number(tsfin.mileage_pay_rate) : null;
  const mileageChargeRate = (tsfin.mileage_charge_rate != null) ? Number(tsfin.mileage_charge_rate) : null;

  const mileageRatesOk =
    Number.isFinite(mileagePayRate) &&
    Number.isFinite(mileageChargeRate) &&
    mileagePayRate > 0 &&
    mileageChargeRate > 0;

  const mileageUnitsLive  = Number(expDraft.mileage_units || 0) || 0;
  const mileagePayLive    = mileageRatesOk ? round2(mileageUnitsLive * mileagePayRate) : 0;
  const mileageChargeLive = mileageRatesOk ? round2(mileageUnitsLive * mileageChargeRate) : 0;
  const mileageMarginLive = round2(mileageChargeLive - mileagePayLive);

  // ─────────────────────────────────────────────────────────────
  // Core TSFIN-derived buckets (actual snapshot)
  // ─────────────────────────────────────────────────────────────
  const hours = {
    day:   Number(tsfin.hours_day   || 0),
    night: Number(tsfin.hours_night || 0),
    sat:   Number(tsfin.hours_sat   || 0),
    sun:   Number(tsfin.hours_sun   || 0),
    bh:    Number(tsfin.hours_bh    || 0)
  };

  const pay = {
    day:   tsfin.pay_day,
    night: tsfin.pay_night,
    sat:   tsfin.pay_sat,
    sun:   tsfin.pay_sun,
    bh:    tsfin.pay_bh
  };

  const chg = {
    day:   tsfin.charge_day,
    night: tsfin.charge_night,
    sat:   tsfin.charge_sat,
    sun:   tsfin.charge_sun,
    bh:    tsfin.charge_bh
  };

  const buckets = ['day','night','sat','sun','bh'];
  const bucketLabel = {
    day:  'Day',
    night:'Night',
    sat:  'Saturday',
    sun:  'Sunday',
    bh:   'Bank Holiday'
  };

  const computeStandardFromRates = ({ hoursObj, payObj, chgObj, erniApplies, erniMult }) => {
    let missing = false;
    let payExSum = 0;
    let chgExSum = 0;
    let marSum   = 0;

    for (const b of buckets) {
      const hrs = Number(hoursObj?.[b] || 0) || 0;
      const payR = (payObj?.[b] != null && Number.isFinite(Number(payObj[b]))) ? Number(payObj[b]) : null;
      const chgR = (chgObj?.[b] != null && Number.isFinite(Number(chgObj[b]))) ? Number(chgObj[b]) : null;

      if (hrs > 0 && (payR == null || chgR == null)) missing = true;

      const payEx = (payR != null) ? (hrs * payR) : 0;
      const chgEx = (chgR != null) ? (hrs * chgR) : 0;

      const payCost = erniApplies ? (payEx * (Number.isFinite(Number(erniMult)) ? Number(erniMult) : 1)) : payEx;
      const marEx   = chgEx - payCost;

      payExSum += payEx;
      chgExSum += chgEx;
      marSum   += marEx;
    }

    return {
      missingRates: !!missing,
      pay_ex_vat: round2(payExSum),
      charge_ex_vat: round2(chgExSum),
      margin_ex_vat: round2(marSum)
    };
  };

  const tsfinBucketRows = buckets.map(b => {
    const hrs   = hours[b] || 0;
    const payR  = pay[b] != null ? Number(pay[b]) : null;
    const chgR  = chg[b] != null ? Number(chg[b]) : null;

    const payEx = (payR != null) ? (hrs * payR) : null;
    const chgEx = (chgR != null) ? (hrs * chgR) : null;

    const payCostEx = (payEx != null) ? applyErniToPayEx(payEx) : null;
    const marEx = (payCostEx != null && chgEx != null) ? (chgEx - payCostEx) : null;

    return `
      <tr>
        <td>${bucketLabel[b]}</td>
        <td>${hrs || 0}</td>
        <td>${payR != null ? fmtMoney(payR) : '—'}</td>
        <td>${chgR != null ? fmtMoney(chgR) : '—'}</td>
        <td>${payEx != null ? fmtMoney(payEx) : '—'}</td>
        <td>${chgEx != null ? fmtMoney(chgEx) : '—'}</td>
        <td>${marEx != null ? fmtMoney(marEx) : '—'}</td>
      </tr>
    `;
  }).join('');

  let addUnits = tsfin.additional_units_json || {};
  if (typeof addUnits === 'string') {
    try { addUnits = JSON.parse(addUnits); } catch { addUnits = {}; }
  }
  if (!addUnits || typeof addUnits !== 'object') addUnits = {};

  const additionalRows = Object.entries(addUnits).map(([code, ex]) => {
    if (!ex || typeof ex !== 'object') return '';
    const bucketName = (ex.bucket_name || code || '').trim();
    const unitName   = (ex.unit_name || 'units').trim();
    const unitCount  = Number(ex.unit_count || 0) || 0;

    const payEx      = Number(ex.pay_ex_vat    || 0);
    const chgEx      = Number(ex.charge_ex_vat || 0);

    const hasServerMargin = (ex.margin_ex_vat != null && Number.isFinite(Number(ex.margin_ex_vat)));
    const marEx = hasServerMargin
      ? Number(ex.margin_ex_vat)
      : (chgEx - applyErniToPayEx(payEx));

    if (!unitCount && !payEx && !chgEx) return '';

    return `
      <tr>
        <td>${enc(bucketName || code)}</td>
        <td>${unitCount}</td>
        <td>${enc(unitName)}</td>
        <td>${fmtMoney(ex.pay_rate    ?? null)}</td>
        <td>${fmtMoney(ex.charge_rate ?? null)}</td>
        <td>${fmtMoney(payEx)}</td>
        <td>${fmtMoney(chgEx)}</td>
        <td>${fmtMoney(marEx)}</td>
      </tr>
    `;
  }).filter(Boolean).join('');

  const hasAdditional = !!additionalRows;

  let frameMode = 'view';
  try {
    if (typeof window.__getModalFrame === 'function') {
      const fr = window.__getModalFrame();
      if (fr && typeof fr.mode === 'string') frameMode = fr.mode;
    }
  } catch {}

  const meta           = mc.timesheetMeta || {};
  const isPlannedWeek  = !!meta.isPlannedWeek;
  const isEditing      = (frameMode === 'edit' || frameMode === 'create');

  const recomputeScheduleIfPossible = () => {
    try {
      if (typeof buildWeeklyScheduleFromLinesAndValidate !== 'function') return null;
      if (!st || !st.weeklyLinesByDate || typeof st.weeklyLinesByDate !== 'object') return null;
      const wd = Array.isArray(st.__weekDaysForSchedule) && st.__weekDaysForSchedule.length ? st.__weekDaysForSchedule : null;
      const out = buildWeeklyScheduleFromLinesAndValidate(st.weeklyLinesByDate, wd || undefined, {
        allowOvernight: true,
        allowBreakMins: true
      });
      st.schedule = Array.isArray(out?.schedule) ? out.schedule : [];
      st.scheduleErrorsByDate = (out?.errorsByDate && typeof out.errorsByDate === 'object') ? out.errorsByDate : {};
      st.scheduleHasErrors = !!out?.hasErrors;
      st.__scheduleUpdatedAt = Date.now();
      return out;
    } catch {
      return null;
    }
  };

  if (sheetScope === 'WEEKLY' && subMode === 'MANUAL') {
    const hasLines = !!(st.weeklyLinesByDate && typeof st.weeklyLinesByDate === 'object' && Object.keys(st.weeklyLinesByDate).length);
    const hasScheduleAlready = Array.isArray(st.schedule);
    const hasErrFlags = (typeof st.scheduleHasErrors === 'boolean') && (st.scheduleErrorsByDate && typeof st.scheduleErrorsByDate === 'object');
    if (hasLines && (!hasScheduleAlready || !hasErrFlags)) {
      recomputeScheduleIfPossible();
    }
  }

  const schedule = Array.isArray(st.schedule) ? st.schedule : null;
  const hasSchedule = !!(schedule && schedule.length);
  const useProposedBuckets = hasSchedule && (isEditing || isPlannedWeek);

  const scheduleHasErrors = !!st.scheduleHasErrors;
  const scheduleErrorsByDate = (st.scheduleErrorsByDate && typeof st.scheduleErrorsByDate === 'object')
    ? st.scheduleErrorsByDate
    : {};

  const addPayEx    = Number(tsfin.additional_pay_ex_vat    || 0) || 0;
  const addChgEx    = Number(tsfin.additional_charge_ex_vat || 0) || 0;

  const addMarginEx =
    (tsfin.additional_margin_ex_vat != null && Number.isFinite(Number(tsfin.additional_margin_ex_vat)))
      ? Number(tsfin.additional_margin_ex_vat)
      : round2(addChgEx - applyErniToPayEx(addPayEx));

  const stdFromSnapshot = computeStandardFromRates({
    hoursObj: hours,
    payObj: pay,
    chgObj: chg,
    erniApplies: erniCtx.applies,
    erniMult: erniCtx.erni_mult
  });

  const stdPayInit   = stdFromSnapshot.missingRates ? null : stdFromSnapshot.pay_ex_vat;
  const stdChgInit   = stdFromSnapshot.missingRates ? null : stdFromSnapshot.charge_ex_vat;
  const stdMarInit   = stdFromSnapshot.missingRates ? null : stdFromSnapshot.margin_ex_vat;

  const liveTotalsBase = resolveTimesheetLiveFinanceTotals({ row, details, state: st });
  const serverTotalPay   = Number.isFinite(Number(liveTotalsBase.total_pay_ex_vat)) ? Number(liveTotalsBase.total_pay_ex_vat) : null;
  const serverTotalChg   = Number.isFinite(Number(liveTotalsBase.total_charge_ex_vat)) ? Number(liveTotalsBase.total_charge_ex_vat) : null;
  const serverTotalMar   = Number.isFinite(Number(liveTotalsBase.margin_ex_vat)) ? Number(liveTotalsBase.margin_ex_vat) : null;

  const buildSummaryTableHtml = (vals) => {
    const v = vals || {};

    const cell = (n) => (n == null ? '—' : fmtMoney(n));
    const rowHtml = (label, payV, chgV, marV, isTotal) => `
      <tr ${isTotal ? 'style="font-weight:700"' : ''}>
        <td>${label}</td>
        <td>${cell(payV)}</td>
        <td>${cell(chgV)}</td>
        <td>${cell(marV)}</td>
      </tr>
    `;

    return `
      <table class="grid mini">
        <thead>
          <tr>
            <th style="width:240px">Category</th>
            <th style="width:160px">Pay (ex VAT)</th>
            <th style="width:160px">Charge (ex VAT)</th>
            <th style="width:160px">Margin (ex VAT)</th>
          </tr>
        </thead>
        <tbody>
          ${rowHtml('Standard hours', v.std_pay, v.std_chg, v.std_mar, false)}
          ${rowHtml('Additional',      v.add_pay, v.add_chg, v.add_mar, false)}
          ${rowHtml('Expenses',        v.exp_pay, v.exp_chg, v.exp_mar, false)}
          ${rowHtml('Mileage',         v.mil_pay, v.mil_chg, v.mil_mar, false)}
          ${rowHtml('Totals',          v.tot_pay, v.tot_chg, v.tot_mar, true)}
        </tbody>
      </table>
    `;
  };

  const computeTotals = (stdPay, stdChg, stdMar) => {
    const standardPay   = (stdPay == null ? null : Number(stdPay));
    const standardChg   = (stdChg == null ? null : Number(stdChg));
    const standardMar   = (stdMar == null ? null : Number(stdMar));

    if (!useProposedBuckets) {
      return {
        std_pay: standardPay, std_chg: standardChg, std_mar: standardMar,
        add_pay: addPayEx, add_chg: addChgEx, add_mar: addMarginEx,
        exp_pay: expensesPayLive, exp_chg: expensesChargeLive, exp_mar: expensesMarginLive,
        mil_pay: mileagePayLive, mil_chg: mileageChargeLive, mil_mar: mileageMarginLive,
        tot_pay: (serverTotalPay != null ? serverTotalPay : (standardPay != null ? round2(standardPay + addPayEx + expensesPayLive + mileagePayLive) : null)),
        tot_chg: (serverTotalChg != null ? serverTotalChg : (standardChg != null ? round2(standardChg + addChgEx + expensesChargeLive + mileageChargeLive) : null)),
        tot_mar: (serverTotalMar != null ? serverTotalMar : (standardMar != null ? round2(standardMar + addMarginEx + expensesMarginLive + mileageMarginLive) : null)),
      };
    }

    return {
      std_pay: standardPay, std_chg: standardChg, std_mar: standardMar,
      add_pay: addPayEx, add_chg: addChgEx, add_mar: addMarginEx,
      exp_pay: expensesPayLive, exp_chg: expensesChargeLive, exp_mar: expensesMarginLive,
      mil_pay: mileagePayLive, mil_chg: mileageChargeLive, mil_mar: mileageMarginLive,
      tot_pay: (standardPay != null ? round2(standardPay + addPayEx + expensesPayLive + mileagePayLive) : null),
      tot_chg: (standardChg != null ? round2(standardChg + addChgEx + expensesChargeLive + mileageChargeLive) : null),
      tot_mar: (standardMar != null ? round2(standardMar + addMarginEx + expensesMarginLive + mileageMarginLive) : null),
    };
  };

  const summaryInnerId = 'tsFinanceSummaryInner';
  const summaryInitVals = computeTotals(stdPayInit, stdChgInit, stdMarInit);
  const summaryInitHtml = buildSummaryTableHtml(summaryInitVals);

  const paymentSummaryHtml = buildPaymentSummaryHtml({ includeTitle: true });

  let previewHoursHtml = '';
  let bucketCardHtml = '';
  const previewHoursInnerId = 'tsFinancePreviewHoursInner';

  const buildProposedBucketTable = (preview) => {
    if (!preview || typeof preview !== 'object') {
      return `<span class="mini">Bucket preview unavailable.</span>`;
    }

    const h = preview.hours  || {};
    const p = preview.pay    || {};
    const c = preview.charge || {};

    const f = (preview.finance && typeof preview.finance === 'object') ? preview.finance : {};
    const erniApplies = f.erni_applies === true;
    const erniMult = Number.isFinite(Number(f.erni_multiplier)) ? Number(f.erni_multiplier) : 1;

    const applyErniPreview = (payEx) => {
      const x = Number(payEx || 0);
      if (!Number.isFinite(x)) return 0;
      return erniApplies ? (x * erniMult) : x;
    };

    const rows = buckets.map(b => {
      const hrs   = Number(h[b] || 0);
      const payR  = p[b] != null ? Number(p[b]) : null;
      const chgR  = c[b] != null ? Number(c[b]) : null;

      const payEx = payR != null ? hrs * payR : null;
      const chgEx = chgR != null ? hrs * chgR : null;

      const payCostEx = (payEx != null) ? applyErniPreview(payEx) : null;
      const marEx = (payCostEx != null && chgEx != null) ? (chgEx - payCostEx) : null;

      return `
        <tr>
          <td>${bucketLabel[b]}</td>
          <td>${hrs || 0}</td>
          <td>${payR  != null ? fmtMoney(payR)  : '—'}</td>
          <td>${chgR  != null ? fmtMoney(chgR)  : '—'}</td>
          <td>${payEx != null ? fmtMoney(payEx) : '—'}</td>
          <td>${chgEx != null ? fmtMoney(chgEx) : '—'}</td>
          <td>${marEx != null ? fmtMoney(marEx) : '—'}</td>
        </tr>
      `;
    }).join('');

    return `
      <table class="grid mini">
        <thead>
          <tr>
            <th>Bucket</th>
            <th>Hours</th>
            <th>Pay rate</th>
            <th>Charge rate</th>
            <th>Pay (ex VAT)</th>
            <th>Charge (ex VAT)</th>
            <th>Margin (ex VAT)</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    `;
  };

  try {
    const tsId   = mc.data?.timesheet_id || row.timesheet_id || null;
    const weekId = mc.data?.contract_week_id || row.contract_week_id || null;
    if (schedule && schedule.length) {
      const hasPreviewContext = !!(tsId || weekId);

      if (scheduleHasErrors) {
        const errDates = Object.keys(scheduleErrorsByDate || {});
        const errHint = errDates.length
          ? `Fix schedule errors on: ${errDates.map(d => enc(d)).join(', ')}`
          : 'Fix schedule errors in Lines before previewing hours.';

        previewHoursHtml = `
          <div class="card" style="margin-top:10px;">
            <div class="row">
              <label>Line hours</label>
              <div class="controls">
                <div id="${previewHoursInnerId}">
                  <div class="hint mini">
                    <span class="warn-icon" title="Schedule errors">&#9888;</span>
                    ${errHint}
                  </div>
                </div>
              </div>
            </div>
          </div>
        `;
      } else {
        previewHoursHtml = `
          <div class="card" style="margin-top:10px;">
            <div class="row">
              <label>Line hours</label>
              <div class="controls">
                <div id="${previewHoursInnerId}">
                  <span class="mini">Loading total hours…</span>
                </div>
              </div>
            </div>
          </div>
        `;
      }

      if (useProposedBuckets) {
        const containerId = 'tsBucketPreview';
        const innerId = 'tsBucketPreviewInner';

        if (scheduleHasErrors) {
          const errDates = Object.keys(scheduleErrorsByDate || {});
          const errHint = errDates.length
            ? `Fix schedule errors on: ${errDates.map(d => enc(d)).join(', ')}`
            : 'Fix schedule errors in Lines before previewing buckets.';

          bucketCardHtml = `
            <div class="card">
              <div class="row">
                <label>Core hours & rates</label>
                <div class="controls">
                  <span class="pill pill-bad">Proposed Buckets</span>
                  <div class="hint mini" style="margin-top:6px;">
                    <span class="warn-icon" title="Schedule errors">&#9888;</span>
                    ${errHint}
                  </div>
                </div>
              </div>
            </div>
          `;
        } else {
          bucketCardHtml = `
            <div class="card">
              <div class="row">
                <label>Core hours & rates</label>
                <div class="controls">
                  <span class="pill pill-bad">Proposed Buckets</span>
                  <div id="${containerId}">
                    <div id="${innerId}">
                      <span class="mini" id="tsBucketPreviewStatus">Loading bucket preview…</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          `;
        }
      }

      if (hasPreviewContext && !scheduleHasErrors) {
        try {
          const additionalUnitsWeek = {};
          if (st.additionalRates && typeof st.additionalRates === 'object') {
            Object.entries(st.additionalRates).forEach(([code, r]) => {
              if (!r) return;
              const units = Number(r.units_week || 0);
              if (!Number.isFinite(units) || units === 0) return;
              additionalUnitsWeek[code] = units;
            });
          }

          const payload = {
            timesheet_id:         tsId || null,
            contract_week_id:     tsId ? null : (weekId || null),
            actual_schedule_json: schedule,
            additional_units_week: additionalUnitsWeek
          };

          const url = API('/api/timesheets/bucket-preview');
          authFetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          })
            .then(res => {
              if (!res.ok) {
                return res.text().then(msg => { throw new Error(msg || 'Bucket preview failed'); });
              }
              return res.json();
            })
            .then(data => {
              try {
                const cacheKey = tsId || `cw:${weekId || 'unknown'}`;
                window.__tsBucketPreviewCache = window.__tsBucketPreviewCache || {};
                window.__tsBucketPreviewCache[String(cacheKey)] = { ok: true, data };
              } catch {}

              try {
                const hPrev = (data?.hours && typeof data.hours === 'object') ? data.hours : {};
                const totalPaidHours = round2(
                  Number(hPrev.day || 0) +
                  Number(hPrev.night || 0) +
                  Number(hPrev.sat || 0) +
                  Number(hPrev.sun || 0) +
                  Number(hPrev.bh || 0)
                );
                const previewEl = document.getElementById(previewHoursInnerId);
                if (previewEl) {
                  previewEl.innerHTML = `
                    <div class="mini">
                      Total hours: <strong>${totalPaidHours.toFixed(2)}</strong>
                    </div>
                  `;
                }
              } catch {}

              if (useProposedBuckets) {
                const container = document.getElementById(innerId);
                if (container) {
                  container.innerHTML = buildProposedBucketTable(data);
                }
              }

              try {
                const h = data?.hours  || {};
                const p = data?.pay    || {};
                const c = data?.charge || {};
                const f = (data?.finance && typeof data.finance === 'object') ? data.finance : {};

                const erniApplies = (f.erni_applies === true);
                const erniMult    = Number.isFinite(Number(f.erni_multiplier)) ? Number(f.erni_multiplier) : 1;

                const stdFromPreview = computeStandardFromRates({
                  hoursObj: h,
                  payObj: p,
                  chgObj: c,
                  erniApplies,
                  erniMult
                });

                const mc2 = window.modalCtx || {};
                const st2 = mc2.timesheetState || {};
                const ed2 = (st2.expensesDraft && typeof st2.expensesDraft === 'object') ? st2.expensesDraft : expDraft;

                const tp = round2(Number(ed2.travel_pay || 0));
                const tc = round2(Number(ed2.travel_charge || 0));
                const ap = round2(Number(ed2.accommodation_pay || 0));
                const ac = round2(Number(ed2.accommodation_charge || 0));
                const op = round2(Number(ed2.other_pay || 0));
                const oc = round2(Number(ed2.other_charge || 0));

                const expPay2 = round2(tp + ap + op);
                const expChg2 = round2(tc + ac + oc);
                const expMar2 = round2(expChg2 - expPay2);

                const mu2 = Number(ed2.mileage_units || 0) || 0;
                const pr2 = (mc2.timesheetDetails?.tsfin?.mileage_pay_rate != null) ? Number(mc2.timesheetDetails.tsfin.mileage_pay_rate) : mileagePayRate;
                const cr2 = (mc2.timesheetDetails?.tsfin?.mileage_charge_rate != null) ? Number(mc2.timesheetDetails.tsfin.mileage_charge_rate) : mileageChargeRate;

                const ratesOk2 =
                  Number.isFinite(pr2) && Number.isFinite(cr2) && pr2 > 0 && cr2 > 0;

                const milPay2 = ratesOk2 ? round2(mu2 * pr2) : 0;
                const milChg2 = ratesOk2 ? round2(mu2 * cr2) : 0;
                const milMar2 = round2(milChg2 - milPay2);

                const stdPay2 = stdFromPreview.missingRates ? null : stdFromPreview.pay_ex_vat;
                const stdChg2 = stdFromPreview.missingRates ? null : stdFromPreview.charge_ex_vat;
                const stdMar2 = stdFromPreview.missingRates ? null : stdFromPreview.margin_ex_vat;

                const vals2 = {
                  std_pay: stdPay2, std_chg: stdChg2, std_mar: stdMar2,
                  add_pay: addPayEx, add_chg: addChgEx, add_mar: addMarginEx,
                  exp_pay: expPay2, exp_chg: expChg2, exp_mar: expMar2,
                  mil_pay: milPay2, mil_chg: milChg2, mil_mar: milMar2,
                  tot_pay: (stdPay2 != null ? round2(stdPay2 + addPayEx + expPay2 + milPay2) : null),
                  tot_chg: (stdChg2 != null ? round2(stdChg2 + addChgEx + expChg2 + milChg2) : null),
                  tot_mar: (stdMar2 != null ? round2(stdMar2 + addMarginEx + expMar2 + milMar2) : null),
                };

                const sumEl = document.getElementById(summaryInnerId);
                if (sumEl) sumEl.innerHTML = buildSummaryTableHtml(vals2);
              } catch {}
            })
            .catch(err => {
              const msg = err?.message || 'Bucket preview failed';
              try {
                const cacheKey = tsId || `cw:${weekId || 'unknown'}`;
                window.__tsBucketPreviewCache = window.__tsBucketPreviewCache || {};
                window.__tsBucketPreviewCache[String(cacheKey)] = { error: msg };
              } catch {}

              const safeMsg = enc(msg);

              const previewEl = document.getElementById(previewHoursInnerId);
              if (previewEl) {
                previewEl.innerHTML = `<span class="warn-icon" title="${safeMsg}">&#9888;</span>`;
              }

              if (useProposedBuckets) {
                const statusEl = document.getElementById('tsBucketPreviewStatus');
                if (statusEl) {
                  statusEl.innerHTML = `<span class="warn-icon" title="${safeMsg}">&#9888;</span>`;
                }
              }
            });
        } catch (e) {
          if (LOGM) L('[FINANCE] bucket-preview wiring failed', e);
        }
      }
    }
  } catch (e) {
    if (LOGM) L('[FINANCE] preview wiring failed', e);
  }

  if (!useProposedBuckets) {
    bucketCardHtml = `
      <div class="card">
        <div class="row">
          <label>Core hours & rates</label>
          <div class="controls">
            <span class="pill pill-ok">Actual Buckets</span>
            <table class="grid mini">
              <thead>
                <tr>
                  <th>Bucket</th>
                  <th>Hours</th>
                  <th>Pay rate</th>
                  <th>Charge rate</th>
                  <th>Pay (ex VAT)</th>
                  <th>Charge (ex VAT)</th>
                  <th>Margin (ex VAT)</th>
                </tr>
              </thead>
              <tbody>
                ${tsfinBucketRows}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    `;
  }

  const erniNote = '';

  GE();

  return `
    <div class="tabc">
      ${bucketCardHtml}

      <div class="card" style="margin-top:10px;">
        <div class="row">
          <label>Additional rates</label>
          <div class="controls">
            ${
              hasAdditional
                ? `
                  <table class="grid mini">
                    <thead>
                      <tr>
                        <th>Bucket</th>
                        <th>Units</th>
                        <th>Unit name</th>
                        <th>Pay rate</th>
                        <th>Charge rate</th>
                        <th>Pay (ex VAT)</th>
                        <th>Charge (ex VAT)</th>
                        <th>Margin (ex VAT)</th>
                      </tr>
                    </thead>
                    <tbody>${additionalRows}</tbody>
                  </table>
                `
                : '<span class="mini">No additional rate units recorded on this snapshot.</span>'
            }
          </div>
        </div>
      </div>

      <div class="card" style="margin-top:10px;">
        <div class="row">
          <label>Summary</label>
          <div class="controls">
            <div id="${summaryInnerId}">
              ${summaryInitHtml}
            </div>
            ${paymentSummaryHtml}
            ${erniNote}
          </div>
        </div>
      </div>

      ${previewHoursHtml}
    </div>
  `;
}




function resolveTimesheetPreviewCacheKey(input = {}) {
  const tsId = String(input?.timesheetId || '').trim();
  if (tsId) return tsId;
  const weekId = String(input?.contractWeekId || '').trim();
  return `cw:${weekId || 'unknown'}`;
}

function resolveTimesheetLiveFinanceTotals(input = {}) {
  const row = (input && input.row && typeof input.row === 'object') ? input.row : {};
  const details = (input && input.details && typeof input.details === 'object') ? input.details : {};
  const state = (input && input.state && typeof input.state === 'object') ? input.state : {};
  const tsfin = (details && details.tsfin && typeof details.tsfin === 'object') ? details.tsfin : {};
  const ts = (details && details.timesheet && typeof details.timesheet === 'object') ? details.timesheet : {};
  const previewInput = (input && input.previewData && typeof input.previewData === 'object') ? input.previewData : null;
  const previewData = (previewInput && previewInput.ok === true && previewInput.data && typeof previewInput.data === 'object')
    ? previewInput.data
    : previewInput;

  const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  const nOrNull = (v) => (v != null && Number.isFinite(Number(v))) ? Number(v) : null;
  const trimStr = (v) => String(v == null ? '' : v).trim();

  const serverTotals = {
    total_pay_ex_vat: nOrNull(tsfin.total_pay_ex_vat) ?? nOrNull(row.total_pay_ex_vat) ?? 0,
    total_charge_ex_vat: nOrNull(tsfin.total_charge_ex_vat) ?? nOrNull(row.total_charge_ex_vat) ?? 0,
    margin_ex_vat: nOrNull(tsfin.margin_ex_vat) ?? nOrNull(row.margin_ex_vat) ?? 0
  };

  const sheetScope = trimStr(details.sheet_scope || row.sheet_scope || ts.sheet_scope || '').toUpperCase();
  const subMode = trimStr(ts.submission_mode || row.submission_mode || '').toUpperCase();
  const isDailyManual = (sheetScope === 'DAILY' && subMode === 'MANUAL');

  const unwrapPreviewPayload = (value) => {
    const src = (value && typeof value === 'object') ? value : null;
    if (!src) return null;
    if (src.ok === true && src.data && typeof src.data === 'object') return src.data;
    return src;
  };

  const extractAuthoritativeTotals = (payloadLike) => {
    const payload = unwrapPreviewPayload(payloadLike);
    if (!payload || typeof payload !== 'object') return null;
    const candidates = [
      payload,
      (payload.totals && typeof payload.totals === 'object') ? payload.totals : null,
      (payload.finance && typeof payload.finance === 'object') ? payload.finance : null,
      (payload.finance && payload.finance.totals && typeof payload.finance.totals === 'object') ? payload.finance.totals : null,
      (payload.snapshot && typeof payload.snapshot === 'object') ? payload.snapshot : null
    ].filter(Boolean);
    for (const candidate of candidates) {
      const pay = nOrNull(candidate.total_pay_ex_vat);
      const charge = nOrNull(candidate.total_charge_ex_vat);
      const margin = nOrNull(candidate.margin_ex_vat);
      if (pay != null && charge != null && margin != null) {
        return {
          total_pay_ex_vat: pay,
          total_charge_ex_vat: charge,
          margin_ex_vat: margin
        };
      }
    }
    return null;
  };

  if (isDailyManual) {
    const previewFromState = (state && state.__dailyFinancePreview && typeof state.__dailyFinancePreview === 'object')
      ? state.__dailyFinancePreview.data
      : null;
    const authoritativeDailyTotals = extractAuthoritativeTotals(previewFromState || previewData);
    return authoritativeDailyTotals || serverTotals;
  }

  if (!previewData) return serverTotals;

  const h = (previewData.hours && typeof previewData.hours === 'object') ? previewData.hours : {};
  const p = (previewData.pay && typeof previewData.pay === 'object') ? previewData.pay : {};
  const c = (previewData.charge && typeof previewData.charge === 'object') ? previewData.charge : {};
  const f = (previewData.finance && typeof previewData.finance === 'object') ? previewData.finance : {};
  const erniApplies = (f.erni_applies === true);
  const erniMult = Number.isFinite(Number(f.erni_multiplier)) ? Number(f.erni_multiplier) : 1;

  const buckets = ['day', 'night', 'sat', 'sun', 'bh'];
  let stdPay = 0;
  let stdCharge = 0;
  let stdMargin = 0;
  let hasMissingRates = false;

  for (const b of buckets) {
    const hrs = Number(h[b] || 0) || 0;
    const payRate = nOrNull(p[b]);
    const chargeRate = nOrNull(c[b]);
    if (hrs > 0 && (payRate == null || chargeRate == null)) hasMissingRates = true;
    const payEx = (payRate != null) ? (hrs * payRate) : 0;
    const chargeEx = (chargeRate != null) ? (hrs * chargeRate) : 0;
    const payCost = erniApplies ? (payEx * erniMult) : payEx;
    stdPay += payEx;
    stdCharge += chargeEx;
    stdMargin += (chargeEx - payCost);
  }

  if (hasMissingRates) return serverTotals;

  const addPay = Number(tsfin.additional_pay_ex_vat || 0) || 0;
  const addCharge = Number(tsfin.additional_charge_ex_vat || 0) || 0;
  const addMargin = (tsfin.additional_margin_ex_vat != null && Number.isFinite(Number(tsfin.additional_margin_ex_vat)))
    ? Number(tsfin.additional_margin_ex_vat)
    : round2(addCharge - addPay);

  const expDraft = (state.expensesDraft && typeof state.expensesDraft === 'object') ? state.expensesDraft : {};
  const expPay = round2(
    Number(expDraft.travel_pay || 0) +
    Number(expDraft.accommodation_pay || 0) +
    Number(expDraft.other_pay || 0)
  );
  const expCharge = round2(
    Number(expDraft.travel_charge || 0) +
    Number(expDraft.accommodation_charge || 0) +
    Number(expDraft.other_charge || 0)
  );
  const expMargin = round2(expCharge - expPay);

  const mileageUnits = Number(expDraft.mileage_units || 0) || 0;
  const mileagePayRate = nOrNull(tsfin.mileage_pay_rate);
  const mileageChargeRate = nOrNull(tsfin.mileage_charge_rate);
  const mileagePay = (mileagePayRate != null && mileageChargeRate != null && mileagePayRate > 0 && mileageChargeRate > 0)
    ? round2(mileageUnits * mileagePayRate)
    : 0;
  const mileageCharge = (mileagePayRate != null && mileageChargeRate != null && mileagePayRate > 0 && mileageChargeRate > 0)
    ? round2(mileageUnits * mileageChargeRate)
    : 0;
  const mileageMargin = round2(mileageCharge - mileagePay);

  return {
    total_pay_ex_vat: round2(stdPay + addPay + expPay + mileagePay),
    total_charge_ex_vat: round2(stdCharge + addCharge + expCharge + mileageCharge),
    margin_ex_vat: round2(stdMargin + addMargin + expMargin + mileageMargin)
  };
}



async function getTimesheetPdfUrl(timesheetId) {
  if (typeof window.openTimesheetDocumentV8 === 'function') {
    return window.openTimesheetDocumentV8(timesheetId);
  }
  throw new Error('Timesheet document viewing is temporarily unavailable while the new invoice system is being updated.');

  const LOGM = (typeof window.__LOG_MODAL === 'boolean') ? window.__LOG_MODAL : false;
  const L    = (...a) => { if (LOGM) console.log('[TS][PDF][GET]', ...a); };
  const GC   = (label) => { if (LOGM) console.groupCollapsed('[TS][PDF][GET]', label); };
  const GE   = () => { if (LOGM) console.groupEnd(); };

  if (!timesheetId) {
    throw new Error('getTimesheetPdfUrl: timesheetId is required');
  }

  GC('getTimesheetPdfUrl');
  L('START', { timesheetId });

  const encId = encodeURIComponent(timesheetId);
  const metaUrl = API(`/api/timesheets/${encId}/pdf`);

  let pdfMeta;
  try {
    const res  = await authFetch(metaUrl);
    const text = await res.text();

    if (!res.ok) {
      // Treat any non-OK as "no CURRENT pdf" for the purposes of the Evidence dialog
      L('timesheet pdf meta failed', { status: res.status, bodyPreview: text.slice(0, 400) });
      GE();
      return null;
    }

    pdfMeta = text ? JSON.parse(text) : {};
  } catch (err) {
    // Network / parse errors → treat as "no pdf" for the dialog
    L('meta fetch error', err);
    GE();
    return null;
  }

  const r2Key =
    pdfMeta.r2_key ||
    pdfMeta.key ||
    pdfMeta.manual_pdf_r2_key ||
    null;

  if (!r2Key) {
    L('no r2_key in pdfMeta', pdfMeta);
    GE();
    return null;
  }

  L('meta resolved', { r2Key, rotation_degrees: pdfMeta.rotation_degrees });

  // Ask files API for a presigned download URL
  const presignUrl = API('/api/files/presign-download');
  let signed;
  try {
    const res  = await authFetch(presignUrl, {
      method: 'POST',
      headers: { 'Content-Type':'application/json' },
      body: JSON.stringify({ key: r2Key })
    });
    const text = await res.text();

    if (!res.ok) {
      L('presign-download failed', { status: res.status, bodyPreview: text.slice(0, 400) });
      GE();
      return null;
    }

    signed = text ? JSON.parse(text) : {};
  } catch (err) {
    L('presign error', err);
    GE();
    return null;
  }

  const url = signed.url || signed.signed_url || null;
  if (!url) {
    L('no URL in presign response', signed);
    GE();
    return null;
  }

  L('RESOLVE OK', { url });
  GE();

  return {
    url,
    r2_key: r2Key,
    rotation_degrees: pdfMeta.rotation_degrees ?? 0,
    meta: pdfMeta
  };
}

async function apiSaveMyEmailSignature(input) {
  const trimStr = (v) => String(v == null ? '' : v).trim();

  let emailSignatureHtml = null;

  if (typeof input === 'string' || input == null) {
    emailSignatureHtml = (input == null || trimStr(input) === '') ? null : String(input);
  } else if (typeof input === 'object' && !Array.isArray(input)) {
    const raw =
      Object.prototype.hasOwnProperty.call(input, 'email_signature_html')
        ? input.email_signature_html
        : (Object.prototype.hasOwnProperty.call(input, 'signature_html') ? input.signature_html : null);

    if (raw !== null && raw !== undefined && typeof raw !== 'string') {
      throw new Error('email_signature_html_must_be_string_or_null');
    }

    emailSignatureHtml = (raw == null || trimStr(raw) === '') ? null : String(raw);
  } else {
    throw new Error('invalid_signature_payload');
  }

  const res = await authFetch(API('/api/users/me/signature'), {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      email_signature_html: emailSignatureHtml
    })
  });

  const txt = await res.text().catch(() => '');
  let payload = null;
  try { payload = txt ? JSON.parse(txt) : null; } catch { payload = null; }

  if (!res.ok) {
    throw new Error(
      (payload && typeof payload === 'object' && (payload.error || payload.message))
        ? String(payload.error || payload.message)
        : (txt || `Failed to save email signature (${res.status})`)
    );
  }

  const user = (payload && payload.user && typeof payload.user === 'object') ? payload.user : {};
  const savedHtml = Object.prototype.hasOwnProperty.call(user, 'email_signature_html')
    ? (user.email_signature_html ?? null)
    : emailSignatureHtml;

  try {
    window.SESSION = window.SESSION || {};
    window.SESSION.user = window.SESSION.user || {};
    window.SESSION.user.email_signature_html = savedHtml;
  } catch {}

  try {
    window.__me = window.__me || {};
    window.__me.email_signature_html = savedHtml;
  } catch {}

  try {
    window.currentUser = window.currentUser || {};
    window.currentUser.email_signature_html = savedHtml;
  } catch {}

  try {
    window.__currentUserSignatureHtml = savedHtml;
  } catch {}

  try {
    if (window.modalCtx && typeof window.modalCtx === 'object') {
      window.modalCtx.currentUser = window.modalCtx.currentUser || {};
      window.modalCtx.currentUser.email_signature_html = savedHtml;
      window.modalCtx.currentUserSignatureHtml = savedHtml;
    }
  } catch {}

  return {
    ok: true,
    user: {
      ...(user || {}),
      email_signature_html: savedHtml
    }
  };
}

function renderMyEmailSignatureEditor() {
  const htmlWrap = (typeof html === 'function') ? html : (s) => String(s ?? '');
  const safeHtml = (typeof escapeHtml === 'function')
    ? escapeHtml
    : (s) => String(s ?? '')
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#39;');

  window.modalCtx = window.modalCtx || {};
  modalCtx = window.modalCtx;

  const draft = (modalCtx.myEmailSignatureDraft && typeof modalCtx.myEmailSignatureDraft === 'object')
    ? modalCtx.myEmailSignatureDraft
    : {
        entity: 'my_email_signature',
        openToken: `my-email-signature:${Date.now()}:${Math.random().toString(36).slice(2)}`,
        html: '',
        saving: false,
        dirty: false,
        saveResult: null,
        imageUploadCount: 0
      };

  modalCtx.myEmailSignatureDraft = draft;

  const statusHtml = (() => {
    const r = draft.saveResult;
    if (!r || typeof r !== 'object') return '';
    if (r.ok) {
      return `
        <div class="card" style="padding:10px;margin-bottom:10px;border-color:rgba(90,200,140,0.35);">
          <div class="mini" style="color:rgba(150,255,190,0.98);">Signature saved successfully.</div>
        </div>
      `;
    }
    return `
      <div class="card" style="padding:10px;margin-bottom:10px;border-color:rgba(220,120,120,0.35);">
        <div class="mini" style="color:rgba(255,180,180,0.98);">${safeHtml(String(r.error || 'Failed to save signature'))}</div>
      </div>
    `;
  })();

  setTimeout(() => {
    const root = document.getElementById('myEmailSignatureRoot');
    if (!root) return;

    const notifyDirty = () => {
      draft.dirty = true;
      draft.saveResult = null;
      try { window.dispatchEvent(new Event('modal-dirty')); } catch {}
    };

    const syncFromDom = () => {
      try {
        const hidden = document.getElementById('myEmailSignatureHtml');
        if (hidden) {
          const nextHtml = String(hidden.value ?? '');
          const prevHtml = String(draft.html || '');
          draft.html = nextHtml;
          if (nextHtml !== prevHtml) {
            notifyDirty();
          }
          return nextHtml;
        }
      } catch {}
      return String(draft.html || '');
    };

    const getSignatureEditorParts = () => {
      const host = document.getElementById('myEmailSignatureRichEditorHost');
      const hidden = document.getElementById('myEmailSignatureHtml');
      const surface = host && host.querySelector ? host.querySelector('[data-rich-editor-surface="1"]') : null;
      return { host, hidden, surface };
    };

    const flushSignatureEditorHtmlNow = () => {
      try {
        const { host } = getSignatureEditorParts();
        if (host && typeof host.__syncHtml === 'function') {
          host.__syncHtml();
        }
      } catch {}
      return syncFromDom();
    };

    draft.flushHtmlFromEditor = flushSignatureEditorHtmlNow;

    const rerender = () => {
      try {
        flushSignatureEditorHtmlNow();
        const bodyEl = document.getElementById('modalBody');
        if (bodyEl) bodyEl.innerHTML = renderMyEmailSignatureEditor();
      } catch (e) {
        console.error('[MY_EMAIL_SIGNATURE] rerender failed', e);
      }
    };

    try {
      initTemplateRichEditor({
        hostId: 'myEmailSignatureRichEditorHost',
        hiddenInputId: 'myEmailSignatureHtml',
        initialHtml: String(draft.html || ''),
        placeholder: 'Create or edit your default email signature…',
        onChange: (htmlVal) => {
          const nextHtml = String(htmlVal || '');
          const prevHtml = String(draft.html || '');
          draft.html = nextHtml;
          if (nextHtml !== prevHtml) {
            notifyDirty();
          }
        }
      });
    } catch (e) {
      console.warn('[MY_EMAIL_SIGNATURE] rich editor init failed', e);
    }

    if (!root.dataset.myEmailSignatureWired) {
      root.dataset.myEmailSignatureWired = '1';

      root.addEventListener('click', async (ev) => {
        const btn = ev.target && ev.target.closest ? ev.target.closest('[data-signature-act]') : null;
        if (!btn) return;

        ev.preventDefault();
        const act = String(btn.getAttribute('data-signature-act') || '').trim();

        if (act === 'insert-image') {
          try {
            await handleTemplateImageInsert({
              hostId: 'myEmailSignatureRichEditorHost',
              hiddenInputId: 'myEmailSignatureHtml',
              replaceAllContent: true,
              onChange: (htmlVal) => {
                const nextHtml = String(htmlVal || '');
                const prevHtml = String(draft.html || '');
                draft.html = nextHtml;
                if (nextHtml !== prevHtml) {
                  notifyDirty();
                }
              },
              onUploaded: () => {
                draft.imageUploadCount = Number(draft.imageUploadCount || 0) + 1;
              }
            });

            flushSignatureEditorHtmlNow();
          } catch (e) {
            draft.saveResult = { ok: false, error: String(e?.message || e || 'Failed to insert image') };
            rerender();
          }
          return;
        }

        if (act === 'clear') {
          let confirmed = true;
          if (typeof openUiConfirmModal === 'function') {
            const res = await openUiConfirmModal({
              title: 'Clear signature?',
              message: 'This will clear the current signature content from the editor. You can still save an empty signature if you want to remove it.',
              confirm_label: 'Clear',
              cancel_label: 'Cancel',
              confirm_class: 'btn btn-warn',
              cancel_class: 'btn btn-outline'
            });
            confirmed = !!(res && res.confirmed === true);
          }

          if (!confirmed) return;

          try {
            const hidden = document.getElementById('myEmailSignatureHtml');
            const host = document.getElementById('myEmailSignatureRichEditorHost');
            const surface = host && host.querySelector ? host.querySelector('[data-rich-editor-surface="1"]') : null;

            if (surface) surface.innerHTML = '';
            if (hidden) hidden.value = '';
            draft.html = '';
            notifyDirty();
          } catch {}

          rerender();
        }
      }, true);

      root.addEventListener('input', () => {
        syncFromDom();
      }, true);

      root.addEventListener('change', () => {
        syncFromDom();
      }, true);
    }
  }, 0);

  return htmlWrap(`
    <div id="myEmailSignatureRoot">
      ${statusHtml}

      <div class="card" style="padding:12px;">
        <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap;">
          <div>
            <div style="font-weight:700;font-size:14px;">Default email signature</div>
            <div class="mini" style="opacity:.8;line-height:1.35;margin-top:4px;">
              This signature is stored on your user record and is injected into email editors by default.
              It becomes normal editable content, so you can still delete or change it in a specific email.
            </div>
          </div>

          <div style="display:flex;gap:8px;flex-wrap:wrap;">
            <button type="button" class="btn btn-outline" data-signature-act="insert-image">Insert image</button>
            <button type="button" class="btn btn-outline" data-signature-act="clear">Clear</button>
          </div>
        </div>
      </div>

      <div class="card" style="padding:12px;margin-top:12px;">
        <div style="font-weight:700;font-size:13px;margin-bottom:8px;">Signature editor</div>
        <div id="myEmailSignatureRichEditorHost"></div>
        <textarea id="myEmailSignatureHtml" style="display:none;">${safeHtml(String(draft.html || ''))}</textarea>

        <div class="mini" style="opacity:.72;margin-top:10px;line-height:1.35;">
          Supported content includes formatted text, colours, links, tables, and uploaded images.
          Images are inserted at a normalised size and can be resized by dragging from the bottom-right corner without changing aspect ratio.
        </div>
      </div>
    </div>
  `);
}


async function saveMyEmailSignature() {
  window.modalCtx = window.modalCtx || {};
  modalCtx = window.modalCtx;

  const draft = (modalCtx.myEmailSignatureDraft && typeof modalCtx.myEmailSignatureDraft === 'object')
    ? modalCtx.myEmailSignatureDraft
    : null;

  if (!draft) {
    throw new Error('my_email_signature_draft_missing');
  }

  try {
    const host = document.getElementById('myEmailSignatureRichEditorHost');
    if (host && typeof host.__syncHtml === 'function') {
      host.__syncHtml();
    }
  } catch {}

  const hidden = document.getElementById('myEmailSignatureHtml');
  if (hidden) {
    draft.html = String(hidden.value ?? '');
  }

  draft.saving = true;
  draft.saveResult = null;

  try {
    const res = await apiSaveMyEmailSignature({
      email_signature_html: draft.html
    });

    const savedHtml =
      res && res.user && Object.prototype.hasOwnProperty.call(res.user, 'email_signature_html')
        ? (res.user.email_signature_html ?? null)
        : (draft.html == null || String(draft.html).trim() === '' ? null : String(draft.html));

    const signatureChangedToken = `sig:${Date.now()}:${Math.random().toString(36).slice(2)}`;

    draft.html = savedHtml || '';
    draft.dirty = false;
    draft.saving = false;
    draft.saveResult = { ok: true };
    draft.signature_changed_token = signatureChangedToken;

    try {
      if (window.modalCtx && typeof window.modalCtx === 'object') {
        window.modalCtx.currentUser = window.modalCtx.currentUser || {};
        window.modalCtx.currentUser.email_signature_html = savedHtml;
        window.modalCtx.currentUserSignatureHtml = savedHtml;
        window.modalCtx.myEmailSignatureChangedToken = signatureChangedToken;
      }
    } catch {}

    try {
      window.SESSION = window.SESSION || {};
      window.SESSION.user = window.SESSION.user || {};
      window.SESSION.user.email_signature_html = savedHtml;
    } catch {}

    try {
      window.__me = window.__me || {};
      window.__me.email_signature_html = savedHtml;
    } catch {}

    try {
      window.currentUser = window.currentUser || {};
      window.currentUser.email_signature_html = savedHtml;
    } catch {}

    try {
      window.__currentUserSignatureHtml = savedHtml;
    } catch {}

    return {
      ok: true,
      signature_changed_token: signatureChangedToken,
      user: {
        ...(res && res.user ? res.user : {}),
        email_signature_html: savedHtml
      }
    };
  } catch (e) {
    draft.saving = false;
    draft.saveResult = {
      ok: false,
      error: String(e?.message || e || 'Failed to save email signature')
    };
    throw e;
  }
}


async function openTimesheet(row) {
  const { LOGM, L, GC, GE } = getTsLoggers('[TS][OPEN]');
  GC('openTimesheet');

  try {
    if (!row || typeof row !== 'object') {
      alert('No timesheet row provided.');
      GE();
      return;
    }

    const baseRow = { ...row, __timesheetWorkbenchFetchPurpose: 'initial_open' };
    const lifecycleSeedSignature = String(
      baseRow.backend_row_signature ||
      baseRow.mutation_row_signature ||
      baseRow.row_signature ||
      baseRow.expected_row_signature ||
      ''
    ).trim();
    const lifecycleSeedTrusted = !!(
      baseRow.lifecycle_state_trusted === true &&
      baseRow.lifecycle_refresh_required !== true &&
      lifecycleSeedSignature
    );
    const ids = timesheetFastOpenIdsFromRow(baseRow);
    const realTsId = ids.realTsId || null;
    const weekId = ids.weekId || null;
    const hasTs = !!ids.hasTs;
    const isPlannedWeek = !!ids.isPlannedWeek;

    if (!hasTs && !isPlannedWeek) {
      L('ERROR: missing timesheet_id / contract_week_id on row', { row });
      GE();
      alert('Timesheet or week id missing.');
      return;
    }

    let tsId = hasTs ? realTsId : null;
    baseRow.id = hasTs ? realTsId : (weekId || baseRow.id);

    const openToken = `timesheet:${Date.now()}:${Math.random().toString(36).slice(2)}`;
    const initialCtx = makeInitialTimesheetModalCtx(baseRow, ids, openToken);
  initialCtx.__timesheetLifecycleMutationSeq = Number(initialCtx.__timesheetLifecycleMutationSeq || 0) || 0;
  initialCtx.__timesheetLatestLifecycleMutationSeq = Number(initialCtx.__timesheetLatestLifecycleMutationSeq || 0) || 0;
  initialCtx.__timesheetLazyRefreshSeq = Number(initialCtx.__timesheetLazyRefreshSeq || 0) || 0;
  initialCtx.__timesheetWorkbenchFetchPurpose = 'initial_open';
  initialCtx.__timesheetTabRefreshTokens = initialCtx.__timesheetTabRefreshTokens || {};
  initialCtx.__timesheetLazyTabBadges = initialCtx.__timesheetLazyTabBadges || {};
  if (!lifecycleSeedTrusted && !isPlannedWeek) {
    initialCtx.__timesheetLifecyclePermissionStateComplete = false;
    initialCtx.__timesheetLifecyclePriorityBadgesComplete = false;
    initialCtx.__timesheetLifecycleCriticalStateIncomplete = true;
    initialCtx.__timesheetLifecycleCriticalStateReason = 'MODAL_OPEN_LIFECYCLE_HYDRATION_PENDING';
    initialCtx.__timesheetLifecycleTrusted = null;
  } else if (isPlannedWeek) {
    // A planned Manual contract week has no physical timesheet lifecycle row to
    // hydrate yet. Its edit authority comes from the contract-week route and
    // submission-mode snapshot, while the normal lifecycle gates take over as
    // soon as the first physical timesheet is created.
    initialCtx.__timesheetLifecyclePermissionStateComplete = true;
    initialCtx.__timesheetLifecyclePriorityBadgesComplete = true;
    initialCtx.__timesheetLifecycleCriticalStateIncomplete = false;
    initialCtx.__timesheetLifecycleCriticalStateReason = '';
    initialCtx.__timesheetLifecycleTrusted = null;
  }
    window.modalCtx = initialCtx;
    try { if (typeof modalCtx !== 'undefined') modalCtx = window.modalCtx; } catch {}

    L('ENTRY_FAST_OPEN', {
      tsId,
      weekId,
      isPlannedWeek,
      sheetScopeRaw: ids.sheetScope,
      subModeRaw: ids.subMode,
      rowKeys: Object.keys(baseRow || {})
    });

    const tabDefs = makeTimesheetFastOpenTabDefs();
    const renderTab = makeTimesheetFastOpenRenderTab(openToken, baseRow);
    const onSaveTimesheet = async () => {
      const mc = (window.modalCtx && typeof window.modalCtx === 'object') ? window.modalCtx : {};
      const hydration = (mc.timesheetHydration && typeof mc.timesheetHydration === 'object') ? mc.timesheetHydration : {};
      const realSave = (typeof mc.__timesheetRealOnSave === 'function') ? mc.__timesheetRealOnSave : null;

      if (!isActiveTimesheetModalToken(openToken)) {
        return { ok: false, error: 'Timesheet modal is no longer active.' };
      }

      if (hydration.detailsLoaded !== true || !realSave) {
        const msg = String(hydration.detailsError || 'Timesheet details are still loading. Try again once the modal has finished loading.');
        try { window.__toast ? window.__toast(msg) : alert(msg); } catch {}
        return { ok: false, error: msg };
      }

      return await realSave();
    };

    const weeklySourceCategory = String(baseRow.weekly_source_category || '').trim().toUpperCase();
    const weeklySourceCandidateName = String(baseRow.candidate_name || baseRow.candidate_display_name || '').trim();
    const hasWeeklySourceIdentity = !!(
      weeklySourceCandidateName &&
      ['NHSP', 'CLIENT_PROVIDED_HOURS', 'TIMESHEETS_CHECKED_WITH_CLIENT'].includes(weeklySourceCategory)
    );
    const title = hasTs
      ? (baseRow.__bpayNextExactPhysicalId && baseRow.reference_number ? `Timesheet · ${baseRow.reference_number}` : (hasWeeklySourceIdentity ? `Timesheet · ${weeklySourceCandidateName}` : `Timesheet ${String(tsId).slice(0, 8)}…`))
      : `Weekly timesheet (planned) ${String(weekId).slice(0, 8)}…`;

    const hasRelatedId = !!(tsId || weekId);

    showModal(
      title,
      tabDefs,
      renderTab,
      onSaveTimesheet,
      hasRelatedId,
      undefined,
      { kind: 'timesheets' }
    );

    Promise.resolve()
      .then(() => hydrateTimesheetModalAfterOpen(openToken, { ...baseRow, __timesheetWorkbenchFetchPurpose: 'initial_open' }, ids))
      .catch(async (err) => {
        if (((typeof window.__LOG_MODAL === 'boolean') ? window.__LOG_MODAL : false)) {
          console.error('[TS][OPEN][FAST_OPEN_BACKGROUND] EXCEPTION', err);
        }
        if (isActiveTimesheetModalToken(openToken)) {
          setTimesheetFastOpenHydrationError(openToken, err, 'details');
          try { await safeRerenderTimesheetModal(openToken); } catch {}
        }
      });

    GE();
  } catch (err) {
    if (((typeof window.__LOG_MODAL === 'boolean') ? window.__LOG_MODAL : false)) {
      console.error('[TS][OPEN] EXCEPTION', err);
    }
    alert(err?.message || 'Failed to open timesheet.');
    GE();
  }
}


function timesheetFastOpenIdsFromRow(baseRowArg) {
  const baseRow = (baseRowArg && typeof baseRowArg === 'object') ? baseRowArg : {};
  const realTsId = baseRow.timesheet_id || null;
  const weekId = baseRow.contract_week_id || null;
  const hasTs = !!realTsId;
  const isPlannedWeek = !hasTs && !!weekId;
  return {
    realTsId,
    weekId,
    hasTs,
    isPlannedWeek,
    sheetScope: String(baseRow.sheet_scope || '').toUpperCase(),
    subMode: String(baseRow.submission_mode || '').toUpperCase(),
    cwSubmissionModeSnapshot: String(baseRow.submission_mode_snapshot || baseRow.submission_mode || '').toUpperCase()
  };
}

function makeInitialTimesheetDetailsPlaceholder(baseRowArg, idsArg) {
  const baseRow = (baseRowArg && typeof baseRowArg === 'object') ? baseRowArg : {};
  const ids = (idsArg && typeof idsArg === 'object') ? idsArg : timesheetFastOpenIdsFromRow(baseRow);
  const readyToPay = (typeof baseRow.ready_to_pay === 'boolean') ? baseRow.ready_to_pay : null;

  return {
    __placeholder: true,
    __loading: true,
    timesheet: null,
    tsfin: null,
    validations: [],
    shifts: [],
    segments: [],
    invoiceBreakdown: null,
    isSegmentsMode: false,
    sheet_scope: baseRow.sheet_scope || null,
    contract_week_id: baseRow.contract_week_id || null,
    contract_week: null,
    policy: null,
    action_flags: null,
    ready_to_pay: readyToPay,
    pay_state: null,
    segment_snoozes: [],
    current_timesheet_id: ids.realTsId || null,
    requested_timesheet_id: ids.realTsId || null
  };
}

function makeInitialTimesheetRelatedPlaceholder(baseRowArg) {
  const baseRow = (baseRowArg && typeof baseRowArg === 'object') ? baseRowArg : {};

  const candidate = (baseRow.candidate_id || baseRow.candidate_name || baseRow.occupant_key_norm)
    ? {
        id: baseRow.candidate_id || null,
        display_name: baseRow.candidate_name || baseRow.occupant_key_norm || null,
        first_name: null,
        last_name: null
      }
    : null;

  const client = (baseRow.client_id || baseRow.client_name)
    ? {
        id: baseRow.client_id || null,
        name: baseRow.client_name || null
      }
    : null;

  return {
    counts: {},
    candidate,
    client,
    invoices: [],
    invoice: null,
    invoice_no_by_invoice_id: {},
    umbrella: null,
    contract: null,
    series: []
  };
}

function makeInitialTimesheetStatePlaceholder(baseRowArg, idsArg) {
  const baseRow = (baseRowArg && typeof baseRowArg === 'object') ? baseRowArg : {};
  return {
    reference: baseRow.reference_number || '',
    payHoldDesired: null,
    payHoldReason: '',
    markPaid: false,
    segmentOverrides: {},
    segmentInvoiceTargets: {},
    manualHours: {},
    additionalRates: {},
    schedule: [],
    baselineSchedule: [],
    dayReferences: {},
    evidence: [],
    expensesDraft: {},
    expensesBaseline: {}
  };
}

function makeInitialTimesheetMetaPlaceholder(baseRowArg, idsArg) {
  const baseRow = (baseRowArg && typeof baseRowArg === 'object') ? baseRowArg : {};
  const ids = (idsArg && typeof idsArg === 'object') ? idsArg : timesheetFastOpenIdsFromRow(baseRow);
  const isPaid = !!baseRow.paid_at_utc;
  const isInvoiced = !!baseRow.locked_by_invoice_id;

  return {
    hasTs: !!ids.hasTs,
    isPlannedWeek: !!ids.isPlannedWeek,
    expected_timesheet_id: ids.realTsId || null,
    contract_week_id: ids.weekId || null,
    sheetScope: ids.sheetScope || String(baseRow.sheet_scope || '').toUpperCase(),
    subMode: ids.subMode || String(baseRow.submission_mode || '').toUpperCase(),
    cw_submission_mode_snapshot: ids.cwSubmissionModeSnapshot || String(baseRow.submission_mode_snapshot || baseRow.submission_mode || '').toUpperCase(),
    isPaid,
    isInvoiced,
    isLocked: !!(isPaid || isInvoiced),
    hasElectronicOriginal: false
  };
}

function makeInitialTimesheetHydrationState() {
  return {
    fastOpen: true,
    detailsLoading: true,
    detailsLoaded: false,
    detailsError: '',
    relatedLoading: false,
    relatedLoaded: false,
    relatedError: '',
    evidenceLoading: false,
    evidenceLoaded: false,
    evidenceError: '',
    deletePreviewLoading: false,
    deletePreviewLoaded: false,
    deletePreviewError: '',
    contractLoading: false,
    contractLoaded: false,
    contractError: ''
  };
}

function makeInitialTimesheetModalData(baseRowArg, idsArg) {
  const baseRow = (baseRowArg && typeof baseRowArg === 'object') ? baseRowArg : {};
  const ids = (idsArg && typeof idsArg === 'object') ? idsArg : timesheetFastOpenIdsFromRow(baseRow);
  const id = ids.hasTs ? ids.realTsId : (ids.weekId || baseRow.id || null);

  return {
    ...baseRow,
    id,
    timesheet_id: ids.hasTs ? (ids.realTsId || null) : null,
    contract_week_id: ids.weekId || null,
    sheet_scope: baseRow.sheet_scope || null,
    submission_mode: baseRow.submission_mode || null,
    submission_mode_snapshot: baseRow.submission_mode_snapshot || null,
    route_type: baseRow.route_type || null,
    route_display: baseRow.route_display || null,
    route_family: baseRow.route_family || null,
    route_subfamily: baseRow.route_subfamily || null,
    underlying_channel_family: baseRow.underlying_channel_family || null,
    candidate_name: baseRow.candidate_name || null,
    client_name: baseRow.client_name || null,
    job_title_norm: baseRow.job_title_norm || null,
    band: baseRow.band || null,
    week_ending_date: baseRow.week_ending_date || null,
    processing_status: baseRow.processing_status || null,
    summary_stage: baseRow.summary_stage || null,
    tools_stage: baseRow.tools_stage || null,
    ready_to_pay: (typeof baseRow.ready_to_pay === 'boolean') ? baseRow.ready_to_pay : baseRow.ready_to_pay,
    locked_by_invoice_id: baseRow.locked_by_invoice_id || null,
    paid_at_utc: baseRow.paid_at_utc || null
  };
}

function makeInitialTimesheetModalCtx(baseRowArg, idsArg, openToken) {
  const baseRow = (baseRowArg && typeof baseRowArg === 'object') ? baseRowArg : {};
  const ids = (idsArg && typeof idsArg === 'object') ? idsArg : timesheetFastOpenIdsFromRow(baseRow);
  const data = makeInitialTimesheetModalData(baseRow, ids);
  const forId = ids.hasTs
    ? `timesheet:${String(ids.realTsId || data.id || '')}`
    : `contract_week:${String(ids.weekId || data.id || '')}`;

  return {
    entity: 'timesheets',
    mode: 'view',
    openToken,
    data,
    timesheetDetails: makeInitialTimesheetDetailsPlaceholder(baseRow, ids),
    timesheetRelated: makeInitialTimesheetRelatedPlaceholder(baseRow),
    timesheetPayState: null,
    timesheetPayStateError: '',
    timesheetDeletePreview: null,
    timesheetState: makeInitialTimesheetStatePlaceholder(baseRow, ids),
    timesheetMeta: makeInitialTimesheetMetaPlaceholder(baseRow, ids),
    timesheetHydration: makeInitialTimesheetHydrationState(),
    formState: {
      __forId: forId,
      main: {},
      pay: {}
    }
  };
}

function isActiveTimesheetModalToken(openToken) {
  try {
    return !!(
      openToken &&
      window.modalCtx &&
      window.modalCtx.entity === 'timesheets' &&
      window.modalCtx.openToken === openToken
    );
  } catch {
    return false;
  }
}

function renderTimesheetLoadingCard(label, message, isExactNavigationError = false) {
  const enc = (typeof escapeHtml === 'function')
    ? escapeHtml
    : ((v) => String(v == null ? '' : v)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;'));

  const title = String(label || 'Timesheet').trim() || 'Timesheet';
  const msg = String(message || 'Timesheet details are loading…').trim() || 'Timesheet details are loading…';

  return `
    <div class="tabc">
      <div class="card">
        <div class="row">
          <label>${enc(title)}</label>
          <div class="controls"><span class="mini"${isExactNavigationError ? ' role="alert"' : ''}>${enc(msg)}</span></div>
        </div>
      </div>
    </div>`;
}

function setTimesheetFastOpenHydrationError(openToken, err, area) {
  if (!isActiveTimesheetModalToken(openToken)) return false;

  const mc = window.modalCtx || {};
  const key = String(area || 'details').trim() || 'details';
  const msg = String(err && err.message ? err.message : (err || 'Failed to load timesheet details.')).trim() || 'Failed to load timesheet details.';
  const hydration = {
    ...makeInitialTimesheetHydrationState(),
    ...(mc.timesheetHydration && typeof mc.timesheetHydration === 'object' ? mc.timesheetHydration : {})
  };

  if (key === 'related') {
    hydration.relatedLoading = false;
    hydration.relatedLoaded = false;
    hydration.relatedError = msg;
  } else if (key === 'evidence') {
    hydration.evidenceLoading = false;
    hydration.evidenceLoaded = false;
    hydration.evidenceError = msg;
  } else if (key === 'deletePreview') {
    hydration.deletePreviewLoading = false;
    hydration.deletePreviewLoaded = false;
    hydration.deletePreviewError = msg;
  } else if (key === 'contract') {
    hydration.contractLoading = false;
    hydration.contractLoaded = false;
    hydration.contractError = msg;
  } else {
    hydration.detailsLoading = false;
    hydration.detailsLoaded = false;
    hydration.detailsError = msg;
  }

  mc.timesheetHydration = hydration;
  window.modalCtx = mc;
  return true;
}

function makeTimesheetFastOpenTabDefs() {
  return [
    { key: 'overview', title: 'Overview' },
    { key: 'lines',    title: 'Lines' },
    { key: 'expenses', title: 'Expenses' },
    { key: 'evidence', title: 'Evidence' },
    { key: 'issues',   title: 'Issues' },
    { key: 'finance',  title: 'Finance' },
    { key: 'audit',    title: 'Audit' }
  ];
}

function makeTimesheetFastOpenRenderTab(openToken, baseRowArg) {
  const baseRow = (baseRowArg && typeof baseRowArg === 'object') ? baseRowArg : {};

  return (key, mergedRow) => {
    if (!isActiveTimesheetModalToken(openToken)) {
      return renderTimesheetLoadingCard('Timesheet', 'This timesheet modal is no longer active.');
    }

    const mc = window.modalCtx || {};
    const hydration = (mc.timesheetHydration && typeof mc.timesheetHydration === 'object') ? mc.timesheetHydration : {};
    const detailsError = String(hydration.detailsError || '').trim();

    // Keep the same Daily identity and Refresh-only result after an unknown read.
    const retainedDailyStatus=key==='overview' && mc._dailyProcessingRequestState?.unknown===true
      && mc._dailyProcessingRequestState.key===SESSION?.user?.id+':'+openToken+':'+mc.data?.timesheet_id+':'+mc.timesheetDetails?.timesheet?.version
      && SESSION?.user?.role==='admin' && bankingNextOwnerClient()?.peek()?.active_owner==='NEXT'
      && window.CloudTMSBpayNextOffice?.dailyProcessingState?.(mc.timesheetDetails);
    if (detailsError && !retainedDailyStatus) {
      return renderTimesheetLoadingCard('Timesheet details', detailsError, baseRow.__bpayNextExactPhysicalId != null);
    }

    const detailsLoaded = hydration.detailsLoaded === true;
    const activeEditDomains = (mc.timesheetEditDomains && typeof mc.timesheetEditDomains === 'object') ? mc.timesheetEditDomains : null;
    const ctxForTab = {
      row: mergedRow || mc.data || baseRow,
      details: (mc.timesheetDetails && typeof mc.timesheetDetails === 'object') ? mc.timesheetDetails : makeInitialTimesheetDetailsPlaceholder(baseRow),
      related: (mc.timesheetRelated && typeof mc.timesheetRelated === 'object') ? mc.timesheetRelated : makeInitialTimesheetRelatedPlaceholder(baseRow),
      state: (mc.timesheetState && typeof mc.timesheetState === 'object') ? mc.timesheetState : makeInitialTimesheetStatePlaceholder(baseRow),
      policy: activeEditDomains,
      editDomains: activeEditDomains,
      timesheetEditDomains: activeEditDomains,
      canEditHoursSchedule: activeEditDomains ? (activeEditDomains.canEditHoursSchedule === true) : undefined,
      hoursScheduleDisabledReason: activeEditDomains ? String(activeEditDomains.hoursScheduleDisabledReason || '') : '',
      expenseStorageTarget: activeEditDomains?.expenseStorageTarget || mc.expenseStorageTarget || mc.expense_storage_target || null,
      expense_storage_target: activeEditDomains?.expenseStorageTarget || mc.expenseStorageTarget || mc.expense_storage_target || null,
      hasContractWeekExpenseDraftTarget: activeEditDomains?.hasContractWeekExpenseDraftTarget === true,
      has_contract_week_expense_draft_target: activeEditDomains?.hasContractWeekExpenseDraftTarget === true,
      supportsUnprocessedExpenseDraft: activeEditDomains?.supportsUnprocessedExpenseDraft === true,
      supports_unprocessed_expense_draft: activeEditDomains?.supportsUnprocessedExpenseDraft === true,
      expenseEvidenceStorageTarget: activeEditDomains?.expenseEvidenceStorageTarget || mc.expenseEvidenceStorageTarget || mc.expense_evidence_storage_target || null,
      expense_evidence_storage_target: activeEditDomains?.expenseEvidenceStorageTarget || mc.expenseEvidenceStorageTarget || mc.expense_evidence_storage_target || null,
      canManageExpenseEvidence: activeEditDomains?.canManageExpenseEvidence === true,
      requiresAdditionalManualForExpenses: activeEditDomains?.requiresAdditionalManualForExpenses === true,
      candidateOfficeSurface: 'SIMPLE_TIMESHEET',
      suppress_action_buttons: !detailsLoaded,
      suppress_timesheet_action_buttons: !detailsLoaded
    };

    if (key === 'overview') {
      try {
        return renderTimesheetOverviewTab(ctxForTab);
      } catch (err) {
        return renderTimesheetLoadingCard('Timesheet overview', err?.message || 'Timesheet overview is loading…');
      }
    }

    if (!detailsLoaded) {
      return renderTimesheetLoadingCard('Timesheet details', 'Timesheet details are loading…');
    }

    switch (key) {
      case 'lines':
        return renderTimesheetLinesTab(ctxForTab);
      case 'expenses':
        if (typeof renderTimesheetExpensesTab === 'function') return renderTimesheetExpensesTab(ctxForTab);
        return renderTimesheetLoadingCard('Expenses', 'Expenses are not available for this row.');
      case 'evidence':
        return renderTimesheetEvidenceTab(ctxForTab);
      case 'issues':
        return renderTimesheetIssuesTab(ctxForTab);
      case 'finance':
        return renderTimesheetFinanceTab(ctxForTab);
      case 'audit':
        return renderTimesheetAuditTab(ctxForTab);
      default:
        return renderTimesheetLoadingCard('Timesheet', `Unknown tab: ${key}`);
    }
  };
}

function refreshTimesheetModalTabsChrome(openToken) {
  if (!isActiveTimesheetModalToken(openToken)) return false;

  let fr = null;
  try { fr = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null; } catch { fr = null; }
  if (!fr || fr.entity !== 'timesheets') return false;

  const tabsEl = document.getElementById('modalTabs');
  if (!tabsEl) return false;

  const tabs = Array.isArray(fr.tabs) ? fr.tabs : [];
  tabsEl.innerHTML = '';

  tabs.forEach((tab) => {
    const t = (tab && typeof tab === 'object') ? tab : {};
    const key = String(t.key || '').trim();
    if (!key) return;

    const b = document.createElement('button');
    b.textContent = t.label || t.title || key;
    try { b.dataset.testid = `timesheet-tab-${key}`; } catch {}

    const disabled = !!t.disabled;
    const reason = String(t.disabled_reason || 'This tab is currently unavailable.').trim();
    if (disabled) {
      b.classList.add('disabled');
      b.dataset.disabled = '1';
      b.setAttribute('title', reason);
    } else {
      b.dataset.disabled = '';
    }

    if (key === fr.currentTabKey) b.classList.add('active');

    b.onclick = async () => {
      if (fr.mode === 'saving' || disabled) return;

      const tabIntent = { key, expires_at: Date.now() + 5000 };
      fr.__timesheetHydrationTabIntent = tabIntent;
      window.modalCtx.__timesheetHydrationTabIntent = tabIntent;

      tabsEl.querySelectorAll('button').forEach((x) => x.classList.remove('active'));
      b.classList.add('active');
      try {
        await Promise.resolve(fr.setTab(key));
        if (getActiveTimesheetFrame() === fr && String(fr.currentTabKey || '') !== key) {
          await Promise.resolve(fr.setTab(key));
        }
      } catch {}

      if (getActiveTimesheetFrame() !== fr) return;
      tabsEl.querySelectorAll('button').forEach((x) => {
        const xKey = String(x.dataset.testid || '').replace(/^timesheet-tab-/, '');
        x.classList.toggle('active', xKey === String(fr.currentTabKey || ''));
      });
    };

    tabsEl.appendChild(b);
  });

  return true;
}


async function safeRerenderTimesheetModal(openToken, preferredTab, opts = {}) {
  if (!isActiveTimesheetModalToken(openToken)) return false;

  let fr = null;
  try { fr = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null; } catch { fr = null; }
  if (!fr || fr.entity !== 'timesheets' || fr.kind !== 'timesheets') return false;

  if (!isActiveTimesheetModalToken(openToken)) return false;

  const sameActiveFrame = () => {
    if (!isActiveTimesheetModalToken(openToken)) return false;
    try {
      const currentFr = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
      return !!(
        currentFr &&
        currentFr === fr &&
        currentFr.entity === 'timesheets' &&
        currentFr.kind === 'timesheets'
      );
    } catch {
      return false;
    }
  };

  try {
    if (opts && opts.title) {
      fr.title = String(opts.title || 'Timesheet');
      const titleEl = document.getElementById('modalTitle');
      if (titleEl) titleEl.textContent = fr.title;
    }
  } catch {}

  try {
    if (opts && opts.refreshTabs) refreshTimesheetModalTabsChrome(openToken);
  } catch {}

  const tabKey = String(preferredTab || fr.currentTabKey || 'overview').trim() || 'overview';

  try {
    if (!sameActiveFrame()) return false;
    fr.__timesheetSuppressDirtyToken = String(openToken || '');
    fr._suppressDirty = true;
    await Promise.resolve(fr.setTab(tabKey));
    if (!sameActiveFrame()) return false;
  } catch (err) {
    try {
      if (sameActiveFrame()) {
        const body = document.getElementById('modalBody');
        if (body) body.innerHTML = renderTimesheetLoadingCard('Timesheet details', err?.message || 'Failed to render timesheet tab.');
      }
    } catch {}
  } finally {
    try {
      const cleanupFrame = (typeof window.__getModalFrame === 'function') ? window.__getModalFrame() : null;
      if (cleanupFrame === fr && fr && fr.entity === 'timesheets' && fr.kind === 'timesheets' && String(fr.__timesheetSuppressDirtyToken || '') === String(openToken || '')) {
        fr._suppressDirty = false;
        delete fr.__timesheetSuppressDirtyToken;
      }
    } catch {}
  }

  if (!sameActiveFrame()) return false;

  try {
    if (opts && opts.refreshTabs) refreshTimesheetModalTabsChrome(openToken);
  } catch {}

  if (!sameActiveFrame()) return false;
  try { fr._updateButtons && fr._updateButtons(); } catch {}
  return true;
}

// New Phase 3 helper functions for FRONTEND 10052026.js


function cloneTimesheetFastOpenValue(value) {
  if (value == null || typeof value !== 'object') return value;
  try { return JSON.parse(JSON.stringify(value)); } catch {}
  if (Array.isArray(value)) return value.slice();
  return { ...value };
}


function boolishTimesheetFastOpenFlag(value) {
  if (value === true || value === 1) return true;
  if (value === false || value === 0 || value == null) return false;
  const raw = String(value).trim().toLowerCase();
  return raw === 'true' || raw === '1' || raw === 'yes' || raw === 'y' || raw === 'on';
}


