      const mDate = ymdStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
      const mTime = hm.match(/^(\d{2}):(\d{2})$/);
      if (!mDate || !mTime) return [];

      const Y  = Number(mDate[1]);
      const Mo = Number(mDate[2]);
      const D  = Number(mDate[3]);
      const H  = Number(mTime[1]);
      const Mi = Number(mTime[2]);
