  const bannerEl = q('tsDailyErrorsBanner');
  if (!(dateEl && startEl && endEl && breakStartEl && breakEndEl && breakMinsEl && paidHoursEl && dowCellEl && bannerEl)) return { ok: false };

  const st = (stateObj && typeof stateObj === 'object') ? stateObj : {};
